def project_metadata(payload: dict, create: bool = False) -> dict:
    """Use the HAGISILTA schema for new projects and read legacy NORT projects."""
    if "hagisilta_project" in payload or "nort_project" not in payload:
        return payload.setdefault("hagisilta_project", {}) if create else (payload.get("hagisilta_project", {}) or {})
    return payload.setdefault("nort_project", {}) if create else (payload.get("nort_project", {}) or {})


def dataset_metadata(payload: dict, create: bool = False) -> dict:
    if "hagisilta_dataset" in payload or "nort_dataset" not in payload:
        return payload.setdefault("hagisilta_dataset", {}) if create else (payload.get("hagisilta_dataset", {}) or {})
    return payload.setdefault("nort_dataset", {}) if create else (payload.get("nort_dataset", {}) or {})


DATASET_BODYPART_PLACEHOLDER = "미지정"


def parse_dataset_bodyparts_text(value: str) -> list[str]:
    """Parse the shared bodypart editor without persisting its display placeholder."""
    bodyparts = [part for part in re.split(r"[,\s]+", str(value).strip()) if part]
    if bodyparts in ([DATASET_BODYPART_PLACEHOLDER], [tr(DATASET_BODYPART_PLACEHOLDER)]):
        return []
    return bodyparts


def populate_nort_role_combo(combo: QComboBox, selected: str) -> None:
    """Keep role identities independent of the visible language."""
    combo.clear()
    combo.addItem(tr("미지정"), "unassigned")
    for label in ("A=Novel · B=Familiar", "A=Familiar · B=Novel"):
        combo.addItem(label, label)
    selected = "unassigned" if selected == "미지정" else selected
    combo.setCurrentIndex(max(0, combo.findData(selected)))


def populate_experiment_combo(combo: QComboBox, values: list[str], selected: str) -> None:
    """Translate only the built-in placeholder; custom experiment names are data."""
    combo.clear()
    for value in dict.fromkeys([*values, selected]):
        combo.addItem(tr("미지정") if value == "미지정" else value, value)
    combo.setCurrentIndex(max(0, combo.findData(selected)))


def experiment_combo_value(combo: QComboBox) -> str:
    index = combo.currentIndex()
    if index >= 0 and combo.currentText() == combo.itemText(index):
        return str(combo.itemData(index) or "미지정")
    return combo.currentText().strip() or "미지정"


def apply_windows_titlebar_theme(widget: QWidget) -> None:
    """Keep native window controls while matching the HAGISILTA dark palette."""
    if sys.platform != "win32":
        return
    try:
        if not widget.isWindow():
            return
        window_handle = ctypes.c_void_p(int(widget.winId()))
        dwmapi = ctypes.windll.dwmapi
        setter = dwmapi.DwmSetWindowAttribute
        setter.argtypes = [
            ctypes.c_void_p,
            ctypes.c_uint,
            ctypes.c_void_p,
            ctypes.c_uint,
        ]
        setter.restype = ctypes.c_long
        enabled = ctypes.c_int(1)
        # Windows 11/current Windows 10 use attribute 20; older Windows 10 uses 19.
        result = setter(
            window_handle, 20, ctypes.byref(enabled), ctypes.sizeof(enabled)
        )
        if result != 0:
            setter(
                window_handle, 19, ctypes.byref(enabled), ctypes.sizeof(enabled)
            )

        def colorref(red: int, green: int, blue: int) -> ctypes.c_uint:
            return ctypes.c_uint(red | (green << 8) | (blue << 16))

        for attribute, color in (
            (35, colorref(11, 20, 34)),    # caption: #0b1422
            (36, colorref(234, 242, 255)), # text: #eaf2ff
            (34, colorref(43, 63, 89)),    # border: #2b3f59
        ):
            setter(
                window_handle,
                attribute,
                ctypes.byref(color),
                ctypes.sizeof(color),
            )
    except Exception:
        # Unsupported Windows builds simply keep their native title bar.
        pass


class DarkTitleBarFilter(QObject):
    """Apply the native dark caption to every window and dialog on first show."""

    def eventFilter(self, watched, event) -> bool:
        if event.type() == QEvent.Show and isinstance(watched, QWidget) and watched.isWindow():
            apply_windows_titlebar_theme(watched)
        return super().eventFilter(watched, event)


class TrackingActivityArea(QScrollArea):
    """Fit the active ROI rows, scrolling only when their content exceeds 160px."""

    def fit_contents(self) -> None:
        label = self.widget()
        if label is None:
            return
        width = max(1, self.viewport().width())
        height = max(label.fontMetrics().height(), label.heightForWidth(width))
        height = min(160, height + 2 * self.frameWidth() + 2)
        if self.minimumHeight() != height or self.maximumHeight() != height:
            self.setFixedHeight(height)

    def resizeEvent(self, event) -> None:
        super().resizeEvent(event)
        self.fit_contents()


class MultiRowContextTableWidget(QTableWidget):
    """Keep a Ctrl/Shift row selection when right-clicking inside it."""

    def __init__(self, *args, **kwargs) -> None:
        super().__init__(*args, **kwargs)
        self._right_click_rows: set[int] = set()
        self._restoring_context_rows = False

    def selectionCommand(self, index, event=None):
        """Never let a right-click collapse an existing selected-row set."""
        if (
            event is not None
            and event.type() in (QEvent.MouseButtonPress, QEvent.MouseButtonRelease)
            and event.button() == Qt.RightButton
            and index.isValid()
        ):
            selection = self.selectionModel()
            selected_rows = {
                selected.row() for selected in selection.selectedIndexes()
            } if selection else set()
            if index.row() in selected_rows:
                return QItemSelectionModel.NoUpdate
        return super().selectionCommand(index, event)

    def _capture_context_rows(self, index) -> None:
        selection = self.selectionModel()
        selected_rows = {
            selected.row() for selected in selection.selectedIndexes()
        } if selection else set()
        self._right_click_rows = (
            set(selected_rows)
            if index.isValid() and index.row() in selected_rows
            else ({index.row()} if index.isValid() else set())
        )
        if index.isValid() and index.row() not in selected_rows and selection:
            selection.setCurrentIndex(
                index,
                QItemSelectionModel.ClearAndSelect | QItemSelectionModel.Rows,
            )

    def mousePressEvent(self, event) -> None:
        if event.button() == Qt.RightButton:
            index = self.indexAt(event.position().toPoint())
            self._capture_context_rows(index)
            # Continue through QTableWidget so Windows/Qt still generates its
            # normal CustomContextMenu event. selectionCommand() above returns
            # NoUpdate for the captured selected row, so this no longer
            # collapses the row set or suppresses the menu itself.
        super().mousePressEvent(event)

    def register_context_cell_widget(self, widget: QWidget | None) -> None:
        """Route context clicks from persistent cell editors through the table."""
        if widget is not None:
            widget.installEventFilter(self)

    def eventFilter(self, watched, event) -> bool:
        if isinstance(watched, QWidget) and watched is not self.viewport():
            if event.type() == QEvent.MouseButtonPress and event.button() == Qt.RightButton:
                position = watched.mapTo(self.viewport(), event.position().toPoint())
                self._capture_context_rows(self.indexAt(position))
                event.accept()
                return True
            if event.type() == QEvent.MouseButtonRelease and event.button() == Qt.RightButton:
                position = watched.mapTo(self.viewport(), event.position().toPoint())
                self.customContextMenuRequested.emit(position)
                event.accept()
                return True
            if event.type() == QEvent.ContextMenu:
                event.accept()
                return True
        return super().eventFilter(watched, event)

    def restore_right_click_rows(self, position) -> list[int]:
        """Restore the row set captured before Qt's context-menu processing."""
        index = self.indexAt(position)
        selection = self.selectionModel()
        live_rows = {
            selected.row() for selected in selection.selectedIndexes()
        } if selection else set()
        # The cache is captured on this exact right-button press, before Qt can
        # alter the selection. Never fall back to selection history from an
        # earlier click: a deliberate later single selection must stay single.
        if index.isValid() and index.row() in self._right_click_rows:
            rows = set(self._right_click_rows)
        elif index.isValid() and index.row() in live_rows:
            rows = set(live_rows)
        else:
            rows = {index.row()} if index.isValid() else set()
        if not rows and index.isValid():
            rows = {index.row()}
        if selection and rows:
            if live_rows != rows:
                self._restoring_context_rows = True
                try:
                    selection.clearSelection()
                    for row in sorted(rows):
                        selection.select(
                            self.model().index(row, 0),
                            QItemSelectionModel.Select | QItemSelectionModel.Rows,
                        )
                finally:
                    self._restoring_context_rows = False
            if index.isValid():
                selection.setCurrentIndex(index, QItemSelectionModel.NoUpdate)
        return sorted(rows)


def detailed_tooltip(
    purpose: str,
    effect: str,
    recommendation: str,
    distinction: str = "",
) -> str:
    """Build consistent, beginner-friendly tooltips for adjustable settings."""
    sections = [
        purpose.strip(),
        tr('값을 바꾸면: {value1}', value1=effect.strip()),
    ]
    if distinction.strip():
        sections.append(tr('헷갈리기 쉬운 점: {value1}', value1=distinction.strip()))
    sections.append(tr('권장: {value1}', value1=recommendation.strip()))
    return "\n\n".join(sections)


def discover_config(work_root: Path | None = None) -> Path | None:
    work_root = work_root or get_work_root()
    configs = sorted(
        (work_root / "dlc_workspace").glob("**/config.yaml"),
        key=lambda path: path.stat().st_mtime,
        reverse=True,
    )
    return configs[0] if configs else None


def project_summary(config: Path | None) -> dict:
    if not config or not config.is_file():
        return {"valid": False, "labels": 0, "bodyparts": [], "videos": 0}
    payload = yaml.safe_load(config.read_text(encoding="utf-8")) or {}
    project = Path(payload.get("project_path", config.parent))
    video_sets = payload.get("video_sets", {}) or {}
    active_video_names = {Path(str(path)).stem for path in video_sets}
    labeled_root = project / "labeled-data"
    label_images = 0
    label_sets = 0
    if labeled_root.exists():
        for folder in labeled_root.iterdir():
            if (
                not folder.is_dir()
                or folder.name.endswith("_labeled")
                or folder.name.endswith(".importing")
            ):
                continue
            if active_video_names and folder.name not in active_video_names:
                continue
            count = sum(1 for path in folder.iterdir() if path.suffix.lower() in {".png", ".jpg", ".jpeg"})
            if count:
                label_sets += 1
                label_images += count
    return {
        "valid": True,
        "task": payload.get("Task", config.parent.name),
        "project": project,
        "labels": label_images,
        "label_sets": label_sets,
        "bodyparts": payload.get("bodyparts", []),
        "videos": len(video_sets),
        "pcutoff": float(payload.get("pcutoff", 0.6)),
    }


def latest_evaluation(config: Path | None) -> dict | None:
    if not config:
        return None
    files = sorted(config.parent.glob("evaluation-results*/**/CombinedEvaluation-results.csv"))
    if not files:
        return None
    try:
        row = pd.read_csv(files[-1]).iloc[-1]
        return {
            "train_rmse": float(row.get("train rmse", float("nan"))),
            "validation_rmse": float(row.get("test rmse", float("nan"))),
            "validation_map": float(row.get("test mAP", float("nan"))),
            "epochs": int(row.get("Training epochs", 0)),
            "path": files[-1],
        }
    except Exception:
        return None


def next_shuffle(config: Path | None) -> int:
    if not config:
        return 1
    found: list[int] = []
    for path in config.parent.glob("dlc-models*/**/*shuffle*"):
        match = re.search(r"shuffle(\d+)", path.name, re.IGNORECASE)
        if match:
            found.append(int(match.group(1)))
    if not found:
        return 1
    highest = max(found)
    checkpoint_suffixes = {".pt", ".pth", ".ckpt"}
    trained = any(
        path.is_file()
        and re.search(rf"shuffle{highest}(?:\D|$)", str(path), re.IGNORECASE)
        and (path.suffix.lower() in checkpoint_suffixes or path.name.lower().startswith("snapshot"))
        for path in config.parent.glob("dlc-models*/**/*")
    )
    # Dataset preparation creates the shuffle directory before training. Keep
    # that same number until an actual checkpoint exists so training can resume.
    return highest + 1 if trained else highest


def reinforcement_shuffle(config: Path | None, source_shuffle: int | None) -> int:
    """Reserve a new number after the source and every existing local run."""
    used = [int(source_shuffle or 0)]
    if config:
        for path in config.parent.glob("dlc-models*/**/*shuffle*"):
            match = re.search(r"shuffle(\d+)", path.name, re.IGNORECASE)
            if match and path.is_dir():
                used.append(int(match.group(1)))
        for path in project_state_root(config.parent).glob("training-splits/shuffle-*.json"):
            match = re.match(r"shuffle-(\d+)-", path.name)
            if match:
                used.append(int(match.group(1)))
    return max(used) + 1


def shuffle_has_checkpoint(config: Path | None, shuffle: int) -> bool:
    if not config:
        return False
    return any(
        path.is_file()
        and re.search(rf"shuffle{shuffle}(?:\D|$)", str(path.relative_to(config.parent)), re.IGNORECASE)
        and (path.suffix.lower() in {".pt", ".pth", ".ckpt"} or path.name.lower().startswith("snapshot"))
        for path in config.parent.glob("dlc-models*/**/*")
    )


def trained_model_inventory(config: Path | None) -> list[dict]:
    """Return one concise row per trained PyTorch Shuffle in a project."""
    if not config or not config.is_file():
        return []
    by_shuffle: dict[int, dict] = {}
    model_root = config.parent / "dlc-models-pytorch"
    if model_root.is_dir():
        for snapshot in model_root.glob("**/snapshot*.pt"):
            match = re.search(r"shuffle(\d+)", str(snapshot), re.IGNORECASE)
            if not match:
                continue
            shuffle = int(match.group(1))
            row = by_shuffle.setdefault(shuffle, {
                "shuffle": shuffle, "snapshots": [], "best": None,
                "train_rmse": None, "validation_rmse": None, "validation_map": None,
                "validation_mar": None, "test_rmse": None, "test_map": None,
                "test_mar": None, "test_coverage": None,
                "test_frames": None, "epochs": None,
                "test_median_error": None, "test_normalized_error": None,
                "test_pck_3": None, "test_pck_5": None, "test_pck_10": None,
                "test_dropout": None, "test_per_keypoint": {},
                "test_result_path": None, "test_artifacts": {},
            })
            row["snapshots"].append(snapshot)
    for row in by_shuffle.values():
        candidates = row["snapshots"]
        preferred = [path for path in candidates if "best" in path.stem.lower()]
        row["best"] = max(preferred or candidates, key=lambda path: path.stat().st_mtime)

    evaluation_files = sorted(
        config.parent.glob("evaluation-results*/**/CombinedEvaluation-results.csv"),
        key=lambda path: path.stat().st_mtime,
    )
    for evaluation_file in evaluation_files:
        try:
            frame = pd.read_csv(evaluation_file)
        except Exception:
            continue
        for _, result in frame.iterrows():
            try:
                shuffle = int(result.get("Shuffle number"))
            except (TypeError, ValueError):
                continue
            if shuffle not in by_shuffle:
                continue
            row = by_shuffle[shuffle]
            row.update({
                "train_rmse": float(result.get("train rmse", float("nan"))),
                "validation_rmse": float(result.get("test rmse", float("nan"))),
                "validation_map": float(result.get("test mAP", float("nan"))),
                "validation_mar": float(result.get("test mAR", float("nan"))),
                "epochs": int(result.get("Training epochs", 0)),
            })
    test_root = project_state_root(config.parent) / "test-evaluations"
    for shuffle, row in by_shuffle.items():
        result_path = test_root / f"shuffle-{shuffle:02d}" / "final-test-results.json"
        if not result_path.is_file():
            continue
        try:
            result = json.loads(result_path.read_text(encoding="utf-8"))
            row["test_rmse"] = float(result.get("rmse_px"))
            test_map = result.get("mAP")
            test_mar = result.get("mAR")
            row["test_map"] = float(test_map) if test_map is not None else None
            row["test_mar"] = float(test_mar) if test_mar is not None else None
            row["test_coverage"] = float(result.get("coverage_at_pcutoff"))
            row["test_frames"] = int(result.get("test_frames", 0))
            row["test_median_error"] = result.get("median_error_px")
            row["test_normalized_error"] = result.get("normalized_error_percent")
            row["test_pck_3"] = result.get("pck_3px")
            row["test_pck_5"] = result.get("pck_5px")
            row["test_pck_10"] = result.get("pck_10px")
            row["test_dropout"] = result.get("dropout_rate")
            row["test_per_keypoint"] = result.get("per_keypoint", {}) or {}
            row["test_result_path"] = result_path
            row["test_artifacts"] = result.get("artifacts", {}) or {}
        except (OSError, TypeError, ValueError, json.JSONDecodeError):
            continue
    return [by_shuffle[key] for key in sorted(by_shuffle)]


def write_portable_model_bundle(
    model_config: Path,
    snapshot: Path,
    shuffle: int,
    destination: Path,
) -> Path:
    """Package the files DLC needs for inference into one portable ZIP."""
    model_config = model_config.resolve()
    snapshot = snapshot.resolve()
    if not model_config.is_file() or not snapshot.is_file():
        raise FileNotFoundError(tr('모델 config.yaml 또는 체크포인트를 찾을 수 없습니다.'))
    try:
        relative_snapshot = snapshot.relative_to(model_config.parent)
    except ValueError as error:
        raise ValueError(tr('체크포인트가 선택한 DLC 프로젝트 폴더 안에 있지 않습니다.')) from error
    pose_config = snapshot.parent / "pytorch_config.yaml"
    if not pose_config.is_file():
        raise FileNotFoundError(tr('모델 구조 설정이 없습니다: {value1}', value1=pose_config))
    test_pose_config = snapshot.parent.parent / "test" / "pose_cfg.yaml"
    project_payload = yaml.safe_load(model_config.read_text(encoding="utf-8")) or {}
    project_payload["project_path"] = "__HAGISILTA_MODEL_ROOT__"
    project_payload["video_sets"] = {}
    for key in list(project_payload):
        if str(key).startswith("nort_"):
            project_payload.pop(key, None)
    snapshot_selector: int | str = (
        "best" if snapshot.name.lower().startswith("snapshot-best") else 0
    )
    manifest = {
        "schema": "hagisilta-portable-dlc-model",
        "schema_version": 2,
        "created_at": time.strftime("%Y-%m-%dT%H:%M:%S"),
        "task": str(project_payload.get("Task", model_config.parent.name)),
        "shuffle": int(shuffle),
        "snapshot": relative_snapshot.as_posix(),
        "snapshot_index": snapshot_selector,
        "bodyparts": list(map(str, project_payload.get("bodyparts", []) or [])),
    }
    destination = destination.with_suffix(".zip") if destination.suffix.lower() != ".zip" else destination
    destination.parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(destination, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        archive.writestr(
            "hagisilta-model.json",
            json.dumps(manifest, ensure_ascii=False, indent=2),
        )
        archive.writestr(
            "config.yaml",
            yaml.safe_dump(project_payload, sort_keys=False, allow_unicode=True),
        )
        pose_payload = yaml.safe_load(pose_config.read_text(encoding="utf-8")) or {}
        pose_metadata = pose_payload.setdefault("metadata", {})
        pose_metadata["project_path"] = "__HAGISILTA_MODEL_ROOT__"
        pose_metadata["pose_config_path"] = "__HAGISILTA_MODEL_ROOT__/pytorch_config.yaml"
        archive.writestr(
            relative_snapshot.parent.joinpath("pytorch_config.yaml").as_posix(),
            yaml.safe_dump(pose_payload, sort_keys=False, allow_unicode=True),
        )
        if test_pose_config.is_file():
            test_pose_payload = yaml.safe_load(test_pose_config.read_text(encoding="utf-8")) or {}
        else:
            bodyparts = list(map(str, project_payload.get("bodyparts", []) or []))
            test_pose_payload = {
                "dataset": "__HAGISILTA_MODEL_ROOT__",
                "dataset_type": "multi-animal-imgaug",
                "num_joints": len(bodyparts),
                "all_joints": [[index] for index in range(len(bodyparts))],
                "all_joints_names": bodyparts,
                "net_type": str(pose_payload.get("net_type", "hrnet_w32")),
                "global_scale": 1,
                "scoremap_dir": "test",
            }
        test_pose_payload["dataset"] = "__HAGISILTA_MODEL_ROOT__"
        archive.writestr(
            relative_snapshot.parent.parent.joinpath("test", "pose_cfg.yaml").as_posix(),
            yaml.safe_dump(test_pose_payload, sort_keys=False, allow_unicode=True),
        )
        archive.write(snapshot, relative_snapshot.as_posix())
        for detector in sorted(snapshot.parent.glob("detector-snapshot*.pt")):
            archive.write(detector, detector.relative_to(model_config.parent).as_posix())
    return destination


def install_portable_model_bundle(bundle: Path, destination: Path) -> dict:
    """Extract a HAGISILTA model ZIP safely and rewrite its internal absolute paths."""
    bundle = bundle.resolve()
    destination = destination.resolve()
    if not bundle.is_file():
        raise FileNotFoundError(bundle)
    destination.mkdir(parents=True, exist_ok=False)
    with zipfile.ZipFile(bundle, "r") as archive:
        names = set(archive.namelist())
        if "hagisilta-model.json" not in names or "config.yaml" not in names:
            raise ValueError(tr('HAGISILTA 모델 ZIP이 아닙니다.'))
        for member in archive.infolist():
            target = (destination / member.filename).resolve()
            if destination != target and destination not in target.parents:
                raise ValueError(tr('안전하지 않은 ZIP 내부 경로가 발견되었습니다.'))
        archive.extractall(destination)
    manifest = json.loads((destination / "hagisilta-model.json").read_text(encoding="utf-8"))
    if manifest.get("schema") != "hagisilta-portable-dlc-model":
        raise ValueError(tr('지원하지 않는 모델 ZIP 형식입니다.'))
    model_config = destination / "config.yaml"
    snapshot = destination / Path(str(manifest.get("snapshot", "")))
    if not model_config.is_file() or not snapshot.is_file():
        raise ValueError(tr('모델 ZIP에 config.yaml 또는 체크포인트가 없습니다.'))
    project_payload = yaml.safe_load(model_config.read_text(encoding="utf-8")) or {}
    project_payload["project_path"] = str(destination)
    project_payload["video_sets"] = {}
    model_config.write_text(
        yaml.safe_dump(project_payload, sort_keys=False, allow_unicode=True),
        encoding="utf-8",
    )
    for pose_config in destination.glob("dlc-models-pytorch/**/pytorch_config.yaml"):
        pose_payload = yaml.safe_load(pose_config.read_text(encoding="utf-8")) or {}
        metadata = pose_payload.setdefault("metadata", {})
        metadata["project_path"] = str(destination)
        metadata["pose_config_path"] = str(pose_config)
        pose_config.write_text(
            yaml.safe_dump(pose_payload, sort_keys=False, allow_unicode=True),
            encoding="utf-8",
        )
    test_pose_config = snapshot.parent.parent / "test" / "pose_cfg.yaml"
    if test_pose_config.is_file():
        test_pose_payload = yaml.safe_load(test_pose_config.read_text(encoding="utf-8")) or {}
    else:
        train_pose_config = snapshot.parent / "pytorch_config.yaml"
        pose_payload = (
            yaml.safe_load(train_pose_config.read_text(encoding="utf-8")) or {}
            if train_pose_config.is_file()
            else {}
        )
        bodyparts = list(map(str, project_payload.get("bodyparts", []) or []))
        test_pose_payload = {
            "dataset_type": "multi-animal-imgaug",
            "num_joints": len(bodyparts),
            "all_joints": [[index] for index in range(len(bodyparts))],
            "all_joints_names": bodyparts,
            "net_type": str(pose_payload.get("net_type", "hrnet_w32")),
            "global_scale": 1,
            "scoremap_dir": "test",
        }
    test_pose_payload["dataset"] = str(destination)
    test_pose_config.parent.mkdir(parents=True, exist_ok=True)
    test_pose_config.write_text(
        yaml.safe_dump(test_pose_payload, sort_keys=False, allow_unicode=True),
        encoding="utf-8",
    )
    return {
        "config": model_config,
        "snapshot": snapshot,
        "shuffle": int(manifest["shuffle"]),
        "snapshot_index": manifest.get("snapshot_index", "best"),
        "bodyparts": list(map(str, manifest.get("bodyparts", []) or [])),
    }


def import_portable_model_into_project(bundle: Path, project_config: Path) -> dict:
    """Install a compatible portable model as a new local Shuffle."""
    project_config = project_config.resolve()
    if not project_config.is_file():
        raise FileNotFoundError(project_config)
    project_root = project_config.parent
    project_payload = yaml.safe_load(project_config.read_text(encoding="utf-8")) or {}
    current_parts = list(map(str, project_payload.get("bodyparts", []) or []))
    with zipfile.ZipFile(bundle.resolve(), "r") as archive:
        if "hagisilta-model.json" not in archive.namelist():
            raise ValueError(tr('HAGISILTA 모델 ZIP이 아닙니다.'))
        manifest = json.loads(archive.read("hagisilta-model.json").decode("utf-8"))
    imported_parts = list(map(str, manifest.get("bodyparts", []) or []))
    if current_parts and imported_parts != current_parts:
        raise ValueError(
            tr('현재 프로젝트와 모델 ZIP의 신체점 구성이 달라 평가 모델로 가져올 수 없습니다.\n\n현재 프로젝트 ({value1}개): {value2}\n모델 ZIP ({value3}개): {value4}\n\n같은 신체점 이름과 순서로 만든 HAGISILTA 모델 ZIP을 선택하세요.', value1=len(current_parts), value2=', '.join(current_parts), value3=len(imported_parts), value4=', '.join(imported_parts))
        )
    state_root = project_state_root(project_root)
    staging_parent = state_root / "model-import-staging"
    staging_parent.mkdir(parents=True, exist_ok=True)
    staging = staging_parent / f"import-{time.strftime('%Y%m%d-%H%M%S')}-{os.getpid()}"
    suffix = 2
    while staging.exists():
        staging = staging_parent / f"import-{time.strftime('%Y%m%d-%H%M%S')}-{os.getpid()}-{suffix}"
        suffix += 1
    target_model: Path | None = None
    try:
        imported = install_portable_model_bundle(bundle, staging)

        iteration_root = project_root / "dlc-models-pytorch" / "iteration-0"
        used_shuffles = {
            int(match.group(1))
            for path in iteration_root.glob("*shuffle*") if path.is_dir()
            for match in [re.search(r"shuffle(\d+)", path.name, re.IGNORECASE)]
            if match
        }
        shuffle = 1
        while shuffle in used_shuffles:
            shuffle += 1
        task = str(project_payload.get("Task", project_root.name)).strip() or project_root.name
        date = str(project_payload.get("date", "")).strip()
        fractions = project_payload.get("TrainingFraction", [0.8]) or [0.8]
        trainset = int(round(float(fractions[0]) * 100))
        target_model = iteration_root / f"{task}{date}-trainset{trainset}shuffle{shuffle}"
        if target_model.exists():
            raise FileExistsError(tr('가져올 Shuffle 폴더가 이미 존재합니다: {value1}', value1=target_model))

        source_snapshot = Path(imported["snapshot"])
        source_train = source_snapshot.parent
        source_test = source_train.parent / "test"
        target_train = target_model / "train"
        target_test = target_model / "test"
        target_model.parent.mkdir(parents=True, exist_ok=True)
        shutil.copytree(source_train, target_train)
        if source_test.is_dir():
            shutil.copytree(source_test, target_test)
        else:
            target_test.mkdir(parents=True, exist_ok=True)
        target_snapshot = target_train / source_snapshot.name

        train_config = target_train / "pytorch_config.yaml"
        if train_config.is_file():
            train_payload = yaml.safe_load(train_config.read_text(encoding="utf-8")) or {}
            metadata = train_payload.setdefault("metadata", {})
            metadata["project_path"] = str(project_root)
            metadata["pose_config_path"] = str(train_config)
            if current_parts:
                metadata["bodyparts"] = current_parts
            train_config.write_text(
                yaml.safe_dump(train_payload, sort_keys=False, allow_unicode=True),
                encoding="utf-8",
            )
        test_config = target_test / "pose_cfg.yaml"
        if test_config.is_file():
            test_payload = yaml.safe_load(test_config.read_text(encoding="utf-8")) or {}
            test_payload["dataset"] = str(project_root)
            test_config.write_text(
                yaml.safe_dump(test_payload, sort_keys=False, allow_unicode=True),
                encoding="utf-8",
            )

        provenance_root = state_root / "imported-models"
        provenance_root.mkdir(parents=True, exist_ok=True)
        provenance = {
            "schema": "hagisilta-imported-evaluation-model",
            "imported_at": time.strftime("%Y-%m-%dT%H:%M:%S"),
            "source_bundle": str(bundle.resolve()),
            "source_shuffle": int(imported["shuffle"]),
            "local_shuffle": shuffle,
            "snapshot": str(target_snapshot),
            "bodyparts": current_parts or imported_parts,
        }
        (provenance_root / f"shuffle-{shuffle:02d}.json").write_text(
            json.dumps(provenance, ensure_ascii=False, indent=2), encoding="utf-8"
        )
        return {
            **provenance,
            "shuffle": shuffle,
            "snapshot": target_snapshot,
            "model_root": target_model,
        }
    except Exception:
        if target_model is not None and target_model.exists():
            shutil.rmtree(target_model, ignore_errors=True)
        raise
    finally:
        if staging.exists():
            shutil.rmtree(staging, ignore_errors=True)


def training_snapshot_metadata(snapshot: Path) -> dict:
    """Read the compatibility information needed before transfer learning."""
    snapshot = snapshot.resolve()
    if not snapshot.is_file():
        raise FileNotFoundError(tr('체크포인트를 찾을 수 없습니다: {value1}', value1=snapshot))
    pose_config = snapshot.parent / "pytorch_config.yaml"
    if not pose_config.is_file():
        raise FileNotFoundError(
            tr('체크포인트와 같은 train 폴더에 pytorch_config.yaml이 없습니다.')
        )
    pose_payload = yaml.safe_load(pose_config.read_text(encoding="utf-8")) or {}
    metadata = pose_payload.get("metadata", {}) or {}
    bodyparts = list(map(str, metadata.get("bodyparts", []) or []))
    net_type = str(
        pose_payload.get("net_type")
        or ((pose_payload.get("model", {}) or {}).get("backbone", {}) or {}).get("model_name")
        or ""
    )
    manifest = None
    for parent in snapshot.parents:
        candidate = parent / "hagisilta-model.json"
        if candidate.is_file():
            manifest = json.loads(candidate.read_text(encoding="utf-8"))
            if manifest.get("schema") == "hagisilta-portable-dlc-model":
                bodyparts = list(map(str, manifest.get("bodyparts", []) or bodyparts))
            break
    return {
        "snapshot": snapshot,
        "pose_config": pose_config,
        "bodyparts": bodyparts,
        "net_type": net_type,
        "task": str((manifest or {}).get("task", "")),
        "shuffle": (manifest or {}).get("shuffle") or next(
            (int(match.group(1)) for parent in snapshot.parents
             if (match := re.search(r"shuffle(\d+)(?:\D|$)", parent.name, re.IGNORECASE))),
            None,
        ),
    }


def model_bodyparts_from_config(model_config: Path | str) -> list[str]:
    """Return a model's inference schema without consulting the active project."""
    path = Path(model_config)
    if not path.is_file():
        return []
    payload = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    values = payload.get("bodyparts", []) if isinstance(payload, dict) else []
    if not isinstance(values, (list, tuple)):
        return []
    return list(dict.fromkeys(str(part) for part in values if part is not None and str(part).strip()))


def snapshot_for_pose_result(config: Path | None, pose: Path | None) -> Path | None:
    """Find the exact project checkpoint encoded in a DLC result filename."""
    if not config or not pose:
        return None
    shuffle_match = re.search(r"shuffle(\d+)", pose.stem, re.IGNORECASE)
    snapshot_match = re.search(r"snapshot[_-](best[-_])?(\d+)", pose.stem, re.IGNORECASE)
    if not shuffle_match:
        return None
    shuffle = int(shuffle_match.group(1))
    candidates = [
        path for path in config.parent.glob("dlc-models-pytorch/**/*")
        if path.is_file()
        and path.suffix.lower() in {".pt", ".pth"}
        and re.search(rf"shuffle{shuffle}(?:\D|$)", str(path), re.IGNORECASE)
        and path.name.lower().startswith("snapshot")
    ]
    if not candidates:
        return None
    if snapshot_match:
        epoch = int(snapshot_match.group(2))
        wants_best = bool(snapshot_match.group(1))
        exact = [
            path for path in candidates
            if re.search(rf"(?:best[-_])?0*{epoch}(?:\D|$)", path.stem, re.IGNORECASE)
            and (not wants_best or "best" in path.stem.lower())
        ]
        if exact:
            return max(exact, key=lambda path: path.stat().st_mtime)
    best = [path for path in candidates if "best" in path.stem.lower()]
    return max(best or candidates, key=lambda path: path.stat().st_mtime)


class NoWheelSpinBox(QSpinBox):
    """Keep page scrolling from accidentally changing a numeric setting."""

    def wheelEvent(self, event) -> None:
        event.ignore()


class TableNumberSpinBox(NoWheelSpinBox):
    """Stable whole-value editor for numeric table cells.

    A table count is normally replaced as one value.  Selecting the complete
    value on click avoids the line edit's drag-selection gesture following the
    pointer across digits, and disabling keyboard tracking prevents temporary
    values such as ``1`` and ``10`` from being treated as committed while the
    user is still typing ``100``.
    """

    def __init__(self, parent=None) -> None:
        super().__init__(parent)
        self.setKeyboardTracking(False)

    def mousePressEvent(self, event) -> None:
        if event.button() == Qt.LeftButton:
            self.setFocus(Qt.MouseFocusReason)
            self.lineEdit().selectAll()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event) -> None:
        if event.buttons() & Qt.LeftButton:
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseDoubleClickEvent(self, event) -> None:
        if event.button() == Qt.LeftButton:
            self.setFocus(Qt.MouseFocusReason)
            self.lineEdit().selectAll()
            event.accept()
            return
        super().mouseDoubleClickEvent(event)


class NoWheelDoubleSpinBox(QDoubleSpinBox):
    """Keep page scrolling from accidentally changing a decimal setting."""

    def wheelEvent(self, event) -> None:
        event.ignore()


class NoWheelComboBox(QComboBox):
    """Keep page scrolling from accidentally changing a selected option."""

    popupShown = Signal()
    popupHidden = Signal()

    def wheelEvent(self, event) -> None:
        event.ignore()

    def showPopup(self) -> None:  # noqa: N802
        self.popupShown.emit()
        super().showPopup()

    def hidePopup(self) -> None:  # noqa: N802
        super().hidePopup()
        self.popupHidden.emit()


class DashboardProjectToolStrip(QFrame):
    """Keep the recent picker intact; move secondary tools below on narrow pages."""

    def __init__(self, recent: QFrame, secondary: QWidget) -> None:
        super().__init__(objectName="dashboardToolStrip")
        self.recent = recent
        self.secondary = secondary
        self._stacked = True
        layout = QGridLayout(self)
        layout.setContentsMargins(7, 6, 7, 6)
        layout.setHorizontalSpacing(14)
        layout.setVerticalSpacing(7)
        # Horizontal placement must not force the page to retain that width
        # when the user subsequently narrows the window.
        layout.setSizeConstraint(QLayout.SetNoConstraint)
        layout.addWidget(recent, 0, 0)
        layout.addWidget(secondary, 1, 0, Qt.AlignRight)
        layout.setColumnStretch(0, 1)

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        margins = self.layout().contentsMargins()
        width = max(self.recent.minimumSizeHint().width(), self.secondary.minimumSizeHint().width())
        return QSize(width + margins.left() + margins.right(), self.layout().minimumSize().height())

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        layout = self.layout()
        margins = layout.contentsMargins()
        required = (self.recent.minimumSizeHint().width() + self.secondary.sizeHint().width()
                    + margins.left() + margins.right() + layout.horizontalSpacing())
        stacked = self.width() < required
        if stacked != self._stacked:
            self._stacked = stacked
            layout.removeWidget(self.secondary)
            layout.addWidget(self.secondary, 1 if stacked else 0, 0 if stacked else 1, Qt.AlignRight)
            self.updateGeometry()


class CheckableComboBox(NoWheelComboBox):
    """Compact multi-select combo that keeps its popup open while items are checked."""

    checkedItemsChanged = Signal()

    def __init__(
        self, *args, placeholder: str = "선택 없음", summary_noun: str = "항목", **kwargs,
    ) -> None:
        super().__init__(*args, **kwargs)
        placeholder, summary_noun = tr(placeholder), tr(summary_noun)
        self._placeholder = placeholder
        self._summary_noun = summary_noun
        self.setEditable(True)
        self.lineEdit().setReadOnly(True)
        self.lineEdit().setPlaceholderText(placeholder)
        self.view().viewport().installEventFilter(self)
        self.setInsertPolicy(QComboBox.NoInsert)
        self._update_summary()

    def addCheckItem(self, text: str, data=None, checked: bool = False) -> None:  # noqa: N802
        item = QStandardItem(text)
        item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsUserCheckable)
        item.setData(data, Qt.UserRole)
        item.setCheckState(Qt.Checked if checked else Qt.Unchecked)
        self.model().appendRow(item)
        self._update_summary()

    def setCheckItems(self, items: list[tuple[str, object]], checked_data=()) -> None:  # noqa: N802
        wanted = set(checked_data)
        self.blockSignals(True)
        self.clear()
        for text, data in items:
            self.addCheckItem(text, data, data in wanted)
        self.blockSignals(False)
        self._update_summary()

    def checkedData(self) -> list[object]:  # noqa: N802
        values: list[object] = []
        for row in range(self.model().rowCount()):
            item = self.model().item(row)
            if item and item.checkState() == Qt.Checked:
                values.append(item.data(Qt.UserRole))
        return values

    def setCheckedData(self, values, emit: bool = True) -> None:  # noqa: N802
        wanted = set(values)
        changed = False
        for row in range(self.model().rowCount()):
            item = self.model().item(row)
            if not item:
                continue
            state = Qt.Checked if item.data(Qt.UserRole) in wanted else Qt.Unchecked
            if item.checkState() != state:
                item.setCheckState(state)
                changed = True
        self._update_summary()
        if changed and emit:
            self.checkedItemsChanged.emit()

    def _update_summary(self) -> None:
        labels = []
        for row in range(self.model().rowCount()):
            item = self.model().item(row)
            if item and item.checkState() == Qt.Checked:
                labels.append(item.text())
        if not labels:
            summary = self._placeholder
        elif len(labels) <= 2:
            summary = " · ".join(labels)
        else:
            summary = tr('{value1} 외 {value2}개 {value3}', value1=labels[0], value2=len(labels) - 1, value3=self._summary_noun)
        self.lineEdit().setText(summary)

    def eventFilter(self, watched, event) -> bool:
        if watched is self.view().viewport() and event.type() == QEvent.MouseButtonRelease:
            index = self.view().indexAt(event.position().toPoint())
            if index.isValid():
                item = self.model().itemFromIndex(index)
                if item:
                    item.setCheckState(Qt.Unchecked if item.checkState() == Qt.Checked else Qt.Checked)
                    self._update_summary()
                    self.checkedItemsChanged.emit()
                return True
        return super().eventFilter(watched, event)


class WorkflowHeaderFrame(QFrame):
    """Clickable workflow header; the chevron is only a state indicator."""

    clicked = Signal()

    def mousePressEvent(self, event) -> None:
        if event.button() == Qt.LeftButton:
            self.clicked.emit()
            event.accept()
            return
        super().mousePressEvent(event)


class DisclosureHeaderFrame(WorkflowHeaderFrame):
    """A full-width checkable header for nested advanced settings."""

    toggled = Signal(bool)

    def __init__(self, *args, **kwargs) -> None:
        super().__init__(*args, **kwargs)
        self._checked = False
        self.clicked.connect(lambda: self.setChecked(not self._checked))

    def isChecked(self) -> bool:
        return self._checked

    def setChecked(self, checked: bool) -> None:
        checked = bool(checked)
        if checked == self._checked:
            return
        self._checked = checked
        self.setProperty("expanded", checked)
        self.style().unpolish(self)
        self.style().polish(self)
        self.toggled.emit(checked)


class TableHeightResizeHandle(QFrame):
    """A small, persistent vertical resize handle for long data tables."""

    def __init__(
        self,
        table: QTableWidget,
        settings_key: str,
        *,
        min_height: int = 150,
        max_height: int = 760,
        default_height: int = 260,
        parent=None,
    ) -> None:
        super().__init__(parent or table.parentWidget())
        self.table = table
        self.settings_key = settings_key
        self.min_height = min_height
        self.max_height = max_height
        self.default_height = default_height
        self._drag_start_y: float | None = None
        self._drag_start_height: int | None = None
        self._drag_last_global_y: float | None = None
        self._drag_motion_direction = 0
        self._drag_scroll_offset = 0
        self._auto_scroll_area: QScrollArea | None = None
        self._auto_scroll_step_value = 0
        self._auto_scroll_timer = QTimer(self)
        self._auto_scroll_timer.setInterval(24)
        self._auto_scroll_timer.timeout.connect(self._perform_auto_scroll)
        self._settings = QSettings("HAGISILTA", "HAGISILTA")
        self.setObjectName("tableHeightResizeHandle")
        self.setFixedHeight(4)
        self.setCursor(Qt.SizeVerCursor)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        self.setToolTip(
            tr('위아래로 드래그해 표 높이를 조절합니다. 더블클릭하면 현재 헤더와 행 내용에 맞는 높이로 자동 조절합니다.')
        )
        try:
            saved_height = int(float(self._settings.value(settings_key, default_height)))
        except (TypeError, ValueError):
            saved_height = default_height
        self._apply_height(saved_height)

    def _apply_height(self, height: int) -> None:
        height = max(self.min_height, min(self.max_height, int(height)))
        self.table.setMinimumHeight(height)
        self.table.setMaximumHeight(height)
        # Keep the shared table+handle container in lockstep with the table.
        # Changing only the child table lets the page scroll while the handle's
        # parent geometry stays stale, so the handle visibly falls behind the
        # captured mouse cursor during a drag.
        container = self.parentWidget()
        if container is not None and container.objectName() == "resizableTableContainer":
            container_height = height + self.height()
            container.setMinimumHeight(container_height)
            container.setMaximumHeight(container_height)
            container.updateGeometry()

    def _content_fitted_height(self) -> int:
        header = self.table.horizontalHeader()
        header_height = header.height() if not header.isHidden() else 0
        rows_height = sum(
            self.table.rowHeight(row)
            for row in range(self.table.rowCount())
            if not self.table.isRowHidden(row)
        )
        horizontal_bar = self.table.horizontalScrollBar()
        horizontal_bar_height = (
            horizontal_bar.sizeHint().height()
            if horizontal_bar.maximum() > horizontal_bar.minimum()
            else 0
        )
        frame_height = self.table.frameWidth() * 2
        return header_height + rows_height + horizontal_bar_height + frame_height + 2

    def _find_page_scroll_area(self) -> QScrollArea | None:
        parent = self.parentWidget()
        while parent is not None:
            if isinstance(parent, QScrollArea):
                return parent
            parent = parent.parentWidget()
        return None

    def _apply_drag_height(self) -> None:
        if self._drag_start_y is None or self._drag_start_height is None or self._drag_last_global_y is None:
            return
        pointer_delta = self._drag_last_global_y - self._drag_start_y
        self._apply_height(self._drag_start_height + int(pointer_delta) + self._drag_scroll_offset)

    def _update_auto_scroll(self, global_position) -> None:
        scroll = self._auto_scroll_area
        if scroll is None:
            self._auto_scroll_step_value = 0
            self._auto_scroll_timer.stop()
            return
        viewport = scroll.viewport()
        local_y = viewport.mapFromGlobal(global_position.toPoint()).y()
        edge = 56
        if local_y < edge and self._drag_motion_direction < 0:
            distance = edge - local_y
            self._auto_scroll_step_value = -max(4, min(28, distance // 2))
        elif local_y > viewport.height() - edge and self._drag_motion_direction > 0:
            distance = local_y - (viewport.height() - edge)
            self._auto_scroll_step_value = max(4, min(28, distance // 2))
        else:
            self._auto_scroll_step_value = 0
        if self._auto_scroll_step_value:
            if not self._auto_scroll_timer.isActive():
                self._auto_scroll_timer.start()
        else:
            self._auto_scroll_timer.stop()

    def _perform_auto_scroll(self) -> None:
        if self._drag_start_y is None or self._auto_scroll_area is None or not self._auto_scroll_step_value:
            self._auto_scroll_timer.stop()
            return
        if (
            self._auto_scroll_step_value > 0 and self.table.minimumHeight() >= self.max_height
        ) or (
            self._auto_scroll_step_value < 0 and self.table.minimumHeight() <= self.min_height
        ):
            self._auto_scroll_timer.stop()
            return
        bar = self._auto_scroll_area.verticalScrollBar()
        requested = self._auto_scroll_step_value
        if requested > 0:
            requested = min(requested, self.max_height - self.table.minimumHeight())
        else:
            requested = max(requested, self.min_height - self.table.minimumHeight())
        if not requested:
            self._auto_scroll_timer.stop()
            return

        # Grow/shrink first so the handle moves with the captured cursor, then
        # scroll the page by exactly the same distance. This avoids a frame in
        # which only the scroll bar moves and the handle jumps away.
        self._drag_scroll_offset += requested
        self._apply_drag_height()
        container = self.parentWidget()
        if container is not None and container.layout() is not None:
            container.layout().activate()
        page = self._auto_scroll_area.widget()
        if page is not None:
            if page.layout() is not None:
                page.layout().activate()
            page.adjustSize()
        previous = bar.value()
        bar.setValue(previous + requested)
        moved = bar.value() - previous
        if moved != requested:
            self._drag_scroll_offset -= requested - moved
            self._apply_drag_height()

    def mousePressEvent(self, event) -> None:
        if event.button() == Qt.LeftButton:
            self._drag_start_y = event.globalPosition().y()
            self._drag_start_height = self.table.height()
            self._drag_last_global_y = event.globalPosition().y()
            self._drag_motion_direction = 0
            self._drag_scroll_offset = 0
            self._auto_scroll_area = self._find_page_scroll_area()
            self._auto_scroll_step_value = 0
            self._auto_scroll_timer.stop()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event) -> None:
        if (
            self._drag_start_y is not None
            and self._drag_start_height is not None
            and event.buttons() & Qt.LeftButton
        ):
            current_y = event.globalPosition().y()
            previous_y = self._drag_last_global_y
            if previous_y is not None:
                movement = current_y - previous_y
                if movement > 0:
                    self._drag_motion_direction = 1
                elif movement < 0:
                    self._drag_motion_direction = -1
            self._drag_last_global_y = current_y
            self._apply_drag_height()
            self._update_auto_scroll(event.globalPosition())
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event) -> None:
        if event.button() == Qt.LeftButton and self._drag_start_y is not None:
            self._auto_scroll_timer.stop()
            self._settings.setValue(self.settings_key, self.table.height())
            self._drag_start_y = None
            self._drag_start_height = None
            self._drag_last_global_y = None
            self._drag_motion_direction = 0
            self._drag_scroll_offset = 0
            self._auto_scroll_area = None
            self._auto_scroll_step_value = 0
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self, event) -> None:
        if event.button() == Qt.LeftButton:
            fitted_height = self._content_fitted_height()
            self._apply_height(fitted_height)
            self._settings.setValue(self.settings_key, self.table.height())
            event.accept()
            return
        super().mouseDoubleClickEvent(event)


def wrap_resizable_table(
    table: QTableWidget,
    settings_key: str,
    *,
    min_height: int = 150,
    max_height: int = 760,
    default_height: int = 260,
) -> QWidget:
    """Place a table and its resize handle flush inside one shared container."""
    container = QWidget()
    container.setObjectName("resizableTableContainer")
    container_layout = QVBoxLayout(container)
    container_layout.setContentsMargins(0, 0, 0, 0)
    container_layout.setSpacing(0)
    container_layout.addWidget(table)
    container_layout.addWidget(
        TableHeightResizeHandle(
            table,
            settings_key,
            min_height=min_height,
            max_height=max_height,
            default_height=default_height,
            parent=container,
        )
    )
    return container


def add_resizable_table(
    layout,
    table: QTableWidget,
    settings_key: str,
    *,
    min_height: int = 150,
    max_height: int = 760,
    default_height: int = 260,
    stretch: int = 0,
) -> QWidget:
    container = wrap_resizable_table(
        table,
        settings_key,
        min_height=min_height,
        max_height=max_height,
        default_height=default_height,
    )
    layout.addWidget(container, stretch)
    return container


class TableComboDelegate(QStyledItemDelegate):
    """Edit a table value without placing a persistent widget over cell borders.

    Use this for choices that should look like plain cells until editing begins.
    If the dropdown must remain visible, use a NoWheelComboBox with the
    ``tableCellCombo`` object name so it stays flush inside the cell grid.
    """

    def __init__(
        self,
        values: list[str],
        parent: QObject | None = None,
        *,
        editable: bool = False,
    ) -> None:
        super().__init__(parent)
        self.values = list(values)
        self.editable = editable

    def createEditor(self, parent, _option, _index):
        editor = NoWheelComboBox(parent)
        editor.setObjectName("tableCellComboEditor")
        editor.setEditable(self.editable)
        if self.editable:
            editor.setInsertPolicy(QComboBox.NoInsert)
        editor.addItems(self.values)
        return editor

    def setEditorData(self, editor, index) -> None:
        if isinstance(editor, QComboBox):
            value = str(index.data(Qt.EditRole) or index.data(Qt.DisplayRole) or "")
            if value and editor.findText(value) < 0:
                editor.addItem(value)
            editor.setCurrentText(value or (self.values[0] if self.values else ""))

    def setModelData(self, editor, model, index) -> None:
        if isinstance(editor, QComboBox):
            model.setData(index, editor.currentText(), Qt.EditRole)


class SortableTableItem(QTableWidgetItem):
    """Display friendly text while sorting by an optional hidden value."""

    def __lt__(self, other: QTableWidgetItem) -> bool:
        left = self.data(Qt.UserRole)
        right = other.data(Qt.UserRole)
        if left is not None and right is not None:
            try:
                return left < right
            except TypeError:
                return str(left) < str(right)
        # Calling the wrapped C++ QTableWidgetItem.__lt__ from this Python
        # override is unstable in PySide6 and can abort sorting for ordinary
        # text columns. Compare the visible strings directly instead.
        return self.text().casefold() < other.text().casefold()


class RoiOverviewDialog(QDialog):
    """Thumbnail contact sheet for checking applied ROI/spatial templates."""

    edit_requested = Signal(dict)
    apply_group_requested = Signal(dict, list)

    def __init__(
        self, records: list[dict], title: str = "전체 영상 ROI 검수",
        guide: str = "모든 영상의 ROI를 한 화면에서 확인합니다.", parent: QWidget | None = None,
        records_provider=None, group_apply: bool = False,
        group_apply_label: str = "체크 영상에 기준 설정 적용",
        group_apply_tooltip: str = "",
        preview_provider=None, record_unit: str = "영상", group_apply_handler=None,
    ) -> None:
        super().__init__(parent)
        title, guide = tr(title), tr(guide)
        group_apply_label, group_apply_tooltip = tr(group_apply_label), tr(group_apply_tooltip)
        self.record_unit_key = record_unit
        record_unit = tr(record_unit)
        self.records = records
        self.records_provider = records_provider
        self.group_apply = group_apply
        self.preview_provider = preview_provider
        self.record_unit = record_unit
        self.group_apply_handler = group_apply_handler
        self.reference_key = ""
        self.checked_keys: set[str] = set()
        self.target_checks = {}
        self.preview_cache = {}
        self._record_signature = self.records_signature(records)
        self.setWindowTitle(f"HAGISILTA · {title}")
        apply_hagisilta_window_identity(self)
        self.setStyleSheet(self.styleSheet() + hagisilta_control_stylesheet())
        self.setWindowFlag(Qt.WindowSystemMenuHint, True)
        self.setWindowFlag(Qt.WindowMinMaxButtonsHint, True)
        self.resize(1420, 900)
        self.setMinimumSize(980, 650)
        root = QVBoxLayout(self)
        root.setContentsMargins(12, 10, 12, 12)
        root.setSpacing(8)
        dialog_header, dialog_header_layout = create_hagisilta_header(
            title, "HAGISILTA · ROI REVIEW"
        )
        dialog_header_layout.addWidget(create_hagisilta_help_button(
            self, tr('{value1} 도움말', value1=title), guide
        ))
        self.count_label = HeaderContext(dialog_header)
        root.addWidget(dialog_header)
        toolbar_frame = QFrame(objectName="stageActionBar")
        toolbar_frame_layout = QHBoxLayout(toolbar_frame)
        toolbar_frame_layout.setContentsMargins(8, 5, 8, 5)
        toolbar_frame_layout.setSpacing(8)
        toolbar = QHBoxLayout()
        if self.group_apply:
            toolbar.addWidget(QLabel(tr('ROI 일괄 적용'), objectName="sectionLabel"))
            self.reference_label = QLabel(tr('적용 기준: 선택 안 됨'), objectName="pageText")
            toolbar.addWidget(self.reference_label)
            self.overwrite_existing = QCheckBox(tr('기존 ROI도 덮어쓰기'))
            self.overwrite_existing.setChecked(False)
            self.overwrite_existing.setToolTip(
                tr('끄면 ROI가 없는 체크 영상에만 기준 설정을 적용합니다. 켜면 이미 개별 ROI가 있는 영상도 기준 ROI로 바뀌며, 적용 전에 한 번 더 확인합니다.')
            )
            toolbar.addWidget(self.overwrite_existing)
        toolbar.addStretch()
        if self.records_provider:
            refresh_button = QPushButton(tr('새로고침'), objectName="toolButton")
            refresh_button.clicked.connect(self.refresh_records)
            toolbar.addWidget(refresh_button)
        toolbar_frame_layout.addLayout(toolbar)
        root.addWidget(toolbar_frame)
        if self.group_apply:
            selection_row = QHBoxLayout()
            self.roi_search = QLineEdit()
            self.roi_search.setPlaceholderText(tr('영상 이름 검색'))
            self.roi_search.textChanged.connect(self.filter_cards)
            selection_row.addWidget(self.roi_search, 1)
            for label, mode in ((tr('모두 선택'), "all"), (tr('검색 결과 선택'), "visible"),
                                (tr('ROI 없는 영상 선택'), "missing"), (tr('모두 해제'), "none")):
                button = QPushButton(label, objectName="toolButton")
                if mode == "missing":
                    self.select_missing_button = button
                button.clicked.connect(lambda _checked=False, value=mode: self.select_targets(value))
                selection_row.addWidget(button)
            root.addLayout(selection_row)
        scroll = QScrollArea(); scroll.setWidgetResizable(True)
        scroll.setObjectName("roiReviewScroll")
        scroll.setFrameShape(QFrame.NoFrame)
        body = QWidget(); self.grid = QGridLayout(body)
        self.grid.setContentsMargins(12, 12, 12, 12); self.grid.setSpacing(14)
        scroll.setWidget(body); root.addWidget(scroll, 1)
        footer = QFrame(objectName="detachedFooter")
        footer_layout = QHBoxLayout(footer)
        footer_layout.setContentsMargins(18, 9, 18, 9)
        self.selection_summary = QLabel(objectName="pageText")
        footer_layout.addWidget(self.selection_summary)
        footer_layout.addStretch()
        if self.group_apply:
            self.apply_group_button = QPushButton(group_apply_label, objectName="primaryButton")
            self.apply_group_button.setEnabled(False)
            self.apply_group_button.setToolTip(
                group_apply_tooltip or
                tr('‘이 설정을 기준으로’를 누른 카드의 설정을 ‘적용 대상’으로 체크한 영상들에 복사합니다. 체크하지 않은 영상과 기존 다른 그룹은 변경하지 않습니다.')
            )
            self.apply_group_button.clicked.connect(self.emit_group_apply)
            footer_layout.addWidget(self.apply_group_button)
        close_button = QPushButton(tr('닫기'), objectName="secondaryButton")
        close_button.clicked.connect(self.accept)
        footer_layout.addWidget(close_button)
        root.addWidget(footer)
        self.populate()
        if self.records_provider:
            self.refresh_timer = QTimer(self)
            self.refresh_timer.setInterval(1000)
            self.refresh_timer.timeout.connect(self.refresh_if_changed)
            self.refresh_timer.start()

    @staticmethod
    def record_key(record: dict) -> str:
        return str(record.get("review_key") or record.get("bundle") or record.get("video") or "")

    @staticmethod
    def record_label(record: dict) -> str:
        return str(record.get("display_name") or Path(str(record.get("video", ""))).name)

    @staticmethod
    def records_signature(records: list[dict]) -> tuple:
        signature = []
        for record in records:
            paths = [str(record.get("profile") or "")]
            paths.extend(str(item.get("setup") or "") for item in record.get("spatial_overlays", []))
            file_state = []
            for text in paths:
                path = Path(text) if text else Path()
                try:
                    stat = path.stat() if path.is_file() else None
                    file_state.append((text, stat.st_mtime_ns if stat else 0, stat.st_size if stat else 0))
                except OSError:
                    file_state.append((text, 0, 0))
            signature.append((RoiOverviewDialog.record_key(record), tuple(file_state), str(record.get("status", ""))))
        return tuple(signature)

    def refresh_if_changed(self) -> None:
        if not self.records_provider:
            return
        records = self.records_provider()
        signature = self.records_signature(records)
        if signature != self._record_signature:
            self.records = records
            self._record_signature = signature
            self.populate()

    def refresh_records(self) -> None:
        self.preview_cache.clear()
        if self.records_provider:
            self.records = self.records_provider()
            self._record_signature = self.records_signature(self.records)
        self.populate()

    def set_reference_record(self, record: dict) -> None:
        if record.get("reference_ready") is False:
            return
        self.reference_key = self.record_key(record)
        self.checked_keys.discard(self.reference_key)
        self.populate()

    def set_record_checked(self, record: dict, checked: bool) -> None:
        key = self.record_key(record)
        if checked:
            self.checked_keys.add(key)
        else:
            self.checked_keys.discard(key)
        self.update_target_summary()

    def update_target_summary(self):
        if not self.group_apply:
            self.selection_summary.setText("")
            return
        self.selection_summary.setText(tr('적용 대상 {value1} / {value2}개', value1=len(self.checked_keys), value2=max(0, len(self.records) - bool(self.reference_key))))
        if hasattr(self, "apply_group_button"):
            self.apply_group_button.setEnabled(bool(self.reference_key and self.checked_keys))

    def select_targets(self, mode):
        for record in self.records:
            key = self.record_key(record)
            checkbox = self.target_checks.get(key)
            if checkbox is None or key == self.reference_key:
                continue
            if mode == "none":
                checkbox.setChecked(False)
            elif mode == "all" or (mode == "visible" and self.matches_search(record)) or (
                mode == "missing" and not Path(str(record.get("profile", ""))).is_file()
            ):
                checkbox.setChecked(True)

    def matches_search(self, record):
        query = self.roi_search.text().strip().casefold() if hasattr(self, "roi_search") else ""
        name = str(record.get("display_name") or Path(record["video"]).stem)
        return query in name.casefold()

    def filter_cards(self, *_args):
        # Searching/reloading must move the spacer too, not leave old stretched
        # rows between the remaining cards or expand a single card to the window.
        for column in range(3):
            self.grid.setColumnStretch(column, 1)
        for row in range(self.grid.rowCount()):
            self.grid.setRowStretch(row, 0)
        visible = 0
        for record, card in getattr(self, "roi_cards", []):
            show = self.matches_search(record)
            card.setVisible(show)
            self.grid.removeWidget(card)
            if show:
                self.grid.addWidget(card, visible // 3, visible % 3)
                visible += 1
        self.grid.setRowStretch((visible + 2) // 3, 1)
        self.update_target_summary()

    def emit_group_apply(self) -> None:
        source = next((record for record in self.records if self.record_key(record) == self.reference_key), None)
        targets = [
            record for record in self.records
            if self.record_key(record) in self.checked_keys and self.record_key(record) != self.reference_key
        ]
        overwrite = bool(getattr(self, "overwrite_existing", None) and self.overwrite_existing.isChecked())
        if self.group_apply_handler is not None:
            if source and targets and self.group_apply_handler(source, targets, overwrite):
                self.checked_keys.clear()
                self.refresh_records()
            return
        existing = [record for record in targets if Path(str(record.get("profile", ""))).is_file()]
        if not overwrite:
            targets = [record for record in targets if record not in existing]
        elif existing:
            answer = QMessageBox.question(
                self,
                tr('기존 ROI 덮어쓰기'),
                tr('체크 영상 중 {value1}개에는 이미 ROI가 있습니다.\n기준 ROI로 덮어쓰시겠습니까?', value1=len(existing)),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return
        if source and not targets:
            QMessageBox.information(
                self,
                tr('적용 대상 없음'),
                tr('ROI가 없는 체크 영상이 없습니다. 기존 ROI도 바꾸려면 ‘기존 ROI도 덮어쓰기’를 켜세요.'),
            )
            return
        if source and targets:
            self.apply_group_requested.emit(source, targets)
            self.checked_keys.clear()
            if self.records_provider:
                self.records = self.records_provider()
                self._record_signature = self.records_signature(self.records)
            self.populate()

    @staticmethod
    def read_preview_frame(video: Path, seconds: float) -> np.ndarray | None:
        """Read a representative frame, including profiles saved at video EOF."""
        capture = cv2.VideoCapture(str(video))
        if not capture.isOpened():
            capture.release()
            return None
        frame_count = max(0, int(capture.get(cv2.CAP_PROP_FRAME_COUNT) or 0))
        fps = float(capture.get(cv2.CAP_PROP_FPS) or 0.0)
        candidates: list[int] = []
        if frame_count > 0:
            if seconds > 0 and fps > 0:
                # A setup slider may be saved at exactly the displayed duration.
                # That timestamp is one frame beyond EOF for many codecs.
                candidates.append(min(max(0, int(round(seconds * fps))), frame_count - 1))
            candidates.extend([frame_count // 2, 0])
        else:
            candidates.append(0)
        seen: set[int] = set()
        for frame_index in candidates:
            if frame_index in seen:
                continue
            seen.add(frame_index)
            capture.set(cv2.CAP_PROP_POS_FRAMES, frame_index)
            ok, frame = capture.read()
            if ok and frame is not None:
                capture.release()
                return frame
        capture.release()
        return None

    @staticmethod
    def preview_pixmap(record: dict) -> QPixmap:
        video = Path(record["video"])
        profile = Path(record["profile"])
        payload = {}
        try:
            payload = json.loads(profile.read_text(encoding="utf-8")) if profile.is_file() else {}
        except Exception:
            payload = {}
        seconds = float(payload.get("setup_frame_seconds", 0.0) or 0.0)
        frame = RoiOverviewDialog.read_preview_frame(video, seconds)
        if frame is None:
            frame = np.zeros((360, 640, 3), dtype=np.uint8)
            draw_image_text(frame, "VIDEO READ ERROR", (28, 190), cv2.FONT_HERSHEY_SIMPLEX, 0.8, (80, 100, 255), 2)
        colors = {"arm_a": (92, 202, 255), "arm_b": (138, 107, 255), "arm_c": (255, 168, 102), "center": (255, 140, 186)}
        for arena in payload.get("arenas", []):
            mask = arena.get("mask_polygon_source_px") or arena.get("corners_source_px") or []
            if len(mask) >= 3:
                contour = np.rint(np.asarray(mask)).astype(np.int32)
                cv2.polylines(frame, [contour], True, (169, 214, 85), 3, cv2.LINE_AA)
                moments = cv2.moments(contour)
                if abs(moments["m00"]) > 1e-6:
                    x, y = int(moments["m10"] / moments["m00"]), int(moments["m01"] / moments["m00"])
                    arena_text = f"Arena {int(arena.get('id', 0)):02d}"
                    draw_image_text(frame, arena_text, (x - 38, y), cv2.FONT_HERSHEY_SIMPLEX, 0.48, (8, 16, 24), 3, cv2.LINE_AA)
                    draw_image_text(frame, arena_text, (x - 38, y), cv2.FONT_HERSHEY_SIMPLEX, 0.48, (230, 255, 245), 1, cv2.LINE_AA)
            outline = arena.get("maze_outline_polygon_source_px") or []
            if len(outline) >= 3:
                cv2.polylines(frame, [np.rint(np.asarray(outline)).astype(np.int32)], True, (100, 158, 255), 3, cv2.LINE_AA)
            for zone in arena.get("zones", []):
                points = zone.get("polygon_source_px") or []
                zone_id = str(zone.get("id", ""))
                if len(points) < 3 or zone_id not in colors:
                    continue
                contour = np.rint(np.asarray(points)).astype(np.int32)
                overlay = frame.copy(); cv2.fillPoly(overlay, [contour], colors[zone_id]); frame = cv2.addWeighted(overlay, 0.20, frame, 0.80, 0)
                cv2.polylines(frame, [contour], True, colors[zone_id], 2, cv2.LINE_AA)
                moments = cv2.moments(contour)
                if abs(moments["m00"]) > 1e-6:
                    x, y = int(moments["m10"] / moments["m00"]), int(moments["m01"] / moments["m00"])
                    text = {"arm_a": "A", "arm_b": "B", "arm_c": "C", "center": "CENTER"}[zone_id]
                    draw_image_text(frame, text, (x - 12, y + 6), cv2.FONT_HERSHEY_SIMPLEX, 0.62, (10, 18, 28), 4, cv2.LINE_AA)
                    draw_image_text(frame, text, (x - 12, y + 6), cv2.FONT_HERSHEY_SIMPLEX, 0.62, (255, 255, 255), 2, cv2.LINE_AA)
        for spatial in record.get("spatial_overlays", []):
            try:
                setup = json.loads(Path(spatial["setup"]).read_text(encoding="utf-8"))
            except Exception:
                continue
            offset = np.asarray(spatial.get("offset", [0, 0]), dtype=np.float32)
            arena = (setup.get("arenas") or [{}])[0]
            for object_name, color in (("A", (92, 202, 255)), ("B", (138, 107, 255))):
                points = ((arena.get("objects") or {}).get(object_name) or {}).get("polygon_source_px") or []
                if len(points) < 3:
                    continue
                contour = np.rint(np.asarray(points, dtype=np.float32) + offset).astype(np.int32)
                cv2.polylines(frame, [contour], True, color, 3, cv2.LINE_AA)
                x, y = np.rint(np.asarray(points, dtype=np.float32).mean(axis=0) + offset).astype(int)
                draw_image_text(frame, f"Object {object_name}", (int(x) - 32, int(y)), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (8, 16, 24), 3, cv2.LINE_AA)
                draw_image_text(frame, f"Object {object_name}", (int(x) - 32, int(y)), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (255, 255, 255), 1, cv2.LINE_AA)
        height, width = frame.shape[:2]
        image = QImage(frame.data, width, height, frame.strides[0], QImage.Format_BGR888).copy()
        return QPixmap.fromImage(image).scaled(390, 235, Qt.KeepAspectRatio, Qt.SmoothTransformation)

    def populate(self) -> None:
        self.target_checks = {}
        self.roi_cards = []
        valid_keys = {self.record_key(record) for record in self.records}
        self.checked_keys.intersection_update(valid_keys)
        if (self.reference_key not in valid_keys or any(
                self.record_key(record) == self.reference_key and record.get("reference_ready") is False
                for record in self.records)):
            self.reference_key = ""
        while self.grid.count():
            item = self.grid.takeAt(0)
            if item.widget(): item.widget().deleteLater()
        if self.record_unit_key == "영상":
            count_text = tr('{count}개 영상', count=len(self.records))
        elif self.record_unit_key == "Arena":
            count_text = tr('{count}개 Arena', count=len(self.records))
        else:
            count_text = tr('{value1}개 {value2}', value1=len(self.records), value2=self.record_unit)
        self.count_label.setText(count_text)
        if self.group_apply:
            source = next(
                (record for record in self.records if self.record_key(record) == self.reference_key),
                None,
            )
            self.reference_label.setText(
                tr('적용 기준: {value1}', value1=self.record_label(source)) if source else tr('적용 기준: 선택 안 됨')
            )
            self.apply_group_button.setEnabled(bool(source and self.checked_keys))
        for index, record in enumerate(self.records):
            card = QFrame(objectName="workflowCard")
            card.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.Maximum)
            if self.group_apply and self.record_key(record) == self.reference_key:
                card.setStyleSheet("QFrame#workflowCard { border: 2px solid #53d6a5; }")
            layout = QVBoxLayout(card); layout.setContentsMargins(10, 10, 10, 10)
            cache_key = (self.records_signature([record]), str(record["video"]))
            if cache_key not in self.preview_cache:
                self.preview_cache[cache_key] = (self.preview_provider or self.preview_pixmap)(record)
            button = QPushButton(objectName="roiPreviewButton"); button.setIcon(QIcon(self.preview_cache[cache_key]))
            button.setIconSize(QSize(390, 235)); button.setMinimumHeight(245)
            button.setToolTip(record.get("preview_tooltip") or tr('클릭하면 이 영상의 전체 Arena ROI를 편집합니다.'))
            button.clicked.connect(lambda _checked=False, current=record: self.edit_requested.emit(current))
            layout.addWidget(button)
            name = QLabel(self.record_label(record), objectName="sectionLabel"); name.setWordWrap(True)
            layout.addWidget(name)
            mode = str(record.get("status") or (tr('● 개별 보정 적용') if record.get("override") else tr('공통 템플릿 적용')))
            status = QLabel(mode)
            status.setStyleSheet("color: #72e5b2;" if record.get("override") else "color: #93a8c2;")
            layout.addWidget(status)
            if self.group_apply:
                controls = QHBoxLayout()
                target_check = QCheckBox(tr('적용 대상'))
                key = self.record_key(record)
                self.target_checks[key] = target_check
                target_check.setChecked(key in self.checked_keys)
                target_check.setEnabled(key != self.reference_key)
                target_check.toggled.connect(
                    lambda checked, current=record: self.set_record_checked(current, checked)
                )
                reference_button = QPushButton(
                    tr('현재 기준') if key == self.reference_key else tr('이 설정을 기준으로'),
                    objectName="toolButton",
                )
                reference_button.setEnabled(key != self.reference_key and record.get("reference_ready") is not False)
                reference_button.clicked.connect(
                    lambda _checked=False, current=record: self.set_reference_record(current)
                )
                controls.addWidget(target_check)
                controls.addWidget(reference_button, 1)
                layout.addLayout(controls)
            self.grid.addWidget(card, index // 3, index % 3)
            self.roi_cards.append((record, card))
        self.filter_cards()


class ResponsivePreviewLabel(QLabel):
    """Notify the owner when the available preview canvas changes size."""

    resized = Signal()

    def resizeEvent(self, event) -> None:
        super().resizeEvent(event)
        self.resized.emit()


class ClickSeekSlider(QSlider):
    """Seek directly to the position clicked on the timeline groove."""

    def mousePressEvent(self, event) -> None:
        if event.button() == Qt.LeftButton and self.width() > 0:
            ratio = max(0.0, min(1.0, event.position().x() / self.width()))
            self.setValue(self.minimum() + round((self.maximum() - self.minimum()) * ratio))
        super().mousePressEvent(event)


class BehaviorDecisionViewer(QDialog):
    """Play an Arena video with the already calculated behavioral decisions."""

    def __init__(
        self, video: Path, frames_file: Path, mode: str,
        events_file: Path | None = None, parent: QWidget | None = None,
        roi_zones: list[dict] | None = None,
        summary: dict | None = None, playlist: list[dict] | None = None,
    ) -> None:
        super().__init__(parent)
        self.video = video
        self.mode = mode
        self.frames = pd.read_csv(frames_file)
        self.events = pd.read_csv(events_file) if events_file and events_file.is_file() else pd.DataFrame()
        self.capture = cv2.VideoCapture(str(video))
        if not self.capture.isOpened() or self.frames.empty:
            raise ValueError(tr('판정 영상 또는 프레임 결과를 열 수 없습니다.'))
        self.fps = float(self.capture.get(cv2.CAP_PROP_FPS) or 0.0)
        if self.fps <= 0:
            times = pd.to_numeric(self.frames.get("time_seconds"), errors="coerce")
            self.fps = float(1.0 / times.diff().median()) if len(times) > 1 else 1.0
        video_frames = int(self.capture.get(cv2.CAP_PROP_FRAME_COUNT) or len(self.frames))
        self.frame_count = min(video_frames, len(self.frames))
        self.playing = False
        self.playback_speeds = list(PLAYBACK_SPEEDS)
        self.playback_speed = 1.0
        self.capture_position = -1
        self.current_image: QImage | None = None
        self.roi_zones = list(roi_zones or [])
        self.summary = dict(summary or {})
        self.nort_role_a = str(self.summary.get("object_a_role") or "Object A")
        self.nort_role_b = str(self.summary.get("object_b_role") or "Object B")
        self.show_roi = bool(self.roi_zones)
        self.roi_opacity = 0.42
        self.show_center = True
        self.show_roi_labels = True
        self.show_pose_points = True
        self.show_pose_labels = True
        self.show_banner = True
        self.show_live_trail = True
        self.show_final_trail = False
        self.show_live_heatmap = False
        self.show_final_heatmap = False
        self.overlay_opacity = 0.52
        self.final_heatmap: np.ndarray | None = None
        self._refresh_tracking_arrays()
        raw_playlist = playlist or [{
            "video": str(video), "frames": str(frames_file),
            "events": str(events_file or ""), "roi_zones": self.roi_zones,
            "summary": self.summary,
        }]
        self.playlist = [dict(entry) for entry in raw_playlist]
        current_frames = str(Path(frames_file))
        self.current_playlist_index = next((
            index for index, entry in enumerate(self.playlist)
            if str(Path(str(entry.get("frames", "")))) == current_frames
        ), 0)
        self.setWindowTitle(
            f"HAGISILTA · {tr('NORT 탐색 판정') if mode == 'nort' else tr('Y-maze 진입 판정')} · {video.name}"
        )
        apply_hagisilta_window_identity(self)
        enable_full_window_controls(self)
        self.setStyleSheet(self.styleSheet() + hagisilta_control_stylesheet())
        self.resize(1240, 820); self.setMinimumSize(1120, 650)

        if mode == "nort":
            explore_a = self.frames.get("exploring_A", pd.Series(False, index=self.frames.index)).astype(str).str.lower().eq("true")
            explore_b = self.frames.get("exploring_B", pd.Series(False, index=self.frames.index)).astype(str).str.lower().eq("true")
            self.cumulative_a = explore_a.cumsum().to_numpy(dtype=float) / self.fps
            self.cumulative_b = explore_b.cumsum().to_numpy(dtype=float) / self.fps
        else:
            self.cumulative_a = self.cumulative_b = np.zeros(len(self.frames), dtype=float)

        root = QVBoxLayout(self)
        root.setContentsMargins(0, 0, 0, 0)
        root.setSpacing(0)
        header, header_layout = create_hagisilta_header(
            tr('NORT 탐색 판정 검수') if mode == "nort" else tr('Y-maze 진입 판정 검수'),
            "HAGISILTA · BEHAVIOR REVIEW",
        )
        help_text = (
            tr('계산이 끝난 프레임 판정을 원본 Arena 영상과 함께 재생합니다. 실시간 재계산 미리보기가 아니라 저장된 최종 CSV 결과를 확인하는 창입니다.\n\n재생/정지 (Space) · 1프레임 이동 (A/D) · 1초 이동 (Q/E)\n') + tr(PLAYBACK_HELP)
        )
        header_layout.addWidget(create_hagisilta_help_button(
            self, tr('행동 판정 검수 도움말'), help_text,
        ))
        self.header_status = HeaderContext(
            header,
            f"{self.current_playlist_index + 1}/{len(self.playlist)} · 1/{self.frame_count}F",
        )
        root.addWidget(header)

        body = QFrame(objectName="detachedBody")
        body_layout = QHBoxLayout(body)
        body_layout.setContentsMargins(14, 12, 14, 12)
        body_layout.setSpacing(12)

        playlist_panel = QFrame(objectName="detachedSidebar")
        playlist_panel.setMinimumWidth(220); playlist_panel.setMaximumWidth(480)
        playlist_layout = QVBoxLayout(playlist_panel)
        playlist_layout.setContentsMargins(10, 9, 10, 10); playlist_layout.setSpacing(7)
        playlist_layout.addWidget(QLabel(
            tr('판정 영상·Arena'),
            objectName="settingsGroupTitle",
        ))
        playlist_description = QLabel(tr('항목을 클릭하면 이 창에서 바로 전환합니다.'), objectName="settingsGroupDescription")
        playlist_description.setWordWrap(True); playlist_layout.addWidget(playlist_description)
        self.playlist_widget = QListWidget(objectName="decisionPlaylist")
        self.playlist_widget.setSelectionMode(QAbstractItemView.SingleSelection)
        self.playlist_widget.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.playlist_widget.setSpacing(4)
        for entry in self.playlist:
            payload = dict(entry.get("summary") or {})
            bundle = str(payload.get("video_bundle") or Path(str(entry.get("video", ""))).stem)
            arena_value = payload.get("arena", payload.get("arena_id", 1))
            try: arena = int(float(arena_value))
            except (TypeError, ValueError): arena = 1
            detail = f"Arena {arena:02d}"
            if mode == "nort":
                subject = str(payload.get("subject_id") or tr('개체 미지정'))
                di = pd.to_numeric(pd.Series([payload.get("discrimination_index")]), errors="coerce").iloc[0]
                detail += f" · {subject}" + (f" · DI {float(di):.3f}" if not pd.isna(di) else "")
            else:
                percent = pd.to_numeric(pd.Series([payload.get("alternation_percent")]), errors="coerce").iloc[0]
                if not pd.isna(percent): detail += tr(' · 자발적 교대 {value1:.1f}%', value1=float(percent))
            item = QListWidgetItem(f"{bundle}\n{detail}")
            item.setSizeHint(QSize(0, 54)); item.setToolTip(str(entry.get("video", "")))
            self.playlist_widget.addItem(item)
        self.playlist_widget.setCurrentRow(self.current_playlist_index)
        self.playlist_widget.currentRowChanged.connect(self.select_playlist_entry)
        playlist_layout.addWidget(self.playlist_widget, 1)

        workspace = QFrame(objectName="reviewWorkspace")
        workspace.setMinimumWidth(520); workspace.setSizePolicy(QSizePolicy.Ignored, QSizePolicy.Expanding)
        workspace_layout = QVBoxLayout(workspace)
