        sidebar_layout.setContentsMargins(10, 10, 10, 10); sidebar_layout.setSpacing(10)

        base_options = QFrame(objectName="settingsGroup"); base_layout = QVBoxLayout(base_options)
        base_layout.setContentsMargins(10, 9, 10, 10); base_layout.setSpacing(7)
