        def navigation_button(key: str) -> QPushButton:
            index, title = module_lookup[key]
            button = QPushButton(title, objectName="navButton")
            button.setCheckable(True)
            button.setIcon(self.navigation_icon(self.sidebar_icons[key]))
            button.setIconSize(QSize(19, 19))
            button.setToolTip(title)
            button.setProperty("navTitle", title)
            button.setProperty("navModuleKey", key)
            button.setProperty("railMode", False)
            button.clicked.connect(lambda _checked=False, value=index: self.show_module(value))
            # Keep a mouse-event fallback on the window itself.  A detached
            # workbench can occasionally leave one sidebar button's Qt signal
            # blocked after returning to the main window.  The release event is
            # still delivered, so the fallback below restores the requested
            # page without making a normal click refresh twice.
            button.installEventFilter(self)
            self.nav_buttons.append(button)
            self.nav_by_key[key] = button
            return button

        for group_index, (group_title, module_keys) in enumerate(self.sidebar_groups):
            if group_index:
                separator = QFrame(objectName="navGroupSeparator")
                separator.setFixedHeight(1)
                separator.setVisible(False)
                self.sidebar_group_separators.append(separator)
                self.sidebar_nav_layout.addWidget(separator)
