            section_label = QLabel(group_title.upper(), objectName="sectionTitle")
            self.sidebar_section_labels.append(section_label)
            self.sidebar_nav_layout.addWidget(section_label)
            for key in module_keys:
                self.sidebar_nav_layout.addWidget(navigation_button(key))
