        self.log_toggle_button.setText(tr('로그 접기') if log_visible else tr('로그 펼치기'))
        def restore_initial_log_layout() -> None:
            # Choose a compact first-run log width after the real window size is
            # known. Saved widths and subsequent user resizing remain untouched.
            if "log_panel_width" not in layout_settings:
                self.log_panel_last_width = max(260, min(360, self.width() - 1170))
            width = self.log_panel_last_width if self.log_panel_expanded else 46
            available = self.content_splitter.width() - self.content_splitter.handleWidth()
            self.content_splitter.setSizes([max(1, available - width), width])

        QTimer.singleShot(0, restore_initial_log_layout)
        body.addWidget(self.content_splitter, 1)

        self.pages["overview"] = self.build_overview()
        self.pages["quick"] = self.build_quick()
        self.pages["dataset"] = self.build_dataset()
        self.pages["train"] = self.build_train()
        self.pages["evaluate"] = self.build_evaluate()
        self.pages["track"] = self.build_track()
        self.pages["review"] = self.build_video_review()
        self.pages["spatial"] = self.build_spatial()
        self.pages["ymaze"] = self.build_ymaze_pilot()
        self.pages["watermaze"] = WaterMazePage(self)
        self.pages["zone"] = self.build_zone_analysis()
        for key, _title in self.modules:
            self.stack.addWidget(self.pages[key])
        self.set_sidebar_collapsed(
            bool(layout_settings.get("sidebar_collapsed", False)), persist=False
        )

