    def page_shell(self, title: str, description: str) -> tuple[QWidget, QVBoxLayout]:
        page = QScrollArea()
        page.setWidgetResizable(True)
        page.setFrameShape(QFrame.NoFrame)
        content = QWidget()
        page.setWidget(content)
        layout = QVBoxLayout(content)
        layout.setContentsMargins(4, 4, 4, 4)
        heading = QLabel(title, objectName="pageTitle")
        text = QLabel(description, objectName="pageText")
        text.setWordWrap(True)
        layout.addWidget(heading)
        layout.addWidget(text)
        return page, layout

    def workbench_page_shell(
        self, title: str, description: str, kicker: str, *, model_terms: bool = False
    ) -> tuple[QWidget, QVBoxLayout]:
        """Keep a compact workbench identity visible above a scrolling single page."""
        page = QWidget()
        outer = QVBoxLayout(page)
        outer.setContentsMargins(0, 0, 0, 0)
        outer.setSpacing(0)

        fixed_header = QFrame(objectName="stickyPageHeader")
        header_layout = QHBoxLayout(fixed_header)
        header_layout.setContentsMargins(4, 4, 4, 4)
        header_layout.setSpacing(8)
        accent = QFrame(objectName="pageTitleAccent")
        accent.setFixedSize(3, 24)
        header_layout.addWidget(accent)
        header_layout.addWidget(QLabel(kicker, objectName="pageKicker"))
        heading = QLabel(title, objectName="pageWorkbenchTitle")
        heading.setToolTip(description)
        header_layout.addWidget(heading)
        info = QLabel(objectName="pageInfoIcon")
        info.setPixmap(self.navigation_icon("info").pixmap(16, 16))
        info.setFixedSize(20, 20)
        info.setToolTip(description)
        header_layout.addWidget(info)
        header_layout.addStretch(1)
        if model_terms:
            header_layout.addWidget(self.model_terms_button())
        fixed_header.setToolTip(description)
        outer.addWidget(fixed_header)

        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.NoFrame)
        content = QWidget()
        scroll.setWidget(content)
        layout = QVBoxLayout(content)
        layout.setContentsMargins(4, 6, 4, 4)
        outer.addWidget(scroll, 1)
        page.page_scroll_area = scroll  # type: ignore[attr-defined]
        return page, layout

    def tabbed_page_shell(
        self, title: str, description: str, tabs: QFrame, *, kicker: str = "DATA WORKBENCH",
        model_terms: bool = False,
    ) -> tuple[QWidget, QVBoxLayout]:
        """Keep page identity and sibling-page tabs visible while work content scrolls."""
        page = QWidget()
        outer = QVBoxLayout(page)
        outer.setContentsMargins(0, 0, 0, 0)
        outer.setSpacing(0)
        fixed_header = QFrame(objectName="stickyPageHeader")
        header_layout = QVBoxLayout(fixed_header)
        header_layout.setContentsMargins(4, 2, 4, 0)
        header_layout.setSpacing(2)
        title_row = QHBoxLayout()
        title_row.setContentsMargins(0, 0, 0, 0)
        title_row.setSpacing(8)
        accent = QFrame(objectName="pageTitleAccent")
        accent.setFixedSize(3, 24)
        title_row.addWidget(accent)
        title_row.addWidget(QLabel(kicker, objectName="pageKicker"))
        heading = QLabel(title, objectName="pageWorkbenchTitle")
        heading.setToolTip(description)
        title_row.addWidget(heading)
        info = QLabel(objectName="pageInfoIcon")
        info.setPixmap(self.navigation_icon("info").pixmap(16, 16))
        info.setFixedSize(20, 20)
        info.setToolTip(description)
        title_row.addWidget(info)
        title_row.addStretch(1)
        if model_terms:
            title_row.addWidget(self.model_terms_button())
        header_layout.addLayout(title_row)
        header_layout.addWidget(tabs)
        fixed_header.setToolTip(description)
        outer.addWidget(fixed_header)

        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.NoFrame)
        content = QWidget()
        scroll.setWidget(content)
        layout = QVBoxLayout(content)
        layout.setContentsMargins(4, 6, 4, 4)
        outer.addWidget(scroll, 1)
        page.page_scroll_area = scroll  # type: ignore[attr-defined]
        return page, layout

    def model_terms_button(self) -> QPushButton:
        button = QPushButton(tr('모델 이용 조건'), objectName="toolButton")
        button.setProperty("modelTermsButton", True)
        self.set_action_icon(button, "info", 14)
        button.setToolTip(tr('사전학습 가중치에는 HAGISILTA와 별도의 이용 조건이 적용됩니다. 다운로드하거나 사용하기 전에 확인하세요.'))
        button.clicked.connect(self.open_model_terms)
        return button

    def open_model_terms(self) -> None:
        document_path = REPO_ROOT / ("PRETRAINED_MODELS.ko.md" if get_language() == "ko" else "PRETRAINED_MODELS.md")
        try:
            content = document_path.read_text(encoding="utf-8-sig")
        except OSError as error:
            QMessageBox.warning(self, tr('모델 이용 조건'), tr('이용 조건 문서를 열 수 없습니다: {detail}', detail=error))
            return
        dialog = QDialog(self)
        dialog.setObjectName("modelTermsDialog")
        dialog.setWindowTitle(tr('모델 이용 조건'))
        apply_hagisilta_window_identity(dialog)
        dialog.setStyleSheet(hagisilta_control_stylesheet())
        dialog.resize(850, 660)
        root = QVBoxLayout(dialog)
        root.setContentsMargins(0, 0, 0, 0)
        header, header_layout = create_hagisilta_header(tr('모델 이용 조건'), "MODEL TERMS")
        header_layout.addWidget(create_hagisilta_help_button(
            dialog, tr('모델 이용 조건'),
            tr('사전학습 가중치에는 HAGISILTA와 별도의 이용 조건이 적용됩니다. 다운로드하거나 사용하기 전에 확인하세요.'),
        ))
        root.addWidget(header)
        browser = QTextBrowser(dialog)
        browser.setObjectName("modelTermsDocument")
        browser.setReadOnly(True)
        browser.setOpenExternalLinks(True)
        browser.document().setDocumentMargin(12)
        browser.document().setBaseUrl(QUrl.fromLocalFile(str(document_path)))
        browser.setMarkdown(content)

        def style_document_links() -> None:
            # Qt's Markdown importer sets an explicit blue brush on anchors.
            document = browser.document()
            links = []
            block = document.begin()
            while block.isValid():
                fragments = block.begin()
                while not fragments.atEnd():
                    fragment = fragments.fragment()
                    if fragment.isValid() and fragment.charFormat().isAnchor():
                        links.append((fragment.position(), fragment.length()))
                    fragments += 1
                block = block.next()
            link_format = QTextCharFormat()
            link_format.setForeground(QColor("#9bb7ff"))
            for start, length in links:
                cursor = QTextCursor(document)
                cursor.setPosition(start)
                cursor.setPosition(start + length, QTextCursor.KeepAnchor)
                cursor.mergeCharFormat(link_format)

        style_document_links()
        browser.sourceChanged.connect(lambda _url: style_document_links())
        browser.setProperty("sourceDocument", str(document_path))
        root.addWidget(browser, 1)
        footer = QFrame(objectName="detachedFooter")
        footer_layout = QHBoxLayout(footer)
        footer_layout.addStretch(1)
        close_button = QPushButton(tr('닫기'), objectName="secondaryButton")
        close_button.clicked.connect(dialog.accept)
        footer_layout.addWidget(close_button)
        root.addWidget(footer)
        dialog.exec()

    def set_sidebar_collapsed(self, collapsed: bool, persist: bool = True) -> None:
        self.sidebar_collapsed = bool(collapsed)
        self.sidebar.setFixedWidth(62 if self.sidebar_collapsed else 245)
        margins = (7, 14, 7, 18) if self.sidebar_collapsed else (14, 14, 14, 18)
        self.sidebar_nav_layout.setContentsMargins(*margins)
        self.sidebar_nav_layout.setAlignment(
            self.sidebar_toggle, Qt.AlignCenter if self.sidebar_collapsed else Qt.AlignRight
        )
        self.sidebar_toggle.setIcon(
            self.navigation_icon("expand" if self.sidebar_collapsed else "collapse")
        )
        self.sidebar_toggle.setToolTip(
            tr('사이드바 펼치기') if self.sidebar_collapsed else tr('사이드바 접기')
        )
        for label in self.sidebar_section_labels:
            label.setVisible(not self.sidebar_collapsed)
        for separator in self.sidebar_group_separators:
            separator.setVisible(self.sidebar_collapsed)
        for button in self.nav_buttons:
            button.setText("" if self.sidebar_collapsed else str(button.property("navTitle")))
            button.setProperty("railMode", self.sidebar_collapsed)
            button.style().unpolish(button)
            button.style().polish(button)
        if persist:
            settings = load_machine_settings()
            settings["sidebar_collapsed"] = self.sidebar_collapsed
            save_machine_settings(settings)

    def toggle_sidebar(self) -> None:
        self.set_sidebar_collapsed(not getattr(self, "sidebar_collapsed", False))

    def dataset_management_tabs(self, active_key: str) -> QFrame:
        tab_bar = QFrame(objectName="pageTabBar")
