    def workflow_ribbon(self, steps: tuple[str, ...] | list[str]) -> QFrame:
        """Build the shared compact workflow map used by every workbench page."""
        ribbon = QFrame(objectName="workflowRibbon")
        ribbon_layout = QHBoxLayout(ribbon)
        ribbon_layout.setContentsMargins(10, 5, 10, 5)
        ribbon_layout.setSpacing(7)
        for index, title in enumerate(steps, 1):
            if index > 1:
                arrow = QLabel("→", objectName="pipelineArrow")
                arrow.setAlignment(Qt.AlignCenter)
                ribbon_layout.addWidget(arrow)
            label = QLabel(f"{index:02d}  {title}", objectName="pipelineChip")
            label.setAlignment(Qt.AlignCenter)
            ribbon_layout.addWidget(label, 1)
        return ribbon

    def metric_card(self, title: str, value: str, object_name: str = "card") -> QFrame:
        card = QFrame(objectName=object_name)
        layout = QVBoxLayout(card)
        title_label = QLabel(title, objectName="cardTitle")
        layout.addWidget(title_label)
        label = QLabel(value, objectName="cardValue")
        layout.addWidget(label)
        card.title_label = title_label  # type: ignore[attr-defined]
        card.value_label = label  # type: ignore[attr-defined]
        return card

    @staticmethod
    def set_metric_tooltip(card: QFrame, text: str) -> None:
        """Attach the same definition to every visible part of a metric card."""
        card.setToolTip(text)
        getattr(card, "title_label", card).setToolTip(text)
        getattr(card, "value_label", card).setToolTip(text)

