    def dataset_composition_summary_widget(
        self,
    ) -> tuple[QWidget, QLabel, dict[str, QLabel], dict[str, QProgressBar], QVBoxLayout]:
        """Build the shared overall/experiment dataset composition cards."""
        container = QWidget()
        cards = QHBoxLayout(container)
        cards.setContentsMargins(0, 0, 0, 0)
        cards.setSpacing(10)

        overall_card = QFrame(objectName="card")
        overall_layout = QVBoxLayout(overall_card)
        overall_layout.setContentsMargins(14, 10, 14, 10)
        overall_layout.setSpacing(6)
        overall_layout.addWidget(QLabel(tr('전체 데이터 구성'), objectName="eyebrowLabel"))
        overall_value = QLabel(tr('라벨을 읽는 중입니다.'), objectName="pageText")
        overall_layout.addWidget(overall_value)
        split_grid = QGridLayout()
        split_grid.setContentsMargins(0, 0, 0, 0)
        split_grid.setHorizontalSpacing(8)
        split_grid.setVerticalSpacing(4)
        count_labels: dict[str, QLabel] = {}
        progress_bars: dict[str, QProgressBar] = {}
        for row, (role, title) in enumerate(
            (("train", "Train"), ("validation", "Validation"), ("test", "Test"))
        ):
            role_label = QLabel(title, objectName="fieldLabel")
            role_label.setMinimumWidth(72)
            count_label = QLabel("0", objectName="pageText")
            count_label.setAlignment(Qt.AlignRight | Qt.AlignVCenter)
            count_label.setMinimumWidth(54)
            progress = QProgressBar()
            progress.setRange(0, 100)
            progress.setValue(0)
            progress.setFormat("0%")
            progress.setFixedHeight(17)
            split_grid.addWidget(role_label, row, 0)
            split_grid.addWidget(count_label, row, 1)
            split_grid.addWidget(progress, row, 2)
            count_labels[role] = count_label
            progress_bars[role] = progress
        split_grid.setColumnStretch(2, 1)
        overall_layout.addLayout(split_grid)
        cards.addWidget(overall_card, 1)

        experiment_card = QFrame(objectName="card")
        experiment_layout = QVBoxLayout(experiment_card)
        experiment_layout.setContentsMargins(14, 10, 14, 10)
        experiment_layout.setSpacing(6)
        experiment_layout.addWidget(QLabel(tr('실험별 구성'), objectName="eyebrowLabel"))
        experiment_rows = QVBoxLayout()
        experiment_rows.setContentsMargins(0, 0, 0, 0)
        experiment_rows.setSpacing(4)
        experiment_layout.addLayout(experiment_rows)
        experiment_layout.addStretch()
        cards.addWidget(experiment_card, 1)
        return container, overall_value, count_labels, progress_bars, experiment_rows

    def render_dataset_composition_summary(
        self,
        overall_value: QLabel,
        count_labels: dict[str, QLabel],
        progress_bars: dict[str, QProgressBar],
        experiment_rows: QVBoxLayout,
        *,
        enabled_count: int,
        total_counts: dict[str, int],
        experiment_totals: dict[str, dict[str, int]],
        valid_percent: float,
    ) -> None:
        total_frames = sum(total_counts.values())
        overall_value.setText(
            tr('사용 {value1}묶음  ·  전체 {value2:,}프레임  ·  유효율 {value3:.1f}%', value1=enabled_count, value2=total_frames, value3=valid_percent)
        )
        for role in ("train", "validation", "test"):
            count = int(total_counts.get(role, 0))
            percent = round(count * 100 / total_frames) if total_frames else 0
            count_labels[role].setText(f"{count:,}")
            progress_bars[role].setValue(percent)
            progress_bars[role].setFormat(f"{percent}%")

        while experiment_rows.count():
            item = experiment_rows.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()
        if experiment_totals:
            for name, values in sorted(experiment_totals.items()):
                row_label = QLabel(
                    tr('{value1}    {value2}묶음  ·  전체 {value3:,}프레임  ·  Train {value4:,}  ·  Validation {value5:,}  ·  Test {value6:,}', value1=tr('미지정') if name == '미지정' else name, value2=values['bundles'], value3=values['frames'], value4=values['train'], value5=values['validation'], value6=values['test']),
                    objectName="pageText",
                )
                row_label.setWordWrap(True)
                experiment_rows.addWidget(row_label)
        else:
            experiment_rows.addWidget(QLabel(tr('실험 데이터 없음'), objectName="pageText"))

    def project_experiment_mode(self) -> str:
        """Return the explicitly selected project assay, or unassigned."""
        if not self.config or not self.config.is_file():
            return "unassigned"
        try:
            payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        except Exception:
            return "unassigned"
        project_meta = project_metadata(payload)
        stored = str(project_meta.get("experiment_mode", "")).lower()
        source = str(project_meta.get("experiment_mode_source", "")).lower()
        return stored if stored in {"nort", "ymaze", "watermaze"} and source == "experiment_settings" else "unassigned"

    def current_project_name(self) -> str:
        if not self.config or not self.config.is_file():
            return tr('프로젝트 없음')
        try:
            payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
            task = str(payload.get("Task", "")).strip()
            if task:
                return task
        except Exception:
            pass
        return self.config.parent.name

    def refresh_project_chrome(self) -> None:
        """Synchronize the compact header and dashboard project manager."""
        name = self.current_project_name()
        config_text = str(self.config) if self.config and self.config.is_file() else ""
        if hasattr(self, "project_badge"):
            self.project_badge.setText(name)
            self.project_badge.setToolTip(
                tr('현재 프로젝트: {value1}\n클릭하면 대시보드의 프로젝트 관리로 이동합니다.', value1=config_text)
                if config_text else
                tr('현재 프로젝트가 없습니다. 클릭하면 대시보드의 프로젝트 관리로 이동합니다.')
            )
        project_folder = self.config.parent if self.config and self.config.is_file() else self.work_root
        if hasattr(self, "work_root_button"):
            self.work_root_button.setToolTip(
                tr('현재 프로젝트 폴더를 탐색기에서 엽니다.\n{value1}', value1=project_folder)
                if self.config and self.config.is_file() else
                tr('활성 프로젝트가 없어 공용 작업 폴더를 엽니다.\n{value1}', value1=project_folder)
            )
        if hasattr(self, "experiment_badge"):
            mode_labels = {
                "nort": "NORT", "ymaze": "Y-maze",
                "watermaze": "Water maze", "unassigned": tr('실험 미지정'),
            }
