    def start_tracking_roi_editor(
        self, video: Path, output: Path, saved_callback, initial_profile: Path | None = None,
    ) -> None:
        """Tracking geometry is independent of the project's behavioural assay."""
        if not self.validate_project_source_names(extra_paths=[video]):
            return
        initial = initial_profile if initial_profile and initial_profile.is_file() else output
        # Legacy calibration files may still be used by NORT analysis. Never
        # replace their schema, even when the caller supplied them as output.
        if output.is_file():
            try:
                legacy = json.loads(output.read_text(encoding="utf-8")).get("profile_type") != "hagisilta_zone_template"
            except (OSError, ValueError):
                legacy = True
            if legacy:
                legacy_output = output
                output = legacy_output.with_name(f"{legacy_output.stem}__tracking-roi.json")
                counter = 2
                while output.exists():
                    output = legacy_output.with_name(f"{legacy_output.stem}__tracking-roi-{counter}.json")
                    counter += 1
        args = [str(video), "--output", str(output), "--roi-only"]
        if initial.is_file():
            args += ["--profile", str(initial)]
        before = output.stat().st_mtime_ns if output.is_file() else None
        project_config = self.config

        def finished(exit_code: int) -> None:
            # Closing an editor without saving also exits with zero. Do not
            # attach an old/stale file to the project on cancellation.
            if exit_code != 0 or not output.is_file():
                return
            if output.stat().st_mtime_ns == before:
                return
            if self.config != project_config:
                self.append_log(tr('ROI 저장 완료 · 원래 프로젝트에서 파일을 불러오세요: {value1}', value1=output))
                return
            saved_callback(output)

        self.start_process(SCRIPTS / "hagisilta_zone_editor.py", args, finished)

    def set_project_experiment_mode(self, mode: str) -> None:
        if mode not in {"nort", "ymaze", "watermaze"} or not self.config or not self.config.is_file():
            return
        if self.project_experiment_mode() == mode:
            return
        try:
            payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
            project_meta = project_metadata(payload, create=True)
            project_meta["experiment_mode"] = mode
            project_meta["experiment_mode_source"] = "experiment_settings"
            self.config.write_text(
                yaml.safe_dump(payload, allow_unicode=True, sort_keys=False), encoding="utf-8"
            )
            names = {"nort": "NORT", "ymaze": "Y-maze", "watermaze": "Water maze"}
            self.append_log(tr('프로젝트 행동실험 설정: {value1}', value1=names[mode]))
        except Exception as error:
            self.append_log(tr('프로젝트 행동실험 저장 실패: {value1}', value1=error))
            return
        self.apply_dashboard_experiment_mode(mode)
        self.refresh_project_chrome()
        self.refresh_dashboard_video_status()

    def apply_dashboard_experiment_mode(self, mode: str) -> None:
        if not hasattr(self, "dashboard_video_table"):
            return
        mode = mode if mode in {"nort", "ymaze", "watermaze"} else "unassigned"
        if hasattr(self, "dashboard_experiment_picker"):
            self.dashboard_experiment_picker.setVisible(mode == "unassigned")
        if hasattr(self, "dashboard_experiment_label"):
            assay_name = (
                "NORT · Novel Object Recognition" if mode == "nort" else
                tr('Y-maze · 자발적 교대') if mode == "ymaze" else
                tr('Water maze · Morris 수중미로') if mode == "watermaze" else
                tr('실험 미지정')
            )
