    def workflow_card(
        self, number: str, title: str, description: str, status: str = "대기", expanded: bool = False
    ) -> tuple[QFrame, QVBoxLayout, QLabel]:
        status = tr(status)
        # A fresh application session always starts with every workbench panel
        # collapsed. The argument remains for call-site compatibility; runtime
        # expansion is controlled only after construction through the header.
        initial_expanded = False
        card = QFrame(objectName="workflowCard")
        outer = QVBoxLayout(card)
        outer.setContentsMargins(0, 0, 0, 0)
        outer.setSpacing(0)
        header_frame = WorkflowHeaderFrame(objectName="workflowPanelHeader")
        header_frame.setCursor(Qt.PointingHandCursor)
        header = QHBoxLayout(header_frame)
        header.setContentsMargins(9, 5, 7, 5)
        header.setSpacing(8)
        number_label = QLabel(number, header_frame, objectName="workflowStepNumber")
        number_label.setAlignment(Qt.AlignCenter)
        number_label.setFixedSize(26, 26)
        number_label.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        number_label.setVisible(bool(number))
        header.addWidget(number_label)
        title_label = QLabel(title, objectName="workflowStepTitle")
        title_label.setToolTip(description)
        title_label.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        header.addWidget(title_label, 1)
        badge = QLabel(status, header_frame, objectName="stepBadge")
        badge.setAlignment(Qt.AlignCenter)
        badge.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        badge.setVisible(bool(status))
        header.addWidget(badge)
        indicator = QLabel(objectName="collapseIndicator")
        indicator.setAlignment(Qt.AlignCenter)
        indicator.setFixedSize(28, 28)
        indicator.setPixmap(
            self.navigation_icon(
                "workflow_collapse" if initial_expanded else "workflow_expand"
            ).pixmap(24, 24)
        )
        indicator.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        header.addWidget(indicator)
        outer.addWidget(header_frame)
        content = QWidget(objectName="workflowPanelContent")
        content_layout = QVBoxLayout(content)
        content_layout.setContentsMargins(12, 10, 12, 12)
        content_layout.setSpacing(9)
        content.setVisible(initial_expanded)
        outer.addWidget(content)
        card.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.Maximum)
        card.workflow_content = content  # type: ignore[attr-defined]
        card.workflow_toggle = indicator  # type: ignore[attr-defined]
        card.workflow_header = header_frame  # type: ignore[attr-defined]
        card.workflow_description = description  # type: ignore[attr-defined]
        header_frame.clicked.connect(
            lambda: self.set_workflow_expanded(card, content.isHidden())
        )
        return card, content_layout, badge

    def collapse_all_workflow_panels(self) -> None:
        for card in self.workflow_cards(self):
            self.set_workflow_expanded(card, False)

    def finish_workflow_startup(self) -> None:
        self.collapse_all_workflow_panels()
        self.workflow_starting_up = False

    def workflow_page_state(self, page: QWidget | None) -> list[tuple[QFrame, bool]]:
        if page is None:
            return []
        return [
            (card, not card.workflow_content.isHidden())  # type: ignore[attr-defined]
            for card in self.workflow_cards(page)
        ]

    @staticmethod
    def workflow_cards(scope: QWidget) -> list[QFrame]:
        """Return only collapsible cards that belong to the scope's own window.

        Modal editors are parented to their originating page.  Qt therefore
        includes a recently closed editor's internal ``workflowCard`` frames
        in ``page.findChildren`` until deferred deletion runs.  Those visual
        cards are not main-page collapsible panels and do not carry the
        ``workflow_content`` attributes used by navigation state capture.
        """
        owner_window = scope.window()
        return [
            card
            for card in scope.findChildren(QFrame, "workflowCard")
            if card.window() is owner_window
            and hasattr(card, "workflow_content")
            and hasattr(card, "workflow_toggle")
            and hasattr(card, "workflow_header")
        ]

    def restore_workflow_page_state(
        self, state: list[tuple[QFrame, bool]], serial: int
    ) -> None:
        if serial != self.workflow_navigation_serial:
            return
        for card, expanded in state:
            self.set_workflow_expanded(card, expanded)

    def set_workflow_expanded(self, card: QFrame, expanded: bool) -> None:
        if getattr(self, "workflow_starting_up", False) and expanded:
            return
        content = card.workflow_content  # type: ignore[attr-defined]
        toggle = card.workflow_toggle  # type: ignore[attr-defined]
        header = card.workflow_header  # type: ignore[attr-defined]
        content.setVisible(expanded)
        card.setSizePolicy(
            QSizePolicy.Preferred,
            QSizePolicy.Preferred if expanded else QSizePolicy.Maximum,
        )
        card.updateGeometry()
        toggle.setPixmap(
            self.navigation_icon(
                "workflow_collapse" if expanded else "workflow_expand"
            ).pixmap(24, 24)
        )
        description = str(getattr(card, "workflow_description", "")).strip()
        action = tr('클릭하여 패널 접기') if expanded else tr('클릭하여 패널 펼치기')
        header.setToolTip(f"{description}\n\n{action}" if description else action)

    def set_workflow_badge(self, badge: QLabel, text: str, ready: bool = False) -> None:
        badge.setText(text)
        badge.setObjectName("stepBadgeReady" if ready else "stepBadge")
        badge.style().unpolish(badge)
        badge.style().polish(badge)

    def set_centered_table_checkbox(
        self, table: QTableWidget, row: int, column: int, checked: bool
    ) -> QCheckBox:
        sort_item = SortableTableItem()
        sort_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
        sort_item.setData(Qt.UserRole, int(checked))
        table.setItem(row, column, sort_item)
        checkbox = QCheckBox(objectName="tableCellCheck")
        checkbox.setFixedSize(19, 19)
        checkbox.setChecked(checked)
        checkbox.stateChanged.connect(
            lambda _state, item=sort_item, box=checkbox: item.setData(Qt.UserRole, int(box.isChecked()))
        )
        cell = QWidget(objectName="tableCellWidget")
        cell.setAttribute(Qt.WA_TranslucentBackground)
        cell_layout = QHBoxLayout(cell)
        cell_layout.setContentsMargins(0, 0, 0, 0)
        cell_layout.setSpacing(0)
        cell_layout.setAlignment(Qt.AlignCenter)
        cell_layout.addWidget(checkbox, 0, Qt.AlignCenter)
        table.setCellWidget(row, column, cell)
        if isinstance(table, MultiRowContextTableWidget):
            table.register_context_cell_widget(cell)
            table.register_context_cell_widget(checkbox)
        return checkbox

    @staticmethod
    def table_checkbox(table: QTableWidget, row: int, column: int) -> QCheckBox | None:
        cell = table.cellWidget(row, column)
        return cell.findChild(QCheckBox) if cell else None

    def path_row(self, label: str, default: str, directory: bool = False) -> tuple[QHBoxLayout, QLineEdit]:
        row = QHBoxLayout()
        row.addWidget(QLabel(label))
        field = QLineEdit(default)
        row.addWidget(field, 1)
        button = QPushButton(tr('찾기'), objectName="secondaryButton")
        if directory:
            button.clicked.connect(lambda: self.pick_directory(field))
        else:
            button.clicked.connect(lambda: self.pick_video(field))
        row.addWidget(button)
        return row, field

