    def build_dataset(self) -> QWidget:
        page, layout = self.tabbed_page_shell(
            tr('데이터셋 관리'),
            tr('원본·라벨·교정 데이터를 구성하고 다음 학습에 반영합니다.'),
            self.dataset_management_tabs("dataset"),
        )
        layout.addWidget(self.workflow_ribbon((tr('영상·추출 계획'), tr('라벨링·검토'), tr('학습 분할'))))

        self.dataset_plan_card, plan_layout, self.dataset_plan_badge = self.workflow_card(
            "01", tr('영상·추출 계획'), tr('원본 영상을 가져온 뒤 추출 여부와 ROI별 프레임 수를 정합니다.'), tr('영상 없음'), True
        )
        # Internal current-video state used by the dataset table and extraction
        # workflow. It no longer needs a duplicate visible field on model evaluation.
        self.dataset_video = QLineEdit(page)
        self.dataset_video.setVisible(False)
        self.dataset_video_list = NoWheelComboBox()
        self.dataset_video_list.currentIndexChanged.connect(self.select_dataset_video)
        self.dataset_video_list.setVisible(False)
        add_video = QPushButton(tr('영상 추가'), objectName="toolButton")
        self.set_action_icon(add_video, "add", 14)
        add_video.clicked.connect(self.add_dataset_videos)
        # These values are retained as project defaults for imports and legacy
        # helpers, but the dataset page edits both values directly in the table.
        self.dataset_frames_per_video = NoWheelSpinBox()
        self.dataset_frames_per_video.setRange(1, 1000)
        self.dataset_bodyparts = QLineEdit()
        self.dataset_bodyparts.setPlaceholderText("nose, head_center, body_center, tail_base")
        self.dataset_bodyparts.setToolTip(
            detailed_tooltip(
                tr('DLC가 프레임마다 예측하도록 학습할 신체점 목록입니다. 쉼표로 나누고 영문·숫자·밑줄 이름을 사용합니다.'),
                tr('점을 늘리면 더 자세한 자세 분석이 가능하지만 라벨링 시간·오류 가능성·모델 출력 수가 늘어납니다. 제거하거나 이름을 바꾸면 기존 라벨 열과 맞지 않을 수 있습니다.'),
                tr('행동 판정에 실제로 쓸 수 있고 영상에서 일관되게 구분 가능한 점만 선택하세요. 현재 NORT/Y-maze 기본은 nose, head_center, body_center, tail_base입니다.'),
                tr('이미 라벨링한 뒤 목록을 바꾸는 것은 단순 표시 변경이 아닙니다. 모든 기존 라벨을 다시 검토해야 합니다.'),
            )
        )
        self.dataset_bodyparts.textChanged.connect(self.update_dataset_bodyparts_column)
        save_settings = QPushButton(tr('계획 저장 후 대표 프레임 추출'), objectName="primaryButton")
        save_settings.setToolTip(
            tr('표의 체크 상태와 직접 입력한 영상별 추출 프레임 수·프로젝트 공통 학습 신체점을 저장한 뒤, 체크된 영상에서 대표 프레임을 바로 추출합니다.')
        )
        save_settings.clicked.connect(self.save_and_extract_dataset_configuration)
