        def training_settings_group(
            title: str,
            description: str,
            fields: tuple[tuple[QLabel, QWidget], ...],
            columns: int = 2,
        ) -> QFrame:
            group = QFrame(objectName="settingsGroup")
            group_layout = QVBoxLayout(group)
            group_layout.setContentsMargins(12, 10, 12, 12)
            group_layout.setSpacing(8)
            group_layout.addWidget(QLabel(title, objectName="settingsGroupTitle"))
            description_label = QLabel(description, objectName="settingsGroupDescription")
            description_label.setWordWrap(True)
            group_layout.addWidget(description_label)
            field_grid = QGridLayout()
            field_grid.setContentsMargins(0, 3, 0, 0)
            field_grid.setHorizontalSpacing(14)
            field_grid.setVerticalSpacing(7)
            for index, (label, field) in enumerate(fields):
                if field.toolTip():
                    label.setToolTip(field.toolTip())
                    label.setToolTipDuration(30000)
                    field.setToolTipDuration(30000)
                column = index % columns
                block_row = (index // columns) * 2
                field_grid.addWidget(label, block_row, column)
                field_grid.addWidget(field, block_row + 1, column)
            for column in range(columns):
                field_grid.setColumnStretch(column, 1)
            group_layout.addLayout(field_grid)
            return group

