        advanced_disclosure = QFrame(objectName="advancedDisclosure")
        advanced_disclosure_layout = QVBoxLayout(advanced_disclosure)
        advanced_disclosure_layout.setContentsMargins(0, 0, 0, 0)
        advanced_disclosure_layout.setSpacing(0)
