    def build_evaluation_filter_panel(self) -> QFrame:
        card, layout, self.eval_filter_badge = self.workflow_card(
            "04", tr('좌표 후처리 비교'), tr('범위 비교·조합 → 보정 설정·일괄 실행 → 보정 결과 확인·교정'), tr('결과 선택'), False,
        )
        self.eval_filter_card = card
        self.eval_filter_source = QLabel(tr('03 영상 테스트 결과에서 한 행을 선택하세요.'), objectName="statusSummaryText")
        self.eval_filter_source.setWordWrap(True)
        layout.addWidget(self.eval_filter_source)
        layout.addWidget(self.build_filter_workflow("eval"))
        self.eval_filter_result_summary = QLabel("", objectName="pageText")
        self.eval_filter_result_summary.setWordWrap(True)
        self.eval_filter_result_summary.setToolTip(tr('원본 대비 좌표 변경량이며 정답 대비 오차가 아닙니다.'))
        self.composition_controls["eval"]["saved_results_layout"].addWidget(self.eval_filter_result_summary)
        return card

    @staticmethod
    def pose_filter_window_combo() -> QComboBox:
        combo = QComboBox()
        for window in range(3, 32, 2):
            combo.addItem(tr('{value1}프레임', value1=window), window)
        combo.setMinimumWidth(132)
        combo.setSizeAdjustPolicy(QComboBox.AdjustToContents)
        combo.view().setMinimumWidth(164)
        combo.view().setTextElideMode(Qt.ElideNone)
        combo.setToolTip(
            tr('현재 프레임과 앞뒤 프레임을 합한 홀수 개수입니다. 큰 범위는 실제 빠른 움직임도 줄일 수 있습니다. 앞뒤 자료가 부족한 영상 양 끝과 좌표 누락 주변은 원본을 유지합니다.')
        )
        return combo

    def build_tracking_filter_panel(self) -> QFrame:
        card, layout, _badge = self.workflow_card(
            "", tr('좌표 후처리 보정'),
            tr('필터 범위 비교·신체점 조합, 선택 결과 일괄 보정, 분석 입력 지정을 펼칩니다.'),
            "",
        )
        icon = QLabel(objectName="advancedDisclosureIcon")
        icon.setAlignment(Qt.AlignCenter)
        icon.setFixedSize(30, 30)
        icon.setPixmap(self.navigation_icon("settings_tune").pixmap(18, 18))
        icon.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        card.workflow_header.layout().insertWidget(0, icon)
        self.track_filter_card = card
        layout.addWidget(self.build_filter_workflow("track"))
        return card

    def build_track(self) -> QWidget:
        page, layout = self.workbench_page_shell(
            tr('영상 트래킹'),
            tr('프로젝트 학습 모델 또는 DLC 사전학습 모델로 체크한 실험 영상을 ROI별로 일괄 처리합니다.'),
            "TRACKING WORKBENCH",
            model_terms=True,
        )
        layout.addWidget(self.workflow_ribbon((tr('모델 선택'), tr('영상·ROI 대상'), tr('실행 설정'), tr('결과 확인'))))
        self.track_video = QLineEdit()
        self.track_video.setVisible(False)

        model_card, model_layout, self.track_model_badge = self.workflow_card(
            "01", tr('트래킹 모델 선택'),
            tr('검증한 프로젝트 모델 또는 학습 없이 쓰는 DLC 사전학습 모델 중 이번 작업에 사용할 모델을 고릅니다.'),
            tr('확인 중'), True,
        )
        self.track_model_source = NoWheelComboBox()
        self.track_model_source.addItem(tr('프로젝트 최종·외부 모델'), "trained")
        self.track_model_source.addItem(tr('DLC 사전학습 모델 · TopViewMouse'), "superanimal")
        self.track_model_source.setToolTip(detailed_tooltip(
            tr('프로젝트 최종·외부 모델은 현재 프로젝트에서 평가를 통과했거나 직접 불러온 체크포인트를 사용합니다.'),
            tr('DLC 사전학습 모델은 추가학습 없이 SuperAnimal TopViewMouse HRNet-W32를 체크한 모든 영상과 ROI에 직접 적용합니다.'),
            tr('새 촬영 조건에서는 먼저 ‘SuperAnimal 모델 확인’에서 대표 영상 한 개의 추론 결과를 직접 확인한 뒤, 결과가 괜찮을 때 여기서 전체 영상을 처리하세요.'),
            tr('이 선택은 체크박스로 고른 전체 트래킹 대상에 적용되며, 파란 행 선택과는 관계없습니다.'),
        ))
        self.track_model_source.currentIndexChanged.connect(
            lambda _index: self.update_batch_target_summary()
        )
        self.track_model_source.currentIndexChanged.connect(
            lambda _index: self.refresh_tracking_bodypart_consumers()
        )
        self.track_model_source.setFixedWidth(360)
        self.track_shuffle = NoWheelSpinBox()
        self.track_shuffle.setRange(1, 99)
        self.track_shuffle.setVisible(False)
        go_evaluate = QPushButton(tr('모델 평가'), objectName="toolButton")
        self.set_action_icon(go_evaluate, "evaluate", 14)
        go_evaluate.clicked.connect(lambda: self.show_module(self.module_index("evaluate")))
        load_external_model = QPushButton(tr('불러오기'), objectName="toolButton")
        self.set_action_icon(load_external_model, "import", 14)
        load_external_model.setToolTip(
            detailed_tooltip(
                tr('현재 프로젝트에서 트래킹에 사용할 외부 DLC 모델을 연결합니다. HAGISILTA 모델 ZIP 또는 다른 DLC 프로젝트의 snapshot 체크포인트를 선택할 수 있습니다.'),
                tr('선택하면 현재 프로젝트의 최종 모델 대신 외부 모델이 사용되며, 원본 외부 파일은 수정하지 않고 ZIP 모델은 프로젝트 전용 폴더에 복사됩니다.'),
                tr('다른 PC에서는 필요한 설정이 함께 든 HAGISILTA 모델 ZIP을 권장합니다. 신체점 이름과 순서가 현재 분석 목적에 맞는지 확인하세요.'),
                tr('모델을 현재 데이터로 다시 학습하는 기능이 아니라 이미 학습된 가중치를 추론에 연결하는 기능입니다.'),
            )
        )
        load_external_model.clicked.connect(self.browse_external_tracking_model)
        export_model = QPushButton(tr('내보내기'), objectName="toolButton")
        self.set_action_icon(export_model, "export", 14)
        export_model.setToolTip(
            detailed_tooltip(
                tr('현재 사용 중인 체크포인트와 DLC 추론 설정을 다른 PC·프로젝트에서 불러올 수 있는 휴대용 ZIP으로 묶습니다.'),
                tr('ZIP 파일 크기는 모델 가중치만큼 늘지만 원본 영상·라벨 이미지·실험 결과는 포함하지 않습니다.'),
                tr('성능이 확인된 최종 모델을 지정한 뒤 내보내고, 다른 PC에서는 ‘외부 모델·ZIP 불러오기’로 선택하세요.'),
                tr('프로젝트 전체 백업 ZIP과 다릅니다. 이 ZIP은 추론 모델만 이동합니다.'),
            )
        )
        export_model.clicked.connect(self.export_tracking_model_bundle)
        self.restore_project_model_button = QPushButton(tr('프로젝트 모델'), objectName="toolButton")
        self.set_action_icon(self.restore_project_model_button, "reset", 14)
        self.restore_project_model_button.setToolTip(
            tr('외부 모델 사용을 해제하고 모델 평가에서 최종 지정한 이 프로젝트 모델로 돌아갑니다.')
        )
        self.restore_project_model_button.clicked.connect(self.clear_external_tracking_model)
        model_selector_row = QHBoxLayout()
