        self.set_action_icon(self.review_open_editor_button, "edit", 14)
        self.review_open_editor_button.setToolTip(
            tr('표에서 선택한 영상과 추론 결과를 영상 교정기에 전달합니다. Space 재생/정지, 점 드래그, X/Delete 점 삭제를 사용할 수 있습니다.')
        )
        self.review_open_editor_button.clicked.connect(self.open_selected_video_review)
        toolbar.addWidget(self.review_open_editor_button)
        self.review_open_folder_button = QPushButton(tr('결과 폴더 열기'), objectName="toolButton")
        self.set_action_icon(self.review_open_folder_button, "folder", 14)
        self.review_open_folder_button.clicked.connect(self.open_selected_review_folder)
        toolbar.addWidget(self.review_open_folder_button)
