    def choose_ymaze_video(self) -> None:
        start = self.ymaze_video_edit.text().strip() or str(self.config.parent if self.config else self.work_root)
        selected, _ = QFileDialog.getOpenFileName(
            self, tr('Y-maze 기준 원본 영상'), start, tr('영상 (*.avi *.mp4 *.mov *.mkv *.wmv);;모든 파일 (*.*)')
        )
        if not selected:
            return
        video = Path(selected)
        self.ymaze_video_edit.setText(str(video))
        self.ymaze_profile_edit.setText(str(self.ymaze_profile_for_video(video)))

    def choose_ymaze_profile(self) -> None:
        start = self.ymaze_profile_edit.text().strip() or str(self.config.parent if self.config else self.work_root)
        selected, _ = QFileDialog.getOpenFileName(self, tr('Y-maze ABC 템플릿'), start, tr('HAGISILTA Y-maze 템플릿 (*.json)'))
        if selected:
            self.ymaze_profile_edit.setText(selected)
            self.set_workflow_badge(self.ymaze_template_badge, tr('템플릿 준비'), True)

    def open_ymaze_editor(self) -> None:
        video = Path(self.ymaze_video_edit.text().strip())
        if not video.is_file():
            # The highlighted source-video row is the reference. Do not require
            # users to discover a separate clickable cell in the Arena table.
            self.use_selected_ymaze_bundle_source(False)
            video = Path(self.ymaze_video_edit.text().strip())
        if not video.is_file():
            QMessageBox.information(self, tr('기준 영상 필요'), tr('01 표에서 원본 영상 묶음을 기준으로 지정하세요.'))
            return
        profile = Path(self.ymaze_profile_edit.text().strip()) if self.ymaze_profile_edit.text().strip() else None
        if profile is None:
            QMessageBox.information(self, tr('템플릿 경로 필요'), tr('01 표의 ‘전체 Arena 편집’을 먼저 누르세요.'))
            return
        args = [
            str(SCRIPTS / "hagisilta_zone_editor.py"), str(video), "--output", str(profile),
            "--preset", "ymaze", "--coordinate-space", "source_px",
        ]
        if profile.is_file():
            args += ["--profile", str(profile)]
        else:
            arena_profile = Path(getattr(self, "ymaze_arena_profile_path", ""))
            if not arena_profile.is_file():
                QMessageBox.information(
                    self, tr('Arena ROI 필요'),
                    tr('선택 영상의 트래킹 ROI 프로필을 찾지 못했습니다. 01 표에서 트래킹 완료 영상을 선택하세요.'),
                )
                return
            args += ["--arena-profile", str(arena_profile)]
        pythonw = Path(sys.executable).with_name("pythonw.exe")
        ok, _pid = QProcess.startDetached(str(pythonw if pythonw.exists() else Path(sys.executable)), args)
        if ok:
            self.append_log(tr('Y-maze 전체 Arena ABC 편집기 실행: {value1}', value1=video.name))
        else:
            QMessageBox.critical(self, tr('Y-maze 편집기'), tr('Y-maze ABC 편집기를 실행하지 못했습니다.'))

    def choose_ymaze_tracked(self) -> None:
        start = self.ymaze_tracked_edit.text().strip()
        if not start and self.config:
            start = str(self.project_tracking_root())
        selected = QFileDialog.getExistingDirectory(self, tr('프로젝트 트래킹 결과 또는 영상 묶음'), start or str(self.work_root))
        if not selected:
            return
        self.ymaze_tracked_edit.setText(selected)
        base = project_output_root(self.config.parent) / "ymaze-pilot" if self.config else self.work_root / "ymaze-pilot"
        self.ymaze_output_edit.setText(str(base))
        self.ymaze_checked_bundles.clear()
        self.ymaze_bundle_checks_initialized = False
        self.refresh_ymaze_bundle_table()
        self.refresh_ymaze_results()

    def use_selected_ymaze_bundle_source(self, navigate: bool = True) -> None:
        if not hasattr(self, "ymaze_bundle_table"):
            return
        row = self.ymaze_bundle_table.currentRow()
        if row < 0:
            for candidate_row in range(self.ymaze_bundle_table.rowCount()):
                checkbox = self.table_checkbox(self.ymaze_bundle_table, candidate_row, 0)
                if checkbox and checkbox.isChecked():
                    row = candidate_row
                    self.ymaze_bundle_table.selectRow(row)
                    break
        item = self.ymaze_bundle_table.item(row, 1) if row >= 0 else None
        if item is None:
            QMessageBox.information(self, tr('Arena 선택'), tr('표에서 기준으로 사용할 Arena 행을 먼저 선택하세요.'))
            return
        arena_text = str(item.data(Qt.UserRole + 2) or "")
        arena_dir = Path(arena_text) if arena_text else None
        arena_id = int(item.data(Qt.UserRole + 3) or 0)
        source_video_text = str(item.data(Qt.UserRole + 1) or "")
        source_video = Path(source_video_text) if source_video_text else None
        if arena_dir is None or not arena_dir.is_dir() or source_video is None or not source_video.is_file():
            QMessageBox.information(
                self, tr('Arena 영상 없음'),
                tr('선택한 행에서 원본 영상과 Arena 정보를 찾지 못했습니다. 먼저 영상 트래킹을 완료하세요.'),
            )
            return
        metadata_path = arena_dir / "roi-metadata.json"
        try:
            metadata = json.loads(metadata_path.read_text(encoding="utf-8")) if metadata_path.is_file() else {}
        except Exception:
            metadata = {}
        self.ymaze_arena_profile_path = str(metadata.get("roi_profile", ""))
        # Experiment geometry is saved per source-video bundle.  The tracking
        # crop profile is an editor input only, never the experiment output.
        bundle = arena_dir.parent
        profile = self.ymaze_override_profile(bundle)
        self.ymaze_video_edit.setText(str(source_video))
        self.ymaze_profile_edit.setText(str(profile))
        if hasattr(self, "ymaze_reference_label"):
            self.ymaze_reference_label.setText(
                tr('기준 영상 · {value1} · Arena {value2:02d}에서 A/B/C/Center를 지정합니다.', value1=source_video.name, value2=arena_id)
            )
        self.append_log(tr('Y-maze 기준 원본 연결: {value1} · 전체 Arena 표시', value1=source_video.name))
        self.refresh_ymaze_bundle_table()
        if navigate:
            self.set_workflow_expanded(self.ymaze_input_card, True)

    def populate_ymaze_bodyparts(
        self, bodyparts: list[str] | tuple[str, ...], selected: list[str] | None = None,
    ) -> None:
        if not hasattr(self, "ymaze_bodyparts"):
            return
        available = list(dict.fromkeys(str(part) for part in bodyparts if str(part).strip()))
        chosen = set()
        for part in selected or []:
            if part in available:
                chosen.add(part)
            else:
                matches = [name for name in available if name.casefold() == str(part).casefold()]
                if len(matches) == 1:
                    chosen.add(matches[0])
        if available and selected is None:
            chosen = {next((part for part in available if part.casefold() == "body_center"), available[0])}
        previous = getattr(self, "ymaze_bodypart_checks", {})
        if list(previous) == available and available and {
            name for name, box in previous.items() if box.isChecked()
        } == chosen:
            return
        while self.ymaze_bodyparts_layout.count():
            layout_item = self.ymaze_bodyparts_layout.takeAt(0)
            widget = layout_item.widget()
            if widget is not None:
                widget.deleteLater()
        self.ymaze_bodypart_checks = {}
        self.ymaze_bodypart_empty_hint = None
        if not available:
            placeholder = QLabel(tr('신체점 정보 없음 · 결과·모델을 확인하세요'), objectName="fieldHint")
            self.ymaze_bodypart_empty_hint = placeholder
            placeholder.setWordWrap(True)
            self.ymaze_bodyparts_layout.addWidget(placeholder)
        for part in available:
            checkbox = QCheckBox(part)
            checkbox.setChecked(part in chosen)
            self.ymaze_bodyparts_layout.addWidget(checkbox)
            self.ymaze_bodypart_checks[part] = checkbox
        self.ymaze_bodyparts_layout.addStretch()

    def selected_ymaze_bodyparts(self) -> list[str]:
        if not hasattr(self, "ymaze_bodyparts"):
            return []
        return [part for part, checkbox in self.ymaze_bodypart_checks.items() if checkbox.isChecked()]

    def ymaze_profile_for_arena(self, arena_id: int) -> Path:
        root = project_state_root(self.config.parent) / "ymaze_profiles" if self.config else self.work_root / "ymaze_profiles"
        return root / "project_ymaze_template.json"

    def ymaze_profile_for_video(self, video: Path) -> Path:
        """Return a private experiment-geometry file for a manually chosen video."""
        root = project_state_root(self.config.parent) / "ymaze_profiles" if self.config else self.work_root / "ymaze_profiles"
        try:
            identity = os.path.normcase(str(video.resolve()))
        except OSError:
            identity = os.path.normcase(str(video))
        digest = hashlib.sha1(identity.encode("utf-8")).hexdigest()[:10]
        safe_name = re.sub(r"[^0-9A-Za-z가-힣_-]+", "_", video.stem).strip("._") or "video"
        return root / "manual" / f"{safe_name}_{digest}.json"

    def ymaze_override_profile(self, bundle: Path) -> Path:
        root = project_state_root(self.config.parent) / "ymaze_profiles" if self.config else self.work_root / "ymaze_profiles"
        safe_name = re.sub(r"[^0-9A-Za-z가-힣._-]+", "_", bundle.name).strip("._") or "video"
        return root / "video_overrides" / f"{safe_name}.json"

    def ymaze_profile_for_bundle(self, bundle: Path) -> Path:
        # A shared template is only an explicit copy source.  Treating it as an
        # active fallback made every video display and edit the same geometry.
        return self.ymaze_override_profile(bundle)

    @staticmethod
    def ymaze_profile_matches_video(profile: Path, video: Path) -> bool:
        """Reject a copied/stale profile that still points at another video."""
        if not profile.is_file() or not video.is_file():
            return False
        try:
            payload = json.loads(profile.read_text(encoding="utf-8"))
        except Exception:
            return False
        source_text = str(payload.get("source_video", "")).strip()
        if not source_text:
            return True  # Preserve legacy profiles that predate source provenance.
        source = Path(source_text)
        try:
            if os.path.normcase(str(source.resolve())) == os.path.normcase(str(video.resolve())):
                return True
        except OSError:
            pass
        return source.name.casefold() == video.name.casefold()

    def ymaze_review_records(self) -> list[dict]:
        root = Path(self.ymaze_tracked_edit.text().strip())
        records: list[dict] = []
        hidden_sources = self.project_hidden_source_keys()
        for bundle in self.discover_ymaze_bundles(root):
            metadata = {}
            for metadata_path in sorted(bundle.glob("arena_*/roi-metadata.json")):
                try:
                    candidate = json.loads(metadata_path.read_text(encoding="utf-8"))
                except Exception:
                    continue
                if candidate.get("source_video"):
                    metadata = candidate
                    break
            video = Path(str(metadata.get("source_video", "")))
            if not video.is_file():
                continue
            if self.normalized_source_key(video) in hidden_sources:
                continue
            override = self.ymaze_override_profile(bundle)
            arena_profile = Path(str(metadata.get("roi_profile", "")))
            override_valid = self.ymaze_profile_matches_video(override, video)
            if override_valid:
                profile = override
                status = tr('● 영상별 A/B/C 보정 적용')
            else:
                profile = Path()
                status = (
                    tr('설정 출처 불일치 · 다시 지정 필요')
                    if override.is_file() else tr('미로 외곽 ROI만 · A/B/C/Center 미지정')
                )
            records.append({
                "bundle": str(bundle), "video": str(video), "profile": str(profile),
                "override_profile": str(override), "override": override_valid,
                "arena_profile": str(arena_profile), "status": status,
                "zones_ready": override_valid,
            })
        return records

    def open_ymaze_roi_overview(self) -> None:
        records = self.ymaze_review_records()
        if not records:
            QMessageBox.information(self, tr('검수 영상 없음'), tr('트래킹이 완료된 원본 영상 묶음을 찾지 못했습니다.'))
            return
        zones_ready = any(bool(record.get("zones_ready")) for record in records)
        dialog = RoiOverviewDialog(
            records,
            tr('Y-maze 전체 영상 ROI 검수'),
            (
                tr('모든 원본 영상의 미로 외곽 ROI와 A/B/C/Center를 겹쳐 표시합니다. 어긋난 영상을 클릭하면 그 영상만 사용하는 개별 보정본으로 편집합니다.')
                if zones_ready else
                tr('아직 A/B/C/Center가 없어 모든 영상의 미로 외곽 ROI만 표시합니다. 카드를 클릭하면 선택한 영상을 기준으로 A/B/C/Center를 지정할 수 있습니다.')
            ),
            self,
            records_provider=self.ymaze_review_records,
            group_apply=True,
            group_apply_label=tr('체크 영상에 Y-maze 설정 적용'),
            group_apply_tooltip=(
                tr('‘이 설정을 기준으로’를 누른 영상의 미로 외곽과 A/B/C/Center를 ‘적용 대상’으로 체크한 영상들에 복사합니다. 카메라와 미로 위치가 같은 영상끼리만 사용하세요. 각 대상 영상의 트래킹 Arena ROI는 그대로 유지하며, 체크하지 않은 영상은 변경하지 않습니다.')
            ),
        )
        dialog.edit_requested.connect(self.open_ymaze_review_record)
        dialog.apply_group_requested.connect(self.apply_ymaze_roi_group)
        dialog.exec()
        self.refresh_ymaze_bundle_table()

    def apply_ymaze_roi_group(self, source_record: dict, target_records: list[dict]) -> None:
        source_profile = Path(str(source_record.get("profile", "")))
        source_video = Path(str(source_record.get("video", "")))
        targets = [
            record for record in target_records
            if Path(str(record.get("video", ""))).is_file()
            and Path(str(record.get("bundle", ""))).is_dir()
        ]
        if not source_profile.is_file() or not source_video.is_file() or not targets:
            QMessageBox.information(
                self, tr('Y-maze 묶음 적용'),
                tr('기준 영상의 저장된 Y-maze 설정 또는 적용 대상 영상을 찾지 못했습니다.'),
            )
            return
        try:
            source_payload = json.loads(source_profile.read_text(encoding="utf-8"))
        except Exception as error:
            QMessageBox.critical(self, tr('Y-maze 묶음 적용'), tr('기준 설정을 읽지 못했습니다.\n\n{value1}', value1=error))
            return
        if not source_payload.get("arenas"):
            QMessageBox.information(
                self, tr('Y-maze 묶음 적용'),
                tr('기준 영상에 저장된 미로 외곽과 A/B/C/Center 설정이 없습니다.'),
            )
            return

        existing = [
            Path(str(record.get("video", ""))).name
            for record in targets
            if self.ymaze_override_profile(Path(str(record.get("bundle", "")))).is_file()
        ]
        if existing:
            answer = QMessageBox.question(
                self, tr('기존 개별 설정 덮어쓰기'),
                tr('다음 영상에는 이미 개별 Y-maze 설정이 있습니다. 기준 영상 설정으로 덮어쓸까요?\n\n')
                + "\n".join(existing),
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return

        expected_size = tuple(int(value) for value in source_payload.get("source_resolution_px", [])[:2])
        backup_root = (
            project_backup_root(self.config.parent) if self.config
            else self.work_root / ".hagisilta-backups"
        )
        stamp = time.strftime("%Y%m%d-%H%M%S")
        applied: list[str] = []
        skipped: list[str] = []
        for record in targets:
            video = Path(str(record.get("video", "")))
            bundle = Path(str(record.get("bundle", "")))
            arena_profile = Path(str(record.get("arena_profile", "")))
            capture = cv2.VideoCapture(str(video))
            width = int(capture.get(cv2.CAP_PROP_FRAME_WIDTH) or 0) if capture.isOpened() else 0
            height = int(capture.get(cv2.CAP_PROP_FRAME_HEIGHT) or 0) if capture.isOpened() else 0
            fps = float(capture.get(cv2.CAP_PROP_FPS) or 0.0) if capture.isOpened() else 0.0
            frames = int(capture.get(cv2.CAP_PROP_FRAME_COUNT) or 0) if capture.isOpened() else 0
            capture.release()
            if width <= 0 or height <= 0:
                skipped.append(tr('{value1}: 영상을 읽지 못함', value1=video.name))
                continue
            if len(expected_size) == 2 and expected_size != (width, height):
                skipped.append(
                    tr('{value1}: 해상도 {value2}×{value3} (기준 {value4}×{value5})', value1=video.name, value2=width, value3=height, value4=expected_size[0], value5=expected_size[1])
                )
                continue

            # A Y-maze experiment profile contains two different layers:
            #
            # * mask/corners: the target video's tracking Arena ROI
            # * maze outline/landmarks/zones: A/B/C/Center experiment geometry
            #
            # Group apply must copy only the latter.  Copying the complete
            # source payload makes every target display the reference video's
            # tracking ROI and can later be mistaken for an overwritten crop.
            try:
                target_arena_payload = json.loads(arena_profile.read_text(encoding="utf-8"))
                target_arenas = list(target_arena_payload.get("arenas") or [])
            except Exception:
                target_arenas = []
            source_arenas = list(source_payload.get("arenas") or [])
            if (
                not arena_profile.is_file()
                or not target_arenas
            ):
                skipped.append(tr('{value1}: 대상 영상의 트래킹 ROI를 찾지 못함', value1=video.name))
                continue
            if len(source_arenas) != len(target_arenas):
                skipped.append(
                    tr('{value1}: Arena 수 {value2}개 (기준 {value3}개)', value1=video.name, value2=len(target_arenas), value3=len(source_arenas))
                )
                continue

            output = self.ymaze_override_profile(bundle)
            if output.is_file():
                backup_dir = backup_root / f"ymaze-group-apply-{stamp}"
                backup_dir.mkdir(parents=True, exist_ok=True)
                shutil.copy2(output, backup_dir / output.name)
            payload = json.loads(json.dumps(source_payload))
            payload_arenas = list(payload.get("arenas") or [])
            target_by_id = {
                int(arena.get("id", index)): arena
                for index, arena in enumerate(target_arenas, start=1)
            }
            for index, arena in enumerate(payload_arenas, start=1):
                arena_id = int(arena.get("id", index))
                target_arena = target_by_id.get(arena_id) or target_arenas[index - 1]
                arena["id"] = int(target_arena.get("id", arena_id))
                # The target profile supplies only the tracking crop geometry.
                # Its visible name is ``ROI n`` and must not leak into the
                # Y-maze experiment vocabulary.
                arena["name"] = f"Arena {arena['id']:02d}"
                arena["mask_locked"] = True
                for key in ("corners_source_px", "mask_polygon_source_px"):
                    arena[key] = json.loads(json.dumps(target_arena.get(key) or []))
            payload["source_video"] = str(video.resolve())
            payload["source_resolution_px"] = [width, height]
            if fps > 0 and frames > 0:
                duration = max(0.0, (frames - 1) / fps)
                payload["setup_frame_seconds"] = min(
                    float(payload.get("setup_frame_seconds", duration) or 0.0), duration,
                )
            payload["template_source_video"] = str(source_video.resolve())
            payload["template_source_profile"] = str(source_profile.resolve())
            payload["template_applied_at"] = time.strftime("%Y-%m-%d %H:%M:%S")
            payload["requires_ymaze_review"] = True
            output.parent.mkdir(parents=True, exist_ok=True)
            temporary = output.with_suffix(output.suffix + ".tmp")
            temporary.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
            temporary.replace(output)
            record.update({
                "profile": str(output), "override_profile": str(output), "override": True,
                "status": tr('● 기준 설정 묶음 적용 · 검토 필요'),
            })
            applied.append(video.name)

        detail = (
            tr('{value1}개 영상에 미로 외곽과 A/B/C/Center를 적용했습니다.\n각 영상의 트래킹 Arena ROI는 유지했습니다.', value1=len(applied))
        )
        if skipped:
            detail += tr('\n\n적용 제외:\n') + "\n".join(skipped[:12])
        QMessageBox.information(
            self, tr('Y-maze 묶음 적용 완료'),
            detail + tr('\n\n전체 검수 카드에서 위치를 확인하고, 어긋난 영상만 클릭해 개별 보정하세요.'),
        )
        self.refresh_ymaze_bundle_table()

    def open_ymaze_review_record(self, record: dict) -> None:
        # Every card opens its own video-specific profile.  A shared template
        # can only be copied through the explicit group-apply command.
        self.open_ymaze_override_editor(record)

    def open_ymaze_override_editor(self, record: dict) -> None:
        video = Path(record.get("video", ""))
        bundle = Path(record.get("bundle", ""))
        override_text = str(record.get("override_profile", "")).strip()
        override = Path(override_text) if override_text else self.ymaze_override_profile(bundle)
        arena_profile = Path(str(record.get("arena_profile", "")))
        if not video.is_file() or not arena_profile.is_file():
            QMessageBox.information(self, tr('ROI 편집 준비 실패'), tr('원본 영상 또는 해당 영상의 트래킹 ROI를 찾지 못했습니다.'))
            return
        override.parent.mkdir(parents=True, exist_ok=True)
        args = [
            str(SCRIPTS / "hagisilta_zone_editor.py"), str(video), "--output", str(override),
            "--preset", "ymaze", "--coordinate-space", "source_px",
        ]
        if self.ymaze_profile_matches_video(override, video):
            args += ["--profile", str(override)]
        args += ["--arena-profile", str(arena_profile)]
        pythonw = Path(sys.executable).with_name("pythonw.exe")
        ok, _pid = QProcess.startDetached(str(pythonw if pythonw.exists() else Path(sys.executable)), args)
        if ok:
            record["profile"] = str(override); record["override"] = True
            self.append_log(tr('Y-maze 영상별 ROI 보정 실행: {value1}', value1=video.name))
        else:
            QMessageBox.critical(self, tr('ROI 편집기'), tr('영상별 Y-maze ROI 편집기를 실행하지 못했습니다.'))

    @staticmethod
    def discover_ymaze_bundles(root: Path) -> list[Path]:
        if not root.is_dir():
            return []
        if any(path.is_dir() for path in root.glob("arena_*")):
            return [root]
        return sorted(
            [
                path for path in root.iterdir()
                if path.is_dir() and any(child.is_dir() for child in path.glob("arena_*"))
            ],
            key=lambda path: path.name.lower(),
        )

    def select_ymaze_video_bundle(self, row: int, _column: int = 0) -> None:
        item = self.ymaze_video_table.item(row, 1) if hasattr(self, "ymaze_video_table") else None
        bundle = str(item.data(Qt.UserRole) or "") if item else ""
        if bundle:
            changed = bundle != self.ymaze_selected_bundle
            self.ymaze_selected_bundle = bundle
            if changed:
                self.refresh_ymaze_bundle_table()
            QTimer.singleShot(0, lambda: self.use_selected_ymaze_bundle_source(False))

    def refresh_ymaze_bundle_table(self) -> None:
        if not hasattr(self, "ymaze_bundle_table"):
            return
        video_table = self.ymaze_video_table if hasattr(self, "ymaze_video_table") else None
        selected_video_keys = {
            str(item.data(Qt.UserRole) or "")
            for row in self.selected_table_rows(video_table)
            if video_table is not None
            and (item := video_table.item(row, 1)) is not None
            and str(item.data(Qt.UserRole) or "")
        }
        current_video_item = (
            video_table.item(video_table.currentRow(), 1)
            if video_table is not None and video_table.currentRow() >= 0
            else None
        )
        current_video_key = str(current_video_item.data(Qt.UserRole) or "") if current_video_item else ""
        arena_table = self.ymaze_bundle_table
        selected_arena_keys = {
            str(item.data(Qt.UserRole + 2) or "")
            for row in self.selected_table_rows(arena_table)
            if (item := arena_table.item(row, 1)) is not None
            and str(item.data(Qt.UserRole + 2) or "")
        }
        current_arena_item = (
            arena_table.item(arena_table.currentRow(), 1)
            if arena_table.currentRow() >= 0
            else None
        )
        current_arena_key = str(current_arena_item.data(Qt.UserRole + 2) or "") if current_arena_item else ""
        root = Path(self.ymaze_tracked_edit.text().strip())
        bundles = self.discover_ymaze_bundles(root)
        sources: list[dict] = []
        hidden_sources: set[str] = set()
        if self.config and self.config.is_file():
            try:
                project_payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
                sources = list((project_metadata(project_payload).get("source_videos", []) or []))
                hidden_sources = self.project_hidden_source_keys(project_payload)
            except Exception:
                sources = []
                hidden_sources = set()
        bundle_sources: dict[str, str] = {}
        for bundle in bundles:
            for metadata_path in sorted(bundle.glob("arena_*/roi-metadata.json")):
                try:
                    source_path = str((json.loads(metadata_path.read_text(encoding="utf-8"))).get("source_video", ""))
                except Exception:
                    source_path = ""
                if source_path:
                    bundle_sources[str(bundle)] = source_path
                    break
        bundles = [
            bundle for bundle in bundles
            if not bundle_sources.get(str(bundle))
            or self.normalized_source_key(bundle_sources[str(bundle)]) not in hidden_sources
        ]
        records: list[tuple[dict | None, Path | None, Path | None]] = []
        used_bundles: set[str] = set()
        for source in sources:
            source_path = str(source.get("path", ""))
            source_stem = Path(source_path).stem.lower()
            match = next(
                (
                    bundle for bundle in bundles
                    if bundle_sources.get(str(bundle))
                    and os.path.normcase(bundle_sources[str(bundle)]) == os.path.normcase(source_path)
                ),
                None,
            )
            if match is None:
                match = next(
                    (
                        bundle for bundle in bundles
                        if bundle.name.lower() == source_stem
                        or bundle.name.lower().startswith(source_stem + "_")
                    ),
                    None,
                )
            if match is not None:
                used_bundles.add(str(match))
                matched_arenas = sorted(path for path in match.glob("arena_*") if path.is_dir())
                records.extend((source, match, arena) for arena in matched_arenas)
            else:
                records.append((source, None, None))
        for bundle in bundles:
            if str(bundle) in used_bundles:
                continue
            records.extend((None, bundle, arena) for arena in sorted(path for path in bundle.glob("arena_*") if path.is_dir()))
        if not self.ymaze_bundle_checks_initialized:
            self.ymaze_checked_bundles = {
                str(arena) for _source, _bundle, arena in records if arena is not None
            }
            self.ymaze_bundle_checks_initialized = True
        else:
            # A hidden/removed source or a different tracking root is not a batch target.
            self.ymaze_checked_bundles.intersection_update(
                str(arena) for _source, _bundle, arena in records if arena is not None
            )
        bundle_records: dict[str, list[tuple[dict | None, Path | None, Path | None]]] = {}
        for record in records:
            key = str(record[1]) if record[1] else f"source:{(record[0] or {}).get('path', '')}"
            bundle_records.setdefault(key, []).append(record)
        if self.ymaze_selected_bundle not in bundle_records:
            self.ymaze_selected_bundle = next(iter(bundle_records), "")
        if hasattr(self, "ymaze_video_table"):
            video_table = self.ymaze_video_table
            video_signals_blocked = video_table.blockSignals(True)
            for old_row in range(video_table.rowCount()):
                old_widget = video_table.cellWidget(old_row, 0)
                if old_widget is not None:
                    video_table.removeCellWidget(old_row, 0)
                    old_widget.hide()
                    old_widget.deleteLater()
            video_table.clearContents()
            video_table.setRowCount(len(bundle_records))
            for video_row, (bundle_key, grouped) in enumerate(bundle_records.items()):
                source, bundle, _arena = grouped[0]
                source_path = str((source or {}).get("path", "")) or bundle_sources.get(str(bundle), "")
                arena_dirs = [item[2] for item in grouped if item[2] is not None]
                pose_count = sum(bool(list(path.glob("*.h5")) or list(path.glob("*.csv"))) for path in arena_dirs)
                name_item = QTableWidgetItem(Path(source_path).name if source_path else (bundle.name if bundle else "-"))
                name_item.setData(Qt.UserRole, bundle_key)
                name_item.setData(Qt.UserRole + 1, source_path)
                name_item.setData(Qt.UserRole + 2, [str(path) for path in arena_dirs])
                name_item.setToolTip(source_path)
                selected_count = sum(str(path) in self.ymaze_checked_bundles for path in arena_dirs)
                video_checkbox = self.set_centered_table_checkbox(
                    video_table, video_row, 0, bool(arena_dirs and selected_count == len(arena_dirs))
                )
                video_checkbox.setEnabled(bool(arena_dirs))
                if arena_dirs and 0 < selected_count < len(arena_dirs):
                    video_checkbox.setTristate(True)
                    video_checkbox.setCheckState(Qt.PartiallyChecked)
                if arena_dirs:
                    video_checkbox.clicked.connect(
                        lambda checked, key=bundle_key, paths=tuple(str(path) for path in arena_dirs):
                            self.set_ymaze_video_checked(key, paths, bool(checked))
                    )
                video_table.setItem(video_row, 1, name_item)
                profile = self.ymaze_profile_for_bundle(bundle) if bundle else Path()
                source_video = Path(source_path) if source_path else Path()
                profile_ready = self.ymaze_profile_matches_video(profile, source_video)
                values = [
                    bundle.name if bundle else tr('미생성'),
                    str(len(arena_dirs)),
                    (
                        tr('모두 있음') if arena_dirs and pose_count == len(arena_dirs)
                        else tr('일부 있음 ({value1}/{value2})', value1=pose_count, value2=len(arena_dirs)) if pose_count
                        else tr('없음')
                    ),
                    tr('개별 보정') if profile_ready else tr('미설정'),
                    tr('준비') if arena_dirs and pose_count == len(arena_dirs) and profile_ready else tr('설정 필요'),
                ]
                for column, value in enumerate(values, start=2):
                    cell = QTableWidgetItem(value); cell.setTextAlignment(Qt.AlignCenter)
                    video_table.setItem(video_row, column, cell)
            video_selection = video_table.selectionModel()
            if video_selection is not None:
                video_selection.clearSelection()
                available_video_keys = {
                    str(video_table.item(row, 1).data(Qt.UserRole) or "")
                    for row in range(video_table.rowCount())
                    if video_table.item(row, 1) is not None
                }
                selected_video_keys.intersection_update(available_video_keys)
                if not selected_video_keys and self.ymaze_selected_bundle in available_video_keys:
                    selected_video_keys.add(self.ymaze_selected_bundle)
                if current_video_key not in available_video_keys:
                    current_video_key = self.ymaze_selected_bundle
                current_index = None
                for row in range(video_table.rowCount()):
                    item = video_table.item(row, 1)
                    key = str(item.data(Qt.UserRole) or "") if item else ""
                    if key in selected_video_keys:
                        video_selection.select(
                            video_table.model().index(row, 0),
                            QItemSelectionModel.Select | QItemSelectionModel.Rows,
                        )
                    if key == current_video_key:
                        current_index = video_table.model().index(row, 0)
                if current_index is not None:
                    video_selection.setCurrentIndex(current_index, QItemSelectionModel.NoUpdate)
            video_table.blockSignals(video_signals_blocked)
        visible_records = bundle_records.get(self.ymaze_selected_bundle, [])
        output_root = Path(self.ymaze_output_edit.text().strip()) if self.ymaze_output_edit.text().strip() else Path()
        latest_result_frame = pd.DataFrame()
        if output_root:
            latest_summary = self.ymaze_project_summary_path(output_root)
            if latest_summary.is_file():
                try:
                    latest_result_frame = pd.read_csv(latest_summary)
                except Exception:
                    latest_result_frame = pd.DataFrame()
        table = self.ymaze_bundle_table
        arena_sorting = table.isSortingEnabled()
        arena_sort_column = table.horizontalHeader().sortIndicatorSection()
        arena_sort_order = table.horizontalHeader().sortIndicatorOrder()
        arena_signals_blocked = table.blockSignals(True)
        table.setSortingEnabled(False)
        for old_row in range(table.rowCount()):
            old_widget = table.cellWidget(old_row, 0)
            if old_widget is not None:
                table.removeCellWidget(old_row, 0)
                old_widget.hide()
                old_widget.deleteLater()
        table.clearContents()
        table.setRowCount(len(visible_records))
        total_arenas = 0; ready_arenas = 0
        for row, (source, bundle, arena_dir) in enumerate(visible_records):
            source_path = str((source or {}).get("path", "")) or bundle_sources.get(str(bundle), "")
            arena_id = self.spatial_arena_id(arena_dir) if arena_dir else None
            arena_video = self.spatial_arena_video(arena_dir) if arena_dir else None
            total_arenas += int(arena_dir is not None)
            pose_ready = bool(arena_dir and (list(arena_dir.glob("*.h5")) or list(arena_dir.glob("*.csv"))))
            profile = self.ymaze_profile_for_bundle(bundle) if arena_id is not None and bundle else Path()
            template_ready = self.ymaze_profile_matches_video(
                profile, Path(source_path) if source_path else Path()
            )
            analyzed = 0
            if not latest_result_frame.empty and bundle is not None:
                try:
                    analyzed = int(
                        (
                            (latest_result_frame["video_bundle"].astype(str) == bundle.name)
                            & (pd.to_numeric(latest_result_frame["arena"], errors="coerce") == arena_id)
                        ).any()
                    )
                except Exception: analyzed = 0
            checked = bool(arena_dir and str(arena_dir) in self.ymaze_checked_bundles)
            checkbox = self.set_centered_table_checkbox(table, row, 0, checked)
            checkbox.setEnabled(arena_dir is not None)
            if arena_dir:
                checkbox.clicked.connect(
                    lambda checked, path=str(arena_dir): self.ymaze_bundle_check_changed(path, bool(checked))
                )
            display_name = Path(source_path).name if source_path else (bundle.name if bundle else "-")
            name = QTableWidgetItem(display_name)
            name.setData(Qt.UserRole, str(bundle) if bundle else "")
            name.setData(Qt.UserRole + 1, source_path or bundle_sources.get(str(bundle), ""))
            name.setData(Qt.UserRole + 2, str(arena_dir) if arena_dir else "")
            name.setData(Qt.UserRole + 3, int(arena_id or 0))
            name.setData(Qt.UserRole + 4, str(arena_video) if arena_video else "")
            name.setToolTip(source_path or (str(bundle) if bundle else ""))
            table.setItem(row, 1, name)
            if arena_dir is None:
                ready_state = tr('Arena 없음')
            elif not pose_ready:
                ready_state = tr('트래킹 좌표 필요')
            elif not template_ready:
                ready_state = tr('영역 설정 필요')
            else:
                ready_state = tr('분석 가능')
            values = [
                f"Arena {arena_id:02d}" if arena_id is not None else "-",
                tr('있음') if pose_ready else tr('없음'),
                tr('완료') if template_ready else tr('미설정'),
                tr('결과 있음') if analyzed else tr('미분석'),
                ready_state,
            ]
            range_record = self.ymaze_range_record(arena_dir) if arena_dir else None
            values.append(
                (range_record["error"] or f"{format_time(range_record['start'])} → {format_time(range_record['end'])} · "
                 f"{format_time(range_record['end'] - range_record['start'])}") if range_record else "-"
            )
            if range_record and range_record["error"]:
                ready_state = tr('구간 확인 필요')
                values[4] = ready_state
            if arena_dir is not None and pose_ready and template_ready and not (range_record and range_record["error"]):
                ready_arenas += 1
            for column, value in enumerate(values, start=2):
                item = SortableTableItem(value); item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row, column, item)
        table.setSortingEnabled(arena_sorting)
        if arena_sorting:
            table.sortItems(arena_sort_column, arena_sort_order)
        arena_selection = table.selectionModel()
        if arena_selection is not None:
            arena_selection.clearSelection()
            available_arena_keys = {
                str(table.item(row, 1).data(Qt.UserRole + 2) or "")
                for row in range(table.rowCount())
                if table.item(row, 1) is not None
                and str(table.item(row, 1).data(Qt.UserRole + 2) or "")
            }
            selected_arena_keys.intersection_update(available_arena_keys)
            if not selected_arena_keys and available_arena_keys:
                first_item = table.item(0, 1)
                first_key = str(first_item.data(Qt.UserRole + 2) or "") if first_item else ""
                if first_key:
                    selected_arena_keys.add(first_key)
            if current_arena_key not in available_arena_keys:
                current_arena_key = next(iter(selected_arena_keys), "")
            current_index = None
            for row in range(table.rowCount()):
                item = table.item(row, 1)
                key = str(item.data(Qt.UserRole + 2) or "") if item else ""
                if key in selected_arena_keys:
                    arena_selection.select(
                        table.model().index(row, 0),
                        QItemSelectionModel.Select | QItemSelectionModel.Rows,
                    )
                if key == current_arena_key:
                    current_index = table.model().index(row, 0)
            if current_index is not None:
                arena_selection.setCurrentIndex(current_index, QItemSelectionModel.NoUpdate)
        table.blockSignals(arena_signals_blocked)
        arena_paths = {str(arena) for _source, _bundle, arena in records if arena is not None}
        selected = len(self.ymaze_checked_bundles.intersection(arena_paths))
        self.set_workflow_badge(
            self.ymaze_input_badge,
            tr('{value1}개 영상 · {value2}/{value3} Arena 사용 · {value4}/{value5} 영역 설정', value1=len(bundle_records), value2=selected, value3=len(arena_paths), value4=ready_arenas, value5=total_arenas),
            bool(bundle_records and selected and total_arenas and ready_arenas == total_arenas),
        )
        self.update_ymaze_analysis_selection_summary()

    def ymaze_range_record(self, arena: Path) -> dict:
        video = self.spatial_arena_video(arena)
        duration = self.nort_video_duration(video)
        start, end, error, source_error, configured = 0.0, duration, "", "", False
        try:
            saved = load_ymaze_range(arena)
            configured = bool(saved)
            start = float(saved.get("start_seconds", 0.0))
            end = float(saved.get("end_seconds", duration))
            if not all(math.isfinite(value) for value in (start, end)):
                raise ValueError(tr('저장된 분석 구간이 유효한 숫자가 아닙니다.'))
        except (OSError, ValueError, TypeError) as exc:
            source_error = str(exc)
            start, end = 0.0, duration
        try:
            validate_range(start, end, duration)
        except ValueError as exc:
            error = str(exc)
        return {"id": str(arena), "label": f"{arena.parent.name} · {arena.name}",
                "video": video, "start": start, "end": end, "duration": duration,
                "error": source_error or error, "source_error": source_error, "configured": configured}

    def selected_ymaze_range_record(self) -> dict | None:
        rows = self.selected_table_rows(self.ymaze_bundle_table)
        if len(rows) != 1:
            return None
        item = self.ymaze_bundle_table.item(rows[0], 1)
        path = str(item.data(Qt.UserRole + 2) or "") if item else ""
        return self.ymaze_range_record(Path(path)) if path else None

    def open_ymaze_analysis_range_dialog(self) -> None:
        record = self.selected_ymaze_range_record()
        if not record or not record["video"]:
            QMessageBox.information(self, tr('분석 구간'), tr('Arena 영상이 있는 파란 행 하나를 선택하세요.'))
            return
        try:
            if record["source_error"]:
                QMessageBox.warning(self, tr('저장된 구간 확인'), record["source_error"] + tr('\n전체 영상 범위로 편집기를 엽니다. 시작·종료를 다시 지정한 뒤 저장하면 기존 설정이 교체됩니다.'))
            records = [record] + [self.ymaze_range_record(arena) for arena in same_video_ymaze_arenas(Path(record["id"]))[1:]]
            dialog = NortAnalysisRangeDialog(
                record["video"], record["start"], record["end"], self, experiment_name="Y-maze",
                range_records=records, on_save=self.save_ymaze_range_proposals,
            )
            dialog.exec()
        except (OSError, ValueError) as error:
            QMessageBox.warning(self, tr('분석 구간'), str(error))

    def save_ymaze_range_proposals(self, proposals: list[dict]) -> None:
        # Validate the entire request before writing any sidecar. Original video,
        # tracking coordinates and other experiment settings are never touched.
        for item in proposals:
            validate_range(item["new_start"], item["new_end"], item["duration"])
        saved = 0
        try:
            for item in proposals:
                save_ymaze_range(Path(item["id"]), item["new_start"], item["new_end"], item["duration"])
                saved += 1
        except (OSError, ValueError) as error:
            raise OSError(tr('{value1}/{value2}개 ROI 저장 완료. 나머지는 저장하지 못했습니다.\n{value3}', value1=saved, value2=len(proposals), value3=error)) from error
        finally:
            self.refresh_ymaze_bundle_table()

    def open_ymaze_batch_range_dialog(self) -> None:
        self.sync_visible_ymaze_bundle_checks()
        records = [self.ymaze_range_record(Path(path)) for path in sorted(self.ymaze_checked_bundles) if Path(path).is_dir()]
        if not records:
            QMessageBox.information(self, tr('구간 일괄 설정'), tr('적용할 영상·Arena의 사용 체크를 켜세요.'))
            return
        selected = self.selected_ymaze_range_record() or records[0]
        dialog = BatchAnalysisRangeDialog(records, (selected["start"], selected["end"]), self)
        if dialog.exec() != QDialog.Accepted:
            return
        saved, errors = 0, []
        for item in dialog.accepted_proposals():
            try:
                save_ymaze_range(Path(item["id"]), item["new_start"], item["new_end"], item["duration"])
                saved += 1
            except (OSError, ValueError) as error:
                errors.append(f"{item['label']}: {error}")
        self.refresh_ymaze_bundle_table()
        QMessageBox.information(self, tr('구간 적용 결과'), tr('{value1}개 저장 · {value2}개 미적용\n', value1=saved, value2=len(records) - saved) + "\n".join(errors))

    def update_ymaze_analysis_selection_summary(self) -> None:
        self.refresh_ymaze_analysis_bodyparts()
        if not hasattr(self, "ymaze_analysis_selection_value"):
            return
        selected = sorted(
            (Path(value) for value in self.ymaze_checked_bundles if Path(value).is_dir()),
            key=lambda path: (path.parent.name.lower(), int(self.spatial_arena_id(path) or 0)),
        )
        if not selected:
            self.ymaze_analysis_selection_value.setText(tr('선택된 Arena 없음'))
            self.ymaze_analysis_selection_detail.setText(
                tr('위 표의 사용 체크로 실행 대상을 선택하세요.')
            )
            self.ymaze_analysis_selection_summary.setToolTip("")
            return
        grouped: dict[str, list[int]] = {}
        for arena_dir in selected:
            grouped.setdefault(arena_dir.parent.name, []).append(
                int(self.spatial_arena_id(arena_dir) or 0)
            )
        self.ymaze_analysis_selection_value.setText(
            tr('{value1}개 영상 · {value2} Arena', value1=len(grouped), value2=len(selected))
        )
        details = [
            f"{bundle} · " + ", ".join(f"Arena {arena_id:02d}" for arena_id in arenas if arena_id)
            for bundle, arenas in grouped.items()
        ]
        full_detail = "\n".join(details)
        inline_detail = "  |  ".join(details)
        if len(inline_detail) > 170:
            inline_detail = inline_detail[:167].rstrip() + "…"
        self.ymaze_analysis_selection_detail.setText(inline_detail)
        self.ymaze_analysis_selection_summary.setToolTip(full_detail)

    def ymaze_bundle_check_changed(self, path: str, checked: bool) -> None:
        if checked: self.ymaze_checked_bundles.add(path)
        else: self.ymaze_checked_bundles.discard(path)
        existing = [Path(value) for value in self.ymaze_checked_bundles if Path(value).is_dir()]
        selected = len(existing); videos = {str(path.parent) for path in existing}
        self.set_workflow_badge(self.ymaze_input_badge, tr('{value1}개 영상 · {value2}개 Arena 선택', value1=len(videos), value2=selected), selected > 0)
        self.refresh_ymaze_video_check_states()
        self.update_ymaze_analysis_selection_summary()

    def set_ymaze_video_checked(
        self, bundle_key: str, arena_paths: tuple[str, ...], checked: bool,
    ) -> None:
        for arena_path in arena_paths:
            if checked:
                self.ymaze_checked_bundles.add(arena_path)
            else:
                self.ymaze_checked_bundles.discard(arena_path)
        if bundle_key == self.ymaze_selected_bundle:
            for row in range(self.ymaze_bundle_table.rowCount()):
                item = self.ymaze_bundle_table.item(row, 1)
                checkbox = self.table_checkbox(self.ymaze_bundle_table, row, 0)
                arena_path = str(item.data(Qt.UserRole + 2) or "") if item else ""
                if checkbox and arena_path in arena_paths:
                    checkbox.setChecked(checked)
        self.refresh_ymaze_video_check_states()
        existing = [Path(value) for value in self.ymaze_checked_bundles if Path(value).is_dir()]
        videos = {str(path.parent) for path in existing}
        self.set_workflow_badge(
            self.ymaze_input_badge,
            tr('{value1}개 영상 · {value2}개 Arena 선택', value1=len(videos), value2=len(existing)),
            bool(existing),
        )
        self.update_ymaze_analysis_selection_summary()

    def refresh_ymaze_video_check_states(self) -> None:
        if not hasattr(self, "ymaze_video_table"):
            return
        table = self.ymaze_video_table
        for row in range(table.rowCount()):
            item = table.item(row, 1)
            checkbox = self.table_checkbox(table, row, 0)
            arena_paths = list(item.data(Qt.UserRole + 2) or []) if item else []
            if checkbox is None:
                continue
            selected_count = sum(path in self.ymaze_checked_bundles for path in arena_paths)
            checkbox.blockSignals(True)
            checkbox.setTristate(bool(arena_paths and 0 < selected_count < len(arena_paths)))
            checkbox.setCheckState(
                Qt.PartiallyChecked if arena_paths and 0 < selected_count < len(arena_paths)
                else (Qt.Checked if arena_paths and selected_count == len(arena_paths) else Qt.Unchecked)
            )
            checkbox.blockSignals(False)

    def set_all_ymaze_video_checks(self, checked: bool) -> None:
        table = self.ymaze_video_table
        all_paths: set[str] = set()
        for row in range(table.rowCount()):
            item = table.item(row, 1)
            if item:
                all_paths.update(str(path) for path in (item.data(Qt.UserRole + 2) or []))
        if checked:
            self.ymaze_checked_bundles.update(all_paths)
        else:
            self.ymaze_checked_bundles.difference_update(all_paths)
        self.refresh_ymaze_video_check_states()
        if hasattr(self, "ymaze_bundle_table"):
            for row in range(self.ymaze_bundle_table.rowCount()):
                item = self.ymaze_bundle_table.item(row, 1)
                checkbox = self.table_checkbox(self.ymaze_bundle_table, row, 0)
                arena_path = str(item.data(Qt.UserRole + 2) or "") if item else ""
                if checkbox and arena_path:
                    checkbox.setChecked(arena_path in self.ymaze_checked_bundles)
        existing = [Path(value) for value in self.ymaze_checked_bundles if Path(value).is_dir()]
        videos = {str(path.parent) for path in existing}
        self.set_workflow_badge(
            self.ymaze_input_badge,
            tr('{value1}개 영상 · {value2}개 Arena 선택', value1=len(videos), value2=len(existing)),
            bool(existing),
        )
        self.update_ymaze_analysis_selection_summary()

    def set_all_ymaze_bundle_checks(self, checked: bool) -> None:
        table = self.ymaze_bundle_table
        for row in range(table.rowCount()):
            checkbox = self.table_checkbox(table, row, 0)
            item = table.item(row, 1)
            arena_path = str(item.data(Qt.UserRole + 2) or "") if item else ""
            if checkbox and checkbox.isEnabled() and arena_path:
                checkbox.setChecked(checked)
                self.ymaze_bundle_check_changed(arena_path, checked)
        self.update_ymaze_analysis_selection_summary()

    def sync_visible_ymaze_bundle_checks(self) -> None:
        """Copy the visible checkbox state into the persistent analysis selection."""
        table = self.ymaze_bundle_table
        for row in range(table.rowCount()):
            item = table.item(row, 1)
            checkbox = self.table_checkbox(table, row, 0)
            arena_path = str(item.data(Qt.UserRole + 2) or "") if item else ""
            if not arena_path or checkbox is None or not checkbox.isEnabled():
                continue
            if checkbox.isChecked():
                self.ymaze_checked_bundles.add(arena_path)
            else:
                self.ymaze_checked_bundles.discard(arena_path)

    def run_ymaze_analysis(self) -> None:
        self.sync_visible_ymaze_bundle_checks()
        items = []
        range_errors = []
        for arena_text in sorted(self.ymaze_checked_bundles):
            arena_dir = Path(arena_text)
            if not arena_dir.is_dir():
                continue
            arena_id = int(self.spatial_arena_id(arena_dir) or 0)
            if arena_id <= 0:
                continue
            metadata_path = arena_dir / "roi-metadata.json"
            try:
                metadata = json.loads(metadata_path.read_text(encoding="utf-8")) if metadata_path.is_file() else {}
            except Exception:
                metadata = {}
            range_record = self.ymaze_range_record(arena_dir)
            if range_record["error"]:
                range_errors.append(f"{range_record['label']}: {range_record['error']}")
            items.append({
                "bundle": str(arena_dir.parent), "arena_id": arena_id,
                "profile": str(self.ymaze_profile_for_bundle(arena_dir.parent)),
                "video": str(metadata.get("source_video", "")),
                "analysis_range": {"start_seconds": range_record["start"], "end_seconds": range_record["end"]},
            })
        if range_errors:
            QMessageBox.warning(self, tr('분석 구간 확인'), "\n".join(range_errors))
            return
        if not items:
            QMessageBox.information(self, tr('추적 결과 필요'), tr('분석할 영상×Arena 행을 하나 이상 체크하세요.'))
            return
        missing_profiles = sorted({
            Path(item["profile"]).name
            for item in items
            if not self.ymaze_profile_matches_video(Path(item["profile"]), Path(item["video"]))
        })
        if missing_profiles:
            QMessageBox.information(
                self, tr('ABC 템플릿 필요'),
                tr('선택한 Arena에 필요한 템플릿을 먼저 저장하세요.\n\n') + "\n".join(missing_profiles),
            )
            return
        output = Path(self.ymaze_output_edit.text().strip()) if self.ymaze_output_edit.text().strip() else (
            (project_output_root(self.config.parent) if self.config else self.work_root) / "ymaze-pilot"
        )
        self.ymaze_output_edit.setText(str(output))
        selected_bodyparts = self.selected_ymaze_bodyparts()
        if not selected_bodyparts:
            QMessageBox.information(self, tr('판정 신체점 필요'), tr('A/B/C/Center 판정에 사용할 신체점을 하나 이상 체크하세요.'))
            return
        plan = {
            "items": items,
            "pcutoff": self.ymaze_pcutoff.value(), "bodyparts": selected_bodyparts,
            "minimum_dwell": self.ymaze_minimum_dwell.value(), "bridge_gap": self.ymaze_bridge_gap.value(),
            "reentry_center_dwell": self.ymaze_reentry_center_dwell.value(),
        }
        runtime = (project_state_root(self.config.parent) if self.config else self.work_root) / "runtime"
        runtime.mkdir(parents=True, exist_ok=True)
        plan_path = runtime / "ymaze-batch-plan.json"
        plan_path.write_text(json.dumps(plan, ensure_ascii=False, indent=2), encoding="utf-8")
        self.start_process(SCRIPTS / "hagisilta_ymaze_analysis.py", ["batch", str(plan_path), str(output)], self.ymaze_analysis_finished)

    def ymaze_analysis_finished(self, code: int) -> None:
        if code == 0:
            self.refresh_ymaze_results()
            QMessageBox.information(self, tr('Y-maze 분석 완료'), tr('ABC 진입 순서·자발적 교대율·궤적·히트맵을 생성했습니다.'))
        else:
            self.set_workflow_badge(self.ymaze_run_badge, tr('분석 실패'), False)
            QMessageBox.critical(self, tr('Y-maze 분석 실패'), tr('실행 로그에서 오류 내용을 확인하세요.'))

    def ymaze_project_summary_path(self, output_root: Path | None = None) -> Path:
        output_root = output_root or Path(self.ymaze_output_edit.text())
        latest_run = output_root / "latest-run.json"
        if latest_run.is_file():
            try:
                latest = Path(str(json.loads(latest_run.read_text(encoding="utf-8")).get("summary_csv", "")))
                if latest.is_file():
                    return latest
            except Exception:
                pass
        pointer = output_root / "project-ymaze-summary.latest.json"
        if pointer.is_file():
            try:
                latest = Path(str(json.loads(pointer.read_text(encoding="utf-8")).get("csv", "")))
                if latest.is_file():
                    return latest
            except Exception:
                pass
        standard = output_root / "project-ymaze-summary.csv"
        if standard.is_file():
            return standard
        legacy = output_root / "ymaze-summary.csv"
        return legacy if legacy.is_file() else standard

    def displayed_ymaze_summary_path(self) -> Path:
        displayed = Path(str(getattr(self, "ymaze_display_summary_path", "") or ""))
        if displayed.is_file():
            return displayed
        output_root = Path(self.ymaze_output_edit.text())
        return self.ymaze_project_summary_path(output_root)

    def ymaze_summary_for_run_directory(self, run_directory: Path) -> Path:
        pointer = run_directory / "project-ymaze-summary.latest.json"
        if pointer.is_file():
            try:
                summary = Path(str(json.loads(pointer.read_text(encoding="utf-8")).get("csv", "")))
                if summary.is_file():
                    return summary
            except Exception:
                pass
        standard = run_directory / "project-ymaze-summary.csv"
        if standard.is_file():
            return standard
        candidates = sorted(
            run_directory.glob("project-ymaze-summary*.csv"),
            key=lambda path: path.stat().st_mtime,
            reverse=True,
        )
        return candidates[0] if candidates else standard

    def choose_ymaze_result_run(self) -> None:
        if not self.ymaze_output_edit.text().strip():
            return
        output_root = Path(self.ymaze_output_edit.text())
        run_root = output_root / "runs"
        if not run_root.is_dir() or not any(path.is_dir() for path in run_root.glob("run_*")):
            QMessageBox.information(self, tr('Y-maze 분석 이력'), tr('저장된 Y-maze 분석 실행이 없습니다.'))
            return
        selected = QFileDialog.getExistingDirectory(
            self,
            tr('이전 Y-maze 실행 선택'),
            str(run_root),
        )
        if not selected:
            return
        summary_path = self.ymaze_summary_for_run_directory(Path(selected))
        if not summary_path.is_file():
            QMessageBox.warning(
                self,
                tr('Y-maze 분석 이력'),
                tr('선택한 폴더에서 Y-maze 분석 결과를 찾지 못했습니다.'),
            )
            return
        self.refresh_ymaze_results(summary_path)

    def refresh_ymaze_results(self, requested_summary: Path | None = None) -> None:
        if not hasattr(self, "ymaze_result_table") or not self.ymaze_output_edit.text().strip():
            return
        output_root = Path(self.ymaze_output_edit.text())
        summary_path = Path(requested_summary) if requested_summary else self.ymaze_project_summary_path(output_root)
        if not summary_path.is_file():
            self.ymaze_display_summary_path = Path()
            if hasattr(self, "ymaze_result_run_label"):
                self.ymaze_result_run_label.setText(tr('표시 결과 없음'))
                self.ymaze_result_run_label.setToolTip(tr('저장된 분석 결과가 없습니다.'))
            return
        try:
            frame = pd.read_csv(summary_path)
        except Exception as error:
            self.append_log(tr('Y-maze 결과 로드 실패: {value1}', value1=error))
            return
        table = self.ymaze_result_table
        selected_result_keys = {
            (
                str(item.data(Qt.UserRole + 11) or item.text()),
                int(item.data(Qt.UserRole + 10) or 0),
            )
            for row in self.selected_table_rows(table)
            if (item := table.item(row, 0)) is not None
        }
        current_result_item = table.item(table.currentRow(), 0) if table.currentRow() >= 0 else None
        current_result_key = (
            (
                str(current_result_item.data(Qt.UserRole + 11) or current_result_item.text()),
                int(current_result_item.data(Qt.UserRole + 10) or 0),
            )
            if current_result_item is not None
            else None
        )
        result_sorting = table.isSortingEnabled()
        result_sort_column = table.horizontalHeader().sortIndicatorSection()
        result_sort_order = table.horizontalHeader().sortIndicatorOrder()
        result_signals_blocked = table.blockSignals(True)
        table.setSortingEnabled(False)
        table.setRowCount(len(frame))
        for row_index, row in frame.iterrows():
            alt = row.get("alternation_percent", float("nan"))
            alt_text = tr('산출 불가') if pd.isna(alt) else f"{float(alt):.1f}%"
            sequence = str(row.get("sequence", ""))
            display_sequence = sequence if len(sequence) <= 42 else sequence[:39] + "…"
            bundle = str(row.get("video_bundle", output_root.name))
            total_entries = int(row.get("total_entries", 0))
            successes = int(row.get("alternation_successes", 0))
            opportunities = int(row.get("alternation_opportunities", 0))
            entries_a = int(row.get("entries_a", 0))
            entries_b = int(row.get("entries_b", 0))
            entries_c = int(row.get("entries_c", 0))
            dwell_a = float(row.get("dwell_a_seconds", 0))
            dwell_b = float(row.get("dwell_b_seconds", 0))
            dwell_c = float(row.get("dwell_c_seconds", 0))
            center_seconds = float(row.get("center_seconds", 0))
            valid_pose_percent = float(row.get("valid_pose_percent", 0))
            arena_id = int(row.get("arena", row_index + 1))
            arena_name = str(row.get("arena_name", row.get("arena", ""))).strip()
            arena_match = re.fullmatch(
                r"(?:arena|roi|y-maze)\s*0*(\d+)", arena_name, re.IGNORECASE
            )
            if arena_match:
                arena_name = f"Arena {int(arena_match.group(1)):02d}"
            elif not arena_name:
                arena_name = f"Arena {arena_id:02d}"
            values = [
                bundle, arena_name, display_sequence, str(total_entries),
                f"{successes} / {opportunities}", alt_text,
                str(entries_a), str(entries_b), str(entries_c),
                f"{dwell_a:.1f}", f"{dwell_b:.1f}", f"{dwell_c:.1f}",
                f"{center_seconds:.1f}", f"{valid_pose_percent:.1f}%",
            ]
            sort_keys = [
                bundle.casefold(), arena_id, sequence.casefold(), total_entries,
                (successes, opportunities), -1.0 if pd.isna(alt) else float(alt),
                entries_a, entries_b, entries_c, dwell_a, dwell_b, dwell_c,
                center_seconds, valid_pose_percent,
            ]
            for column, (value, sort_key) in enumerate(zip(values, sort_keys)):
                item = SortableTableItem(value)
                item.setData(Qt.UserRole, sort_key)
                item.setData(Qt.UserRole + 10, arena_id)
                item.setData(Qt.UserRole + 11, bundle)
                if pd.notna(row.get("analysis_start_seconds")) and pd.notna(row.get("analysis_end_seconds")):
                    item.setToolTip(
                        tr('{value1}\n이 결과의 분석 구간: {value2} → {value3}\n구간 설정을 바꾼 뒤에는 다시 분석해야 합니다.', value1=value, value2=format_time(row['analysis_start_seconds']), value3=format_time(row['analysis_end_seconds']))
                    )
                if column != 2:
                    item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row_index, column, item)
        table.setSortingEnabled(result_sorting)
        if result_sorting:
            table.sortItems(result_sort_column, result_sort_order)
        result_selection = table.selectionModel()
        if result_selection is not None:
            result_selection.clearSelection()
            available_result_keys = {
                (
                    str(table.item(row, 0).data(Qt.UserRole + 11) or table.item(row, 0).text()),
                    int(table.item(row, 0).data(Qt.UserRole + 10) or 0),
                )
                for row in range(table.rowCount())
                if table.item(row, 0) is not None
            }
            selected_result_keys.intersection_update(available_result_keys)
            if not selected_result_keys and available_result_keys:
                first_item = table.item(0, 0)
                first_key = (
                    str(first_item.data(Qt.UserRole + 11) or first_item.text()),
                    int(first_item.data(Qt.UserRole + 10) or 0),
                )
                selected_result_keys.add(first_key)
            if current_result_key not in available_result_keys:
                current_result_key = next(iter(selected_result_keys), None)
            current_index = None
            for row in range(table.rowCount()):
                item = table.item(row, 0)
                if item is None:
                    continue
                key = (
                    str(item.data(Qt.UserRole + 11) or item.text()),
                    int(item.data(Qt.UserRole + 10) or 0),
                )
                if key in selected_result_keys:
                    result_selection.select(
                        table.model().index(row, 0),
                        QItemSelectionModel.Select | QItemSelectionModel.Rows,
                    )
                if key == current_result_key:
                    current_index = table.model().index(row, 0)
            if current_index is not None:
                result_selection.setCurrentIndex(current_index, QItemSelectionModel.NoUpdate)
        table.blockSignals(result_signals_blocked)
        self.ymaze_display_summary_path = summary_path
        if hasattr(self, "ymaze_result_run_label"):
            latest_summary = self.ymaze_project_summary_path(output_root)
            is_latest = latest_summary.is_file() and summary_path.resolve() == latest_summary.resolve()
            run_name = summary_path.parent.name
            self.ymaze_result_run_label.setText(
                tr('최신 분석 결과') if is_latest else tr('분석 이력 · {value1}', value1=run_name)
            )
            self.ymaze_result_run_label.setToolTip(str(summary_path.parent))
        self.set_workflow_badge(self.ymaze_run_badge, tr('분석 완료'), True)
        self.set_workflow_badge(self.ymaze_result_badge, tr('{value1}개 Arena', value1=len(frame)), True)
        self.refresh_ymaze_bundle_table()
        self.refresh_dashboard_video_status()

    def selected_ymaze_result(self) -> tuple[str, int] | None:
        row = self.ymaze_result_table.currentRow()
        if row < 0 or not self.ymaze_result_table.item(row, 0):
            QMessageBox.information(self, tr('Y-maze 결과'), tr('결과 표에서 Arena를 먼저 선택하세요.'))
            return None
        item = self.ymaze_result_table.item(row, 0)
        return str(item.data(Qt.UserRole + 11) or item.text()), int(item.data(Qt.UserRole + 10) or 1)

    def ymaze_decision_roi_zones(
        self, tracked_bundle: Path, arena: int, zones_file: Path | None = None,
    ) -> list[dict]:
        """Load the exact analysis zones and convert source coordinates to the cropped Arena video."""
        if zones_file and zones_file.is_file():
            snapshot = json.loads(zones_file.read_text(encoding="utf-8"))
            coordinate_space = str(snapshot.get("coordinate_space", "source_px"))
            region = snapshot.get("region")
        else:
            profile_path = self.ymaze_profile_for_bundle(tracked_bundle)
            metadata_path = tracked_bundle / f"arena_{arena:02d}" / "roi-metadata.json"
            try:
                metadata = json.loads(metadata_path.read_text(encoding="utf-8")) if metadata_path.is_file() else {}
            except Exception:
                metadata = {}
            source_video = Path(str(metadata.get("source_video", "")))
            if not self.ymaze_profile_matches_video(profile_path, source_video):
                return []
            profile = json.loads(profile_path.read_text(encoding="utf-8"))
            coordinate_space = str(profile.get("coordinate_space", "source_px"))
            region = next(
                (item for item in profile.get("arenas", []) if int(item.get("id", 0) or 0) == int(arena)),
                None,
            )
        if not region:
            return []
        offset = np.zeros(2, dtype=float)
        metadata_path = tracked_bundle / f"arena_{arena:02d}" / "roi-metadata.json"
        if coordinate_space != "arena_crop_px" and metadata_path.is_file():
            metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
            offset = np.asarray(metadata.get("source_offset_px", [0, 0]), dtype=float)
        labels = {"arm_a": "A", "arm_b": "B", "arm_c": "C", "center": "Center"}
        zones: list[dict] = []
        for zone in region.get("zones", []):
            polygon = np.asarray(zone.get("polygon_source_px") or [], dtype=float)
            if len(polygon) < 3:
                continue
            zone_id = str(zone.get("id", ""))
            zones.append({
                "id": zone_id,
                "label": labels.get(zone_id, str(zone.get("name") or zone_id)),
                "polygon": (polygon - offset).tolist(),
            })
        return zones

    def open_selected_ymaze_decision_video(self) -> None:
        selected = self.selected_ymaze_result()
        if selected is None:
            return
        bundle, arena = selected
        output_root = Path(self.ymaze_output_edit.text())
        summary_path = self.displayed_ymaze_summary_path()
        try:
            summary = pd.read_csv(summary_path)
            match = summary[
                (summary["video_bundle"].astype(str) == bundle)
                & (pd.to_numeric(summary["arena"], errors="coerce") == arena)
            ]
            if match.empty:
                raise ValueError(tr('선택한 Arena 결과가 없습니다.'))
            playlist: list[dict] = []
            selected_entry: dict | None = None
            for _row_index, row in summary.iterrows():
                row_bundle = str(row.get("video_bundle", ""))
                row_arena = int(pd.to_numeric(pd.Series([row.get("arena")]), errors="coerce").fillna(0).iloc[0])
                tracked_bundle = Path(str(row.get("tracked_bundle", "")))
                arena_dir = tracked_bundle / f"arena_{row_arena:02d}"
                video = self.spatial_arena_video(arena_dir)
                frames_file = Path(str(row.get("frames_file", "")))
                events_file = Path(str(row.get("events_file", "")))
                if video is None or not frames_file.is_file():
                    continue
                zones_file = Path(str(row.get("zones_file", "")))
                entry = {
                    "video": str(video), "frames": str(frames_file), "events": str(events_file),
                    "roi_zones": self.ymaze_decision_roi_zones(tracked_bundle, row_arena, zones_file),
                    "summary": row.to_dict(),
                }
                playlist.append(entry)
                if row_bundle == bundle and row_arena == arena:
                    selected_entry = entry
            if selected_entry is None:
                raise ValueError(tr('선택한 Arena 영상 또는 프레임별 판정 파일을 찾지 못했습니다.'))
            BehaviorDecisionViewer(
                Path(selected_entry["video"]), Path(selected_entry["frames"]), "ymaze",
                Path(selected_entry["events"]), self,
                roi_zones=selected_entry["roi_zones"], summary=selected_entry["summary"],
                playlist=playlist,
            ).exec()
        except Exception as error:
            QMessageBox.information(self, tr('Y-maze 판정 영상'), str(error))

    def open_selected_ymaze_visual(self) -> None:
        selected = self.selected_ymaze_result()
        if selected is None:
            return
        bundle, arena = selected
        entries: list[dict] = []
        current_index = 0
        try:
            summary = pd.read_csv(self.displayed_ymaze_summary_path())
            for _row_index, result in summary.iterrows():
                result_bundle = str(result.get("video_bundle", ""))
                result_arena = int(pd.to_numeric(pd.Series([result.get("arena")]), errors="coerce").fillna(0).iloc[0])
                tracked_bundle = Path(str(result.get("tracked_bundle", "")))
                arena_dir = tracked_bundle / f"arena_{result_arena:02d}"
                video = self.spatial_arena_video(arena_dir)
                frames_file = Path(str(result.get("frames_file", "")))
                zones_file = Path(str(result.get("zones_file", "")))
                if video is None or not frames_file.is_file():
                    continue
                zones = self.ymaze_decision_roi_zones(tracked_bundle, result_arena, zones_file)
                if result_bundle == bundle and result_arena == arena:
                    current_index = len(entries)
                entries.append({
                    "video": str(video),
                    "frames": str(frames_file),
                    "zones": zones,
                    "summary": result.where(pd.notna(result), "").to_dict(),
                })
        except Exception as error:
            QMessageBox.warning(self, tr('Y-maze 궤적·히트맵 편집'), str(error))
            return
        if not entries:
            QMessageBox.information(
                self, tr('Y-maze 궤적·히트맵 편집'),
                tr('원본 Arena 영상·프레임 판정 CSV·Y-maze 구역 설정을 찾지 못했습니다.'),
            )
            return
        try:
            YMazeVisualComposer(entries, current_index, self).exec()
        except Exception as error:
            QMessageBox.warning(self, tr('Y-maze 궤적·히트맵 편집 실패'), str(error))

    def open_selected_ymaze_events(self) -> None:
        selected = self.selected_ymaze_result()
        if selected is None: return
        bundle, arena = selected
        path = Path()
        try:
            summary = pd.read_csv(self.displayed_ymaze_summary_path())
            match = summary[
                (summary["video_bundle"].astype(str) == bundle)
                & (pd.to_numeric(summary["arena"], errors="coerce") == arena)
            ]
            if not match.empty:
                path = Path(str(match.iloc[0].get("events_file", "")))
        except Exception:
            pass
        if not path.is_file():
            path = Path(self.ymaze_output_edit.text()) / bundle / f"arena_{arena:02d}_arm_events.csv"
        if path.is_file(): QDesktopServices.openUrl(QUrl.fromLocalFile(str(path)))
        else: QMessageBox.information(self, tr('팔 진입 사건'), tr('팔 진입 사건 CSV가 없습니다.'))

    def open_ymaze_result_folder(self) -> None:
        root = Path(self.ymaze_output_edit.text()) if self.ymaze_output_edit.text().strip() else None
        summary = self.displayed_ymaze_summary_path() if root else Path()
        path = summary.parent if summary.is_file() else root
        if path and path.is_dir(): QDesktopServices.openUrl(QUrl.fromLocalFile(str(path)))
        else: QMessageBox.information(self, tr('Y-maze 결과'), tr('아직 생성된 분석 결과가 없습니다.'))

