    def choose_zone_video(self) -> None:
        start = self.zone_video_edit.text().strip() or str(self.config.parent if self.config else self.work_root)
        selected, _ = QFileDialog.getOpenFileName(
            self, tr('구역 템플릿 기준 영상'), start, tr('영상 (*.avi *.mp4 *.mov *.mkv *.wmv);;모든 파일 (*.*)')
        )
        if not selected:
            return
        self.zone_video_edit.setText(selected)
        if not self.zone_profile_edit.text().strip():
            root = project_state_root(self.config.parent) / "zone_profiles" if self.config else self.work_root / "zone_profiles"
            self.zone_profile_edit.setText(str(root / f"{Path(selected).stem}_zones.json"))

    def choose_zone_profile(self) -> None:
        start = self.zone_profile_edit.text().strip() or str(self.config.parent if self.config else self.work_root)
        selected, _ = QFileDialog.getOpenFileName(self, tr('구역 템플릿'), start, tr('HAGISILTA 구역 템플릿 (*.json)'))
        if selected:
            self.zone_profile_edit.setText(selected)
            self.set_workflow_badge(self.zone_template_badge, tr('템플릿 준비'), True)

    def choose_zone_tracked(self) -> None:
        start = self.zone_tracked_edit.text().strip()
        if not start and self.config:
            start = str(self.project_tracking_root())
        selected = QFileDialog.getExistingDirectory(self, tr('한 영상의 추적 영역 묶음'), start or str(self.work_root))
        if not selected:
            return
        self.zone_tracked_edit.setText(selected)
        base = project_output_root(self.config.parent) / "zone-analysis" if self.config else self.work_root / "zone-analysis"
        self.zone_output_edit.setText(str(base / Path(selected).name))
        self.set_workflow_badge(self.zone_analysis_badge, tr('분석 준비'), True)
        self.refresh_zone_results()

    def open_zone_editor(self) -> None:
        video = Path(self.zone_video_edit.text().strip())
        if not video.is_file():
            QMessageBox.information(self, tr('원본 영상 필요'), tr('구역 배치가 보이는 원본 영상을 먼저 선택하세요.'))
            return
        profile = Path(self.zone_profile_edit.text().strip()) if self.zone_profile_edit.text().strip() else None
        if profile is None:
            root = project_state_root(self.config.parent) / "zone_profiles" if self.config else self.work_root / "zone_profiles"
            profile = root / f"{video.stem}_zones.json"
            self.zone_profile_edit.setText(str(profile))
        args = [str(SCRIPTS / "hagisilta_zone_editor.py"), str(video), "--output", str(profile)]
        if profile.is_file():
            args += ["--profile", str(profile)]
        pythonw = Path(sys.executable).with_name("pythonw.exe")
        ok, _pid = QProcess.startDetached(str(pythonw if pythonw.exists() else Path(sys.executable)), args)
        if ok:
            self.append_log(tr('구역 템플릿 Studio 실행: {value1}', value1=video.name))
        else:
            QMessageBox.critical(self, tr('구역 편집기'), tr('구역 템플릿 Studio를 실행하지 못했습니다.'))

    def run_zone_analysis(self) -> None:
        if not self.zone_bodypart.currentData():
            QMessageBox.information(self, tr('판정 신체점 필요'), tr('모델의 신체점 정보를 확인하고 판정할 점을 선택하세요.'))
            return
        tracked = Path(self.zone_tracked_edit.text().strip())
        profile = Path(self.zone_profile_edit.text().strip())
        if not tracked.is_dir() or not list(tracked.glob("arena_*")):
            QMessageBox.information(self, tr('추적 결과 필요'), tr('arena_01 등이 들어 있는 한 영상의 추적 결과 폴더를 선택하세요.'))
            return
        if not profile.is_file():
            QMessageBox.information(self, tr('구역 템플릿 필요'), tr('다각형 ROI·구역 템플릿을 먼저 저장하세요.'))
            return
        output = Path(self.zone_output_edit.text().strip()) if self.zone_output_edit.text().strip() else (
            (project_output_root(self.config.parent) if self.config else self.work_root) / "zone-analysis" / tracked.name
        )
        self.zone_output_edit.setText(str(output))
        self.start_process(
            SCRIPTS / "hagisilta_zone_analysis.py",
            [str(tracked), str(profile), str(output), "--pcutoff", str(self.zone_pcutoff.value()),
             "--bodypart", str(self.zone_bodypart.currentData()), "--minimum-dwell", str(self.zone_minimum_dwell.value())],
            self.zone_analysis_finished,
        )

    def zone_analysis_finished(self, code: int) -> None:
        if code == 0:
            self.refresh_zone_results()
            QMessageBox.information(self, tr('구역 행동분석 완료'), tr('구역별 체류·진입·전이와 궤적·히트맵을 생성했습니다.'))
        else:
            self.set_workflow_badge(self.zone_analysis_badge, tr('실패'), False)
            QMessageBox.critical(self, tr('구역 행동분석 실패'), tr('실행 로그에서 오류 내용을 확인하세요.'))

    def refresh_zone_results(self) -> None:
        if not hasattr(self, "zone_result_table") or not self.zone_output_edit.text().strip():
            return
        output = Path(self.zone_output_edit.text().strip())
        summary_path = output / "zone-summary.csv"
        overall_path = output / "experiment-summary.json"
        if not summary_path.is_file():
            return
        try:
            frame = pd.read_csv(summary_path)
            overall = json.loads(overall_path.read_text(encoding="utf-8")) if overall_path.is_file() else []
        except Exception as error:
            self.append_log(tr('구역 결과 로드 실패: {value1}', value1=error))
            return
        table = self.zone_result_table
        table.setSortingEnabled(False); table.setRowCount(len(frame))
        role_labels = {"choice": tr('선택 구역'), "center": tr('중앙/전이'), "other": tr('기타')}
        for row_index, row in frame.iterrows():
            first = row.get("first_entry_seconds", float("nan"))
            values = [
                f"{row.get('region_name', '')}", row.get("zone_name", ""), role_labels.get(row.get("zone_role", ""), row.get("zone_role", "")),
                f"{float(row.get('occupancy_seconds', 0)):.2f}", str(int(row.get("entries", 0))),
                "-" if pd.isna(first) else f"{float(first):.2f}", tr('완료'),
            ]
            for column, value in enumerate(values):
                item = SortableTableItem(str(value))
                if column == 0: item.setData(Qt.UserRole, int(row.get("region_id", 1)))
                if column >= 3: item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row_index, column, item)
        table.setSortingEnabled(True); table.sortItems(0, Qt.AscendingOrder)
        if table.rowCount(): table.selectRow(0)
        summaries = []
        for result in overall:
            alt = result.get("alternation_percent")
            alt_text = tr('산출 불가') if alt is None or (isinstance(alt, float) and math.isnan(alt)) else f"{float(alt):.1f}%"
            summaries.append(
                tr('{value1}: 교대율 {value2} · 선택 진입 {value3}회 · 유효 좌표 {value4:.1f}%', value1=result.get('region_name', ''), value2=alt_text, value3=len(result.get('choice_sequence', [])), value4=float(result.get('valid_pose_percent', 0)))
            )
        self.zone_overall_summary.setText("\n".join(summaries))
        self.set_workflow_badge(self.zone_result_badge, tr('{value1}개 구역', value1=len(frame)), True)
        self.set_workflow_badge(self.zone_analysis_badge, tr('분석 완료'), True)

    def open_selected_zone_visual(self) -> None:
        row = self.zone_result_table.currentRow()
        if row < 0 or not self.zone_result_table.item(row, 0):
            QMessageBox.information(self, tr('구역 시각화'), tr('결과 표에서 한 구역을 선택하세요.'))
            return
        region_id = int(self.zone_result_table.item(row, 0).data(Qt.UserRole) or 1)
        path = Path(self.zone_output_edit.text()) / f"region_{region_id:02d}_zone_visual.png"
        if path.is_file(): QDesktopServices.openUrl(QUrl.fromLocalFile(str(path)))
        else: QMessageBox.information(self, tr('구역 시각화'), tr('시각화 파일이 없습니다. 분석을 다시 실행하세요.'))

    def open_zone_result_folder(self) -> None:
        path = Path(self.zone_output_edit.text()) if self.zone_output_edit.text().strip() else None
        if path and path.is_dir(): QDesktopServices.openUrl(QUrl.fromLocalFile(str(path)))
        else: QMessageBox.information(self, tr('구역 결과'), tr('아직 생성된 구역 분석 결과가 없습니다.'))

    def default_spatial_bundle(self) -> Path | None:
        if not self.config:
            return None
        return self.project_tracking_root()

    def nort_common_spatial_template_path(self) -> Path:
        project_root = self.config.parent if self.config else self.work_root
        return project_state_root(project_root) / "spatial" / "common-template.json"

    def nort_common_spatial_subject(self) -> str:
        path = self.nort_common_spatial_template_path()
        try:
            payload = json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}
            return str(payload.get("subject", "")).strip()
        except Exception:
            return ""

    def set_nort_common_spatial_subject(self, subject: Path) -> None:
        path = self.nort_common_spatial_template_path()
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            json.dumps(
                {
                    "subject": subject.name,
                    "subject_path": str(subject.resolve()),
                    "updated_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    def apply_nort_common_spatial_template_to_missing(self, subjects: list[Path]) -> int:
        source_name = self.nort_common_spatial_subject()
        source_subject = next((path for path in subjects if path.name == source_name), None)
        if not source_subject:
            return 0
        checked = set(self.spatial_checked_subjects)
        project_root = self.config.parent if self.config else self.work_root
        source_setup_root = project_state_root(project_root) / "spatial" / source_subject.name
        source_payloads: dict[int, tuple[dict, Path]] = {}
        for arena_dir in sorted(source_subject.glob("arena_*")):
            arena_id = self.spatial_arena_id(arena_dir)
            if arena_id is None:
                continue
            setup_path = source_setup_root / f"arena_{arena_id:02d}_nort_setup.json"
            if self.spatial_setup_state(setup_path)[2] != "ready":
                continue
            try:
                source_payloads[arena_id] = (
                    json.loads(setup_path.read_text(encoding="utf-8")),
                    setup_path,
                )
            except Exception:
                continue
        if not source_payloads:
            return 0

        applied = 0
        for target in subjects:
            if target == source_subject or (checked and str(target) not in checked):
                continue
            target_output_root = project_state_root(project_root) / "spatial" / target.name
            target_arenas = {
                self.spatial_arena_id(path): path
                for path in target.glob("arena_*")
                if self.spatial_arena_id(path) is not None
            }
            for arena_id, (source_payload, source_setup_path) in source_payloads.items():
                output = target_output_root / f"arena_{arena_id:02d}_nort_setup.json"
                if output.is_file():
                    continue
                arena_dir = target_arenas.get(arena_id)
                video = self.spatial_arena_video(arena_dir) if arena_dir else None
                if not arena_dir or not video:
                    continue
                payload = json.loads(json.dumps(source_payload))
                source_video_meta = payload.get("video") or {}
                target_video_meta = self.spatial_video_metadata(arena_dir, video, source_video_meta)
                source_size = (source_video_meta.get("width"), source_video_meta.get("height"))
                target_size = (target_video_meta.get("width"), target_video_meta.get("height"))
                if all(source_size) and all(target_size) and source_size != target_size:
                    continue
                payload["source_video"] = str(video.resolve())
                payload["video"] = target_video_meta
                payload["created_by"] = "HAGISILTA · common spatial template"
                payload["template_source_subject"] = source_subject.name
                payload["template_source_setup"] = str(source_setup_path.resolve())
                payload["template_assignment"] = "common"
                payload["requires_object_review"] = False
                payload["template_applied_at"] = time.strftime("%Y-%m-%d %H:%M:%S")
                output.parent.mkdir(parents=True, exist_ok=True)
                output.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
                applied += 1
        if applied:
            self.append_log(
                tr('NORT 공통 설정 자동 적용: {value1} 기준 · {value2}개 Arena', value1=source_subject.name, value2=applied)
            )
        return applied

    def project_tracking_root(self) -> Path:
        if self.config:
            output_root = project_output_root(self.config.parent)
            current = output_root / "tracked"
            legacy = output_root / "tracked2"
            if not current.is_dir() and legacy.is_dir():
                return legacy
            return current
        return self.work_root / "platform" / "tracked"

    def choose_spatial_bundle(self) -> None:
        start = self.spatial_root_edit.text().strip()
        if not start:
            default = self.default_spatial_bundle()
            start = str(default or (self.config.parent if self.config else self.work_root))
        selected = QFileDialog.getExistingDirectory(self, tr('프로젝트 또는 Arena 트래킹 결과 묶음 선택'), start)
        if not selected:
            return
        self.spatial_root_edit.setText(selected)
        self.spatial_checked_subjects.clear()
        self.spatial_checked_arenas.clear()
        self.spatial_checks_initialized = False
        self.refresh_spatial_bundle()

    @staticmethod
    def spatial_setup_state(path: Path) -> tuple[str, str, str]:
        if not path.is_file():
            return "unconfigured", "unconfigured", "needs_configuration"
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
            arena = (payload.get("arenas") or [{}])[0]
            calibration = arena.get("calibration") or {}
            cm_ready = bool(calibration.get("points_source_px")) and float(calibration.get("pixels_per_cm", 0)) > 0
            objects = arena.get("objects") or {}
            object_ready = all(label in objects and objects[label].get("polygon_source_px") for label in ("A", "B"))
            review_required = bool(payload.get("requires_object_review", False))
            common_applied = bool(payload.get("template_source_subject"))
            if cm_ready and object_ready and review_required:
                return "complete", "template_review" if common_applied else "check_required", "review_required"
            return (
                "complete" if cm_ready else "unconfigured",
                ("template_applied" if common_applied else "objects_complete") if object_ready else "unconfigured",
                "ready" if cm_ready and object_ready else "needs_configuration",
            )
        except Exception:
            return "check_required", "check_required", "file_error"


    @staticmethod
    def spatial_state_label(state: str) -> str:
        labels = {
            'unconfigured': tr('미설정'),
            'needs_configuration': tr('설정 필요'),
            'complete': tr('완료'),
            'template_review': tr('공통 적용·검토 필요'),
            'check_required': tr('확인 필요'),
            'review_required': tr('검토 필요'),
            'template_applied': tr('공통 적용'),
            'objects_complete': tr('A/B 완료'),
            'ready': tr('준비'),
            'file_error': tr('파일 오류'),
        }
        return labels.get(state, state)

    def refresh_spatial_bundle(self) -> None:
        if not hasattr(self, "spatial_table"):
            return
        if self._spatial_refreshing:
            return
        self._spatial_refreshing = True
        raw = self.spatial_root_edit.text().strip()
        root = Path(raw) if raw else self.default_spatial_bundle()
        direct_arenas = sorted(root.glob("arena_*")) if root and root.is_dir() else []
        if direct_arenas:
            subjects = [root]
        elif root and root.is_dir():
            subjects = sorted(
                [
                    path for path in root.iterdir()
                    if path.is_dir() and any(child.is_dir() for child in path.glob("arena_*"))
                ],
                key=lambda path: path.name.lower(),
            )
        else:
            subjects = []

        source_records: list[dict] = []
        hidden_sources: set[str] = set()
        use_project_library = bool(self.config and not direct_arenas)
        if use_project_library:
            try:
                project_payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
                source_records = list(
                    (project_metadata(project_payload).get("source_videos", []) or [])
                )
                hidden_sources = self.project_hidden_source_keys(project_payload)
            except Exception:
                source_records = []
                hidden_sources = set()
        subject_sources: dict[str, str] = {}
        for subject in subjects:
            for metadata_path in sorted(subject.glob("arena_*/roi-metadata.json")):
                try:
                    source_path = str((json.loads(metadata_path.read_text(encoding="utf-8"))).get("source_video", ""))
                except Exception:
                    source_path = ""
                if source_path:
                    subject_sources[str(subject)] = source_path
                    break
        subjects = [
            subject for subject in subjects
            if not subject_sources.get(str(subject))
            or self.normalized_source_key(subject_sources[str(subject)]) not in hidden_sources
        ]
        project_rows: list[tuple[dict | None, Path | None]] = []
        used_subjects: set[str] = set()
        for source in source_records:
            source_path = str(source.get("path", ""))
            source_stem = Path(source_path).stem.lower()
            match = next(
                (
                    subject for subject in subjects
                    if subject_sources.get(str(subject))
                    and os.path.normcase(subject_sources[str(subject)]) == os.path.normcase(source_path)
                ),
                None,
            )
            if match is None:
                match = next(
                    (
                        subject for subject in subjects
                        if subject.name.lower() == source_stem
                        or subject.name.lower().startswith(source_stem + "_")
                    ),
                    None,
                )
            if match is not None:
                used_subjects.add(str(match))
            project_rows.append((source, match))
        project_rows.extend((None, subject) for subject in subjects if str(subject) not in used_subjects)
        if not project_rows:
            project_rows = [(None, subject) for subject in subjects]

        if not self.spatial_checks_initialized:
            self.spatial_checked_subjects = {str(path) for path in subjects}
        # Never propagate experiment geometry during a table refresh.  Shared
        # NORT geometry is copied only by the explicit checked-video action.

        if self.spatial_selected_subject not in subjects:
            self.spatial_selected_subject = subjects[0] if subjects else None
        summary_table = self.spatial_experiment_table
        selected_subject_keys = {
            str(item.data(Qt.UserRole) or "")
            for row in self.selected_table_rows(summary_table)
            if (item := summary_table.item(row, 1)) is not None
            and str(item.data(Qt.UserRole) or "")
        }
        current_subject_key = str(self.spatial_selected_subject or "")
        if not selected_subject_keys and current_subject_key:
            selected_subject_keys.add(current_subject_key)
        signals_blocked = summary_table.blockSignals(True)
        summary_sorting = summary_table.isSortingEnabled()
        summary_table.setSortingEnabled(False)
        summary_table.setRowCount(len(project_rows))
        common_source_name = self.nort_common_spatial_subject()
        for row_index, (source, subject_path) in enumerate(project_rows):
            source_path = str((source or {}).get("path", ""))
            arena_dirs_for_subject = sorted(subject_path.glob("arena_*")) if subject_path else []
            output_root_for_subject = (
                (project_state_root(self.config.parent) if self.config else self.work_root)
                / "spatial" / (subject_path.name if subject_path else Path(source_path).stem)
            )
            spatial_done = 0
            object_done = 0
            common_done = 0
            for arena_dir in arena_dirs_for_subject:
                match = re.search(r"(\d+)$", arena_dir.name)
                arena_id = int(match.group(1)) if match else 0
                cm_state, object_state, _status = self.spatial_setup_state(
                    output_root_for_subject / f"arena_{arena_id:02d}_nort_setup.json"
                )
                spatial_done += int(cm_state == "complete")
                object_done += int(object_state in {"objects_complete", "template_applied"})
                common_done += int(object_state == "template_applied")
            total = len(arena_dirs_for_subject)
            status = (
                tr('트래킹 필요') if subject_path is None else
                tr('기준 영상') if total and subject_path.name == common_source_name and object_done == total else
                tr('공통 적용') if total and common_done == total else
                tr('준비') if total and object_done == total else
                (tr('설정 중') if spatial_done or object_done else tr('설정 필요'))
            )
            values = [
                Path(source_path).name if source_path else subject_path.name,
                f"{total}/{total}" if total else "0/0", f"{spatial_done}/{total}",
                f"{object_done}/{total}", status,
            ]
            checkbox = self.set_centered_table_checkbox(
                summary_table, row_index, 0,
                bool(subject_path and str(subject_path) in self.spatial_checked_subjects)
            )
            checkbox.setEnabled(subject_path is not None)
            if subject_path:
                checkbox.toggled.connect(
                    lambda checked, path=str(subject_path): self.set_spatial_subject_checked(path, checked)
                )
            for column, value in enumerate(values, start=1):
                item = QTableWidgetItem(value)
                if column == 1:
                    item.setData(Qt.UserRole, str(subject_path) if subject_path else "")
                    item.setData(Qt.UserRole + 1, source_path or subject_sources.get(str(subject_path), ""))
                    item.setToolTip(source_path or (str(subject_path) if subject_path else ""))
                else:
                    item.setTextAlignment(Qt.AlignCenter)
                summary_table.setItem(row_index, column, item)
        summary_table.setSortingEnabled(summary_sorting)
        if summary_sorting:
            summary_table.sortItems(
                summary_table.horizontalHeader().sortIndicatorSection(),
                summary_table.horizontalHeader().sortIndicatorOrder(),
            )
        selection = summary_table.selectionModel()
        if selection:
            selection.clearSelection()
            current_index = None
            for row in range(summary_table.rowCount()):
                item = summary_table.item(row, 1)
                key = str(item.data(Qt.UserRole) or "") if item else ""
                if key in selected_subject_keys:
                    selection.select(
                        summary_table.model().index(row, 0),
                        QItemSelectionModel.Select | QItemSelectionModel.Rows,
                    )
                if key == current_subject_key:
                    current_index = summary_table.model().index(row, 0)
            if current_index is not None:
                selection.setCurrentIndex(current_index, QItemSelectionModel.NoUpdate)
        summary_table.blockSignals(signals_blocked)

        subject_root = self.spatial_selected_subject
        arena_dirs = sorted(subject_root.glob("arena_*")) if subject_root else []
        rows: list[dict] = []
        subject = subject_root.name if subject_root else "experiment"
        output_root = (
            (project_state_root(self.config.parent) if self.config else self.work_root)
            / "spatial" / subject
        )
        for arena_dir in arena_dirs:
            match = re.search(r"(\d+)$", arena_dir.name)
            arena_id = int(match.group(1)) if match else len(rows) + 1
            from hagisilta_labeled_video import source_video_candidates
            videos = source_video_candidates(arena_dir)
            pose_files = sorted(arena_dir.glob("*.h5")) or sorted(arena_dir.glob("*.csv"))
            video = videos[0] if videos else None
            pose = pose_files[0] if pose_files else None
            output = output_root / f"arena_{arena_id:02d}_nort_setup.json"
            cm_state, object_state, status = self.spatial_setup_state(output)
            rows.append({
                "arena_id": arena_id, "arena_dir": arena_dir, "video": video,
                "pose": pose, "output": output, "cm": cm_state,
                "objects": object_state, "status": status,
            })
        self.spatial_rows = rows
        if not self.spatial_checks_initialized:
            self.spatial_checked_arenas = {int(row["arena_id"]) for row in rows}
            self.spatial_checks_initialized = True
        completed = sum(1 for row in rows if row["status"] == "ready")
        self.spatial_progress_label.setText("")
        if hasattr(self, "spatial_source_selection_label"):
            if subject_root:
                source_video = self.selected_spatial_source_video()
                display_name = source_video.name if source_video else subject_root.name
                self.spatial_source_selection_label.setText(
                    f"{display_name} · {len(rows)} Arena"
                )
                self.spatial_source_selection_label.setToolTip(str(subject_root))
            else:
                self.spatial_source_selection_label.setText(
                    tr('위 표에서 편집할 원본 영상을 선택하세요.')
                )
                self.spatial_source_selection_label.setToolTip("")
        self.set_workflow_badge(
            self.nort_source_badge,
            tr('{value1}개 영상 · {value2}/{value3} 공간', value1=len(project_rows), value2=completed, value3=len(rows)) if project_rows else tr('영상 없음'),
            bool(rows) and completed == len(rows),
        )
        # Polling updates source readiness every 1.5 s, but must not rebuild
        # the experiment table when its Arena structure is unchanged. A forced
        # rebuild discards an A/B role selection before the user can save it.
        self.refresh_nort_experiment_table()
        self.update_spatial_action_state()
        self._spatial_refreshing = False

    def spatial_subject_changed(self) -> None:
        if self._spatial_refreshing or not hasattr(self, "spatial_experiment_table"):
            return
        row = self.spatial_experiment_table.currentRow()
        item = self.spatial_experiment_table.item(row, 1) if row >= 0 else None
        if item:
            subject_path = str(item.data(Qt.UserRole) or "")
            if subject_path:
                self.spatial_selected_subject = Path(subject_path)
                self.refresh_spatial_bundle()
            else:
                self.spatial_selected_subject = None
                self.spatial_rows = []
                self.spatial_table.setRowCount(0)
                self.spatial_progress_label.setText("")
                if hasattr(self, "spatial_source_selection_label"):
                    self.spatial_source_selection_label.setText(
                        tr('트래킹 좌표가 준비되면 Arena를 편집할 수 있습니다.')
                    )
                self.refresh_nort_experiment_table()

    def update_spatial_action_state(self) -> None:
        if hasattr(self, "spatial_open_button"):
            self.spatial_open_button.setEnabled(bool(self.spatial_rows))

    def set_spatial_subject_checked(self, path: str, checked: bool) -> None:
        if checked:
            self.spatial_checked_subjects.add(path)
            if self.nort_common_spatial_subject():
                QTimer.singleShot(0, self.refresh_spatial_bundle)
        else:
            self.spatial_checked_subjects.discard(path)
        self.update_nort_workflow_readiness()

    def set_spatial_arena_checked(self, arena_id: int, checked: bool) -> None:
        if checked:
            self.spatial_checked_arenas.add(int(arena_id))
        else:
            self.spatial_checked_arenas.discard(int(arena_id))

    def set_all_spatial_subject_checks(self, checked: bool) -> None:
        paths: set[str] = set()
        for row in range(self.spatial_experiment_table.rowCount()):
            item = self.spatial_experiment_table.item(row, 1)
            path = str(item.data(Qt.UserRole)) if item and item.data(Qt.UserRole) else ""
            if path:
                paths.add(path)
            checkbox = self.table_checkbox(self.spatial_experiment_table, row, 0)
            if checkbox:
                checkbox.setChecked(checked)
        self.spatial_checked_subjects = paths if checked else set()
        self.update_nort_workflow_readiness()

    def set_all_spatial_arena_checks(self, checked: bool) -> None:
        arena_ids: set[int] = set()
        for row in range(self.spatial_table.rowCount()):
            item = self.spatial_table.item(row, 1)
            arena_id = item.data(Qt.UserRole) if item else None
            if arena_id is not None:
                arena_ids.add(int(arena_id))
            checkbox = self.table_checkbox(self.spatial_table, row, 0)
            if checkbox:
                checkbox.setChecked(checked)
        self.spatial_checked_arenas = arena_ids if checked else set()

    def checked_spatial_subject_paths(self) -> list[Path]:
        return [Path(path) for path in sorted(self.spatial_checked_subjects)]

    def checked_spatial_arena_ids(self) -> set[int]:
        return set(self.spatial_checked_arenas)

    def nort_experiment_info_path(self, subject: Path | None = None) -> Path | None:
        subject = subject or self.spatial_selected_subject
        if not subject:
            return None
        project_root = self.config.parent if self.config else self.work_root
        return project_state_root(project_root) / "nort-experiment" / f"{subject.name}.json"

    def nort_subject_preview_video(self, subject: Path | None = None) -> Path | None:
        subject = subject or self.spatial_selected_subject
        if not subject or not subject.is_dir():
            return None
        arena_dirs = sorted(path for path in subject.glob("arena_*") if path.is_dir())
        for arena_dir in arena_dirs:
            video = self.spatial_arena_video(arena_dir)
            if video:
                return video
        return None

    @staticmethod
    def nort_video_duration(video: Path | None) -> float:
        if not video or not video.is_file():
            return 0.0
        import cv2

        capture = cv2.VideoCapture(str(video))
        fps = float(capture.get(cv2.CAP_PROP_FPS) or 0.0)
        frames = int(capture.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
        capture.release()
        return frames / fps if fps > 0 and frames > 0 else 0.0

    def nort_subject_source_video(self, subject: Path | None, arena_id: int) -> Path | None:
        if not subject:
            return None
        arena_dir = subject / f"arena_{arena_id:02d}"
        metadata_path = arena_dir / "roi-metadata.json"
        try:
            metadata = json.loads(metadata_path.read_text(encoding="utf-8")) if metadata_path.is_file() else {}
            source_video = Path(str(metadata.get("source_video", "")))
            if source_video.is_file():
                return source_video
        except Exception:
            pass
        return self.spatial_arena_video(arena_dir)

    def selected_nort_experiment_arena(self) -> tuple[int, int] | None:
        table = self.nort_experiment_table
        row = table.currentRow()
        item = table.item(row, 1) if row >= 0 else None
        if not item:
            return None
        return row, int(item.data(Qt.UserRole))

    def nort_range_for_row(self, row: int) -> tuple[float, float]:
        item = self.nort_experiment_table.item(row, 7)
        value = item.data(Qt.UserRole) if item else None
        if isinstance(value, (list, tuple)) and len(value) == 2:
            return float(value[0]), float(value[1])
        return 0.0, 0.0

    def set_nort_range_for_arena(self, arena_id: int, start: float, end: float) -> None:
        table = self.nort_experiment_table
        sorting = table.isSortingEnabled()
        sort_column = table.horizontalHeader().sortIndicatorSection()
        sort_order = table.horizontalHeader().sortIndicatorOrder()
        table.setSortingEnabled(False)
        for row in range(table.rowCount()):
            arena_item = table.item(row, 1)
            if not arena_item or int(arena_item.data(Qt.UserRole)) != int(arena_id):
                continue
            duration = max(0.0, end - start)
            item = table.item(row, 7) or SortableTableItem()
            item.setText(
                tr('{value1} → {value2} · {value3:.1f}초', value1=NortAnalysisRangeDialog.format_seconds(start), value2=NortAnalysisRangeDialog.format_seconds(end), value3=duration)
            )
            item.setData(Qt.UserRole, (float(start), float(end)))
            item.setTextAlignment(Qt.AlignCenter)
            table.setItem(row, 7, item)
            self.update_nort_experiment_row_status(row)
            break
        table.setSortingEnabled(sorting)
        if sorting:
            table.sortItems(sort_column, sort_order)
        self.select_nort_experiment_arena(arena_id)
        self.update_nort_range_summary()

    @staticmethod
    def nort_role_label(role_a: str, role_b: str) -> str:
        if role_a == "Novel" and role_b == "Familiar":
            return "A=Novel · B=Familiar"
        if role_a == "Familiar" and role_b == "Novel":
            return "A=Familiar · B=Novel"
        return "미지정"

    @staticmethod
    def nort_roles_from_label(label: str) -> tuple[str, str]:
        if label == "A=Novel · B=Familiar":
            return "Novel", "Familiar"
        if label == "A=Familiar · B=Novel":
            return "Familiar", "Novel"
        return "미지정", "미지정"

    def update_nort_experiment_row_status(self, row: int) -> None:
        combo = self.nort_experiment_table.cellWidget(row, 6)
        role_ready = isinstance(combo, QComboBox) and combo.currentData() != "unassigned"
        start, end = self.nort_range_for_row(row)
        arena_item = self.nort_experiment_table.item(row, 1)
        arena_id = int(arena_item.data(Qt.UserRole)) if arena_item and arena_item.data(Qt.UserRole) is not None else -1
        spatial = next((item for item in self.spatial_rows if int(item["arena_id"]) == arena_id), None)
        spatial_ready = bool(spatial and spatial.get("status") == "ready")
        status = (
            tr('준비') if spatial_ready and role_ready and end > start else
            tr('공간 설정 필요') if not spatial_ready else
            tr('역할 필요') if not role_ready else tr('구간 필요')
        )
        item = self.nort_experiment_table.item(row, 8) or QTableWidgetItem()
        item.setText(status)
        item.setTextAlignment(Qt.AlignCenter)
        self.nort_experiment_table.setItem(row, 8, item)

    def update_nort_range_summary(self, *_args) -> None:
        if not hasattr(self, "nort_range_summary"):
            return
        selected = self.selected_nort_experiment_arena()
        if not selected:
            self.nort_range_summary.setText(tr('표에서 Arena를 선택하세요.'))
            return
        row, arena_id = selected
        start, end = self.nort_range_for_row(row)
        length = max(0.0, end - start)
        valid = end > start
        self.nort_range_summary.setText(
            tr('Arena {value1:02d} · {value2} → {value3} · {value4:.1f}초', value1=arena_id, value2=NortAnalysisRangeDialog.format_seconds(start), value3=NortAnalysisRangeDialog.format_seconds(end), value4=length)
            if valid else tr('시작·종료 지정 필요')
        )
        if hasattr(self, "nort_experiment_badge"):
            self.update_nort_workflow_readiness()

    def open_nort_analysis_range_dialog(self) -> None:
        selected = self.selected_nort_experiment_arena()
        if not selected:
            QMessageBox.information(self, tr('분석 구간'), tr('먼저 표에서 Arena를 선택하세요.'))
            return
        row, arena_id = selected
        video = self.nort_subject_source_video(self.spatial_selected_subject, arena_id)
        if not video:
            QMessageBox.information(self, tr('분석 구간'), tr('선택 Arena의 원본 영상을 찾을 수 없습니다.'))
            return
        start, end = self.nort_range_for_row(row)
        role_combo = self.nort_experiment_table.cellWidget(row, 6)
        role_label = str(role_combo.currentData() or "unassigned") if isinstance(role_combo, QComboBox) else "unassigned"
        try:
            dialog = NortAnalysisRangeDialog(video, start, end, self, role_label=role_label)
            dialog.setWindowTitle(tr('HAGISILTA · Arena {value1:02d} 분석 구간 · 원본 영상', value1=arena_id))
        except Exception as error:
            QMessageBox.critical(self, tr('분석 구간'), str(error))
            return
        if dialog.exec() == QDialog.Accepted:
            tracked_duration = self.nort_video_duration(
                self.spatial_arena_video(self.spatial_selected_subject / f"arena_{arena_id:02d}")
            )
            end_seconds = dialog.end_spin.value()
            try:
                validate_range(dialog.start_spin.value(), end_seconds, tracked_duration or dialog.duration)
            except ValueError as error:
                QMessageBox.warning(self, tr('트래킹 구간 부족'), str(error))
                return
            self.set_nort_range_for_arena(arena_id, dialog.start_spin.value(), end_seconds)
            selected_after_sort = self.selected_nort_experiment_arena()
            if selected_after_sort:
                selected_row, _arena_id = selected_after_sort
                combo = self.nort_experiment_table.cellWidget(selected_row, 6)
                if isinstance(combo, QComboBox):
                    combo.setCurrentIndex(max(0, combo.findData(dialog.role_combo.currentData())))

    def set_selected_nort_arena_full_range(self) -> None:
        selected = self.selected_nort_experiment_arena()
        if not selected:
            QMessageBox.information(self, tr('분석 구간'), tr('먼저 표에서 Arena를 선택하세요.'))
            return
        _row, arena_id = selected
        video = self.spatial_arena_video(self.spatial_selected_subject / f"arena_{arena_id:02d}")
        duration = self.nort_video_duration(video)
        if duration <= 0:
            QMessageBox.information(self, tr('분석 구간'), tr('영상 길이를 확인할 수 없습니다.'))
            return
        self.set_nort_range_for_arena(arena_id, 0.0, duration)

    def apply_nort_range_to_checked_subjects(self) -> None:
        self.open_nort_batch_range_dialog(same_arena=True)

    def open_nort_batch_range_dialog(self, _checked=False, same_arena: bool = False) -> None:
        selected = self.selected_nort_experiment_arena()
        reference = self.nort_range_for_row(selected[0]) if selected else (0.0, 600.0)
        arena_ids = {selected[1]} if same_arena and selected else self.checked_spatial_arena_ids()
        records, documents = [], {}
        current_rows, _errors = self.collect_nort_experiment_info()
        drafts = {int(item["arena_id"]): item for item in current_rows}
        for subject in self.checked_spatial_subject_paths():
            path = self.nort_experiment_info_path(subject)
            if not path:
                continue
            error = ""
            try:
                payload = json.loads(path.read_text(encoding="utf-8-sig")) if path.is_file() else {}
                if not isinstance(payload, dict):
                    raise ValueError(tr('실험 정보는 JSON 객체여야 합니다.'))
                existing = {int(item["arena_id"]): item for item in payload.get("arenas", [])}
            except (OSError, ValueError, TypeError, KeyError) as exc:
                payload, existing, error = {}, {}, str(exc)
            documents[str(path)] = (subject, payload, existing)
            for arena in sorted(subject.glob("arena_*")):
                number = self.spatial_arena_id(arena)
                if number not in arena_ids or not arena.is_dir():
                    continue
                duration = self.nort_video_duration(self.spatial_arena_video(arena))
                saved = existing.get(number, {}).get("analysis_range") or payload.get("analysis_range") or {}
                if subject == self.spatial_selected_subject and number in drafts:
                    saved = drafts[number]["analysis_range"]
                start, end, range_error = 0.0, duration, error
                try:
                    if not isinstance(saved, dict):
                        raise ValueError(tr('저장된 분석 구간 형식을 확인하세요.'))
                    start = float(saved.get("start_seconds", 0.0))
                    end = float(saved.get("end_seconds", duration))
                    if not all(math.isfinite(value) for value in (start, end)):
                        raise ValueError(tr('저장된 분석 구간이 유효한 숫자가 아닙니다.'))
                except (TypeError, ValueError) as exc:
                    start, end, range_error = 0.0, duration, str(exc)
                records.append({
                    "id": str(arena), "path": str(path), "arena_id": number,
                    "label": f"{subject.name} · Arena {number:02d}",
                    "start": start, "end": end,
                    "duration": duration, "source_error": range_error,
                })
        if not records:
            QMessageBox.information(self, tr('구간 일괄 설정'), tr('적용할 영상과 Arena의 사용 체크를 켜세요.'))
            return
        dialog = BatchAnalysisRangeDialog(records, reference, self)
        if same_arena:
            dialog.mode.setCurrentIndex(1)
        if dialog.exec() != QDialog.Accepted:
            return
        from hagisilta_atomic_io import atomic_json
        saved_count, failures = 0, []
        changes = {}
        for item in dialog.accepted_proposals():
            changes.setdefault(item["path"], []).append(item)
        for path, items in changes.items():
            subject, payload, existing = documents[path]
            for item in items:
                number = item["arena_id"]
                record = existing.setdefault(number, {"arena_id": number, "subject_id": f"{subject.name}_A{number:02d}"})
                record["analysis_range"] = {
                    "start_seconds": item["new_start"], "end_seconds": item["new_end"],
                    "duration_seconds": item["new_end"] - item["new_start"],
                }
            payload.update(schema_version=1, experiment_type="NORT", video_bundle=subject.name,
                           tracked_root=str(subject.resolve()), arenas=[existing[key] for key in sorted(existing)],
                           saved_at=time.strftime("%Y-%m-%d %H:%M:%S"))
            # Keep a legacy top-level range for untouched Arenas.
            try:
                atomic_json(Path(path), payload)
                saved_count += len(items)
                if subject == self.spatial_selected_subject:
                    for item in items:
                        self.set_nort_range_for_arena(item["arena_id"], item["new_start"], item["new_end"])
            except OSError as exc:
                failures.append(f"{subject.name}: {exc}")
        self.update_nort_workflow_readiness()
        QMessageBox.information(self, tr('구간 적용 결과'),
                                tr('{value1}개 Arena 저장 · {value2}개 미적용\n', value1=saved_count, value2=len(records) - saved_count) + "\n".join(failures))

    def apply_nort_roles_to_checked_subjects(self, role_a: str, role_b: str) -> None:
        if role_a == role_b:
            QMessageBox.information(self, tr('역할 일괄 지정'), tr('Object A와 B는 Novel/Familiar를 하나씩 지정해야 합니다.'))
            return
        subjects = [path for path in self.checked_spatial_subject_paths() if path.is_dir()]
        if not subjects:
            QMessageBox.information(self, tr('역할 일괄 지정'), tr('역할을 적용할 영상 묶음을 체크하세요.'))
            return
        answer = QMessageBox.question(
            self, tr('역할 일괄 지정'),
            tr('체크한 {value1}개 영상의 모든 Arena에 A={value2}, B={value3}를 적용할까요?', value1=len(subjects), value2=role_a, value3=role_b),
            QMessageBox.Yes | QMessageBox.No, QMessageBox.Yes,
        )
        if answer != QMessageBox.Yes:
            return
        role_label = self.nort_role_label(role_a, role_b)
        for row in range(self.nort_experiment_table.rowCount()):
            combo = self.nort_experiment_table.cellWidget(row, 6)
            if isinstance(combo, QComboBox):
                combo.setCurrentIndex(max(0, combo.findData("unassigned" if role_label == "미지정" else role_label)))
        for subject in subjects:
            path = self.nort_experiment_info_path(subject)
            try:
                payload = json.loads(path.read_text(encoding="utf-8")) if path and path.is_file() else {}
            except Exception:
                payload = {}
            existing = {int(record.get("arena_id", 0)): record for record in payload.get("arenas", [])}
            for arena_dir in sorted(subject.glob("arena_*")):
                number = self.spatial_arena_id(arena_dir)
                if number is None:
                    continue
                record = existing.get(number, {
                    "arena_id": number,
                    "subject_id": f"{subject.name}_A{number:02d}",
                })
                record["object_a_role"] = role_a
                record["object_b_role"] = role_b
                existing[number] = record
            payload.update({
                "schema_version": 1, "experiment_type": "NORT",
                "video_bundle": subject.name, "tracked_root": str(subject.resolve()),
                "saved_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                "arenas": [existing[key] for key in sorted(existing)],
            })
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        self.update_nort_workflow_readiness()
        QMessageBox.information(self, tr('역할 적용 완료'), tr('{value1}개 영상에 A/B 역할을 저장했습니다.', value1=len(subjects)))

    def refresh_nort_experiment_table(self, force: bool = False) -> None:
        if not hasattr(self, "nort_experiment_table"):
            return
        subject = self.spatial_selected_subject
        subject_key = str(subject) if subject else ""
        spatial_signature = tuple(
            (
                int(row.get("arena_id", 0)),
                str(row.get("status", "")),
                str(row.get("video", "")),
                str(row.get("pose", "")),
                str(row.get("cm", "")),
                str(row.get("objects", "")),
            )
            for row in self.spatial_rows
        )
        same_subject = getattr(self, "nort_experiment_subject", None) == subject_key
        if (
            not force
            and same_subject
            and getattr(self, "nort_experiment_spatial_signature", None) == spatial_signature
        ):
            self.update_nort_workflow_readiness()
            return
        draft_rows: dict[int, dict] = {}
        if same_subject:
            for row in range(self.nort_experiment_table.rowCount()):
                arena_item = self.nort_experiment_table.item(row, 1)
                if arena_item is None or arena_item.data(Qt.UserRole) is None:
                    continue
                arena_id = int(arena_item.data(Qt.UserRole))
                subject_item = self.nort_experiment_table.item(row, 5)
                combo = self.nort_experiment_table.cellWidget(row, 6)
                start, end = self.nort_range_for_row(row)
                draft_rows[arena_id] = {
                    "subject_id": subject_item.text().strip() if subject_item else "",
                    "role_label": str(combo.currentData() or "unassigned") if isinstance(combo, QComboBox) else "unassigned",
                    "analysis_range": {
                        "start_seconds": start,
                        "end_seconds": end,
                    },
                }
        self.nort_experiment_subject = subject_key
        self.nort_experiment_spatial_signature = spatial_signature
        path = self.nort_experiment_info_path(subject)
        try:
            payload = json.loads(path.read_text(encoding="utf-8")) if path and path.is_file() else {}
        except Exception:
            payload = {}
        saved = {int(row.get("arena_id", 0)): row for row in payload.get("arenas", [])}
        table = self.nort_experiment_table
        selected_arena_ids = {
            int(item.data(Qt.UserRole))
            for row in self.selected_table_rows(table)
            if (item := table.item(row, 1)) is not None
            and item.data(Qt.UserRole) is not None
        }
        current_item = table.item(table.currentRow(), 1) if table.currentRow() >= 0 else None
        current_arena_id = (
            int(current_item.data(Qt.UserRole))
            if current_item is not None and current_item.data(Qt.UserRole) is not None
            else None
        )
        signals_blocked = table.blockSignals(True)
        sorting = table.isSortingEnabled()
        table.setSortingEnabled(False)
        table.setRowCount(len(self.spatial_rows))
        for row_index, spatial in enumerate(self.spatial_rows):
            arena_id = int(spatial["arena_id"])
            record = saved.get(arena_id, {})
            draft = draft_rows.get(arena_id, {})
            checkbox = self.set_centered_table_checkbox(
                table, row_index, 0, arena_id in self.spatial_checked_arenas
            )
            checkbox.toggled.connect(
                lambda checked, selected_arena=arena_id: self.set_spatial_arena_checked(selected_arena, checked)
            )
            arena_item = SortableTableItem(f"Arena {arena_id:02d}")
            arena_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            arena_item.setData(Qt.UserRole, arena_id)
            arena_item.setTextAlignment(Qt.AlignCenter)
            table.setItem(row_index, 1, arena_item)
            roi_dlc_state = (
                tr('준비') if spatial.get("video") and spatial.get("pose") else
                (tr('Arena 영상 없음') if not spatial.get("video") else tr('좌표 없음'))
            )
            for column, value in (
                (2, roi_dlc_state), (3, self.spatial_state_label(spatial.get("cm", "unconfigured"))),
                (4, self.spatial_state_label(spatial.get("objects", "unconfigured"))),
            ):
                item = SortableTableItem(str(value))
                item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row_index, column, item)
            table.setItem(
                row_index, 5,
                QTableWidgetItem(str(draft.get(
                    "subject_id",
                    record.get("subject_id", f"{subject.name if subject else 'animal'}_A{arena_id:02d}"),
                ))),
            )
            role_label = str(draft.get("role_label") or self.nort_role_label(
                str(record.get("object_a_role", "미지정")),
                str(record.get("object_b_role", "미지정")),
            ))
            role_item = SortableTableItem("")
            role_item.setData(Qt.UserRole, role_label)
            role_item.setTextAlignment(Qt.AlignCenter)
            table.setItem(row_index, 6, role_item)
            combo = NoWheelComboBox(objectName="tableCellCombo")
            populate_nort_role_combo(combo, role_label)
            combo.setCurrentIndex(max(0, combo.findData("unassigned" if role_label == "미지정" else role_label)))
            combo.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
            combo.currentIndexChanged.connect(
                lambda _index, item=role_item, control=combo: self.nort_role_changed(item, str(control.currentData() or "unassigned"))
            )
            combo.activated.connect(
                lambda _index, selected_arena=arena_id: self.select_nort_experiment_arena(selected_arena)
            )
            # The NORT source list refreshes every 1.5 s. Rebuilding the table
            # while this popup is open destroys the editor and makes the list
            # appear to close by itself, so pause polling for the interaction.
            combo.popupShown.connect(self.spatial_refresh_timer.stop)
            combo.popupHidden.connect(self.resume_spatial_refresh_after_combo)
            table.setCellWidget(row_index, 6, combo)
            table.register_context_cell_widget(combo)
            duration = self.nort_video_duration(spatial.get("video"))
            legacy_range = payload.get("analysis_range") or {}
            saved_range = draft.get("analysis_range") or record.get("analysis_range") or legacy_range
            range_start = min(max(float(saved_range.get("start_seconds", 0.0) or 0.0), 0.0), duration) if duration else 0.0
            range_end = min(max(float(saved_range.get("end_seconds", duration) or duration), 0.0), duration) if duration else 0.0
            range_duration = max(0.0, range_end - range_start)
            range_item = SortableTableItem(
                tr('{value1} → {value2} · {value3:.1f}초', value1=NortAnalysisRangeDialog.format_seconds(range_start), value2=NortAnalysisRangeDialog.format_seconds(range_end), value3=range_duration)
            )
            range_item.setData(Qt.UserRole, (float(range_start), float(range_end)))
            range_item.setTextAlignment(Qt.AlignCenter)
            table.setItem(row_index, 7, range_item)
            self.update_nort_experiment_row_status(row_index)
        table.setSortingEnabled(sorting)
        if sorting:
            table.sortItems(table.horizontalHeader().sortIndicatorSection(), table.horizontalHeader().sortIndicatorOrder())
        selection = table.selectionModel()
        if selection:
            selection.clearSelection()
            if not selected_arena_ids and table.rowCount():
                first = table.item(0, 1)
                if first is not None and first.data(Qt.UserRole) is not None:
                    selected_arena_ids.add(int(first.data(Qt.UserRole)))
                    if current_arena_id is None:
                        current_arena_id = int(first.data(Qt.UserRole))
            current_index = None
            for row in range(table.rowCount()):
                item = table.item(row, 1)
                arena_id = int(item.data(Qt.UserRole)) if item and item.data(Qt.UserRole) is not None else -1
                if arena_id in selected_arena_ids:
                    selection.select(
                        table.model().index(row, 0),
                        QItemSelectionModel.Select | QItemSelectionModel.Rows,
                    )
                if arena_id == current_arena_id:
                    current_index = table.model().index(row, 0)
            if current_index is not None:
                selection.setCurrentIndex(current_index, QItemSelectionModel.NoUpdate)
        table.blockSignals(signals_blocked)
        self.nort_experiment_columns_balanced = False
        QTimer.singleShot(0, self.balance_nort_experiment_columns)
        self.update_nort_range_summary()
        self.update_nort_workflow_readiness()

    def nort_role_changed(self, item: QTableWidgetItem, text: str) -> None:
        item.setData(Qt.UserRole, text)
        self.update_nort_experiment_row_status(item.row())
        self.update_nort_workflow_readiness()

    def resume_spatial_refresh_after_combo(self) -> None:
        QTimer.singleShot(
            250,
            lambda: self.spatial_refresh_timer.start()
            if hasattr(self, "spatial_refresh_timer") and self.spatial_experiment_table.isVisible()
            else None,
        )

    def select_nort_experiment_arena(self, arena_id: int) -> None:
        table = self.nort_experiment_table
        selection = table.selectionModel()
        selected_rows = set(self.selected_table_rows(table))
        for row in range(table.rowCount()):
            item = table.item(row, 1)
            if item and int(item.data(Qt.UserRole)) == int(arena_id):
                index = table.model().index(row, 0)
                if selection is not None:
                    # A persistent cell editor (such as the A/B role combo)
                    # must not collapse an existing blue multi-row selection.
                    # Keep the set when this Arena is already selected and only
                    # move the current-row anchor used by row-specific actions.
                    command = (
                        QItemSelectionModel.NoUpdate
                        if row in selected_rows
                        else QItemSelectionModel.ClearAndSelect | QItemSelectionModel.Rows
                    )
                    selection.setCurrentIndex(index, command)
                return

    def balance_nort_experiment_columns(self) -> None:
        if self.nort_experiment_columns_balanced or not self.nort_experiment_table.isVisible():
            return
        table = self.nort_experiment_table
        available = max(1250, table.viewport().width() - 4)
        widths = (70, 105, 120, 105, 120, 190, 245, 290, 135)
        scale = max(1.0, available / sum(widths))
        for column, base_width in enumerate(widths):
            width = int(base_width * scale)
            table.setColumnWidth(column, width)
        self.nort_experiment_columns_balanced = True

    def collect_nort_experiment_info(self) -> tuple[list[dict], list[str]]:
        rows: list[dict] = []
        errors: list[str] = []
        table = self.nort_experiment_table
        for row in range(table.rowCount()):
            arena_item = table.item(row, 1)
            subject_item = table.item(row, 5)
            arena_id = int(arena_item.data(Qt.UserRole)) if arena_item else row + 1
            subject_id = subject_item.text().strip() if subject_item else ""
            role_combo = table.cellWidget(row, 6)
            role_a, role_b = self.nort_roles_from_label(
                str(role_combo.currentData() or "unassigned") if isinstance(role_combo, QComboBox) else "unassigned"
            )
            range_start, range_end = self.nort_range_for_row(row)
            if not subject_id:
                errors.append(tr('Arena {value1:02d}: 개체 ID 없음', value1=arena_id))
            if {role_a, role_b} != {"Novel", "Familiar"}:
                errors.append(tr('Arena {value1:02d}: A/B를 Novel과 Familiar로 하나씩 지정하세요.', value1=arena_id))
            if range_end <= range_start:
                errors.append(tr('Arena {value1:02d}: 분석 종료 시각은 시작 시각보다 뒤여야 합니다.', value1=arena_id))
            rows.append({
                "arena_id": arena_id, "subject_id": subject_id,
                "object_a_role": role_a, "object_b_role": role_b,
                "analysis_range": {
                    "start_seconds": range_start,
                    "end_seconds": range_end,
                    "duration_seconds": range_end - range_start,
                },
            })
        return rows, errors

    def save_nort_experiment_info(self) -> None:
        subject = self.spatial_selected_subject
        path = self.nort_experiment_info_path(subject)
        if not subject or not path:
            QMessageBox.information(self, tr('실험 정보'), tr('먼저 입력 영상 묶음을 선택하세요.'))
            return
        rows, errors = self.collect_nort_experiment_info()
        if errors:
            QMessageBox.information(self, tr('실험 정보 미완성'), "\n".join(errors))
            return
        payload = {
            "schema_version": 1,
            "experiment_type": "NORT",
            "video_bundle": subject.name,
            "tracked_root": str(subject.resolve()),
            "saved_at": time.strftime("%Y-%m-%d %H:%M:%S"),
            "arenas": rows,
        }
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        self.update_nort_workflow_readiness()
        QMessageBox.information(self, tr('실험 정보 저장'), tr('Novel/Familiar 정보를 저장했습니다.\n\n{value1}', value1=path))

    def update_nort_workflow_readiness(self, *_args) -> None:
        self.refresh_nort_analysis_bodyparts()
        if not hasattr(self, "nort_experiment_badge"):
            return
        rows, errors = self.collect_nort_experiment_info() if hasattr(self, "nort_experiment_table") else ([], [tr('없음')])
        info_path = self.nort_experiment_info_path()
        saved_matches = False
        if info_path and info_path.is_file() and rows and not errors:
            try:
                saved_payload = json.loads(info_path.read_text(encoding="utf-8"))
                saved_rows = sorted(saved_payload.get("arenas") or [], key=lambda row: int(row.get("arena_id", 0)))
                current_rows = sorted(rows, key=lambda row: int(row.get("arena_id", 0)))
                saved_matches = saved_rows == current_rows
            except Exception:
                saved_matches = False
        info_saved = bool(saved_matches)
        spatial_ready = bool(self.spatial_rows) and all(row["status"] == "ready" for row in self.spatial_rows)
        role_errors = self.nort_role_errors()
        roles_ready = not role_errors
        ready = spatial_ready and info_saved and roles_ready
        checked_count = len(self.checked_spatial_subject_paths()) if hasattr(self, "spatial_checked_subjects") else 0
        checked_paths = self.checked_spatial_subject_paths() if hasattr(self, "spatial_checked_subjects") else []
        arena_count = sum(len(list(path.glob("arena_*"))) for path in checked_paths if path.is_dir())
        selected_state = tr('저장 완료') if info_saved else (tr('입력 중') if rows else tr('입력 필요'))
        self.set_workflow_badge(
            self.nort_experiment_badge,
            tr('{value1}개 영상 · {value2}개 Arena · {value3}', value1=checked_count, value2=len(rows), value3=selected_state),
            ready,
        )
        if hasattr(self, "nort_run_summary"):
            self.nort_run_summary.setText(
                tr('실행 대상 · {value1}개 영상 · {value2}개 Arena', value1=checked_count, value2=arena_count)
                if checked_count else tr('실행 대상 없음')
            )
        if hasattr(self, "nort_run_detail"):
            direction = tr('머리 방향 포함') if self.nort_orientation_check.isChecked() else tr('거리 조건만')
            roles = self.nort_bodypart_roles()
            role_text = tr('코 {value1}', value1=roles.get('nose') or tr('미지정'))
            if self.nort_orientation_check.isChecked():
                role_text += tr(' · 머리 {value1}', value1=roles.get('head_center') or tr('미지정'))
            self.nort_run_detail.setText(
                tr('신뢰도 {value1:.2f} · 최소 탐색 {value2:.2f}초 · 누락 연결 {value3:.2f}초 · {value4} · {value5}', value1=self.nort_pcutoff.value(), value2=self.nort_minimum_exploration.value(), value3=self.nort_bridge_gap.value(), value4=direction, value5=role_text)
            )
        if hasattr(self, "nort_head_bodypart"):
            self.nort_head_bodypart.setEnabled(self.nort_orientation_check.isChecked())
        self.set_workflow_badge(
            self.nort_analysis_badge,
            (role_errors[0] if role_errors else (tr('{value1}개 선택', value1=checked_count) if checked_count else (tr('실행 가능') if ready else tr('준비 전')))),
            bool(checked_count and ready),
        )
        self.nort_run_button.setEnabled(bool(checked_count and ready))
        self.nort_run_button.setToolTip(
            tr('체크한 영상의 공간 설정·Arena별 구간·A/B 역할을 검사한 뒤 준비된 영상을 모두 분석합니다.')
        )

    def nort_result_root(self, subject: Path | None = None) -> Path | None:
        subject = subject or self.spatial_selected_subject
        if not subject:
            return None
        project_root = self.config.parent if self.config else self.work_root
        return project_output_root(project_root) / "nort-analysis" / subject.name

    def nort_result_base(self) -> Path:
        project_root = self.config.parent if self.config else self.work_root
        return project_output_root(project_root) / "nort-analysis"

    def nort_summary_paths(self) -> list[Path]:
        displayed = [
            Path(path) for path in getattr(self, "nort_display_summary_paths", [])
            if Path(path).is_file()
        ]
        if displayed:
            return displayed
        paths: list[Path] = []
        root = self.nort_result_base()
        if not root.is_dir():
            return paths
        for bundle in sorted(path for path in root.iterdir() if path.is_dir()):
            latest_run = bundle / "latest-run.json"
            if latest_run.is_file():
                try:
                    latest = Path(str(json.loads(latest_run.read_text(encoding="utf-8")).get("summary_csv", "")))
                    if latest.is_file():
                        paths.append(latest); continue
                except Exception:
                    pass
            pointer = bundle / "nort-summary.latest.json"
            if pointer.is_file():
                try:
                    latest = Path(str(json.loads(pointer.read_text(encoding="utf-8")).get("csv", "")))
                    if latest.is_file():
                        paths.append(latest); continue
                except Exception:
                    pass
            standard = bundle / "nort-summary.csv"
            if standard.is_file():
                paths.append(standard)
        return paths

    def choose_nort_result_run(self) -> None:
        root = self.nort_result_base()
        if not root.is_dir():
            QMessageBox.information(self, tr('NORT 분석 이력'), tr('저장된 NORT 분석 실행이 없습니다.'))
            return
        selected = QFileDialog.getExistingDirectory(self, tr('이전 NORT 분석 폴더 선택'), str(root))
        if not selected:
            return
        selected_root = Path(selected)
        candidates = sorted(
            {
                path.resolve()
                for pattern in ("nort-summary.csv", "nort-summary-*.csv")
                for path in selected_root.rglob(pattern)
                if path.is_file()
            },
            key=lambda path: path.stat().st_mtime,
            reverse=True,
        )
        if not candidates:
            QMessageBox.warning(
                self, tr('NORT 분석 이력'),
                tr('선택한 폴더에서 NORT 분석 결과 CSV를 찾지 못했습니다.'),
            )
            return
        # A folder can contain superseded copies for one video. Keep the newest
        # summary per video bundle so the result table never duplicates a run.
        chosen: dict[str, Path] = {}
        for path in candidates:
            try:
                sample = pd.read_csv(path, nrows=1)
                bundle = str(sample.iloc[0].get("video_bundle", path.parent.name)) if not sample.empty else path.parent.name
            except Exception:
                continue
            chosen.setdefault(bundle, path)
        if not chosen:
            QMessageBox.warning(self, tr('NORT 분석 이력'), tr('읽을 수 있는 NORT 분석 결과가 없습니다.'))
            return
        self.nort_display_summary_paths = list(chosen.values())
        self.refresh_nort_results()
        self.nort_result_run_label.setText(tr('불러온 분석 이력 · {value1}개 영상', value1=len(chosen)))
        self.nort_result_run_label.setToolTip(str(selected_root))

    def nort_summary_for_bundle(self, bundle: str) -> Path:
        for path in self.nort_summary_paths():
            try:
                sample = pd.read_csv(path, nrows=1)
                if not sample.empty and str(sample.iloc[0].get("video_bundle", "")) == bundle:
                    return path
            except Exception:
                continue
        return self.nort_result_base() / bundle / "nort-summary.csv"

    def validate_nort_subject(self, subject: Path) -> list[str]:
        errors: list[str] = []
        info_path = self.nort_experiment_info_path(subject)
        try:
            payload = json.loads(info_path.read_text(encoding="utf-8")) if info_path and info_path.is_file() else {}
        except Exception:
            payload = {}
        records = {int(record.get("arena_id", 0)): record for record in payload.get("arenas", [])}
        project_root = self.config.parent if self.config else self.work_root
        setup_root = project_state_root(project_root) / "spatial" / subject.name
        for arena_dir in sorted(subject.glob("arena_*")):
            number = self.spatial_arena_id(arena_dir)
            if number is None:
                continue
            setup_path = setup_root / f"arena_{number:02d}_nort_setup.json"
            if self.spatial_setup_state(setup_path)[2] != "ready":
                errors.append(tr('Arena {value1:02d} 공간 설정 미완료', value1=number))
            record = records.get(number)
            if not record:
                errors.append(tr('Arena {value1:02d} 실험 정보 없음', value1=number))
                continue
            if {record.get("object_a_role"), record.get("object_b_role")} != {"Novel", "Familiar"}:
                errors.append(tr('Arena {value1:02d} A/B 역할 미완료', value1=number))
            selected_range = record.get("analysis_range") or payload.get("analysis_range") or {}
            if float(selected_range.get("end_seconds", 0.0) or 0.0) <= float(selected_range.get("start_seconds", 0.0) or 0.0):
                errors.append(tr('Arena {value1:02d} 분석 구간 미완료', value1=number))
        if not records:
            errors.append(tr('저장된 실험 정보 없음'))
        return errors

    def run_selected_nort_analysis(self) -> None:
        self.nort_display_summary_paths = []
        role_errors = self.nort_role_errors()
        if role_errors:
            QMessageBox.information(
                self, tr('NORT 신체점 역할'), "\n".join(role_errors) + tr('\n\n판정 설정에서 역할을 선택하세요.')
            )
            return
        subjects = [path for path in self.checked_spatial_subject_paths() if path.is_dir()]
        if not subjects:
            QMessageBox.information(self, tr('NORT 분석'), tr('분석할 영상 묶음을 체크하세요.'))
            return
        project_root = self.config.parent if self.config else self.work_root
        problems: list[str] = []
        jobs: list[dict] = []
        for subject in subjects:
            errors = self.validate_nort_subject(subject)
            if errors:
                problems.append(f"{subject.name}: " + ", ".join(errors))
                continue
            jobs.append({
                "name": subject.name,
                "subject_root": str(subject.resolve()),
                "setup_root": str((project_state_root(project_root) / "spatial" / subject.name).resolve()),
                "experiment_info": str(self.nort_experiment_info_path(subject).resolve()),
                "output": str((self.nort_result_base() / subject.name).resolve()),
                "pcutoff": float(self.nort_pcutoff.value()),
                "orientation": bool(self.nort_orientation_check.isChecked()),
                "minimum_exploration": float(self.nort_minimum_exploration.value()),
                "bridge_gap": float(self.nort_bridge_gap.value()),
                "bodypart_roles": self.nort_bodypart_roles(),
            })
        if problems:
            QMessageBox.information(
                self, tr('NORT 일괄 분석 준비 필요'),
                tr('체크한 영상 중 준비되지 않은 항목이 있습니다.\n\n') + "\n".join(problems[:20]),
            )
            return
        runtime = project_state_root(project_root, create=True) / "runtime"
        runtime.mkdir(parents=True, exist_ok=True)
        plan_path = runtime / "nort-analysis-plan.json"
        plan_path.write_text(json.dumps({"jobs": jobs}, ensure_ascii=False, indent=2), encoding="utf-8")
        self.nort_analysis_job_count = len(jobs)
        self.set_workflow_badge(self.nort_analysis_badge, tr('0/{value1} 분석 중', value1=len(jobs)), False)
        self.start_process(
            SCRIPTS / "hagisilta_nort_analysis.py",
            ["--batch-plan", str(plan_path)],
            lambda code: self.nort_analysis_finished(code),
        )

    def nort_analysis_finished(self, code: int) -> None:
        if code == 0:
            self.refresh_nort_results()
            self.set_workflow_expanded(self.nort_result_step, True)
            QMessageBox.information(
                self, tr('NORT 분석 완료'),
                tr('체크한 {value1}개 영상의 탐색시간 계산이 완료되었습니다.', value1=getattr(self, 'nort_analysis_job_count', 0))
            )
        else:
            self.set_workflow_badge(self.nort_analysis_badge, tr('실패'), False)
            QMessageBox.critical(self, tr('NORT 분석 실패'), tr('실행 로그에서 오류 내용을 확인하세요.'))

    def refresh_nort_results(self) -> None:
        if not hasattr(self, "nort_result_table"):
            return
        summary_paths = self.nort_summary_paths()
        if not summary_paths:
            self.nort_result_table.setRowCount(0)
            if hasattr(self, "nort_result_run_label"):
                self.nort_result_run_label.setText(tr('표시 결과 없음'))
                self.nort_result_run_label.setToolTip(tr('저장된 분석 결과가 없습니다.'))
            self.set_workflow_badge(self.nort_result_badge, tr('결과 없음'), False)
            return
        try:
            frame = pd.concat([pd.read_csv(path) for path in summary_paths], ignore_index=True)
        except Exception as error:
            self.append_log(tr('NORT 결과 로드 실패: {value1}', value1=error))
            return
        table = self.nort_result_table
        selected_result_keys = {
            (
                table.item(row, 0).text().strip(),
                int(table.item(row, 1).data(Qt.UserRole)),
            )
            for row in self.selected_table_rows(table)
            if table.item(row, 0) is not None
            and table.item(row, 1) is not None
            and table.item(row, 1).data(Qt.UserRole) is not None
        }
        current_key = None
        if table.currentRow() >= 0 and table.item(table.currentRow(), 0) and table.item(table.currentRow(), 1):
            arena_value = table.item(table.currentRow(), 1).data(Qt.UserRole)
            if arena_value is not None:
                current_key = (table.item(table.currentRow(), 0).text().strip(), int(arena_value))
        signals_blocked = table.blockSignals(True)
        sorting = table.isSortingEnabled()
        table.setSortingEnabled(False)
        table.setRowCount(len(frame))
        for row_index, result in frame.iterrows():
            novel_seconds = float(result.get("novel_seconds", 0.0))
            familiar_seconds = float(result.get("familiar_seconds", 0.0))
            values = [
                result.get("video_bundle", ""),
                f"Arena {int(result.get('arena_id', row_index + 1)):02d}",
                result.get("subject_id", ""),
                tr(self.nort_role_label(
                    str(result.get("object_a_role", "미지정")),
                    str(result.get("object_b_role", "미지정")),
                )),
                f"{novel_seconds:.2f}",
                f"{familiar_seconds:.2f}",
                f"{novel_seconds + familiar_seconds:.2f}",
                f"{float(result.get('discrimination_index', float('nan'))):.3f}",
                f"{float(result.get('valid_pose_percent', 0.0)):.1f}",
            ]
            for column, value in enumerate(values):
                item = SortableTableItem(str(value))
                if column == 0:
                    item.setData(Qt.UserRole + 1, result.to_dict())
                if column == 1:
                    item.setData(Qt.UserRole, int(result.get("arena_id", row_index + 1)))
                elif column in {4, 5, 6, 8}:
                    item.setData(Qt.UserRole, float(value))
                elif column == 7:
                    try:
                        item.setData(Qt.UserRole, float(value))
                    except ValueError:
                        pass
                if column in {1, 3, 4, 5, 6, 7, 8}:
                    item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row_index, column, item)
        table.setSortingEnabled(sorting)
        if sorting:
            table.sortItems(table.horizontalHeader().sortIndicatorSection(), table.horizontalHeader().sortIndicatorOrder())
        selection = table.selectionModel()
        if selection:
            selection.clearSelection()
            if not selected_result_keys and table.rowCount():
                first_bundle = table.item(0, 0)
                first_arena = table.item(0, 1)
                if first_bundle and first_arena and first_arena.data(Qt.UserRole) is not None:
                    current_key = (first_bundle.text().strip(), int(first_arena.data(Qt.UserRole)))
                    selected_result_keys.add(current_key)
            current_index = None
            for row in range(table.rowCount()):
                bundle_item = table.item(row, 0)
                arena_item = table.item(row, 1)
                if not bundle_item or not arena_item or arena_item.data(Qt.UserRole) is None:
                    continue
                key = (bundle_item.text().strip(), int(arena_item.data(Qt.UserRole)))
                if key in selected_result_keys:
                    selection.select(
                        table.model().index(row, 0),
                        QItemSelectionModel.Select | QItemSelectionModel.Rows,
                    )
                if key == current_key:
                    current_index = table.model().index(row, 0)
            if current_index is not None:
                selection.setCurrentIndex(current_index, QItemSelectionModel.NoUpdate)
        table.blockSignals(signals_blocked)
        self.set_workflow_badge(self.nort_analysis_badge, tr('완료'), True)
        self.set_workflow_badge(self.nort_result_badge, tr('{value1}개 결과', value1=len(frame)), True)
        if hasattr(self, "nort_result_run_label"):
            run_directories = list(dict.fromkeys(str(path.parent) for path in summary_paths))
            if len(run_directories) == 1:
                text = tr('최신 분석 결과')
            else:
                text = tr('최신 분석 결과 · {value1}개 영상', value1=len(run_directories))
            self.nort_result_run_label.setText(text)
            self.nort_result_run_label.setToolTip("\n".join(run_directories))
        self.update_nort_result_detail()

    def update_nort_result_detail(self) -> None:
        if not hasattr(self, "nort_result_detail_value") or not hasattr(self, "nort_result_table"):
            return
        row = self.nort_result_table.currentRow()
        item = self.nort_result_table.item(row, 0) if row >= 0 else None
        result = item.data(Qt.UserRole + 1) if item is not None else None
        if not isinstance(result, dict):
            self.nort_result_detail_value.setText(tr('결과 행을 선택하면 탐색 구간과 판정 품질이 표시됩니다.'))
            return

        def number(key: str, digits: int = 2, suffix: str = "") -> str:
            try:
                value = float(result.get(key, float("nan")))
            except (TypeError, ValueError):
                return "-"
            return f"{value:.{digits}f}{suffix}" if math.isfinite(value) else "-"

        try:
            raw_preference = float(result.get("preference_ratio", float("nan")))
            preference = f"{raw_preference * 100.0:.1f}%" if math.isfinite(raw_preference) else "-"
        except (TypeError, ValueError):
            preference = "-"
        novel_bouts = int(float(result.get("novel_bout_count", 0) or 0))
        familiar_bouts = int(float(result.get("familiar_bout_count", 0) or 0))
        qc_frames = int(float(result.get("climbing_qc_candidate_frames", 0) or 0))
        excluded_frames = int(float(result.get("climbing_excluded_frames", 0) or 0))
        self.nort_result_detail_value.setText(
            tr('Novel 선호율 {value1} · 탐색 구간 Novel {value2}회 / Familiar {value3}회 · 평균 지속 {value4} / {value5} · 중앙 지속 {value6} / {value7}\n최초 탐색 {value8} / {value9} · 최소 코–오브젝트 거리 {value10} / {value11} · 평균 머리 방향각 {value12} / {value13} · 오브젝트 올라탐 후보 {value14}프레임 · 강한 조건 자동 제외 {value15}프레임', value1=preference, value2=novel_bouts, value3=familiar_bouts, value4=number('novel_mean_bout_seconds', 2, tr('초')), value5=number('familiar_mean_bout_seconds', 2, tr('초')), value6=number('novel_median_bout_seconds', 2, tr('초')), value7=number('familiar_median_bout_seconds', 2, tr('초')), value8=number('novel_first_exploration_latency_seconds', 2, tr('초')), value9=number('familiar_first_exploration_latency_seconds', 2, tr('초')), value10=number('novel_minimum_nose_object_distance_px', 1, 'px'), value11=number('familiar_minimum_nose_object_distance_px', 1, 'px'), value12=number('novel_mean_head_direction_angle_degrees', 1, '°'), value13=number('familiar_mean_head_direction_angle_degrees', 1, '°'), value14=qc_frames, value15=excluded_frames)
        )

    def selected_nort_result(self) -> tuple[str, int] | None:
        table = self.nort_result_table
        row = table.currentRow()
        if row < 0 or not table.item(row, 0) or not table.item(row, 1):
            QMessageBox.information(self, tr('NORT 시각화'), tr('결과 표에서 Arena 한 행을 먼저 선택하세요.'))
            return None
        bundle = table.item(row, 0).text().strip()
        arena = table.item(row, 1).data(Qt.UserRole)
        if arena is None:
            match = re.search(r"(\d+)", table.item(row, 1).text())
            arena = int(match.group(1)) if match else 1
        return bundle, int(arena)

    def selected_nort_results(self) -> list[tuple[str, int]]:
        """Return the real blue-row selection, independent from the use checkboxes."""
        results: list[tuple[str, int]] = []
        for row in self.selected_table_rows(self.nort_result_table):
            bundle_item = self.nort_result_table.item(row, 0)
            arena_item = self.nort_result_table.item(row, 1)
            if bundle_item is None or arena_item is None:
                continue
            arena = arena_item.data(Qt.UserRole)
            if arena is None:
                match = re.search(r"(\d+)", arena_item.text())
                arena = int(match.group(1)) if match else 1
            results.append((bundle_item.text().strip(), int(arena)))
        return list(dict.fromkeys(results))

    def delete_selected_nort_results(self) -> None:
        """Move generated Arena result files to the project trash and keep source data."""
        if not self.require_config():
            return
        targets = self.selected_nort_results()
        if not targets:
            return
        answer = QMessageBox.question(
            self,
            tr('NORT 분석 결과 삭제'),
            tr('선택한 {value1}개 Arena 분석 결과를 프로젝트 휴지통으로 이동할까요?\n\n프레임별 판정 CSV와 궤적·히트맵 이미지가 이동됩니다. 원본 영상, 트래킹 좌표, Arena·Object 설정은 유지됩니다.\n복구 위치: .hagisilta-trash/nort-results', value1=len(targets)),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if answer != QMessageBox.Yes:
            return

        trash_root = (
            self.config.parent / ".hagisilta-trash" / "nort-results"
            / time.strftime("%Y%m%d-%H%M%S")
        )
        file_columns = (
            "per_frame_file", "trajectory_image", "occupancy_heatmap_image",
            "occupancy_heatmap_csv", "exploration_heatmap_image",
            "exploration_heatmap_csv",
        )
        moved = 0
        failures: list[str] = []
        grouped: dict[Path, set[int]] = {}
        for bundle, arena in targets:
            grouped.setdefault(self.nort_summary_for_bundle(bundle), set()).add(arena)

        for summary_path, arenas in grouped.items():
            if not summary_path.is_file():
                continue
            try:
                frame = pd.read_csv(summary_path)
                arena_values = pd.to_numeric(frame.get("arena_id"), errors="coerce")
                removing = frame[arena_values.isin(arenas)].copy()
                keeping = frame[~arena_values.isin(arenas)].copy()
                bucket = trash_root / summary_path.parent.parent.name / summary_path.parent.name
                bucket.mkdir(parents=True, exist_ok=True)
                for _index, result in removing.iterrows():
                    arena_bucket = bucket / f"arena_{int(result.get('arena_id', 0)):02d}"
                    arena_bucket.mkdir(parents=True, exist_ok=True)
                    for column in file_columns:
                        source = Path(str(result.get(column, "")))
                        if not source.is_file():
                            continue
                        destination = arena_bucket / source.name
                        try:
                            shutil.move(str(source), str(destination))
                            moved += 1
                        except OSError as error:
                            failures.append(f"{source}: {error}")
                if keeping.empty:
                    for sibling_name in (
                        "nort-summary.csv", "nort-summary.json",
                        "nort-summary.latest.json", "nort-visual-summary.png",
                    ):
                        source = summary_path.parent / sibling_name
                        if source.is_file():
                            shutil.move(str(source), str(bucket / source.name))
                            moved += 1
                else:
                    keeping.to_csv(summary_path, index=False, encoding="utf-8-sig")
                    json_path = summary_path.with_suffix(".json")
                    if json_path.is_file():
                        json_path.write_text(
                            json.dumps(keeping.to_dict(orient="records"), ensure_ascii=False, indent=2),
                            encoding="utf-8",
                        )
            except Exception as error:
                failures.append(f"{summary_path}: {error}")

        self.refresh_nort_results()
        self.append_log(tr('NORT 결과 삭제: {value1}개 Arena · {value2}개 파일 휴지통 이동', value1=len(targets), value2=moved))
        if failures:
            QMessageBox.warning(
                self, tr('일부 NORT 결과 삭제 실패'),
                tr('일부 파일을 이동하지 못했습니다. 실행 로그를 확인하세요.'),
            )
            for failure in failures:
                self.append_log(tr('NORT 결과 삭제 실패: {value1}', value1=failure))

    def nort_visual_entries(self) -> list[dict]:
        """Return all current NORT Arena results for shared review/composer windows."""
        entries: list[dict] = []
        for summary_path in self.nort_summary_paths():
            try:
                summary = pd.read_csv(summary_path)
            except Exception as error:
                self.append_log(tr('NORT 결과 목록 읽기 실패: {value1} · {value2}', value1=summary_path, value2=error))
                continue
            for _index, result in summary.iterrows():
                arena_dir = Path(str(result.get("arena_dir", "")))
                video = self.spatial_arena_video(arena_dir)
                frames = Path(str(result.get("per_frame_file", "")))
                setup = Path(str(result.get("setup_file", "")))
                if video is None or not frames.is_file() or not setup.is_file():
                    continue
                summary_data = result.to_dict()
                roi_zones: list[dict] = []
                try:
                    setup_payload = json.loads(setup.read_text(encoding="utf-8"))
                    arena_payload = (setup_payload.get("arenas") or [{}])[0]
                    arena_polygon = arena_payload.get("corners_source_px") or []
                    if len(arena_polygon) >= 3:
                        roi_zones.append({"id": "arena", "label": "Arena", "polygon": arena_polygon})
                    exploration_distance = float(setup_payload.get("exploration_distance_cm", 0.0) or 0.0)
                    for label, object_payload in (arena_payload.get("objects") or {}).items():
                        key = str(label).lower()
                        role = str(summary_data.get(f"object_{key}_role") or f"Object {label}")
                        exploration_polygon = object_payload.get("exploration_boundary_source_px") or []
                        object_polygon = object_payload.get("polygon_source_px") or []
                        if len(exploration_polygon) >= 3:
                            roi_zones.append({
                                "id": f"exploration_{key}",
                                "label": tr('{value1} 탐색 범위 {value2:g} cm', value1=role, value2=exploration_distance),
                                "polygon": exploration_polygon,
                            })
                        if len(object_polygon) >= 3:
                            roi_zones.append({
                                "id": f"object_{key}", "label": role,
                                "polygon": object_polygon,
                            })
                except Exception:
                    roi_zones = []
                entries.append({
                    "video": str(video), "frames": str(frames), "setup": str(setup),
                    "summary": summary_data, "roi_zones": roi_zones,
                })
        return entries

    def selected_nort_entry_index(self, entries: list[dict]) -> int:
        selected = self.selected_nort_result()
        if not selected:
            return 0
        bundle, arena = selected
        return next((
            index for index, entry in enumerate(entries)
            if str((entry.get("summary") or {}).get("video_bundle", "")) == bundle
            and int(float((entry.get("summary") or {}).get("arena_id", 0) or 0)) == arena
        ), 0)

    def open_selected_nort_decision_video(self) -> None:
        try:
            entries = self.nort_visual_entries()
            if not entries:
                raise ValueError(tr('열 수 있는 NORT 판정 결과가 없습니다.'))
            index = self.selected_nort_entry_index(entries)
            entry = entries[index]
            BehaviorDecisionViewer(
                Path(entry["video"]), Path(entry["frames"]), "nort", parent=self,
                roi_zones=list(entry.get("roi_zones") or []),
                summary=dict(entry.get("summary") or {}), playlist=entries,
            ).exec()
        except Exception as error:
            QMessageBox.information(self, tr('NORT 판정 영상'), str(error))

    def open_selected_nort_visual_composer(self) -> None:
        try:
            entries = self.nort_visual_entries()
            if not entries:
                raise ValueError(tr('편집할 NORT 결과가 없습니다. 먼저 분석을 실행하세요.'))
            NortVisualComposer(entries, self.selected_nort_entry_index(entries), self).exec()
        except Exception as error:
            QMessageBox.warning(self, tr('NORT 궤적·히트맵 편집'), str(error))

    def open_selected_nort_summary_csv(self) -> None:
        selected = self.selected_nort_result()
        if not selected:
            return
        path = self.nort_summary_for_bundle(selected[0])
        if not path.is_file():
            QMessageBox.information(self, tr('NORT 결과 CSV'), tr('선택 영상의 결과 CSV를 찾지 못했습니다.'))
            return
        QDesktopServices.openUrl(QUrl.fromLocalFile(str(path)))

    def open_selected_nort_visual(self, kind: str) -> None:
        selected = self.selected_nort_result()
        if not selected:
            return
        bundle, arena = selected
        column = {
            "trajectory": "trajectory_image",
            "occupancy_heatmap": "occupancy_heatmap_image",
            "exploration_heatmap": "exploration_heatmap_image",
        }.get(kind, "")
        path = Path()
        try:
            summary = pd.read_csv(self.nort_summary_for_bundle(bundle))
            match = summary[pd.to_numeric(summary["arena_id"], errors="coerce") == arena]
            if not match.empty and column:
                path = Path(str(match.iloc[0].get(column, "")))
        except Exception:
            path = Path()
        if not path.is_file():
            QMessageBox.information(self, tr('NORT 시각화'), tr('해당 시각화가 아직 없습니다. NORT 분석을 다시 실행하세요.'))
            return
        QDesktopServices.openUrl(QUrl.fromLocalFile(str(path)))

    def open_selected_nort_summary(self) -> None:
        selected = self.selected_nort_result()
        if not selected:
            return
        bundle, _arena = selected
        path = Path()
        try:
            summary = pd.read_csv(self.nort_summary_for_bundle(bundle))
            if not summary.empty:
                path = Path(str(summary.iloc[0].get("visual_summary_image", "")))
        except Exception:
            path = Path()
        if not path.is_file():
            QMessageBox.information(self, tr('NORT 비교판'), tr('비교판이 아직 없습니다. NORT 분석을 다시 실행하세요.'))
            return
        QDesktopServices.openUrl(QUrl.fromLocalFile(str(path)))

    def open_nort_result_folder(self) -> None:
        selected = self.selected_nort_result() if self.nort_result_table.rowCount() else None
        output = self.nort_summary_for_bundle(selected[0]).parent if selected else self.nort_result_base()
        if not output.is_dir():
            QMessageBox.information(self, tr('NORT 결과'), tr('아직 선택 영상의 NORT 결과가 없습니다.'))
            return
        QDesktopServices.openUrl(QUrl.fromLocalFile(str(output)))

    @staticmethod
    def spatial_arena_id(path: Path) -> int | None:
        match = re.search(r"(\d+)$", path.name)
        return int(match.group(1)) if match else None

    @staticmethod
    def spatial_arena_video(arena_dir: Path) -> Path | None:
        from hagisilta_labeled_video import source_video_candidates
        videos = source_video_candidates(arena_dir)
        return videos[0] if videos else None

    @staticmethod
    def spatial_video_metadata(arena_dir: Path, video: Path, fallback: dict) -> dict:
        result = dict(fallback or {})
        metadata_path = arena_dir / "roi-metadata.json"
        try:
            metadata = json.loads(metadata_path.read_text(encoding="utf-8")) if metadata_path.is_file() else {}
        except Exception:
            metadata = {}
        crop_size = metadata.get("crop_size_px") or []
        if len(crop_size) == 2:
            result["width"], result["height"] = int(crop_size[0]), int(crop_size[1])
        fps = float(metadata.get("fps", result.get("fps", 0.0)) or 0.0)
        frames = int(metadata.get("frames", result.get("frame_count", 0)) or 0)
        result.update({
            "fps": fps, "frame_count": frames,
            "duration_seconds": frames / fps if fps else float(result.get("duration_seconds", 0.0)),
            "setup_frame_seconds": min(
                float(result.get("setup_frame_seconds", 0.0)),
                frames / fps if fps else float(result.get("setup_frame_seconds", 0.0)),
            ),
        })
        return result

    def apply_selected_spatial_template_to_all(self, set_common: bool = True) -> None:
        source_subject = self.spatial_selected_subject
        raw_root = self.spatial_root_edit.text().strip()
        scan_root = Path(raw_root) if raw_root else self.default_spatial_bundle()
        if not source_subject or not scan_root or not source_subject.is_dir():
            QMessageBox.information(self, tr('공간 템플릿'), tr('먼저 기준으로 사용할 영상 묶음을 선택하세요.'))
            return
        if set_common:
            self.set_nort_common_spatial_subject(source_subject)
        subjects = (
            [scan_root] if any(path.is_dir() for path in scan_root.glob("arena_*"))
            else [
                path for path in scan_root.iterdir()
                if path.is_dir() and any(child.is_dir() for child in path.glob("arena_*"))
            ]
        )
        checked_subjects = {str(path) for path in self.checked_spatial_subject_paths()}
        targets = [
            path for path in subjects
            if path != source_subject and str(path) in checked_subjects
        ]
        if not targets:
            QMessageBox.information(
                self, tr('공간 템플릿'),
                tr('기준 영상 외에 일괄 적용할 영상 묶음을 체크하세요.')
            )
            return
        selected_arena_ids = self.checked_spatial_arena_ids()
        if not selected_arena_ids:
            QMessageBox.information(self, tr('공간 템플릿'), tr('일괄 적용할 Arena를 하나 이상 체크하세요.'))
            return
        project_root = self.config.parent if self.config else self.work_root
        source_setup_root = project_state_root(project_root) / "spatial" / source_subject.name
        source_payloads: dict[int, dict] = {}
        incomplete_source: list[str] = []
        for arena_dir in sorted(source_subject.glob("arena_*")):
            arena_id = self.spatial_arena_id(arena_dir)
            if arena_id is None or arena_id not in selected_arena_ids:
                continue
            setup_path = source_setup_root / f"arena_{arena_id:02d}_nort_setup.json"
            cm_state, object_state, status = self.spatial_setup_state(setup_path)
            if status != "ready":
                incomplete_source.append(
                    tr('Arena {value1:02d}: cm {value2} · 오브젝트 {value3}', value1=arena_id, value2=self.spatial_state_label(cm_state), value3=self.spatial_state_label(object_state))
                )
                continue
            source_payloads[arena_id] = json.loads(setup_path.read_text(encoding="utf-8"))
        if not source_payloads:
            QMessageBox.information(
                self, tr('기준 설정 없음'),
                tr('선택한 Arena에 저장된 NORT 공간 설정이 없습니다.')
            )
            return
        if incomplete_source:
            answer = QMessageBox.question(
                self, tr('일부 Arena만 적용'),
                tr('완료된 {value1}개 Arena만 다른 영상에 적용할까요?\n\n', value1=len(source_payloads))
                + "\n".join(incomplete_source),
                QMessageBox.Yes | QMessageBox.No, QMessageBox.Yes,
            )
            if answer != QMessageBox.Yes:
                return

        existing = []
        for target in targets:
            output_root = project_state_root(project_root) / "spatial" / target.name
            if output_root.is_dir() and any(output_root.glob("arena_*_nort_setup.json")):
                existing.append(target.name)
        if existing:
            answer = QMessageBox.question(
                self, tr('기존 설정 덮어쓰기'),
                tr('다음 영상에는 이미 공간 설정이 있습니다. 기준 영상 설정으로 덮어쓸까요?\n\n')
                + "\n".join(existing),
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return

        applied = 0
        skipped: list[str] = []
        for target in targets:
            target_output_root = project_state_root(project_root) / "spatial" / target.name
            target_output_root.mkdir(parents=True, exist_ok=True)
            target_arenas = {
                self.spatial_arena_id(path): path for path in target.glob("arena_*")
                if self.spatial_arena_id(path) is not None
            }
            for arena_id, source_payload in source_payloads.items():
                arena_dir = target_arenas.get(arena_id)
                video = self.spatial_arena_video(arena_dir) if arena_dir else None
                if not arena_dir or not video:
                    skipped.append(tr('{value1} / Arena {value2:02d}: ROI 영상 없음', value1=target.name, value2=arena_id))
                    continue
                payload = json.loads(json.dumps(source_payload))
                source_video_meta = payload.get("video") or {}
                target_video_meta = self.spatial_video_metadata(arena_dir, video, source_video_meta)
                source_size = (source_video_meta.get("width"), source_video_meta.get("height"))
                target_size = (target_video_meta.get("width"), target_video_meta.get("height"))
                if all(source_size) and all(target_size) and source_size != target_size:
                    skipped.append(
                        tr('{value1} / Arena {value2:02d}: 해상도 {value3}×{value4} 불일치', value1=target.name, value2=arena_id, value3=target_size[0], value4=target_size[1])
                    )
                    continue
                payload["source_video"] = str(video.resolve())
                payload["video"] = target_video_meta
                payload["created_by"] = "HAGISILTA · spatial template copy"
                payload["template_source_subject"] = source_subject.name
                payload["template_source_setup"] = str(
                    (source_setup_root / f"arena_{arena_id:02d}_nort_setup.json").resolve()
                )
                payload["requires_object_review"] = True
                payload["template_applied_at"] = time.strftime("%Y-%m-%d %H:%M:%S")
                output = target_output_root / f"arena_{arena_id:02d}_nort_setup.json"
                output.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
                applied += 1
        self.refresh_spatial_bundle()
        detail = tr('{value1}개 영상 묶음에 {value2}개 Arena 설정을 적용했습니다.', value1=len(targets), value2=applied)
        if skipped:
            detail += tr('\n\n적용 제외:\n') + "\n".join(skipped[:12])
        QMessageBox.information(
            self, tr('일괄 적용 완료'), detail + tr("\n\n각 영상의 '검토 필요' Arena에서 오브젝트 위치를 확인하세요.")
        )

    def approve_selected_spatial_bundle(self) -> None:
        subjects = [path for path in self.checked_spatial_subject_paths() if path.is_dir()]
        arena_ids = self.checked_spatial_arena_ids()
        if not subjects:
            QMessageBox.information(self, tr('일괄 검토'), tr('검토 완료로 표시할 영상 묶음을 체크하세요.'))
            return
        if not arena_ids:
            QMessageBox.information(self, tr('일괄 검토'), tr('검토 완료로 표시할 Arena를 체크하세요.'))
            return
        project_root = self.config.parent if self.config else self.work_root
        candidates = []
        for subject in subjects:
            setup_root = project_state_root(project_root) / "spatial" / subject.name
            for arena_id in sorted(arena_ids):
                path = setup_root / f"arena_{arena_id:02d}_nort_setup.json"
                if not path.is_file():
                    continue
                try:
                    payload = json.loads(path.read_text(encoding="utf-8"))
                except Exception:
                    continue
                if payload.get("requires_object_review", False):
                    candidates.append((subject, path, payload))
        if not candidates:
            QMessageBox.information(
                self, tr('일괄 검토'), tr("체크한 조합에 '검토 필요'로 표시된 Arena가 없습니다.")
            )
            return
        answer = QMessageBox.question(
            self, tr('체크 항목 일괄 검토 완료'),
            tr('{value1}개 영상 묶음에서 {value2}개 Arena를 검토 완료로 표시할까요?\n\n카메라·오브젝트 위치가 기준 영상과 동일한지 실제 화면에서 확인한 경우에만 진행하세요.', value1=len(subjects), value2=len(candidates)),
            QMessageBox.Yes | QMessageBox.No, QMessageBox.No,
        )
        if answer != QMessageBox.Yes:
            return
        for subject, path, payload in candidates:
            payload["requires_object_review"] = False
            payload["object_reviewed_at"] = time.strftime("%Y-%m-%d %H:%M:%S")
            payload["object_review_method"] = "bundle_batch_confirmation"
            path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        self.refresh_spatial_bundle()
        QMessageBox.information(
            self, tr('검토 완료'), tr('체크한 조합의 {value1}개 Arena를 검토 완료로 표시했습니다.', value1=len(candidates))
        )

    def selected_spatial_row(self) -> dict | None:
        row_index = self.spatial_table.currentRow()
        if row_index < 0:
            return None
        item = self.spatial_table.item(row_index, 1)
        arena_id = item.data(Qt.UserRole) if item else None
        return next((row for row in self.spatial_rows if row["arena_id"] == arena_id), None)

    def selected_spatial_source_video(self) -> Path | None:
        subject = self.spatial_selected_subject
        if not subject:
            return None
        for row in range(self.spatial_experiment_table.rowCount()):
            item = self.spatial_experiment_table.item(row, 1)
            if not item or str(item.data(Qt.UserRole) or "") != str(subject):
                continue
            source = Path(str(item.data(Qt.UserRole + 1) or ""))
            if source.is_file():
                return source
        return self.nort_subject_source_video(subject, 1)

    def build_nort_bundle_manifest(self, start_arena_id: int) -> Path | None:
        subject = self.spatial_selected_subject
        source_video = self.selected_spatial_source_video()
        if not subject or not source_video or not source_video.is_file() or not self.spatial_rows:
            return None
        profile_candidates: list[Path] = []
        for row in self.spatial_rows:
            metadata_path = Path(row["arena_dir"]) / "roi-metadata.json"
            try:
                metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
                profile_text = str(metadata.get("roi_profile", "")).strip()
                if profile_text:
                    profile_candidates.append(Path(profile_text))
            except Exception:
                pass
        if self.config:
            profile_candidates.extend([
                project_state_root(self.config.parent) / "camera_profiles" / f"{source_video.stem}_roi_profile.json",
                project_state_root(self.config.parent) / "zone_profiles" / f"{source_video.stem}_zones.json",
            ])
        profile_payload = {}
        for candidate in profile_candidates:
            if not candidate.is_file():
                continue
            try:
                profile_payload = json.loads(candidate.read_text(encoding="utf-8"))
                if profile_payload.get("arenas"):
                    break
            except Exception:
                profile_payload = {}
        profile_arenas = {
            int(arena.get("id", index)): arena
            for index, arena in enumerate(profile_payload.get("arenas", []), start=1)
        }
        records = []
        for row in self.spatial_rows:
            arena_dir = Path(row["arena_dir"])
            metadata_path = arena_dir / "roi-metadata.json"
            try:
                metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
            except Exception:
                metadata = {}
            arena_id = int(row["arena_id"])
            offset = metadata.get("source_offset_px") or [0, 0]
            crop_size = metadata.get("crop_size_px") or []
            video = Path(row["video"])
            if len(crop_size) != 2:
                video_meta = self.spatial_video_metadata(arena_dir, video, {})
                crop_size = [int(video_meta.get("width", 0)), int(video_meta.get("height", 0))]
            else:
                video_meta = self.spatial_video_metadata(arena_dir, video, {})
            profile_arena = profile_arenas.get(arena_id, {})
            corners = (
                profile_arena.get("mask_polygon_source_px")
                or profile_arena.get("corners_source_px")
                or []
            )
            if len(corners) < 3:
                x, y = float(offset[0]), float(offset[1])
                width, height = float(crop_size[0]), float(crop_size[1])
                corners = [
                    [x, y], [x + max(width - 1, 0), y],
                    [x + max(width - 1, 0), y + max(height - 1, 0)],
                    [x, y + max(height - 1, 0)],
                ]
            records.append({
                "arena_id": arena_id,
                "roi_video": str(video),
                "output": str(row["output"]),
                "source_offset_px": [float(offset[0]), float(offset[1])],
                "crop_size_px": [int(crop_size[0]), int(crop_size[1])],
                "crop_corners_px": [
                    [0.0, 0.0], [float(max(int(crop_size[0]) - 1, 0)), 0.0],
                    [float(max(int(crop_size[0]) - 1, 0)), float(max(int(crop_size[1]) - 1, 0))],
                    [0.0, float(max(int(crop_size[1]) - 1, 0))],
                ],
                "corners_source_px": corners,
                "video_meta": video_meta,
            })
        runtime = (project_state_root(self.config.parent) if self.config else self.work_root) / "runtime"
        runtime.mkdir(parents=True, exist_ok=True)
        manifest = runtime / f"nort-spatial-{subject.name}.json"
        manifest.write_text(json.dumps({
            "schema_version": 1,
            "source_video": str(source_video),
            "setup_frame_seconds": 275.0,
            "start_arena_id": int(start_arena_id),
            "subject": subject.name,
            "arenas": records,
        }, ensure_ascii=False, indent=2), encoding="utf-8")
        return manifest

    def launch_spatial_arena(self, row: dict) -> None:
        video = row.get("video")
        if not video or not Path(video).is_file():
            QMessageBox.information(self, tr('ROI 영상 없음'), tr('선택한 arena의 ROI 영상을 찾을 수 없습니다.'))
            return
        output = Path(row["output"])
        output.parent.mkdir(parents=True, exist_ok=True)
        pythonw = Path(sys.executable).with_name("pythonw.exe")
        executable = str(pythonw if pythonw.exists() else Path(sys.executable))
        manifest = self.build_nort_bundle_manifest(int(row["arena_id"]))
        if manifest:
            source_video = self.selected_spatial_source_video()
            args = [
                str(SCRIPTS / "hagisilta_nort_editor.py"), str(source_video),
                "--bundle-manifest", str(manifest),
            ]
        else:
            args = [
                str(SCRIPTS / "hagisilta_nort_editor.py"), str(video),
                "--single-arena", "--arena-id", str(row["arena_id"]),
                "--output", str(output),
            ]
        ok, _pid = QProcess.startDetached(executable, args)
        if ok:
            if manifest:
                self.append_log(
                    tr('NORT 공간·오브젝트 편집기 실행: 원본 화면 · {value1}개 Arena · Arena {value2:02d}부터 편집', value1=len(self.spatial_rows), value2=row['arena_id'])
                )
            else:
                self.append_log(tr('NORT 공간·오브젝트 편집기 실행: Arena {value1:02d} · {value2}', value1=row['arena_id'], value2=video))
            self.spatial_refresh_timer.start()
        else:
            QMessageBox.critical(
                self,
                tr('NORT 공간·오브젝트 편집기'),
                tr('NORT 공간·오브젝트 편집기를 실행하지 못했습니다.'),
            )

    def open_selected_spatial_template(self) -> None:
        if not self.spatial_selected_subject or not self.spatial_rows:
            QMessageBox.information(
                self, tr('기준 영상 선택'), tr('위 원본 영상 표에서 트래킹이 완료된 기준 영상을 선택하세요.')
            )
            return
        self.set_nort_common_spatial_subject(self.spatial_selected_subject)
        self.append_log(
            tr('NORT 공통 설정 기준 영상: {value1} · 저장 후 설정이 없는 체크 영상에 자동 적용됩니다.', value1=self.spatial_selected_subject.name)
        )
        self.open_selected_spatial_arena()

    def open_selected_spatial_arena(self, *_args) -> None:
        row = self.selected_spatial_row()
        if row:
            self.launch_spatial_arena(row)

    def open_next_spatial_arena(self) -> None:
        row = next((item for item in self.spatial_rows if item["status"] != "ready"), None)
        if row is None:
            QMessageBox.information(self, tr('공간 설정'), tr('모든 arena의 공간 설정이 완료되었습니다.'))
            return
        self.launch_spatial_arena(row)

    def sync_training_project_context(self, reset_shuffle: bool = False) -> None:
        if not hasattr(self, "train_shuffle") or not hasattr(self, "train_project_context"):
            return
        suggested = next_shuffle(self.config)
        if reset_shuffle:
            self.train_shuffle.setValue(suggested)
            if hasattr(self, "eval_shuffle"):
                models = trained_model_inventory(self.config)
                self.eval_shuffle.setValue(models[-1]["shuffle"] if models else suggested)
        if hasattr(self, "train_start_mode"):
            self.update_training_start_mode()
        self.refresh_training_dataset_summary()
        self.refresh_model_inventory_table()

    def refresh_training_input_size_guidance(self, plan: dict | None = None) -> None:
        """Validate crop against Train labels; inference keeps the full ROI."""
        if not hasattr(self, "train_input_size"):
            return
        tooltip = (
            tr('전체 ROI · 자동: 회전·확대된 이미지 전체를 보존하고 여백을 추가합니다.\n라벨 주변 크롭: 표시된 모든 신체점과 주변 32px를 포함하는 영역을 잘라 넣습니다. 작은 크기에 맞추려고 이미지를 축소하지 않습니다. 크롭 위치는 학습 중 달라질 수 있습니다.\n크롭 가로·세로는 32 이상의 32배수입니다. 모든 Train 라벨과 최대 회전·확대로 최소 크기를 확인합니다. 너무 작으면 실행을 막고 필요한 크기를 알립니다. 라벨이 없는 부위는 미리보기에서 확인하세요.\n회전·배율 증강은 별도로 유지됩니다. 더 작은 크롭이 필요하면 증강 강도도 확인하세요. 원본 이미지·라벨은 변경하지 않습니다.\n이 크기는 Train에만 적용합니다. Validation·Test·추론은 원본 ROI 전체에 필요한 32배수 여백만 추가하며 이 설정으로 축소하지 않습니다. 실행 시 확정된 Train 목록으로 크기를 다시 확인하고 모델 설정에 기록합니다.')
        )
        text = tr('자동 · Train 이미지 확인 필요')
        self._training_input_layout = None
        self._training_input_paths = []
        self._training_input_labels = None
        self._training_input_error = tr('Train 이미지 확인 필요')
        manual = self.train_input_mode.currentData() == "manual"
        for field in (self.train_input_width, self.train_input_height):
            field.setEnabled(manual)
        if self.config and self.config.is_file():
            try:
                if plan is None:
                    plan = load_split_plan(self.config.parent)
                paths = planned_train_images(self.config.parent, plan)
                if paths:
                    sizes = training_image_sizes(paths)
                    strength = str(self.train_augmentation_strength.currentData() or "standard")
                    minimum = training_input_layout(sizes, strength)
                    if not manual:
                        for field, axis in ((self.train_input_width, "width"), (self.train_input_height, "height")):
                            blocked = field.blockSignals(True)
                            field.setValue(minimum[axis])
                            field.blockSignals(blocked)
                    layout = training_input_layout(
                        sizes, strength,
                        (self.train_input_width.value(), self.train_input_height.value()) if manual else None,
                        label_points=(labels := training_label_points(self.config, paths) if manual else None),
                    )
                    self._training_input_layout = layout
                    self._training_input_paths = paths
                    self._training_input_labels = labels
                    self._training_input_error = ""
                    text = (f"{layout['width']} × {layout['height']} px · {tr('라벨 주변 크롭') if manual else tr('자동')}"
                            + tr(' · 크기 맞춤 축소 없음'))
                    if manual:
                        text += tr(' · 라벨 보존 최소 {value1} × {value2} px', value1=layout['minimum_width'], value2=layout['minimum_height'])
                    tooltip += (
                        tr('\nTrain {value1:,}장 · 최대 원본 가로 {value2} px / 세로 {value3} px\n회전 ±{value4}° · 배율 {value5}–{value6}배', value1=layout['train_frames'], value2=layout['native_max_width'], value3=layout['native_max_height'], value4=layout['rotation_degrees'], value5=layout['scale_range'][0], value6=layout['scale_range'][1])
                    )
            except (OSError, ValueError, KeyError, TypeError) as error:
                self._training_input_error = str(error)
                text = tr('적용 불가 · {value1}', value1=error)
                tooltip += f"\n{error}"
        self.train_input_preview.setEnabled(bool(self._training_input_layout))
        self.train_input_size.setText(text)
        self.train_input_size_label.setText(tr('실제 학습 입력 · 라벨 주변 크롭') if manual else tr('실제 학습 입력 · ROI 전체'))
        for widget in (self.train_input_size, getattr(self, "train_input_size_label", None),
                       self.train_input_mode, self.train_input_width, self.train_input_height):
            if widget is not None:
                widget.setToolTip(tooltip)
                widget.setToolTipDuration(30000)

    def training_input_mode_changed(self, _index: int) -> None:
        self.refresh_training_input_size_guidance()

    def restore_training_input_settings(self, settings: dict) -> None:
        # Existing models are untouched; new manual runs now explicitly use label crops.
        controls = (self.train_input_mode, self.train_input_width, self.train_input_height)
        blocks = [field.blockSignals(True) for field in controls]
        self.train_input_width.setValue(int(settings.get("input_width", 512)))
        self.train_input_height.setValue(int(settings.get("input_height", 512)))
        self.train_input_mode.setCurrentIndex(max(0, self.train_input_mode.findData(settings.get("input_mode", "auto"))))
        for field, blocked in zip(controls, blocks):
            field.blockSignals(blocked)
        self.refresh_training_input_size_guidance()

    def open_training_input_preview(self) -> None:
        self.refresh_training_input_size_guidance()
        if not self._training_input_layout:
            QMessageBox.warning(self, tr('학습 입력 확인'), self._training_input_error)
            return
        from hagisilta_input_preview import TrainingInputPreview
        dialog = TrainingInputPreview(self._training_input_paths, self._training_input_layout, self,
                                      labels=self._training_input_labels)
        dialog.exec()

    def refresh_training_dataset_summary(self) -> None:
        if not hasattr(self, "train_dataset_summary_value"):
            return

        def render_empty(message: str, badge: str) -> None:
            self.render_dataset_composition_summary(
                self.train_dataset_summary_value,
                self.train_split_count_labels,
                self.train_split_progress_bars,
                self.train_experiment_summary_rows,
                enabled_count=0,
                total_counts={"train": 0, "validation": 0, "test": 0},
                experiment_totals={},
                valid_percent=0.0,
            )
            self.train_dataset_lock_hint.value_label.setText(message)
            self.set_workflow_badge(self.train_settings_badge, badge, False)

        if not self.config or not self.config.is_file():
            self.refresh_training_input_size_guidance()
            render_empty(
                tr('프로젝트를 열면 데이터셋에서 확정한 분할 구성이 표시됩니다.'),
                tr('프로젝트 필요'),
            )
            return
        plan = load_split_plan(self.config.parent)
        self.refresh_training_input_size_guidance(plan)
        counts = {"train": 0, "validation": 0, "test": 0}
        experiment_totals: dict[str, dict[str, int]] = {}
        enabled_count = 0
        enabled_frame_count = 0
        valid_weighted_sum = 0.0
        for bundle in (plan.get("bundles", {}) or {}).values():
            if bundle.get("missing") or not bundle.get("enabled", True):
                continue
            enabled_count += 1
            bundle_counts = split_counts(bundle.get("assignments", {}))
            bundle_frames = int(bundle.get("frame_count", 0) or sum(bundle_counts.values()))
            enabled_frame_count += bundle_frames
            valid_weighted_sum += float(bundle.get("valid_percent", 0.0) or 0.0) * bundle_frames
            experiment = str(bundle.get("experiment", "미지정") or "미지정")
            experiment_counts = experiment_totals.setdefault(
                experiment,
                {"bundles": 0, "frames": 0, "train": 0, "validation": 0, "test": 0},
            )
            experiment_counts["bundles"] += 1
            experiment_counts["frames"] += bundle_frames
            for role, count in bundle_counts.items():
                counts[role] += int(count)
                experiment_counts[role] += int(count)
        total = sum(counts.values())
        locked = split_plan_is_effectively_locked(plan)
        version = int(plan.get("dataset_version", 1) or 1)
        if not enabled_count or not total:
            render_empty(
                tr('사용 중인 학습 묶음이 없습니다. 데이터셋 구성에서 사용할 항목을 확정하세요.'),
                tr('데이터셋 v{value1} · 분할 필요', value1=version),
            )
            return
        valid_percent = valid_weighted_sum / enabled_frame_count if enabled_frame_count else 0.0
        self.render_dataset_composition_summary(
            self.train_dataset_summary_value,
            self.train_split_count_labels,
            self.train_split_progress_bars,
            self.train_experiment_summary_rows,
            enabled_count=enabled_count,
            total_counts=counts,
            experiment_totals=experiment_totals,
            valid_percent=valid_percent,
        )
        ready = locked and all(counts[role] > 0 for role in counts)
        if ready:
            status_text = (
                tr('데이터셋 v{value1} · 분할 확정', value1=version)
            )
            badge_text = tr('데이터셋 v{value1} · 확정', value1=version)
        elif not locked:
            status_text = (
                tr('데이터셋 v{value1} · 미확정 · 학습에 사용할 행의 분할을 잠그거나 전체 데이터셋 분할을 잠그세요. 잠글 때 자동 검증됩니다.', value1=version)
            )
            badge_text = tr('데이터셋 v{value1} · 미확정', value1=version)
        else:
            status_text = (
                tr('데이터셋 v{value1} · 분할 오류 · Train·Validation·Test 구성을 다시 확인하세요.', value1=version)
            )
            badge_text = tr('데이터셋 v{value1} · 분할 오류', value1=version)
        self.train_dataset_lock_hint.value_label.setText(status_text)
        self.train_dataset_lock_hint.value_label.setToolTip(
            tr('학습 프레임 목록과 Train·Validation·Test 분할 구성의 버전입니다. 모델 번호(Shuffle)와는 별개이며, 같은 데이터셋으로 여러 모델을 학습할 수 있습니다.\n확정된 구성의 사용 영상·프레임·분할이 달라지면 새 버전으로 관리합니다. 각 모델이 학습에 사용한 분할 기록은 별도로 보존됩니다.')
        )
        self.set_workflow_badge(self.train_settings_badge, badge_text, ready)

    def project_final_model_shuffle(self) -> int | None:
        if not self.config:
            return None
        settings = load_machine_settings()
        value = (settings.get("project_final_models", {}) or {}).get(str(self.config.resolve()))
        try:
            return int(value) if value is not None else None
        except (TypeError, ValueError):
            return None

    def project_external_tracking_model(self) -> dict | None:
        if not self.config:
            return None
        settings = load_machine_settings()
        payload = (settings.get("project_external_tracking_models", {}) or {}).get(
            str(self.config.resolve())
        )
        if not isinstance(payload, dict):
            return None
        model_config = Path(str(payload.get("config", "")))
        snapshot = Path(str(payload.get("snapshot", "")))
        try:
            shuffle = int(payload.get("shuffle"))
        except (TypeError, ValueError):
            return None
        if not model_config.is_file() or not snapshot.is_file() or shuffle < 1:
            return None
        bodyparts = list(map(str, payload.get("bodyparts", []) or []))
        if not bodyparts:
            bodyparts = model_bodyparts_from_config(model_config)
        return {
            "config": model_config,
            "snapshot": snapshot,
            "shuffle": shuffle,
            "snapshot_index": payload.get("snapshot_index", "best"),
            "bodyparts": bodyparts,
        }

    def tracking_bodyparts(self) -> list[str]:
        """Bodyparts produced by the model currently selected for tracking."""
        try:
            if hasattr(self, "track_model_source") and self.track_model_source.currentData() == "superanimal":
                from hagisilta_pose_model_catalog import topviewmouse_bodyparts
                return topviewmouse_bodyparts()
            external = self.project_external_tracking_model()
            if external:
                return list(dict.fromkeys(str(part) for part in external.get("bodyparts", []) or [] if str(part).strip()))
            if not self.config or not self.config.is_file():
                return []
            # A model imported as a local Shuffle may intentionally leave the
            # project's training-label bodyparts empty. Read the chosen model.
            final_shuffle = self.project_final_model_shuffle()
            if final_shuffle is not None:
                model = next((row for row in trained_model_inventory(self.config)
                              if int(row["shuffle"]) == final_shuffle), None)
                if model and model.get("best"):
                    try:
                        parts = training_snapshot_metadata(Path(model["best"])).get("bodyparts", [])
                        if parts:
                            return list(dict.fromkeys(str(part) for part in parts if str(part).strip()))
                    except (OSError, ValueError, TypeError, AttributeError, yaml.YAMLError):
                        pass
            return model_bodyparts_from_config(self.config)
        except (OSError, ValueError, TypeError, yaml.YAMLError):
            return []

    def nort_bodypart_roles(self) -> dict[str, str]:
        role_widgets = {
            "nose": "nort_nose_bodypart",
            "head_center": "nort_head_bodypart",
            "body_center": "nort_body_bodypart",
            "rear_center": "nort_rear_bodypart",
        }
        return {
            role: str(getattr(self, attribute).currentData() or "")
            for role, attribute in role_widgets.items()
            if hasattr(self, attribute)
        }

    def nort_role_errors(self) -> list[str]:
        roles = self.nort_bodypart_roles()
        errors: list[str] = []
        if not roles.get("nose"):
            errors.append(tr('코 신체점 지정 필요'))
        if hasattr(self, "nort_orientation_check") and self.nort_orientation_check.isChecked():
            if not roles.get("head_center"):
                errors.append(tr('머리 중심 신체점 지정 필요'))
        return errors

    def apply_nort_bodypart_roles(self, roles: dict | None) -> None:
        roles = roles or {}
        role_widgets = {
            "nose": "nort_nose_bodypart",
            "head_center": "nort_head_bodypart",
            "body_center": "nort_body_bodypart",
            "rear_center": "nort_rear_bodypart",
        }
        for role, attribute in role_widgets.items():
            if not hasattr(self, attribute) or role not in roles:
                continue
            combo = getattr(self, attribute)
            requested = str(roles.get(role, "") or "")
            target = combo.findData(requested)
            if target >= 0:
                combo.setCurrentIndex(target)

    @staticmethod
    def automatic_nort_role(bodyparts: list[str], aliases: tuple[str, ...]) -> str:
        by_normalized = {str(part).strip().lower(): str(part) for part in bodyparts}
        for alias in aliases:
            if alias.lower() in by_normalized:
                return by_normalized[alias.lower()]
        return ""

    def refresh_nort_bodypart_roles(self, bodyparts: list[str]) -> None:
        role_widgets = {
            "nose": ("nort_nose_bodypart", ("nose",)),
            "head_center": ("nort_head_bodypart", ("head_center", "head_midpoint")),
            "body_center": ("nort_body_bodypart", ("body_center", "mouse_center")),
            "rear_center": ("nort_rear_bodypart", ("rear_center",)),
        }
        previous = self.nort_bodypart_roles()
        for role, (attribute, aliases) in role_widgets.items():
            if not hasattr(self, attribute):
                continue
            combo = getattr(self, attribute)
            current_parts = [str(combo.itemData(i)) for i in range(combo.count()) if combo.itemData(i)]
            if current_parts == bodyparts:
                continue
            combo.blockSignals(True)
            combo.clear()
            if role != "nose":
                combo.addItem(tr('사용 안 함'), "")
            for part in bodyparts:
                combo.addItem(str(part), str(part))
            requested = previous.get(role, "") or self.automatic_nort_role(bodyparts, aliases)
            target = combo.findData(requested)
            combo.setCurrentIndex(target if target >= 0 else 0)
            combo.blockSignals(False)

    def analysis_bodypart_resolution(self, arena_dirs) -> dict:
        """Use checked analysis inputs first, then the selected model if none exist."""
        from hagisilta_analysis_bodyparts import resolve_analysis_bodyparts
        result = resolve_analysis_bodyparts(arena_dirs)
        if not result["has_results"] and not result["issues"]:
            result["bodyparts"] = self.tracking_bodyparts()
        details = []
        if result["has_results"]:
            details.append(tr('체크한 분석 대상의 실제 좌표 파일에서 읽은 신체점입니다.'))
        else:
            details.append(tr('좌표 결과가 아직 없어 현재 선택한 트래킹 모델의 신체점을 표시합니다.'))
        if result["mixed"]:
            details.append(tr('결과별 신체점 구성이 달라 모든 결과에 공통으로 있는 이름만 표시합니다.'))
        if result["missing"]:
            details.append(tr('아직 좌표 결과가 없는 Arena {value1}개는 별도 준비가 필요합니다.', value1=len(result['missing'])))
        details.extend(result["issues"])
        details.extend(result["files"][:20])
        result["detail"] = "\n".join(details)
        return result

    def refresh_ymaze_analysis_bodyparts(self) -> None:
        if not hasattr(self, "ymaze_bodyparts"):
            return
        result = self.analysis_bodypart_resolution(sorted(getattr(self, "ymaze_checked_bundles", set())))
        selected = self.selected_ymaze_bodyparts() if getattr(self, "ymaze_bodypart_checks", {}) else None
        project_key = str(self.config.resolve()) if self.config else ""
        if getattr(self, "_ymaze_bodypart_selection_project", None) != project_key:
            self._ymaze_bodypart_selection_project = project_key
            self._ymaze_bodypart_selection_cache = {}
        else:
            previous = tuple(getattr(self, "ymaze_bodypart_checks", {}))
            if previous:
                self._ymaze_bodypart_selection_cache[previous] = list(selected or [])
        schema = tuple(result["bodyparts"])
        cache = self._ymaze_bodypart_selection_cache
        if schema in cache:
            selected = list(cache[schema])
        while len(cache) > 16:
            cache.pop(next(iter(cache)))
        self.populate_ymaze_bodyparts(result["bodyparts"], selected)
        self.ymaze_bodyparts.setToolTip(result["detail"])
        hint = getattr(self, "ymaze_bodypart_empty_hint", None)
        if hint is not None:
            if result["issues"]:
                hint.setText(tr('신체점 조회 실패 · 결과를 확인하세요'))
            elif result["mixed"]:
                hint.setText(tr('공통 신체점 없음 · 분석 대상을 확인하세요'))
            hint.setToolTip(result["detail"])

    def nort_analysis_arena_dirs(self) -> list[Path]:
        arenas = []
        for subject in self.checked_spatial_subject_paths() if hasattr(self, "spatial_checked_subjects") else []:
            info = self.nort_experiment_info_path(subject)
            try:
                records = json.loads(info.read_text(encoding="utf-8")).get("arenas", []) if info and info.is_file() else []
                ids = {int(row["arena_id"]) for row in records}
            except (OSError, ValueError, KeyError, TypeError):
                ids = set()
            arenas.extend(path for path in sorted(subject.glob("arena_*"))
                          if path.is_dir() and (not ids or self.spatial_arena_id(path) in ids))
        return arenas

    def refresh_nort_analysis_bodyparts(self) -> None:
        if not hasattr(self, "nort_nose_bodypart"):
            return
        result = self.analysis_bodypart_resolution(self.nort_analysis_arena_dirs())
        self.refresh_nort_bodypart_roles(result["bodyparts"])
        for name in ("nort_nose_bodypart", "nort_head_bodypart", "nort_body_bodypart", "nort_rear_bodypart"):
            if hasattr(self, name):
                getattr(self, name).setToolTip(result["detail"])

    def refresh_zone_analysis_bodyparts(self) -> None:
        if not hasattr(self, "zone_bodypart"):
            return
        root = self.zone_tracked_edit.text().strip()
        arenas = sorted(Path(root).glob("arena_*")) if root else []
        result = self.analysis_bodypart_resolution([path for path in arenas if path.is_dir()])
        bodyparts = result["bodyparts"]
        self.zone_bodypart.setToolTip(result["detail"])
        if [self.zone_bodypart.itemData(i) for i in range(self.zone_bodypart.count())] == bodyparts:
            return
        selected = str(self.zone_bodypart.currentData() or "")
        self.zone_bodypart.blockSignals(True)
        self.zone_bodypart.clear()
        for part in bodyparts:
            self.zone_bodypart.addItem(part, part)
        self.zone_bodypart.setEnabled(bool(bodyparts))
        target = self.zone_bodypart.findData(selected)
        if target < 0:
            target = self.zone_bodypart.findData("body_center")
        self.zone_bodypart.setCurrentIndex(max(0, target))
        self.zone_bodypart.blockSignals(False)

    def refresh_tracking_bodypart_consumers(self) -> None:
        """Refresh each experiment from its own checked results/model metadata."""
        self.refresh_nort_analysis_bodyparts()
        self.refresh_ymaze_analysis_bodyparts()
        self.refresh_zone_analysis_bodyparts()
        watermaze = getattr(self, "pages", {}).get("watermaze")
        if watermaze is not None and hasattr(watermaze, "refresh_bodyparts"):
            watermaze.refresh_bodyparts()

    def activate_external_tracking_model(
        self,
        model_config: Path,
        snapshot: Path,
        shuffle: int,
        snapshot_index: int | str,
        external_parts: list[str] | None = None,
    ) -> bool:
        if not self.config:
            return False
        if external_parts is None:
            external_parts = model_bodyparts_from_config(model_config)
        settings = load_machine_settings()
        settings.setdefault("project_external_tracking_models", {})[str(self.config.resolve())] = {
            "config": str(model_config.resolve()),
            "snapshot": str(snapshot.resolve()),
            "shuffle": int(shuffle),
            "snapshot_index": snapshot_index,
            "bodyparts": list(external_parts or []),
        }
        save_machine_settings(settings)
        self.append_log(
            tr('외부 트래킹 모델 지정: Shuffle {value1} · {value2}\n모델 프로젝트: {value3}', value1=shuffle, value2=snapshot, value3=model_config)
        )
        self.refresh_tracking_bodypart_consumers()
        self.update_batch_target_summary()
        return True

    def browse_evaluation_model_bundle(self) -> None:
        if not self.require_config():
            return
        selected, _ = QFileDialog.getOpenFileName(
            self,
            tr('모델 평가 표에 추가할 HAGISILTA 모델 ZIP 선택'),
            str(self.config.parent),
            tr('HAGISILTA 모델 ZIP (*.hagimodel.zip *.zip);;모든 파일 (*.*)'),
        )
        if not selected:
            return
        bundle = Path(selected).resolve()
        try:
            imported = import_portable_model_into_project(bundle, self.config)
        except Exception as error:
            QMessageBox.critical(self, tr('평가 모델 ZIP 가져오기 실패'), str(error))
            return
        shuffle = int(imported["shuffle"])
        self.refresh_model_inventory_table(shuffle)
        self.append_log(
            tr('평가 모델 ZIP 가져오기 완료\n원본 ZIP: {value1}\n현재 프로젝트 Shuffle: {value2}\n체크포인트: {value3}', value1=bundle, value2=shuffle, value3=imported['snapshot'])
        )
        QMessageBox.information(
            self,
            tr('평가 모델 ZIP 가져오기 완료'),
            tr('모델을 현재 프로젝트의 Shuffle {value1}로 추가했습니다.\n모델 평가 표에서 선택한 뒤 Validation·Test 평가를 진행할 수 있습니다.\n\n{value2}', value1=shuffle, value2=imported['snapshot']),
        )

    def browse_external_tracking_model(self) -> None:
        if not self.require_config():
            return
        current = self.project_external_tracking_model()
        start = str(current["snapshot"].parent) if current else str(self.config.parent)
        selected, _ = QFileDialog.getOpenFileName(
            self,
            tr('외부 DLC 모델 또는 HAGISILTA 모델 ZIP 선택'),
            start,
            tr('HAGISILTA 모델 ZIP (*.zip);;DLC PyTorch 체크포인트 (snapshot*.pt snapshot*.pth);;모든 파일 (*.*)'),
        )
        if not selected:
            return
        selected_path = Path(selected).resolve()
        if selected_path.suffix.lower() == ".zip":
            model_root = project_state_root(self.config.parent) / "external-models"
            model_root.mkdir(parents=True, exist_ok=True)
            safe_name = re.sub(r"[^A-Za-z0-9._-]+", "-", selected_path.stem).strip("-") or "model"
            destination = model_root / f"{safe_name}-{time.strftime('%Y%m%d-%H%M%S')}"
            try:
                imported = install_portable_model_bundle(selected_path, destination)
                if not self.activate_external_tracking_model(
                    imported["config"],
                    imported["snapshot"],
                    imported["shuffle"],
                    imported["snapshot_index"],
                    imported["bodyparts"],
                ):
                    shutil.rmtree(destination, ignore_errors=True)
                    return
            except Exception as error:
                shutil.rmtree(destination, ignore_errors=True)
                QMessageBox.critical(self, tr('모델 ZIP 가져오기 실패'), str(error))
                return
            QMessageBox.information(
                self,
                tr('모델 ZIP 가져오기 완료'),
                tr('모델을 현재 프로젝트의 전용 폴더로 가져왔습니다.\n\n{value1}', value1=destination),
            )
            return
        snapshot = selected_path
        if snapshot.suffix.lower() not in {".pt", ".pth"}:
            QMessageBox.warning(
                self, tr('체크포인트 확인'), tr('DLC PyTorch 체크포인트(.pt 또는 .pth)를 선택하세요.')
            )
            return
        model_config = next(
            (parent / "config.yaml" for parent in snapshot.parents if (parent / "config.yaml").is_file()),
            None,
        )
        if model_config is None:
            selected_config, _ = QFileDialog.getOpenFileName(
                self,
                tr('이 모델을 만든 DLC 프로젝트의 config.yaml 선택'),
                str(snapshot.parent),
                "DeepLabCut config (config.yaml);;YAML (*.yaml *.yml)",
            )
            if not selected_config:
                return
            model_config = Path(selected_config).resolve()
        try:
            models = trained_model_inventory(model_config)
        except Exception as error:
            QMessageBox.warning(self, tr('외부 모델 확인 실패'), tr('모델 프로젝트를 읽을 수 없습니다.\n\n{value1}', value1=error))
            return
        matching_model = None
        for model in models:
            candidates = [Path(path).resolve() for path in model.get("snapshots", [])]
            if snapshot in candidates:
                matching_model = model
                break
        if matching_model is None:
            QMessageBox.warning(
                self,
                tr('외부 모델 확인 실패'),
                tr('선택한 체크포인트가 지정된 config.yaml의 DLC 모델 목록에 없습니다.\n체크포인트와 같은 프로젝트의 config.yaml을 선택했는지 확인하세요.'),
            )
            return
        shuffle = int(matching_model["shuffle"])
        snapshots = [Path(path).resolve() for path in matching_model.get("snapshots", [])]
        snapshot_index: int | str = (
            "best" if snapshot.name.lower().startswith("snapshot-best") else snapshots.index(snapshot)
        )
        try:
            external_payload = yaml.safe_load(model_config.read_text(encoding="utf-8")) or {}
            external_parts = list(map(str, external_payload.get("bodyparts", []) or []))
        except Exception as error:
            QMessageBox.warning(self, tr('모델 설정 확인 실패'), str(error))
            return
        self.activate_external_tracking_model(
            model_config, snapshot, shuffle, snapshot_index, external_parts
        )

    def export_selected_evaluation_model_bundle(self) -> None:
        if not self.require_config():
            return
        payload = self.selected_model_payload()
        if not payload:
            QMessageBox.information(self, tr('내보낼 모델 선택'), tr('먼저 모델 표에서 내보낼 모델을 선택하세요.'))
            return
        shuffle, snapshot = payload
        if snapshot is None or not snapshot.is_file():
            QMessageBox.warning(
                self,
                tr('모델 체크포인트 확인'),
                tr('선택한 모델의 Best 체크포인트를 찾을 수 없습니다. 목록을 새로고침한 뒤 다시 확인하세요.'),
            )
            return
        self.save_portable_model_bundle(self.config, snapshot, shuffle)

    def save_portable_model_bundle(
        self, model_config: Path, snapshot: Path, shuffle: int
    ) -> Path | None:
        default_name = (
            f"{re.sub(r'[^A-Za-z0-9._-]+', '-', model_config.parent.name)}"
            f"-shuffle{shuffle}-{snapshot.stem}.hagimodel.zip"
        )
        selected, _ = QFileDialog.getSaveFileName(
            self,
            tr('HAGISILTA 휴대용 모델 ZIP 저장'),
            str(self.config.parent / default_name),
            tr('HAGISILTA 모델 ZIP (*.zip)'),
        )
        if not selected:
            return None
        try:
            destination = write_portable_model_bundle(
                model_config, snapshot, shuffle, Path(selected)
            )
        except Exception as error:
            QMessageBox.critical(self, tr('모델 ZIP 내보내기 실패'), str(error))
            return None
        self.append_log(tr('휴대용 모델 ZIP 생성: {value1}', value1=destination))
        QMessageBox.information(
            self,
            tr('모델 ZIP 내보내기 완료'),
            tr('다른 PC나 프로젝트에서 ‘모델·ZIP 불러오기’로 이 파일 하나를 선택하면 됩니다.\n\n{value1}', value1=destination),
        )
        return destination

    def export_tracking_model_bundle(self) -> None:
        if not self.require_config():
            return
        external = self.project_external_tracking_model()
        if external:
            model_config = Path(external["config"])
            snapshot = Path(external["snapshot"])
            shuffle = int(external["shuffle"])
        else:
            final_shuffle = self.project_final_model_shuffle()
            models = {int(model["shuffle"]): model for model in trained_model_inventory(self.config)}
            model = models.get(final_shuffle) if final_shuffle is not None else None
            if not model or not model.get("best"):
                QMessageBox.information(
                    self,
                    tr('내보낼 모델 없음'),
                    tr('모델 평가에서 최종 모델을 지정하거나 외부 모델을 먼저 불러오세요.'),
                )
                return
            model_config = self.config
            snapshot = Path(model["best"])
            shuffle = int(final_shuffle)
        self.save_portable_model_bundle(model_config, snapshot, shuffle)

    def clear_external_tracking_model(self) -> None:
        if not self.config:
            return
        settings = load_machine_settings()
        external_models = settings.setdefault("project_external_tracking_models", {})
        removed = external_models.pop(str(self.config.resolve()), None)
        save_machine_settings(settings)
        if removed:
            self.append_log(tr('외부 트래킹 모델 해제 · 프로젝트 최종 모델로 복귀'))
        self.refresh_tracking_bodypart_consumers()
        self.update_batch_target_summary()

    @staticmethod
    def format_model_metric(value, suffix: str = "") -> str:
        if value is None or pd.isna(value):
            return "-"
        return f"{float(value):.2f}{suffix}"

    def refresh_evaluation_dataset_summary(self) -> None:
        if not hasattr(self, "eval_dataset_summary"):
            return
        if not self.config or not self.config.is_file():
            self.eval_dataset_summary.value_label.setText(tr('프로젝트를 열면 Validation·Test 구성이 표시됩니다.'))
            if hasattr(self, "eval_dataset_state"):
                self.set_workflow_badge(self.eval_dataset_state, tr('프로젝트 필요'), False)
                self.eval_test_card.value_label.setText(tr('0 프레임'))
                self.eval_test_experiment_card.value_label.setText(tr('실험별 Test 데이터가 없습니다.'))
            return
        plan = load_split_plan(self.config.parent)
        counts = {"train": 0, "validation": 0, "test": 0}
        experiment_totals: dict[str, dict[str, int]] = {}
        enabled_count = 0
        for bundle in (plan.get("bundles", {}) or {}).values():
            if bundle.get("missing") or not bundle.get("enabled", True):
                continue
            enabled_count += 1
            bundle_counts = split_counts(bundle.get("assignments", {}))
            experiment = str(bundle.get("experiment", "미지정") or "미지정")
            experiment_counts = experiment_totals.setdefault(
                experiment, {"bundles": 0, "validation": 0, "test": 0}
            )
            experiment_counts["bundles"] += 1
            for role, count in bundle_counts.items():
                counts[role] += int(count)
                if role in {"validation", "test"}:
                    experiment_counts[role] += int(count)
        version = int(plan.get("dataset_version", 1) or 1)
        locked = split_plan_is_effectively_locked(plan)
        complete = locked and counts["validation"] > 0 and counts["test"] > 0
        state = tr('확정') if complete else tr('구성 확인 필요') if locked else tr('미확정')
        total = sum(counts.values())
        validation_percent = counts["validation"] * 100 / total if total else 0.0
        test_percent = counts["test"] * 100 / total if total else 0.0
        self.eval_dataset_summary.value_label.setText(
            tr('데이터셋 v{value1} · {value2} · 사용 {value3}묶음 · Validation {value4:,}프레임 · Test {value5:,}프레임', value1=version, value2=state, value3=enabled_count, value4=counts['validation'], value5=counts['test'])
        )
        if hasattr(self, "eval_dataset_state"):
            self.set_workflow_badge(self.eval_dataset_state, f"v{version} · {state}", complete)
            self.eval_dataset_panel_title.setText(tr('현재 Test 평가 데이터'))
            self.eval_test_card.title_label.setText(tr('현재 공통 Test'))
            self.eval_test_card.value_label.setText(
                tr('{value1:,} 프레임 · {value2:.1f}%', value1=counts['test'], value2=test_percent)
            )
            self.eval_test_card.setToolTip(
                tr('현재 확정 데이터셋의 같은 Test 프레임으로 선택한 모델을 평가합니다.')
            )
            breakdown = "\n".join(
                tr('{value1}  {value2}묶음 · Test {value3:,}프레임', value1=tr('미지정') if name == '미지정' else name, value2=values['bundles'], value3=values['test'])
                for name, values in sorted(experiment_totals.items())
            )
            self.eval_test_experiment_card.value_label.setText(
                breakdown if breakdown else tr('실험별 Test 데이터 없음')
            )

    def refresh_model_inventory_table(self, preferred_shuffle: int | None = None) -> None:
        if not hasattr(self, "eval_model_table"):
            return
        models = trained_model_inventory(self.config)
        self.refresh_evaluation_dataset_summary()
        final_shuffle = self.project_final_model_shuffle()
        table = self.eval_model_table
        selected_shuffles = [
            int(value) for value in self.eval_model_selector.checkedData()
        ] if hasattr(self, "eval_model_selector") else []
        current_shuffle = preferred_shuffle
        if current_shuffle is None and table.currentRow() >= 0:
            item = table.item(table.currentRow(), 0)
            current_shuffle = int(item.data(Qt.UserRole)) if item else None
        if preferred_shuffle is not None:
            selected_shuffles = [preferred_shuffle]
        table.setSortingEnabled(False)
        table.setRowCount(len(models))
        for row_index, model in enumerate(models):
            values = [
                f"Shuffle {model['shuffle']}",
                str(model["epochs"] or "-"),
                self.format_model_metric(model["train_rmse"], " px"),
                self.format_model_metric(model["validation_rmse"], " px"),
                self.format_model_metric(model["validation_map"]),
                self.format_model_metric(model["validation_mar"]),
                self.format_model_metric(model["test_rmse"], " px"),
                self.format_model_metric(model["test_map"]),
                self.format_model_metric(model["test_mar"]),
                self.format_model_metric(
                    model["test_coverage"] * 100 if model["test_coverage"] is not None else None,
                    "%",
                ),
                (
                    tr('최종 평가 완료')
                    if model["test_rmse"] is not None
                    else tr('Validation 완료')
                    if model["validation_rmse"] is not None
                    else tr('평가 전')
                ),
                tr('● 사용 중') if model["shuffle"] == final_shuffle else "-",
            ]
            for column, value in enumerate(values):
                item = SortableTableItem(value)
                item.setTextAlignment(Qt.AlignCenter)
                if column == 0:
                    item.setData(Qt.UserRole, model["shuffle"])
                    item.setData(Qt.UserRole + 1, str(model["best"] or ""))
                elif column == 1:
                    item.setData(Qt.UserRole, model["epochs"] if model["epochs"] is not None else -1)
                elif 2 <= column <= 9:
                    metric_keys = (
                        "train_rmse", "validation_rmse", "validation_map", "validation_mar",
                        "test_rmse", "test_map", "test_mar", "test_coverage",
                    )
                    metric = model[metric_keys[column - 2]]
                    item.setData(Qt.UserRole, float(metric) if metric is not None else -1.0)
                table.setItem(row_index, column, item)
        table.setSortingEnabled(True)
        table.sortItems(0, Qt.AscendingOrder)
        available_shuffles = {int(model["shuffle"]) for model in models}
        selected_shuffles = [shuffle for shuffle in selected_shuffles if shuffle in available_shuffles]
        if not selected_shuffles and models:
            selected_shuffles = [
                current_shuffle if current_shuffle in available_shuffles else int(models[-1]["shuffle"])
            ]
        if hasattr(self, "eval_model_selector"):
            self.eval_model_selector.setCheckItems(
                [(f"Shuffle {model['shuffle']}", int(model["shuffle"])) for model in models],
                selected_shuffles,
            )
        if hasattr(self, "eval_pilot_model_selector"):
            pilot_current = self.eval_pilot_model_selector.currentData()
            saved_pilot_shuffle = getattr(self, "saved_eval_pilot_shuffle", None)
            pilot_preferred = (
                int(pilot_current)
                if pilot_current is not None and int(pilot_current) in available_shuffles
                else int(saved_pilot_shuffle)
                if saved_pilot_shuffle is not None and int(saved_pilot_shuffle) in available_shuffles
                else selected_shuffles[0] if selected_shuffles else None
            )
            self.eval_pilot_model_selector.blockSignals(True)
            self.eval_pilot_model_selector.clear()
            for model in models:
                snapshot_name = Path(model["best"]).name if model["best"] else tr('체크포인트 확인 필요')
                self.eval_pilot_model_selector.addItem(
                    f"Shuffle {model['shuffle']} · {snapshot_name}", int(model["shuffle"])
                )
            pilot_index = self.eval_pilot_model_selector.findData(pilot_preferred)
            self.eval_pilot_model_selector.setCurrentIndex(max(0, pilot_index))
            self.eval_pilot_model_selector.setEnabled(bool(models))
            self.eval_pilot_model_selector.blockSignals(False)
            if self.eval_pilot_model_selector.currentData() is not None:
                self.evaluation_pilot_model_changed(
                    self.eval_pilot_model_selector.currentIndex()
                )
        table.blockSignals(True)
        table.clearSelection()
        first_selected_row = -1
        for row in range(table.rowCount()):
            if int(table.item(row, 0).data(Qt.UserRole)) in selected_shuffles:
                table.selectionModel().select(
                    table.model().index(row, 0),
                    QItemSelectionModel.Select | QItemSelectionModel.Rows,
                )
                if first_selected_row < 0:
                    first_selected_row = row
        if first_selected_row >= 0:
            table.setCurrentCell(first_selected_row, 0, QItemSelectionModel.NoUpdate)
        table.blockSignals(False)
        self.eval_model_table_container.setVisible(bool(models))
        self.set_workflow_badge(self.eval_model_badge, tr('{value1}개', value1=len(models)), bool(models))
        if final_shuffle is not None and hasattr(self, "track_shuffle"):
            self.track_shuffle.setValue(final_shuffle)
        if models:
            latest = models[-1]
            best_name = Path(latest["best"]).name if latest["best"] else tr('체크포인트 확인 필요')
            self.train_completed_summary.value_label.setText(
                f"Shuffle {latest['shuffle']} · {best_name} · "
                f"{tr('최종 평가 완료') if latest['test_rmse'] is not None else tr('Validation 완료') if latest['validation_rmse'] is not None else tr('평가 전')}"
            )
            self.train_evaluate_button.setEnabled(True)
            self.set_workflow_badge(self.train_completion_badge, tr('평가 가능'), True)
            self.select_evaluation_model_from_table()
        else:
            self.eval_inventory_summary.value_label.setText(
                tr('학습된 모델이 없습니다. 모델 학습 탭에서 첫 모델을 만든 뒤 다시 확인하세요.')
            )
            self.eval_target_summary.value_label.setText(tr('평가할 모델이 없습니다.'))
            self.eval_run_summary.value_label.setText(tr('모델 학습을 먼저 완료하세요.'))
            self.train_completed_summary.value_label.setText(
                tr('학습이 끝나면 Shuffle과 Best 체크포인트가 표시됩니다.')
            )
            self.train_evaluate_button.setEnabled(False)
            self.set_workflow_badge(self.train_completion_badge, tr('학습 전'), False)
        self.update_final_model_button()
        if hasattr(self, "batch_source_table"):
            self.update_batch_target_summary()

    def selected_model_payload(self) -> tuple[int, Path | None] | None:
        payloads = self.selected_model_payloads()
        if not payloads:
            return None
        current_row = self.eval_model_table.currentRow()
        if current_row >= 0:
            current_item = self.eval_model_table.item(current_row, 0)
            if current_item:
                current_shuffle = int(current_item.data(Qt.UserRole))
                for payload in payloads:
                    if payload[0] == current_shuffle:
                        return payload
        return payloads[0]

    def selected_model_payloads(self) -> list[tuple[int, Path | None]]:
        if not hasattr(self, "eval_model_table"):
            return []
        selected_rows = self.eval_model_table.selectionModel().selectedRows()
        if not selected_rows:
            return []
        payloads: list[tuple[int, Path | None]] = []
        for index in sorted(selected_rows, key=lambda selected: selected.row()):
            item = self.eval_model_table.item(index.row(), 0)
            if not item:
                continue
            snapshot_text = str(item.data(Qt.UserRole + 1) or "")
            payloads.append(
                (int(item.data(Qt.UserRole)), Path(snapshot_text) if snapshot_text else None)
            )
        return payloads

    def show_evaluation_model_context_menu(self, position) -> None:
        rows = self.eval_model_table.restore_right_click_rows(position)
        if not rows:
            return
        payload = self.selected_model_payload()
        if not payload:
            return
        selected_count = len(self.selected_model_payloads())
        shuffle, snapshot = payload
        menu = QMenu(self.eval_model_table)
        evaluate_action = menu.addAction(
            tr('선택한 {value1}개 모델 현재 Test 일괄 평가', value1=selected_count)
            if selected_count > 1 else
            tr('이 행 모델 Validation·Test 평가')
        )
        menu.addSeparator()
        export_action = menu.addAction(tr('이 행 모델 ZIP으로 내보내기'))
        retrain_action = menu.addAction(tr('이 행 모델 추가학습'))
        final_action = menu.addAction(
            tr('이 행 최종 사용 지정 취소')
            if self.project_final_model_shuffle() == shuffle
            else tr('이 행 최종 사용 모델로 지정')
        )
        menu.addSeparator()
        delete_action = menu.addAction(tr('이 행 모델 삭제…'))
        menu.addSeparator()
        import_action = menu.addAction(tr('모델 ZIP 불러오기'))
        refresh_action = menu.addAction(tr('목록 · 결과 새로고침'))
        export_action.setEnabled(snapshot is not None and snapshot.is_file())
        retrain_action.setEnabled(snapshot is not None and snapshot.is_file())
        for single_model_action in (export_action, retrain_action, final_action, delete_action):
            single_model_action.setEnabled(single_model_action.isEnabled() and selected_count == 1)
        chosen = menu.exec(self.eval_model_table.viewport().mapToGlobal(position))
        if chosen == evaluate_action:
            self.run_selected_model_evaluations()
        elif chosen == export_action:
            self.export_selected_evaluation_model_bundle()
        elif chosen == retrain_action:
            self.retrain_selected_model()
        elif chosen == final_action:
            self.use_selected_model()
        elif chosen == delete_action:
            self.delete_selected_evaluation_model()
        elif chosen == import_action:
            self.browse_evaluation_model_bundle()
        elif chosen == refresh_action:
            self.refresh_model_inventory_table(shuffle)

    def delete_selected_evaluation_model(self) -> None:
        if not self.require_config():
            return
        payload = self.selected_model_payload()
        if not payload:
            QMessageBox.information(self, tr('모델 선택'), tr('삭제할 모델 행을 먼저 선택하세요.'))
            return
        shuffle, snapshot = payload
        if snapshot is None or not snapshot.is_file():
            QMessageBox.warning(self, tr('모델 파일 없음'), tr('선택 모델의 체크포인트를 찾을 수 없습니다.'))
            return
        model_root = snapshot.parent.parent.resolve()
        expected_root = (self.config.parent / "dlc-models-pytorch").resolve()
        if expected_root not in model_root.parents:
            QMessageBox.warning(
                self, tr('모델 위치 확인'), tr('현재 프로젝트 안의 모델 폴더만 이 표에서 삭제할 수 있습니다.')
            )
            return
        answer = QMessageBox.question(
            self,
            tr('모델 삭제'),
            tr('Shuffle {value1} 모델을 삭제할까요?\n\n체크포인트와 모델 설정·해당 Test 결과는 프로젝트 휴지통으로 이동합니다. 학습 데이터와 원본 모델 ZIP은 유지됩니다.', value1=shuffle),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if answer != QMessageBox.Yes:
            return
        trash_root = (
            self.config.parent / ".hagisilta-trash" / "models" /
            time.strftime("%Y%m%d-%H%M%S") / f"shuffle-{shuffle:02d}"
        )
        trash_root.mkdir(parents=True, exist_ok=True)
        shutil.move(str(model_root), str(trash_root / model_root.name))
        test_result = project_state_root(self.config.parent) / "test-evaluations" / f"shuffle-{shuffle:02d}"
        if test_result.exists():
            shutil.move(str(test_result), str(trash_root / "test-evaluation"))
        provenance = project_state_root(self.config.parent) / "imported-models" / f"shuffle-{shuffle:02d}.json"
        if provenance.is_file():
            shutil.move(str(provenance), str(trash_root / provenance.name))
        if self.project_final_model_shuffle() == shuffle:
            settings = load_machine_settings()
            settings.setdefault("project_final_models", {}).pop(str(self.config.resolve()), None)
            save_machine_settings(settings)
        self.append_log(tr('Shuffle {value1} 모델을 프로젝트 휴지통으로 이동: {value2}', value1=shuffle, value2=trash_root))
        self.refresh_model_inventory_table()
        QMessageBox.information(
            self, tr('모델 삭제 완료'), tr('Shuffle {value1} 모델을 프로젝트 휴지통으로 이동했습니다.\n\n{value2}', value1=shuffle, value2=trash_root)
        )

    @staticmethod
    def _metric_number(value, suffix: str = "", digits: int = 2) -> str:
        try:
            number = float(value)
        except (TypeError, ValueError):
            return "-"
        if not np.isfinite(number):
            return "-"
        return f"{number:.{digits}f}{suffix}"

    def refresh_pose_validation_detail(self) -> None:
        if not hasattr(self, "eval_pose_detail_panel"):
            return
        payloads = self.selected_model_payloads()
        if len(payloads) != 1:
            self.eval_pose_detail_panel.setVisible(bool(payloads))
            self.eval_pose_detail_status.setText(
                tr('여러 모델을 선택했습니다. 신체점별 상세는 모델 한 개를 선택하면 표시됩니다.')
            )
            self.eval_pose_bodypart_table.setRowCount(0)
            return
        shuffle = int(payloads[0][0])
        model = next(
            (item for item in trained_model_inventory(self.config) if int(item["shuffle"]) == shuffle),
            None,
        )
        self.eval_pose_detail_panel.setVisible(True)
        if not model or not model.get("test_per_keypoint"):
            self.eval_pose_detail_status.setText(
                tr('이 결과에는 상세 Pose 지표가 없습니다. 현재 Test 평가를 다시 실행하면 생성됩니다.')
            )
            for card in self.eval_pose_metric_cards.values():
                card.value_label.setText("-")
            self.eval_pose_bodypart_table.setRowCount(0)
            return
        self.eval_pose_detail_status.setText(
            tr('Shuffle {value1} · 독립 Test {value2:,}프레임', value1=shuffle, value2=int(model.get('test_frames') or 0))
        )
        values = {
            "rmse": self._metric_number(model.get("test_rmse"), " px"),
            "median": self._metric_number(model.get("test_median_error"), " px"),
            "normalized": self._metric_number(model.get("test_normalized_error"), "%"),
            "pck3": self._metric_number((model.get("test_pck_3") or 0) * 100, "%", 1),
            "pck5": self._metric_number((model.get("test_pck_5") or 0) * 100, "%", 1),
            "pck10": self._metric_number((model.get("test_pck_10") or 0) * 100, "%", 1),
            "coverage": self._metric_number((model.get("test_coverage") or 0) * 100, "%", 1),
            "dropout": self._metric_number((model.get("test_dropout") or 0) * 100, "%", 1),
        }
        for key, text_value in values.items():
            self.eval_pose_metric_cards[key].value_label.setText(text_value)
        per_keypoint = model.get("test_per_keypoint", {}) or {}
        table = self.eval_pose_bodypart_table
        table.setRowCount(len(per_keypoint))
        tooltips = [
            tr('평가한 신체점입니다.'), tr('픽셀 RMSE입니다.'), tr('픽셀 오차 중앙값입니다.'),
            tr('ROI 대각선 대비 오차 백분율 중앙값입니다.'), tr('3픽셀 이내 비율입니다.'),
            tr('5픽셀 이내 비율입니다.'), tr('10픽셀 이내 비율입니다.'),
            tr('신뢰도 기준 이상 검출 비율입니다.'), tr('신뢰도 미달·누락 비율입니다.'),
        ]
        for row, (bodypart, metrics) in enumerate(per_keypoint.items()):
            row_values = [
                str(bodypart),
                self._metric_number(metrics.get("rmse_px"), " px"),
                self._metric_number(metrics.get("median_error_px"), " px"),
                self._metric_number(metrics.get("normalized_error_percent"), "%"),
                self._metric_number((metrics.get("pck_3px") or 0) * 100, "%", 1),
                self._metric_number((metrics.get("pck_5px") or 0) * 100, "%", 1),
                self._metric_number((metrics.get("pck_10px") or 0) * 100, "%", 1),
                self._metric_number((metrics.get("coverage_at_pcutoff") or 0) * 100, "%", 1),
                self._metric_number((metrics.get("dropout_rate") or 0) * 100, "%", 1),
            ]
            for column, text_value in enumerate(row_values):
                item = QTableWidgetItem(text_value)
                item.setTextAlignment(Qt.AlignCenter)
                item.setToolTip(tooltips[column])
                table.setItem(row, column, item)

    def select_evaluation_model_from_table(self) -> None:
        payloads = self.selected_model_payloads()
        payload = self.selected_model_payload()
        if hasattr(self, "eval_model_selector"):
            self.eval_model_selector.setCheckedData(
                [shuffle for shuffle, _snapshot in payloads], emit=False
            )
        if len(payloads) > 1:
            shuffles = [shuffle for shuffle, _snapshot in payloads]
            self.eval_shuffle.blockSignals(True)
            self.eval_shuffle.setValue(shuffles[0])
            self.eval_shuffle.blockSignals(False)
            self.run_evaluation_button.setText(tr('선택한 {value1}개 모델 현재 Test 평가', value1=len(shuffles)))
            self.eval_inventory_summary.value_label.setText(
                tr('선택 {value1}개 · ', value1=len(shuffles)) + " · ".join(f"Shuffle {shuffle}" for shuffle in shuffles)
            )
            self.eval_target_summary.value_label.setText(
                tr('선택한 {value1}개 모델의 기존 Validation은 보존하고 현재 Test만 순차 평가합니다.', value1=len(shuffles))
            )
            self.eval_run_summary.value_label.setText(
                tr('현재 공통 Test 결과만 모델별로 저장하며, 기존 Validation 결과와 모델 가중치는 변경하지 않습니다.')
            )
        elif payload:
            shuffle = payload[0]
            self.eval_shuffle.blockSignals(True)
            self.eval_shuffle.setValue(shuffle)
            self.eval_shuffle.blockSignals(False)
            self.run_evaluation_button.setText(tr('Shuffle {value1} Validation·Test 평가', value1=shuffle))
            row = self.eval_model_table.currentRow()
            if row >= 0:
                epoch = self.eval_model_table.item(row, 1).text()
                validation_rmse = self.eval_model_table.item(row, 3).text()
                test_rmse = self.eval_model_table.item(row, 6).text()
                evaluation_state = self.eval_model_table.item(row, 10).text()
                final_state = self.eval_model_table.item(row, 11).text()
                self.eval_inventory_summary.value_label.setText(
                    f"Shuffle {shuffle} · Epoch {epoch} · Validation RMSE {validation_rmse} · "
                    f"Test RMSE {test_rmse} · {final_state}"
                )
                self.eval_target_summary.value_label.setText(
                    f"Shuffle {shuffle} · {evaluation_state}"
                )
                self.eval_run_summary.value_label.setText(
                    tr('기존 평가 결과를 확인하거나 현재 설정으로 다시 평가할 수 있습니다.')
                )
        else:
            self.eval_inventory_summary.value_label.setText(tr('표에서 확인할 모델을 선택하세요.'))
            self.eval_target_summary.value_label.setText(tr('1단계 모델 표에서 평가할 모델을 선택하세요.'))
        self.refresh_evaluation_dataset_summary()
        self.refresh_pose_validation_detail()
        self.update_final_model_button()

    def evaluation_model_selector_changed(self) -> None:
        if not hasattr(self, "eval_model_table"):
            return
        selected_shuffles = {
            int(value) for value in self.eval_model_selector.checkedData()
        }
        table = self.eval_model_table
        table.blockSignals(True)
        table.clearSelection()
        first_selected_row = -1
        for row in range(table.rowCount()):
            item = table.item(row, 0)
            if item and int(item.data(Qt.UserRole)) in selected_shuffles:
                table.selectionModel().select(
                    table.model().index(row, 0),
                    QItemSelectionModel.Select | QItemSelectionModel.Rows,
                )
                if first_selected_row < 0:
                    first_selected_row = row
        if first_selected_row >= 0:
            table.setCurrentCell(first_selected_row, 0, QItemSelectionModel.NoUpdate)
        table.blockSignals(False)
        self.select_evaluation_model_from_table()

    def update_final_model_button(self) -> None:
        if not hasattr(self, "use_model_button"):
            return
        payloads = self.selected_model_payloads()
        payload = self.selected_model_payload() if len(payloads) == 1 else None
        selected_shuffle = payload[0] if payload else None
        self.use_model_button.setEnabled(payload is not None)
        if hasattr(self, "eval_retrain_button"):
            self.eval_retrain_button.setEnabled(payload is not None)
        if hasattr(self, "eval_export_model_button"):
            self.eval_export_model_button.setEnabled(payload is not None)
        if hasattr(self, "run_evaluation_button"):
            self.run_evaluation_button.setEnabled(bool(payloads))
        is_final = selected_shuffle is not None and selected_shuffle == self.project_final_model_shuffle()
        self.use_model_button.setText(
            tr('최종 사용 지정 취소') if is_final else tr('최종 사용 모델로 지정')
        )
        self.use_model_button.setToolTip(
            tr('이 프로젝트의 최종 사용 모델 지정을 해제합니다. 모델 파일은 삭제되지 않습니다.')
            if is_final else
            tr('선택한 모델을 영상 트래킹에서 사용할 이 프로젝트의 최종 모델로 지정합니다.')
        )

    def evaluation_shuffle_changed(self, shuffle: int) -> None:
        self.run_evaluation_button.setText(tr('Shuffle {value1} Validation·Test 평가', value1=shuffle))
        if hasattr(self, "eval_pilot_output"):
            self.eval_pilot_output.setText(str(self.evaluation_pilot_output_for_shuffle(shuffle)))
        if hasattr(self, "eval_pilot_badge"):
            self.set_workflow_badge(self.eval_pilot_badge, tr('Shuffle {value1} · 시험 전', value1=shuffle), False)
            self.eval_pilot_summary.value_label.setText(
                tr('Shuffle {value1}을(를) 대표 영상 하나에 적용해 확인하세요.', value1=shuffle)
            )
        matching_row = -1
        for row in range(self.eval_model_table.rowCount()):
            item = self.eval_model_table.item(row, 0)
            if item and int(item.data(Qt.UserRole)) == shuffle:
                matching_row = row
                break
        if matching_row >= 0 and self.eval_model_table.currentRow() != matching_row:
            self.eval_model_table.selectRow(matching_row)
        elif matching_row < 0:
            self.eval_model_table.clearSelection()

    def evaluation_pilot_model_changed(self, _index: int) -> None:
        if not hasattr(self, "eval_pilot_model_selector"):
            return
        shuffle = self.eval_pilot_model_selector.currentData()
        if shuffle is None:
            return
        shuffle = int(shuffle)
        self.eval_shuffle.blockSignals(True)
        self.eval_shuffle.setValue(shuffle)
        self.eval_shuffle.blockSignals(False)
        if hasattr(self, "eval_pilot_output"):
            self.eval_pilot_output.setText(
                str(self.evaluation_pilot_output_for_shuffle(shuffle))
            )
        if hasattr(self, "eval_pilot_badge"):
            self.set_workflow_badge(
                self.eval_pilot_badge, tr('Shuffle {value1} · 시험 전', value1=shuffle), False
            )
            self.eval_pilot_summary.value_label.setText(
                tr('Shuffle {value1}을(를) 대표 영상 하나에 적용해 확인하세요.', value1=shuffle)
            )
        self.refresh_evaluation_padding_hint()
        self.save_project_ui_state()

    def refresh_evaluation_padding_hint(self, *_args) -> None:
        if not hasattr(self, "eval_pilot_padding"):
            return
        mode = self.eval_pilot_padding.currentData()
        text = tr('저장된 모델 추론 설정 사용')
        try:
            if mode != "model":
                from hagisilta_evaluation_padding import padding_spec, padding_label
                if not self.config:
                    raise ValueError(tr('프로젝트·모델 선택 필요'))
                spec = padding_spec(self.config, self.eval_shuffle.value(), mode)
                text = (padding_label(spec) + tr(' px · 중앙 패딩') if mode == "training"
                        else tr('ROI별 최소 32배수 · 중앙 패딩'))
        except (OSError, ValueError, KeyError) as error:
            text = str(error)
        self.eval_pilot_padding_hint.setText(text)

    def run_selected_model_evaluations(self) -> None:
        payloads = self.selected_model_payloads()
        if not payloads:
            QMessageBox.information(self, tr('모델 선택'), tr('평가할 모델 행을 하나 이상 선택하세요.'))
            return
        if self.process and self.process.state() != QProcess.NotRunning:
            QMessageBox.information(self, tr('작업 실행 중'), tr('현재 작업이 끝나거나 중지된 뒤 실행하세요.'))
            return
        shuffles = [shuffle for shuffle, _snapshot in payloads]
        if len(shuffles) == 1:
            self.run_training("evaluate", shuffle_override=shuffles[0])
            return
        self.evaluation_batch_queue = list(shuffles)
        self.evaluation_batch_total = len(shuffles)
        self.evaluation_batch_completed = 0
        self.eval_run_summary.value_label.setText(
            tr('일괄 평가 준비 · {value1}개 모델 · ', value1=len(shuffles))
            + ", ".join(f"Shuffle {shuffle}" for shuffle in shuffles)
        )
        self._run_next_evaluation_batch_item()

    def _run_next_evaluation_batch_item(self) -> None:
        queue = list(getattr(self, "evaluation_batch_queue", []))
        if not queue:
            total = int(getattr(self, "evaluation_batch_total", 0))
            self.eval_run_summary.value_label.setText(
                tr('일괄 평가 완료 · 기존 Validation은 보존하고 {value1}개 모델의 현재 Test 결과를 갱신했습니다.', value1=total)
            )
            self.append_log(tr('모델 일괄 평가 완료 · {value1}개', value1=total))
            self.refresh_model_inventory_table()
            return
        shuffle = queue.pop(0)
        self.evaluation_batch_queue = queue
        current = int(getattr(self, "evaluation_batch_completed", 0)) + 1
        total = int(getattr(self, "evaluation_batch_total", current))
        self.eval_run_summary.value_label.setText(
            tr('일괄 평가 {value1}/{value2} · Shuffle {value3} 현재 Test 평가 중', value1=current, value2=total, value3=shuffle)
        )
        self.run_training(
            "evaluate-test",
            shuffle_override=shuffle,
            completion_callback=lambda code, selected_shuffle=shuffle: self._evaluation_batch_item_finished(
                selected_shuffle, code
            ),
        )

    def _evaluation_batch_item_finished(self, shuffle: int, exit_code: int) -> None:
        if exit_code:
            self.evaluation_batch_queue = []
            self.eval_run_summary.value_label.setText(
                tr('일괄 평가 중단 · Shuffle {value1} 평가 오류 · 실행 로그를 확인하세요.', value1=shuffle)
            )
            return
        self.evaluation_batch_completed = int(getattr(self, "evaluation_batch_completed", 0)) + 1
        QTimer.singleShot(0, self._run_next_evaluation_batch_item)

    def evaluation_pilot_output_for_shuffle(self, shuffle: int) -> Path:
        root = project_output_root(self.config.parent) if self.config else self.work_root
        return root / "model-evaluation-pilot" / f"shuffle_{shuffle:02d}"

    def pick_roi_profile(self, field: QLineEdit) -> None:
        initial = field.text().strip()
        if not initial and self.config:
            initial = str(project_state_root(self.config.parent) / "camera_profiles")
        selected, _ = QFileDialog.getOpenFileName(
            self, tr('시험 ROI 설정 선택'), initial, tr('HAGISILTA ROI·구역 설정 (*.json);;모든 파일 (*.*)')
        )
        if selected:
            field.setText(selected)

    def refresh_evaluation_pilot_roi_choices(self) -> None:
        if not hasattr(self, "eval_pilot_arena"):
            return
        previous = [int(value) for value in self.eval_pilot_arena.checkedData()]
        profile = Path(self.eval_pilot_roi_profile.text().strip())
        choices: list[tuple[str, int]] = []
        if profile.is_file():
            try:
                payload = json.loads(profile.read_text(encoding="utf-8"))
                for index, arena in enumerate(payload.get("arenas", []), start=1):
                    arena_id = int(arena.get("id", index))
                    name = str(arena.get("name") or arena.get("label") or "").strip()
                    base_label = f"ROI {arena_id}"
                    label = base_label + (
                        f" · {name}" if name and name.casefold() != base_label.casefold() else ""
                    )
                    choices.append((label, arena_id))
            except Exception:
                choices = []
        available = {data for _label, data in choices}
        checked = [value for value in previous if value in available]
        if not checked and choices:
            checked = [choices[0][1]]
        self.eval_pilot_arena.setCheckItems(choices, checked)

    def evaluation_pilot_roi_default(self) -> Path:
        root = self.config.parent if self.config else self.work_root
        video_stem = Path(self.eval_pilot_video.text().strip()).stem or "evaluation_pilot"
        return project_state_root(root) / "camera_profiles" / f"{video_stem}_evaluation_pilot_roi.json"

    def define_evaluation_pilot_roi(self) -> None:
        video = Path(self.eval_pilot_video.text().strip())
        if not video.is_file():
            self.pick_video(self.eval_pilot_video)
            video = Path(self.eval_pilot_video.text().strip())
            if not video.is_file():
                return
        profile_text = self.eval_pilot_roi_profile.text().strip()
        profile = Path(profile_text) if profile_text else self.evaluation_pilot_roi_default()
        def finished(saved_profile: Path) -> None:
            self.eval_pilot_roi_profile.setText(str(saved_profile))
            self.refresh_evaluation_pilot_roi_choices()
            self.set_workflow_badge(self.eval_pilot_badge, tr('ROI 준비'), True)
            self.eval_pilot_summary.value_label.setText(
                tr('시험 ROI가 저장되었습니다. 사용할 ROI를 체크하고 영상 테스트를 실행하세요.')
            )
            self.save_project_ui_state()

        self.start_tracking_roi_editor(video, profile, finished)

    def validate_evaluation_pilot(self) -> tuple[Path, Path, Path, int, list[int]] | None:
        video = Path(self.eval_pilot_video.text().strip())
        if not video.is_file():
            QMessageBox.information(self, tr('시험 원본 영상 필요'), tr('영상 테스트에 사용할 원본 영상 한 개를 선택하세요.'))
            return None
        profile = Path(self.eval_pilot_roi_profile.text().strip())
        if not profile.is_file():
            QMessageBox.information(
                self, tr('시험 ROI 필요'), tr('‘영상에서 시험 ROI 지정/수정’을 눌러 시험할 ROI 영역을 먼저 저장하세요.')
            )
            return None
        arenas = sorted({int(value) for value in self.eval_pilot_arena.checkedData()})
        try:
            profile_payload = json.loads(profile.read_text(encoding="utf-8"))
            arena_ids = {
                int(item.get("id", index))
                for index, item in enumerate(profile_payload.get("arenas", []), start=1)
            }
        except Exception as error:
            QMessageBox.warning(self, tr('ROI 프로필 오류'), tr('ROI 파일을 읽을 수 없습니다.\n{value1}', value1=error))
            return None
        invalid_arenas = [arena for arena in arenas if arena not in arena_ids]
        if not arenas:
            QMessageBox.information(self, tr('시험 ROI 선택'), tr('영상 테스트에 사용할 ROI를 하나 이상 체크하세요.'))
            return None
        if invalid_arenas:
            QMessageBox.warning(
                self, tr('ROI 번호 없음'),
                tr('ROI 설정에 없는 번호가 선택되었습니다: {value1}\n사용 가능: {value2}', value1=invalid_arenas, value2=sorted(arena_ids)),
            )
            return None
        pilot_shuffle = (
            self.eval_pilot_model_selector.currentData()
            if hasattr(self, "eval_pilot_model_selector") else None
        )
        shuffle = int(pilot_shuffle) if pilot_shuffle is not None else self.eval_shuffle.value()
        trained = {model["shuffle"] for model in trained_model_inventory(self.config)}
        if shuffle not in trained:
            QMessageBox.warning(
                self, tr('학습 모델 없음'), tr('Shuffle {value1}의 학습 체크포인트를 찾지 못했습니다.', value1=shuffle)
            )
            return None
        output_text = self.eval_pilot_output.text().strip()
        output = Path(output_text) if output_text else self.evaluation_pilot_output_for_shuffle(shuffle)
        self.eval_pilot_output.setText(str(output))
        output.mkdir(parents=True, exist_ok=True)
        self.save_project_ui_state()
        return video, profile, output, shuffle, arenas

    def run_evaluation_pilot(self) -> None:
        payload = self.validate_evaluation_pilot()
        if not payload:
            return
        video, profile, output, shuffle, arenas = payload
        try:
            from hagisilta_evaluation_padding import padding_spec
            padding_spec(self.config, shuffle, self.eval_pilot_padding.currentData())
        except (OSError, ValueError, KeyError) as error:
            QMessageBox.warning(self, tr('시험 영상 패딩 확인'), str(error))
            return
        overrides_text = self.eval_pilot_expert_overrides.toPlainText().strip()
        try:
            inference_overrides = json.loads(overrides_text) if overrides_text else {}
            if not isinstance(inference_overrides, dict):
                raise ValueError(tr('JSON 객체 형식이어야 합니다.'))
            from hagisilta_evaluation_padding import validate_padding_overrides
            validate_padding_overrides(self.eval_pilot_padding.currentData(), inference_overrides)
        except (json.JSONDecodeError, ValueError) as error:
            QMessageBox.warning(
                self, tr('추론 설정 JSON 확인'), tr('전문가용 추론 설정을 확인하세요.\n{value1}', value1=error)
            )
            return
        runtime = project_state_root(self.config.parent) / "runtime"
        runtime.mkdir(parents=True, exist_ok=True)
        plan = runtime / f"model-evaluation-pilot-shuffle-{shuffle:02d}.json"
        plan.write_text(json.dumps({"videos": [{
            "path": str(video), "roi_profile": str(profile), "arenas": arenas,
            "group": "model_evaluation_pilot", "subject_id": video.stem,
        }]}, ensure_ascii=False, indent=2), encoding="utf-8")
        arena_text = ", ".join(str(arena) for arena in arenas)
        self.set_workflow_badge(self.eval_pilot_badge, tr('Shuffle {value1} · {value2}개 ROI 추론 중', value1=shuffle, value2=len(arenas)), True)
        self.eval_pilot_summary.value_label.setText(
            tr('{value1}의 ROI {value2} 영역을 처리하고 있습니다.', value1=video.name, value2=arena_text)
        )

        def finished(exit_code: int) -> None:
            if exit_code == 0:
                self.set_workflow_badge(self.eval_pilot_badge, tr('추론 완료'), True)
                self.eval_pilot_summary.value_label.setText(
                    tr('ROI {value1} 테스트가 완료되었습니다. 결과 표에서 영상을 확인하세요.', value1=arena_text)
                )
                self.refresh_video_review_table()
                if self.eval_pilot_auto_qc.isChecked():
                    self.run_evaluation_pilot_qc()
            else:
                self.set_workflow_badge(self.eval_pilot_badge, tr('추론 오류'), False)

        arguments = [
            str(self.config), str(plan), str(output),
            "--shuffle", str(shuffle),
            "--batch-size", str(self.eval_pilot_batch_size.value()),
            "--pcutoff", str(self.eval_pilot_pcutoff.value()),
            "--device", str(self.eval_pilot_device.currentData()),
            "--dotsize", str(self.eval_pilot_dot_size.value()),
            "--execution-mode", "stable",
            "--evaluation-padding", str(self.eval_pilot_padding.currentData()),
            "--temporal-refiner", "off",
            "--roi-workers", "1",
            "--pipeline-chunk-size", "1",
            "--inference-overrides-json", json.dumps(inference_overrides, ensure_ascii=False),
        ]
        if self.eval_pilot_labeled_video.isChecked():
            arguments.append("--labeled-video")
        self.start_process(
            SCRIPTS / "hagisilta_tracking_batch.py",
            arguments,
            finished,
        )

    def evaluation_pilot_videos(self) -> list[Path]:
        output = Path(self.eval_pilot_output.text().strip())
        if not output.is_dir():
            return []
        videos = [
            path for path in output.rglob("*")
            if path.is_file() and path.suffix.lower() in {".avi", ".mp4", ".mov", ".mkv"}
        ]
        labeled = [path for path in videos if "labeled" in path.stem.lower()]
        return sorted(labeled or videos, key=lambda path: path.stat().st_mtime, reverse=True)

    def open_evaluation_pilot_video(self) -> None:
        videos = self.evaluation_pilot_videos()
        if not videos:
            QMessageBox.information(
                self, tr('확인 영상 없음'), tr('먼저 GPU 추론 후 ‘점 표시 영상 생성’을 실행하세요.')
            )
            return
        QDesktopServices.openUrl(QUrl.fromLocalFile(str(videos[0])))
        self.eval_pilot_summary.value_label.setText(tr('확인 중 · {value1}', value1=videos[0].name))

    def open_evaluation_pilot_folder(self) -> None:
        payload = self.evaluation_pilot_review_selected_payload()
        output = payload["pose"].parent if payload else Path(self.eval_pilot_output.text().strip())
        output.mkdir(parents=True, exist_ok=True)
        QDesktopServices.openUrl(QUrl.fromLocalFile(str(output)))

    def run_evaluation_pilot_qc(self) -> None:
        output = Path(self.eval_pilot_output.text().strip())
        report = self.run_qc_directory(
            output, float(self.eval_pilot_pcutoff.value()), update_quick=False
        )
        if not report:
            return
        summary = report.get("coverage_summary", {})
        median = float(summary.get("median_coverage", 0)) * 100
        minimum = float(summary.get("minimum_coverage", 0)) * 100
        lowest = str(summary.get("lowest_bodypart", "-") or "-")
        self.set_workflow_badge(self.eval_pilot_badge, tr('QC 계산 완료'), True)
        self.eval_pilot_summary.value_label.setText(
            tr('신체점 중앙 유효률 {value1:.1f}% · 최저 {value2} {value3:.1f}% · 영상을 직접 확인하세요.', value1=median, value2=lowest, value3=minimum)
        )

    def go_evaluation_pilot_review(self) -> None:
        output = Path(self.eval_pilot_output.text().strip())
        if not output.is_dir():
            QMessageBox.information(
                self, tr('테스트 결과 없음'), tr('먼저 영상 테스트를 실행하세요.')
            )
            return

        source = Path(self.eval_pilot_video.text().strip())
        selected_payload = self.evaluation_pilot_review_selected_payload()
        if selected_payload:
            self.launch_video_review(selected_payload)
            self.eval_pilot_summary.value_label.setText(
                tr('영상 교정 중 · {value1}', value1=selected_payload['pose'].name)
            )
            return
        arenas = [int(value) for value in self.eval_pilot_arena.checkedData()]
        arena = arenas[0] if arenas else 1
        expected_stem = f"{source.stem}_arena_{arena:02d}_roi" if source.stem else ""
        generated_prefix = f"{source.stem}_run" if source.stem else ""
        generated_suffix = f"_arena_{arena:02d}_roi"
        videos = [
            path for path in output.rglob("*_roi.*")
            if path.is_file() and path.suffix.lower() in {".avi", ".mp4", ".mov", ".mkv"}
            and "labeled" not in path.stem.lower()
        ]
        if expected_stem:
            matching_videos = [
                path for path in videos
                if path.stem == expected_stem
                or (path.stem.startswith(generated_prefix) and path.stem.endswith(generated_suffix))
            ]
            if matching_videos:
                videos = matching_videos
        videos.sort(key=lambda path: path.stat().st_mtime, reverse=True)

        selected: tuple[Path, Path] | None = None
        for video in videos:
            poses = [
                path for path in video.parent.glob(f"{video.stem}*.h5")
                if "corrected" not in path.stem.lower()
                and "evaluation-results" not in str(path).lower()
            ]
            if poses:
                poses.sort(key=lambda path: path.stat().st_mtime, reverse=True)
                selected = (video, poses[0])
                break
        if not selected:
            QMessageBox.information(
                self,
                tr('교정 가능한 결과 없음'),
                tr('현재 테스트의 ROI 영상과 DLC H5 좌표를 함께 찾지 못했습니다. 영상 테스트가 완료됐는지 확인하세요.'),
            )
            return

        video, pose = selected
        session = self.find_video_review_session(video, pose)
        self.launch_video_review({"video": video, "pose": pose, "session": session})
        self.eval_pilot_summary.value_label.setText(
            tr('영상 교정 중 · ROI {value1} · {value2}', value1=arena, value2=pose.name)
        )

    def use_evaluation_pilot_model(self) -> None:
        shuffle = self.eval_shuffle.value()
        self.refresh_model_inventory_table(shuffle)
        payload = self.selected_model_payload()
        if not payload or payload[0] != shuffle:
            QMessageBox.warning(self, tr('모델 선택 오류'), tr('Shuffle {value1} 모델을 목록에서 찾지 못했습니다.', value1=shuffle))
            return
        self.set_project_final_model(shuffle)
        self.set_workflow_badge(self.eval_pilot_badge, tr('최종 모델 지정'), True)
        self.eval_pilot_summary.value_label.setText(
            tr('Shuffle {value1}을(를) 최종 사용 모델로 지정했습니다. 전체 처리는 영상 트래킹에서 실행하세요.', value1=shuffle)
        )

    def evaluate_latest_trained_model(self) -> None:
        models = trained_model_inventory(self.config)
        if not models:
            QMessageBox.information(self, tr('완료된 모델 없음'), tr('먼저 모델 학습을 완료하세요.'))
            return
        shuffle = models[-1]["shuffle"]
        self.eval_shuffle.setValue(shuffle)
        self.show_module(self.module_index("evaluate"))
        self.refresh_model_inventory_table(shuffle)
        QTimer.singleShot(0, lambda: self.run_training("evaluate"))

    def retrain_selected_model(self) -> None:
        payload = self.selected_model_payload()
        if not payload:
            QMessageBox.information(self, tr('모델 선택'), tr('추가학습할 모델 행을 먼저 선택하세요.'))
            return
        shuffle, snapshot = payload
        if not snapshot or not snapshot.is_file():
            QMessageBox.warning(self, tr('체크포인트 없음'), tr('선택 모델의 Best 체크포인트를 찾지 못했습니다.'))
            return
        self.show_module(self.module_index("train"))
        self.train_start_mode.setCurrentIndex(max(0, self.train_start_mode.findData("checkpoint")))
        self.train_base_snapshot.setText(str(snapshot))
        self.select_training_destination()
        self.epochs.setValue(100)
        self.update_training_start_mode()
        self.append_log(
            tr('Shuffle {value1} 추가학습 설정을 모델 학습 화면으로 전달했습니다.\n기준 모델: {value2}\n새 Shuffle: {value3}', value1=shuffle, value2=snapshot, value3=self.train_shuffle.value())
        )

    def use_selected_model(self) -> None:
        payload = self.selected_model_payload()
        if not payload or not self.config:
            QMessageBox.information(self, tr('모델 선택'), tr('최종 사용할 모델 행을 먼저 선택하세요.'))
            return
        shuffle, _snapshot = payload
        if self.project_final_model_shuffle() == shuffle:
            settings = load_machine_settings()
            final_models = settings.setdefault("project_final_models", {})
            final_models.pop(str(self.config.resolve()), None)
            save_machine_settings(settings)
            self.refresh_model_inventory_table(shuffle)
            self.refresh_tracking_bodypart_consumers()
            self.append_log(
                tr('최종 사용 모델 지정 취소: Shuffle {value1} · 모델 파일은 유지됩니다.', value1=shuffle)
            )
            return
        self.set_project_final_model(shuffle)

    def set_project_final_model(self, shuffle: int) -> None:
        if not self.config:
            return
        settings = load_machine_settings()
        settings.setdefault("project_final_models", {})[str(self.config.resolve())] = shuffle
        settings.setdefault("project_external_tracking_models", {}).pop(
            str(self.config.resolve()), None
        )
        save_machine_settings(settings)
        self.track_shuffle.setValue(shuffle)
        self.refresh_model_inventory_table(shuffle)
        self.refresh_tracking_bodypart_consumers()
        self.append_log(tr('최종 사용 모델 지정: Shuffle {value1} · 영상 트래킹에 반영', value1=shuffle))

    def training_action_finished(self, action: str, shuffle: int, exit_code: int) -> None:
        self.train_status.value_label.setText(tr('완료') if exit_code == 0 else tr('오류'))
        if exit_code:
            return
        self.refresh_project()
        self.refresh_model_inventory_table(shuffle)
        if action == "fit":
            self.eval_shuffle.setValue(shuffle)
            self.set_workflow_badge(self.train_completion_badge, tr('Shuffle {value1} 완료', value1=shuffle), True)
            if self.train_auto_evaluate.isChecked():
                self.train_status.value_label.setText(tr('학습 완료 · 자동 평가 연결 중'))
                QTimer.singleShot(0, lambda: self.run_training("evaluate"))
        elif action in {"evaluate", "evaluate-test"}:
            self.refresh_model_inventory_table(shuffle)
            self.show_module(self.module_index("evaluate"))
            result_name = tr('현재 Test 평가') if action == "evaluate-test" else tr('평가')
            self.append_log(tr('Shuffle {value1} {value2} 완료 · 모델 평가에서 결과를 확인하세요.', value1=shuffle, value2=result_name))

    def select_training_destination(self, *_args) -> None:
        if not hasattr(self, "train_start_mode"):
            return
        if self.train_start_mode.currentData() == "checkpoint":
            snapshot = Path(self.train_base_snapshot.text().strip())
            if snapshot.is_file():
                try:
                    info = training_snapshot_metadata(snapshot)
                    self.train_shuffle.setValue(reinforcement_shuffle(self.config, info.get("shuffle")))
                except (OSError, ValueError, yaml.YAMLError):
                    pass  # Display the metadata error below; do not guess a source model.
        else:
            self.train_shuffle.setValue(next_shuffle(self.config))
        self.update_training_start_mode()

    def update_training_start_mode(self, *_args) -> None:
        if not hasattr(self, "train_start_mode"):
            return
        refinement = self.train_start_mode.currentData() == "checkpoint"
        target = self.train_shuffle.value()
        project_name = self.config.parent.name if self.config else tr('선택된 프로젝트 없음')
        occupied = shuffle_has_checkpoint(self.config, target)
        detail = (
            tr('Shuffle {value1}은 이미 학습된 모델입니다. 사용하지 않은 새 모델 번호를 선택하세요.', value1=target)
            if occupied else tr('기존 모델을 보존하고 새 모델 Shuffle {value1}을 만듭니다.', value1=target)
        )
        self.train_project_context.setText(tr('현재 프로젝트: {value1} · {value2}', value1=project_name, value2=detail))
        self.train_base_snapshot.setEnabled(refinement)
        self.set_workflow_badge(
            self.train_start_badge,
            tr('기존 모델 보강') if refinement else tr('새 모델'),
            refinement,
        )
        if hasattr(self, "train_imported_model_summary"):
            snapshot_text = self.train_base_snapshot.text().strip()
            if refinement and snapshot_text and Path(snapshot_text).is_file():
                try:
                    info = training_snapshot_metadata(Path(snapshot_text))
                    parts = info.get("bodyparts", []) or []
                    source = f"Shuffle {info['shuffle']} · " if info.get("shuffle") else ""
                    self.train_imported_model_summary.setText(
                        tr('기준 모델: {value1}{value2} · 신체점 {value3}개 · ', value1=source, value2=info.get('net_type') or tr('구조 정보 없음'), value3=len(parts))
                        + (tr('Shuffle {value1} 사용 불가', value1=target) if occupied else tr('새 Shuffle {value1}로 보강학습', value1=target))
                    )
                except Exception as error:
                    self.train_imported_model_summary.setText(tr('기준 모델 확인 필요 · {value1}', value1=error))
            elif refinement:
                self.train_imported_model_summary.setText(
                    tr('체크포인트를 직접 찾거나 ‘내보낸 모델 불러오기’로 모델 ZIP을 선택하세요.')
                )
            else:
                self.train_imported_model_summary.setText(
                    tr('SuperAnimal 사전학습 가중치에서 시작 · 새 Shuffle {value1}로 학습', value1=target)
                )
        self.epochs.setToolTip(
            (
                detailed_tooltip(
                    tr('기준 Best 체크포인트의 포즈 가중치에서 시작해 교정 Ground Truth로 새로 수행할 보강학습 Epoch 수입니다.'),
                    tr('높이면 새 교정 데이터에 더 강하게 맞지만 과적합과 기존 자세 망각 위험이 커지고 학습시간이 늘어납니다.'),
                    tr('교정 GT를 처음 반영하는 시험은 80~120 Epoch로 시작하고, Validation·최종 Test와 영상 QC가 함께 개선될 때만 늘리세요.'),
                    tr('기존 모델의 Epoch 번호를 이어 세지 않으며 원래 모델을 덮어쓰지 않고 새 Shuffle에서 1부터 시작합니다.'),
                )
            )
            if refinement
            else (
                detailed_tooltip(
                    tr('학습 데이터 전체를 모델이 반복해서 보는 횟수입니다.'),
                    tr('높이면 학습시간이 늘고 수렴 기회가 커지지만, 라벨이 적으면 Train 데이터만 외워 실제 영상 성능이 나빠질 수 있습니다.'),
                    tr('첫 모델은 200 Epoch로 시작하세요. Test 지표도 계속 좋아지면 늘리고 Train 오차만 좋아지면 줄이거나 데이터를 추가하세요.'),
                    tr('Iteration은 배치 업데이트 한 번이고 Epoch는 전체 학습 데이터를 한 바퀴 보는 단위입니다.'),
                )
            )
        )

    def browse_training_base_snapshot(self) -> None:
        initial_path: Path | None = None
        current_text = self.train_base_snapshot.text().strip()
        if current_text:
            current_path = Path(current_text)
            if current_path.is_file():
                initial_path = current_path.parent
            elif current_path.is_dir():
                initial_path = current_path

        model_root = self.config.parent / "dlc-models-pytorch" if self.config else None
        if initial_path is None and model_root and model_root.is_dir():
            train_folders = [
                folder for folder in model_root.glob("iteration-*/*/train")
                if folder.is_dir()
            ]
            if not train_folders:
                train_folders = [folder for folder in model_root.rglob("train") if folder.is_dir()]

            def newest_checkpoint_time(folder: Path) -> float:
                snapshots = list(folder.glob("snapshot-best-*.pt")) or list(folder.glob("*.pt"))
                try:
                    return max(path.stat().st_mtime for path in snapshots) if snapshots else folder.stat().st_mtime
                except OSError:
                    return 0.0

            if train_folders:
                initial_path = max(train_folders, key=newest_checkpoint_time)

        if initial_path is None:
            initial_path = model_root if model_root and model_root.is_dir() else get_work_root()
        filename, _ = QFileDialog.getOpenFileName(
            self,
            tr('기준 DLC Best 체크포인트 선택'),
            str(initial_path),
            tr('DLC PyTorch snapshot (*.pt *.pth);;모든 파일 (*.*)'),
        )
        if filename:
            self.train_base_snapshot.setText(filename)
            self.train_start_mode.setCurrentIndex(
                max(0, self.train_start_mode.findData("checkpoint"))
            )
            self.select_training_destination()

    def validate_training_base_snapshot(self, snapshot: Path) -> tuple[bool, str, dict]:
        try:
            info = training_snapshot_metadata(snapshot)
        except Exception as error:
            return False, str(error), {}
        current_payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        current_parts = list(map(str, current_payload.get("bodyparts", []) or []))
        source_parts = list(map(str, info.get("bodyparts", []) or []))
        if current_parts and source_parts and current_parts != source_parts:
            return (
                False,
                tr('현재 프로젝트와 불러온 모델의 신체점 구성이 다릅니다.\n\n현재: {value1}\n모델: {value2}\n\n보강학습에서는 출력층 크기와 점 순서가 같아야 하므로 이 모델을 사용할 수 없습니다.', value1=', '.join(current_parts), value2=', '.join(source_parts)),
                info,
            )
        expected_net = str(self.train_pose_model.currentData() or "hrnet_w32")
        source_net = str(info.get("net_type", "")).lower().replace("-", "_")
        if source_net and source_net != expected_net:
            return (
                False,
                tr('현재 학습 설정과 불러온 모델의 백본 구조가 다릅니다.\n\n현재 설정: {value1}\n모델: {value2}\n\n모델 학습의 SuperAnimal 종류를 원본 모델과 같은 구조로 맞춰야 합니다.', value1=expected_net, value2=info.get('net_type')),
                info,
            )
        return True, "", info

    def browse_training_model_bundle(self) -> None:
        if not self.require_config():
            return
        selected, _ = QFileDialog.getOpenFileName(
            self,
            tr('보강학습에 사용할 HAGISILTA 모델 ZIP 선택'),
            str(self.config.parent),
            tr('HAGISILTA 모델 ZIP (*.hagimodel.zip *.zip);;모든 파일 (*.*)'),
        )
        if not selected:
            return
        bundle = Path(selected).resolve()
        model_root = project_state_root(self.config.parent) / "training-base-models"
        model_root.mkdir(parents=True, exist_ok=True)
        safe_name = re.sub(r"[^A-Za-z0-9._-]+", "-", bundle.stem).strip("-") or "model"
        destination = model_root / f"{safe_name}-{time.strftime('%Y%m%d-%H%M%S')}"
        try:
            imported = install_portable_model_bundle(bundle, destination)
            compatible, reason, info = self.validate_training_base_snapshot(imported["snapshot"])
            if not compatible:
                raise ValueError(reason)
        except Exception as error:
            shutil.rmtree(destination, ignore_errors=True)
            QMessageBox.critical(self, tr('학습 모델 가져오기 실패'), str(error))
            return
        self.train_base_snapshot.setText(str(imported["snapshot"]))
        self.train_start_mode.setCurrentIndex(
            max(0, self.train_start_mode.findData("checkpoint"))
        )
        self.select_training_destination()
        self.append_log(
            tr('보강학습 기준 모델 ZIP 가져오기 완료\n원본 ZIP: {value1}\n체크포인트: {value2}\n새 학습 Shuffle: {value3}', value1=bundle, value2=imported['snapshot'], value3=self.train_shuffle.value())
        )
        self.save_project_ui_state()
        QMessageBox.information(
            self,
            tr('학습 모델 가져오기 완료'),
            tr('현재 프로젝트와 호환되는 모델입니다.\n보강학습 시작점으로 연결했으며 결과는 새 Shuffle {value1}에 저장됩니다.\n\n{value2}', value1=self.train_shuffle.value(), value2=imported['snapshot']),
        )

    def go_review_to_training(self) -> None:
        payload = self.review_selected_payload()
        if not payload:
            QMessageBox.information(self, tr('추론 결과 선택'), tr('먼저 표에서 보강학습 기준이 될 추론 결과를 선택하세요.'))
            return
        edited = int(payload.get("edited", 0) or 0)
        imported = int(payload.get("imported", 0) or 0)
        if edited <= 0:
            QMessageBox.information(
                self,
                tr('교정 프레임 없음'),
                tr('먼저 영상 교정기에서 필요한 프레임을 수정하고 저장한 뒤 학습 데이터로 반영하세요.'),
            )
            return
        if imported < edited:
            QMessageBox.information(
                self,
                tr('학습 반영 필요'),
                tr('아직 학습 데이터에 반영하지 않은 수정 프레임이 {value1}개 있습니다. 현재 수정 프레임을 먼저 반영하세요.', value1=edited - imported),
            )
            return
        snapshot = snapshot_for_pose_result(self.config, Path(payload["pose"]))
        if snapshot is None:
            QMessageBox.warning(
                self,
                tr('기준 모델을 찾지 못함'),
                tr('선택한 DLC 결과 파일명에 대응하는 프로젝트 체크포인트를 찾지 못했습니다. 모델 학습 화면에서 기준 Best 체크포인트를 직접 선택하세요.'),
            )
        self.show_module(self.module_index("train"))
        self.train_start_mode.setCurrentIndex(
            max(0, self.train_start_mode.findData("checkpoint"))
        )
        if snapshot is not None:
            self.train_base_snapshot.setText(str(snapshot))
        self.select_training_destination()
        self.epochs.setValue(100)
        self.update_training_start_mode()
        self.append_log(
            tr('교정 라벨 보강학습 설정: {value1}\n기준 모델: {value2}\n새 Shuffle: {value3}', value1=payload['video'].name, value2=snapshot or tr('직접 선택 필요'), value3=self.train_shuffle.value())
        )

