        self.train_device.setCurrentIndex(0)
        self.train_memory_replay.setChecked(False)
        self.train_augmentation_strength.setCurrentIndex(1)
        self.train_input_mode.setCurrentIndex(0)
        self.refresh_training_input_size_guidance()
        self.train_validation_interval.setCurrentIndex(1)
        self.train_random_seed.setValue(42)
        self.train_display_iters.setValue(50)
