    def show_module(self, index: int) -> None:
        active_key = self.modules[index][0] if 0 <= index < len(self.modules) else None
        target_page = self.pages.get(active_key) if active_key else None
        workflow_state = self.workflow_page_state(target_page)
        self.workflow_navigation_serial += 1
        navigation_serial = self.workflow_navigation_serial
        if active_key == "spatial":
            self.set_project_experiment_mode("nort")
        elif active_key == "ymaze":
            self.set_project_experiment_mode("ymaze")
        elif active_key == "watermaze":
            self.set_project_experiment_mode("watermaze")
        self.stack.setCurrentIndex(index)
        if active_key in {"dataset", "review"}:
            active_nav_key = "dataset"
        elif active_key in {"train", "evaluate"}:
            active_nav_key = "train"
        else:
            active_nav_key = active_key
        for module_key, button in self.nav_by_key.items():
            button.setChecked(module_key == active_nav_key)
        if active_key in {"dataset", "review"}:
            for page_key in ("dataset", "review"):
                for tab_button in self.pages[page_key].findChildren(QPushButton):
                    if tab_button.objectName() == "pageTabButton":
                        tab_button.setChecked(tab_button.property("moduleKey") == active_key)
        if active_key in {"train", "evaluate"}:
            for page_key in ("train", "evaluate"):
                for tab_button in self.pages[page_key].findChildren(QPushButton):
                    if tab_button.objectName() == "pageTabButton":
                        tab_button.setChecked(tab_button.property("moduleKey") == active_key)
        if 0 <= index < len(self.modules) and self.modules[index][0] == "review":
            self.refresh_video_review_table()
        if 0 <= index < len(self.modules) and self.modules[index][0] == "evaluate":
            self.refresh_model_inventory_table()
        if 0 <= index < len(self.modules) and self.modules[index][0] == "track":
            self.load_batch_source_table()
            self.refresh_video_review_table()
        if active_key == "watermaze":
            self.pages["watermaze"].refresh()
        if active_key == "ymaze":
            self.refresh_ymaze_bundle_table()
        if active_key in {"spatial", "ymaze", "zone"}:
            self.refresh_tracking_bodypart_consumers()
        if hasattr(self, "spatial_refresh_timer"):
            if 0 <= index < len(self.modules) and self.modules[index][0] == "spatial":
                self.refresh_spatial_bundle()
                self.refresh_nort_results()
                QTimer.singleShot(0, self.balance_nort_experiment_columns)
                self.spatial_refresh_timer.start()
            else:
                self.spatial_refresh_timer.stop()
        QTimer.singleShot(
            0,
            lambda state=workflow_state, serial=navigation_serial: self.restore_workflow_page_state(
                state, serial
            ),
        )

    def set_recommended_module(self, key: str, reason: str = "") -> None:
        # Recommended routes are presented on the dashboard. The sidebar uses
        # one visual state only: the currently open page (blue).
        for button in self.nav_by_key.values():
            was_recommended = bool(button.property("recommendedNext"))
            button.setProperty("recommendedNext", False)
            if was_recommended:
                button.setToolTip("")
            button.style().unpolish(button)
            button.style().polish(button)

    def module_index(self, key: str) -> int:
        return next(index for index, (module_key, _title) in enumerate(self.modules) if module_key == key)

    def load_dataset_configuration(self) -> None:
        if not self.config or not self.config.is_file() or not hasattr(self, "dataset_bodyparts"):
            return
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        self.dataset_frames_per_video.setValue(int(payload.get("numframes2pick", 20)))
        previous_sync = getattr(self, "_syncing_dataset_bodyparts", False)
        self._syncing_dataset_bodyparts = True
        try:
            self.dataset_bodyparts.setText(", ".join(map(str, payload.get("bodyparts", []))))
        finally:
            self._syncing_dataset_bodyparts = previous_sync
        selected = self.dataset_video_list.currentData()
        self.dataset_video_list.blockSignals(True)
        self.dataset_video_list.clear()
        for video in (payload.get("video_sets", {}) or {}):
            self.dataset_video_list.addItem(Path(str(video)).name, str(video))
        self.dataset_video_list.blockSignals(False)
        if selected:
            index = self.dataset_video_list.findData(selected)
            if index >= 0:
                self.dataset_video_list.setCurrentIndex(index)
        self.select_dataset_video(self.dataset_video_list.currentIndex())
        sorting_enabled = self.dataset_video_table.isSortingEnabled()
        self.dataset_video_table.setSortingEnabled(False)
        self.dataset_video_table.setRowCount(0)
        provenance = (dataset_metadata(payload).get("videos", {}) or {})
        project_sources = project_metadata(payload).get("source_videos", []) or []
        default_frames = int(payload.get("numframes2pick", 20))
        import cv2

        video_paths = [str(video) for video in (payload.get("video_sets", {}) or {})]

        def dataset_path_key(value: str) -> str:
            try:
                return str(Path(value).resolve()).casefold()
            except OSError:
                return str(Path(value)).casefold()

        project_profiles: dict[str, str] = {}
        for source in project_sources:
            source_path = str(source.get("path", "") or "")
            profile_path = str(source.get("roi_profile", "") or "")
            if source_path and profile_path:
                project_profiles[dataset_path_key(source_path)] = profile_path

        roi_children_by_source: dict[str, list[str]] = {}
        roi_child_paths: set[str] = set()
        for child_path in video_paths:
            child_metadata = dict(provenance.get(child_path, {}) or {})
            if child_metadata.get("origin") != "quick_roi_02" or not child_metadata.get("source_video"):
                continue
            roi_child_paths.add(dataset_path_key(child_path))
            roi_children_by_source.setdefault(
                dataset_path_key(str(child_metadata["source_video"])), []
            ).append(child_path)

        # Step 01 is an original-video plan. ROI clips are children of that row
        # and are shown in Step 02 instead of being mixed into this table.
        display_paths = [path for path in video_paths if dataset_path_key(path) not in roi_child_paths]
        known_display = {dataset_path_key(path) for path in display_paths}
        for children in roi_children_by_source.values():
            source_path = str((provenance.get(children[0], {}) or {}).get("source_video", ""))
            if source_path and dataset_path_key(source_path) not in known_display:
                display_paths.append(source_path)
                known_display.add(dataset_path_key(source_path))

        for path in display_paths:
            metadata = dict(provenance.get(path, {}) or {})
            roi_children = roi_children_by_source.get(dataset_path_key(path), [])
            child_metadata = [dict(provenance.get(child, {}) or {}) for child in roi_children]
            # Older video-review imports already have a manifest but predate the
            # provenance fields in config.yaml. Recognize them without modifying
            # the project merely by opening this page.
            review_manifest = project_state_root(self.config.parent) / "video-review-imports" / f"{Path(path).stem}.json"
            if review_manifest.is_file():
                metadata.setdefault("origin", "video_review_gt")
                metadata.setdefault("source_video", path)
                metadata.setdefault("extract_enabled", False)
            row = self.dataset_video_table.rowCount()
            self.dataset_video_table.insertRow(row)
            # The source row is the user-facing switch for the whole ROI group.
            # During first-time ROI materialization children are deliberately
            # created disabled, so looking only at their flags makes the source
            # appear disabled after the table refresh and drops every ROI from
            # the extraction plan.  Prefer the persisted group switch whenever
            # it exists; older projects fall back to the child flags.
            extract_enabled = (
                bool(metadata.get("dataset_group_enabled"))
                if roi_children and "dataset_group_enabled" in metadata
                else any(bool(item.get("extract_enabled", True)) for item in child_metadata)
                if roi_children
                else bool(metadata.get("extract_enabled", True))
            )
            self.set_centered_table_checkbox(self.dataset_video_table, row, 0, extract_enabled)
            name = QTableWidgetItem(Path(path).name)
            name.setData(Qt.UserRole, path)
            name.setData(Qt.UserRole + 1, list(roi_children))
            name.setToolTip(path)
            self.dataset_video_table.setItem(row, 1, name)
            origin_kind = metadata.get("origin")
            origin = (
                tr('ROI {value1}개 연결', value1=len(roi_children)) if roi_children
                else tr('사전학습 ROI 연동') if origin_kind == "quick_roi_02"
                else tr('직접 추가') if origin_kind == "manual"
                else tr('교정 학습 데이터') if origin_kind == "video_review_gt"
                else tr('기존 프로젝트')
            )
            origin_item = QTableWidgetItem(origin)
            if metadata.get("source_video"):
                if origin_kind == "video_review_gt":
                    origin_item.setToolTip(
                        tr('교정 원본: {value1}\n추가 학습 데이터 반영에서 이미 정답 라벨로 반영되어 기본 추출 대상에서 제외됩니다.', value1=metadata['source_video'])
                    )
                else:
                    origin_item.setToolTip(tr('원본: {value1}\nROI 박스: {value2}', value1=metadata['source_video'], value2=metadata.get('arena_id', '-')))
            self.dataset_video_table.setItem(row, 2, origin_item)

            profile_text = str(metadata.get("roi_profile", "") or "")
            if not profile_text:
                profile_text = next(
                    (
                        str(item.get("roi_profile", "") or "")
                        for item in child_metadata
                        if item.get("roi_profile")
                    ),
                    "",
                )
            if not profile_text:
                profile_text = project_profiles.get(dataset_path_key(path), "")
            profile = Path(profile_text) if profile_text else Path()
            roi_count = len(roi_children)
            profile_error = ""
            if profile.is_file():
                try:
                    profile_payload = json.loads(profile.read_text(encoding="utf-8"))
                    roi_count = max(roi_count, len(profile_payload.get("arenas", []) or []))
                except Exception as error:
                    profile_error = str(error)
            if roi_count:
                roi_text = tr('{value1}개 설정', value1=roi_count)
            elif profile_text:
                roi_text = tr('설정 확인 필요')
            else:
                roi_text = tr('미설정')
            roi_item = SortableTableItem(roi_text)
            roi_item.setData(Qt.UserRole, roi_count)
            if profile_text:
                tooltip = tr('ROI 프로필: {value1}', value1=profile_text)
                if profile_error:
                    tooltip += tr('\n읽기 오류: {value1}', value1=profile_error)
                elif roi_count and not roi_children:
                    tooltip += tr('\n좌표가 저장되었습니다. ROI 영상은 대표 프레임 추출 시 생성됩니다.')
                roi_item.setToolTip(tooltip)
            self.dataset_video_table.setItem(row, 3, roi_item)
            width = height = frames = 0
            fps = 0.0
            if Path(path).is_file():
                capture = cv2.VideoCapture(path)
                width = int(capture.get(cv2.CAP_PROP_FRAME_WIDTH))
                height = int(capture.get(cv2.CAP_PROP_FRAME_HEIGHT))
                frames = int(capture.get(cv2.CAP_PROP_FRAME_COUNT))
                fps = float(capture.get(cv2.CAP_PROP_FPS))
                capture.release()
            duration = frames / fps if fps else 0.0
            self.dataset_video_table.setItem(
                row, 4, QTableWidgetItem(tr('{value1}×{value2} · {value3:.1f}초', value1=width, value2=height, value3=duration) if width else tr('파일 없음'))
            )
            bodyparts_text = ", ".join(map(str, payload.get("bodyparts", [])))
            bodyparts_item = QTableWidgetItem(bodyparts_text or tr(DATASET_BODYPART_PLACEHOLDER))
            bodyparts_item.setToolTip(
                tr('이 영상의 프레임에 적용되는 프로젝트 공통 학습 신체점입니다.\n셀을 더블클릭해 수정하면 모든 영상 행에 같은 값으로 반영됩니다.\n')
                + (bodyparts_text or tr('신체점을 입력하세요.'))
            )
            bodyparts_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable | Qt.ItemIsEditable)
            previous_sync = getattr(self, "_syncing_dataset_bodyparts", False)
            self._syncing_dataset_bodyparts = True
            try:
                self.dataset_video_table.setItem(row, 5, bodyparts_item)
            finally:
                self._syncing_dataset_bodyparts = previous_sync
            count = TableNumberSpinBox()
            count.setRange(1, 1000)
            linked_frames = next(
                (int(item.get("frames_to_pick", default_frames)) for item in child_metadata),
                int(metadata.get("frames_to_pick", default_frames)),
            )
            count.setValue(linked_frames)
            count.setAlignment(Qt.AlignCenter)
            count.setButtonSymbols(QAbstractSpinBox.NoButtons)
            count.setObjectName("tableNumberInput")
            count.setFrame(False)
            count_item = SortableTableItem()
            count_item.setData(Qt.UserRole, linked_frames)
            count_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            self.dataset_video_table.setItem(row, 6, count_item)
            count.valueChanged.connect(
                lambda value, item=count_item: item.setData(Qt.UserRole, int(value))
            )
            count.editingFinished.connect(
                lambda editor=count, source_path=path, children=tuple(roi_children), item=count_item:
                self.commit_dataset_frame_count(
                    source_path, children, int(editor.value()), item
                )
            )
            self.dataset_video_table.setCellWidget(row, 6, count)
        self.dataset_video_table.setSortingEnabled(sorting_enabled)
        video_count = self.dataset_video_table.rowCount()
        enabled_count = sum(
            bool(self.table_checkbox(self.dataset_video_table, row, 0).isChecked())
            for row in range(video_count)
            if self.table_checkbox(self.dataset_video_table, row, 0)
        )
        label_count = int(project_summary(self.config).get("labels", 0))
        if hasattr(self, "dataset_plan_badge"):
            self.set_workflow_badge(
                self.dataset_plan_badge,
                tr('{value1}개 영상 · {value2}개 사용', value1=video_count, value2=enabled_count) if video_count else tr('영상 없음'),
                enabled_count > 0 and bool(payload.get("bodyparts", [])),
            )
            self.set_workflow_badge(
                self.dataset_label_badge,
                tr('{value1}프레임 라벨', value1=label_count) if label_count else tr('라벨 확인 필요'),
                label_count > 0,
            )
        self.refresh_labeling_progress()

    def commit_dataset_frame_count(
        self,
        source_path: str,
        roi_children: tuple[str, ...],
        value: int,
        sort_item: QTableWidgetItem | None = None,
    ) -> None:
        """Persist a table count immediately and reuse it for future imports."""
        if not self.config or not self.config.is_file():
            return
        value = max(1, min(int(value), 1000))
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        video_metadata = dataset_metadata(payload, create=True).setdefault("videos", {})
        source_metadata = video_metadata.setdefault(str(source_path), {})
        changed = int(payload.get("numframes2pick", 20) or 20) != value
        if (
            "frames_to_pick" not in source_metadata
            or int(source_metadata.get("frames_to_pick", 20) or 20) != value
        ):
            source_metadata["frames_to_pick"] = value
            changed = True
        for child_path in roi_children:
            child_metadata = video_metadata.setdefault(str(child_path), {})
            if (
                "frames_to_pick" not in child_metadata
                or int(child_metadata.get("frames_to_pick", 20) or 20) != value
            ):
                child_metadata["frames_to_pick"] = value
                changed = True
        # The last explicitly edited row becomes the default for videos added
        # later, while every existing row keeps its own persisted value.
        payload["numframes2pick"] = value
        self.dataset_frames_per_video.blockSignals(True)
        self.dataset_frames_per_video.setValue(value)
        self.dataset_frames_per_video.blockSignals(False)
        if sort_item is not None:
            sort_item.setData(Qt.UserRole, value)
        if changed:
            self.write_project_configuration(
                payload, tr('추출 프레임 자동 저장: {value1} · {value2}프레임', value1=Path(source_path).name, value2=value)
            )

    def write_project_configuration(self, payload: dict, reason: str) -> Path:
        if not self.config:
            raise ValueError(tr('DLC config.yaml이 선택되지 않았습니다.'))
        backup_dir = project_backup_root(self.config.parent)
        backup_dir.mkdir(parents=True, exist_ok=True)
        stamp = f"{time.strftime('%Y%m%d-%H%M%S')}-{time.time_ns() % 1_000_000:06d}"
        backup = backup_dir / f"config-{stamp}.yaml"
        shutil.copy2(self.config, backup)
        self.config.write_text(
            yaml.safe_dump(payload, sort_keys=False, allow_unicode=True), encoding="utf-8"
        )
        self.append_log(tr('데이터셋 구성 저장: {value1}\n백업: {value2}', value1=reason, value2=backup))
        return backup

    def save_dataset_configuration(self, *, show_message: bool = True, advance: bool = True) -> bool:
        if not self.require_config():
            return False
        bodyparts = parse_dataset_bodyparts_text(self.dataset_bodyparts.text())
        if not bodyparts:
            QMessageBox.warning(
                self,
                tr('학습 신체점 입력 필요'),
                tr('표의 ‘학습 신체점’ 열에서 ‘미지정’ 셀을 더블클릭한 뒤 신체점 이름을 입력하세요.\n예: nose, head_center, body_center, tail_base'),
            )
            if self.dataset_video_table.rowCount():
                item = self.dataset_video_table.item(0, 5)
                if item is not None:
                    self.dataset_video_table.setCurrentItem(item)
                    self.dataset_video_table.editItem(item)
            return False
        if len(bodyparts) != len(set(bodyparts)):
            QMessageBox.warning(self, tr('신체점 확인'), tr('신체점 이름은 중복 없이 입력하세요.'))
            return False
        invalid = [part for part in bodyparts if not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]*", part)]
        if invalid:
            QMessageBox.warning(
                self, tr('신체점 이름 확인'),
                tr('영문자로 시작하고 영문·숫자·밑줄만 사용하세요.\n') + ", ".join(invalid),
            )
            return False
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        previous = list(map(str, payload.get("bodyparts", [])))
        if bodyparts != previous and project_summary(self.config).get("labels", 0):
            answer = QMessageBox.warning(
                self,
                tr('기존 라벨과 모델 확인'),
                tr('신체점을 변경하면 기존 라벨을 전용 라벨링 창에서 다시 확인하고 모델을 새로 학습해야 합니다.\n기존 파일은 삭제하지 않고 config 백업을 만든 뒤 변경합니다. 계속할까요?'),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return False
        payload["numframes2pick"] = int(self.dataset_frames_per_video.value())
        payload["bodyparts"] = bodyparts
        payload["skeleton"] = [
            edge for edge in (payload.get("skeleton", []) or [])
            if isinstance(edge, list) and len(edge) == 2 and all(point in bodyparts for point in edge)
        ]
        video_metadata = dataset_metadata(payload, create=True).setdefault("videos", {})
        for row in range(self.dataset_video_table.rowCount()):
            path_item = self.dataset_video_table.item(row, 1)
            count = self.dataset_video_table.cellWidget(row, 6)
            if not path_item or not isinstance(count, QSpinBox):
                continue
            path = str(path_item.data(Qt.UserRole))
            metadata = video_metadata.setdefault(path, {})
            metadata["frames_to_pick"] = int(count.value())
            checkbox = self.table_checkbox(self.dataset_video_table, row, 0)
            checked = bool(checkbox and checkbox.isChecked())
            roi_children = list(path_item.data(Qt.UserRole + 1) or [])
            if roi_children:
                # The original row is the user-facing group. DLC extracts from
                # its ROI children, never from the composite source itself.
                metadata["extract_enabled"] = False
                metadata["dataset_group_enabled"] = checked
                for child_path in roi_children:
                    child = video_metadata.setdefault(str(child_path), {})
                    child["frames_to_pick"] = int(count.value())
                    child["extract_enabled"] = checked
            else:
                metadata["extract_enabled"] = checked
        self.write_project_configuration(payload, tr('프레임 추출 수·신체점 변경'))
        self.refresh_project()
        self.load_dataset_configuration()
        if advance and hasattr(self, "dataset_plan_card"):
            self.set_workflow_expanded(self.dataset_plan_card, False)
            self.set_workflow_expanded(self.dataset_label_card, True)
            self.set_workflow_badge(self.dataset_plan_badge, tr('구성 저장됨'), True)
        if show_message:
            QMessageBox.information(
                self, tr('추출 계획 저장 완료'),
                tr('영상별 추출 프레임 수·체크 상태와 학습 신체점을 저장했습니다.'),
            )
        return True

    def save_and_extract_dataset_configuration(self) -> None:
        if self.save_dataset_configuration(show_message=False, advance=False):
            self.extract_frames()

    def apply_frames_to_checked_dataset_rows(self) -> None:
        value = int(self.dataset_frames_per_video.value())
        changed = 0
        sorting_enabled = self.dataset_video_table.isSortingEnabled()
        self.dataset_video_table.setSortingEnabled(False)
        try:
            for row in range(self.dataset_video_table.rowCount()):
                checkbox = self.table_checkbox(self.dataset_video_table, row, 0)
                count = self.dataset_video_table.cellWidget(row, 6)
                if checkbox and checkbox.isChecked() and isinstance(count, QSpinBox):
                    count.setValue(value)
                    changed += 1
        finally:
            self.dataset_video_table.setSortingEnabled(sorting_enabled)
        if not changed:
            QMessageBox.information(self, tr('적용할 영상 없음'), tr('표의 ‘선택’ 체크박스를 하나 이상 선택하세요.'))

    def update_dataset_bodyparts_column(self, text: str) -> None:
        if not hasattr(self, "dataset_video_table"):
            return
        bodyparts = parse_dataset_bodyparts_text(text)
        display = ", ".join(bodyparts) or tr(DATASET_BODYPART_PLACEHOLDER)
        sorting_enabled = self.dataset_video_table.isSortingEnabled()
        self.dataset_video_table.setSortingEnabled(False)
        try:
            for row in range(self.dataset_video_table.rowCount()):
                item = self.dataset_video_table.item(row, 5)
                if item is None:
                    item = QTableWidgetItem()
                    item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable | Qt.ItemIsEditable)
                    self.dataset_video_table.setItem(row, 5, item)
                item.setText(display)
                item.setToolTip(
                    tr('이 영상의 프레임에 적용되는 프로젝트 공통 학습 신체점입니다.\n셀을 더블클릭해 수정하면 모든 영상 행에 같은 값으로 반영됩니다.\n')
                    + (display if bodyparts else tr('신체점을 입력하세요.'))
                )
        finally:
            self.dataset_video_table.setSortingEnabled(sorting_enabled)

    def edit_dataset_table_bodyparts(self, item: QTableWidgetItem) -> None:
        """Keep the directly editable bodypart cell synced as one project schema."""
        if item.column() != 5 or getattr(self, "_syncing_dataset_bodyparts", False):
            return
        text = ", ".join(parse_dataset_bodyparts_text(item.text()))
        self._syncing_dataset_bodyparts = True
        try:
            self.dataset_bodyparts.setText(text)
            self.update_dataset_bodyparts_column(text)
        finally:
            self._syncing_dataset_bodyparts = False

    def select_dataset_video(self, _index: int = -1) -> None:
        if not hasattr(self, "dataset_video"):
            return
        selected = self.dataset_video_list.currentData()
        if selected:
            self.dataset_video.setText(str(selected))

    def set_all_dataset_extract_checks(self, checked: bool) -> None:
        sorting_enabled = self.dataset_video_table.isSortingEnabled()
        self.dataset_video_table.setSortingEnabled(False)
        for row in range(self.dataset_video_table.rowCount()):
            checkbox = self.table_checkbox(self.dataset_video_table, row, 0)
            if checkbox:
                checkbox.setChecked(checked)
        self.dataset_video_table.setSortingEnabled(sorting_enabled)
        total = self.dataset_video_table.rowCount()
        selected = total if checked else 0
        self.set_workflow_badge(
            self.dataset_plan_badge,
            tr('{value1}개 영상 · {value2}개 추출', value1=total, value2=selected) if total else tr('영상 없음'),
            bool(selected and self.dataset_bodyparts.text().strip()),
        )

    def select_dataset_table_video(self) -> None:
        selected_rows = self.dataset_video_table.selectionModel().selectedRows()
        if not selected_rows or not hasattr(self, "dataset_video"):
            return
        row = selected_rows[-1].row()
        path_item = self.dataset_video_table.item(row, 1)
        if not path_item:
            return
        path = str(path_item.data(Qt.UserRole))
        self.dataset_video.setText(path)
        index = self.dataset_video_list.findData(path)
        if index >= 0:
            self.dataset_video_list.blockSignals(True)
            self.dataset_video_list.setCurrentIndex(index)
            self.dataset_video_list.blockSignals(False)

    def selected_dataset_rows(self) -> list[int]:
        return sorted({index.row() for index in self.dataset_video_table.selectionModel().selectedRows()})

    def set_selected_dataset_extract_checks(self, checked: bool) -> None:
        for row in self.selected_dataset_rows():
            checkbox = self.table_checkbox(self.dataset_video_table, row, 0)
            if checkbox:
                checkbox.setChecked(checked)

    def reveal_selected_dataset_video(self) -> None:
        rows = self.selected_dataset_rows()
        if len(rows) != 1:
            return
        item = self.dataset_video_table.item(rows[0], 1)
        path = Path(str(item.data(Qt.UserRole))) if item else Path()
        if not path.exists():
            QMessageBox.information(self, tr('파일 위치'), tr('선택한 영상 파일을 찾을 수 없습니다.'))
            return
        if sys.platform == "win32":
            QProcess.startDetached("explorer.exe", ["/select,", str(path)])
        else:
            QDesktopServices.openUrl(QUrl.fromLocalFile(str(path.parent)))

    def show_dataset_table_context_menu(self, position) -> None:
        index = self.dataset_video_table.indexAt(position)
        if not index.isValid():
            return
        selected = set(self.dataset_video_table.restore_right_click_rows(position))
        if index.row() not in selected:
            self.dataset_video_table.clearSelection()
            self.dataset_video_table.selectRow(index.row())
        rows = self.selected_dataset_rows()
        if not rows:
            return
        selected_prefix = tr('이 행') if len(rows) == 1 else tr('선택한 {value1}개 행', value1=len(rows))
        menu = QMenu(self.dataset_video_table)
        title = menu.addAction(selected_prefix)
        title.setEnabled(False)
        menu.addSeparator()
        edit_roi = menu.addAction(tr('{value1} ROI 수정', value1=selected_prefix))
        edit_roi.setEnabled(len(rows) == 1)
        check_extract = menu.addAction(tr('{value1} 사용', value1=selected_prefix))
        uncheck_extract = menu.addAction(tr('{value1} 제외', value1=selected_prefix))
        reveal_file = menu.addAction(tr('{value1} 파일 위치 열기', value1=selected_prefix))
        reveal_file.setEnabled(len(rows) == 1)
        menu.addSeparator()
        remove_rows = menu.addAction(tr('{value1} 목록에서 제외', value1=selected_prefix))
        edit_roi.triggered.connect(self.edit_selected_dataset_roi)
        check_extract.triggered.connect(lambda: self.set_selected_dataset_extract_checks(True))
        uncheck_extract.triggered.connect(lambda: self.set_selected_dataset_extract_checks(False))
        reveal_file.triggered.connect(self.reveal_selected_dataset_video)
        remove_rows.triggered.connect(self.remove_dataset_video)
        menu.exec(self.dataset_video_table.viewport().mapToGlobal(position))

    def dataset_roi_review_records(self) -> list[dict]:
        if not self.config or not self.config.is_file():
            return []
        try:
            payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        except Exception:
            return []
        provenance = dataset_metadata(payload).get("videos", {}) or {}
        project_sources = project_metadata(payload).get("source_videos", []) or []
        records: list[dict] = []
        seen: set[str] = set()
        for dataset_path in (payload.get("video_sets", {}) or {}):
            selected_video = Path(str(dataset_path))
            metadata = dict(provenance.get(str(dataset_path), {}) or {})
            if metadata.get("origin") == "quick_roi_02" and metadata.get("source_video"):
                source_video = Path(str(metadata["source_video"]))
            else:
                source_video = selected_video
            if not source_video.is_file():
                continue
            try:
                key = str(source_video.resolve()).lower()
            except OSError:
                key = str(source_video).lower()
            if key in seen:
                continue
            seen.add(key)
            profile_text = str(metadata.get("roi_profile", "") or "")
            if not profile_text:
                for source in project_sources:
                    try:
                        same_source = Path(str(source.get("path", ""))).resolve() == source_video.resolve()
                    except OSError:
                        same_source = False
                    if same_source:
                        profile_text = str(source.get("roi_profile", "") or "")
                        break
            profile = Path(profile_text) if profile_text else Path()
            records.append({
                "kind": "dataset_roi",
                "video": str(source_video),
                "dataset_video": str(source_video) if metadata.get("origin") == "quick_roi_02" else str(selected_video),
                "profile": str(profile) if profile.is_file() else "",
                "status": tr('ROI 준비') if profile.is_file() else tr('ROI 미설정 · 클릭하여 지정'),
            })
        return records

    def open_dataset_roi_record(self, record: dict) -> None:
        target = str(record.get("dataset_video", ""))
        for row in range(self.dataset_video_table.rowCount()):
            item = self.dataset_video_table.item(row, 1)
            if item and str(item.data(Qt.UserRole)) == target:
                self.dataset_video_table.clearSelection()
                self.dataset_video_table.selectRow(row)
                self.edit_selected_dataset_roi()
                return

    def open_dataset_roi_overview(self) -> None:
        if not self.require_config():
            return
        records = self.dataset_roi_review_records()
        if not records:
            QMessageBox.information(self, tr('검수 영상 없음'), tr('데이터셋에 등록된 영상 파일이 없습니다.'))
            return
        dialog = RoiOverviewDialog(
            records,
            tr('데이터셋 전체 영상 ROI 검수'),
            tr('등록된 모든 영상의 ROI를 비교합니다. 어긋난 카드를 클릭하면 해당 영상의 ROI만 바로 수정할 수 있습니다.'),
            self,
            records_provider=self.dataset_roi_review_records,
            group_apply=True,
            group_apply_label=tr('체크 영상에 기준 ROI 적용'),
            group_apply_tooltip=(
                tr('기준 카드의 ROI를 체크한 데이터셋 영상에 복사합니다. 기본값은 ROI가 없는 영상만 적용하며, 이미 설정된 ROI까지 바꾸려면 ‘기존 ROI도 덮어쓰기’를 켜세요.')
            ),
        )
        dialog.edit_requested.connect(self.open_dataset_roi_record)
        dialog.apply_group_requested.connect(self.apply_dataset_roi_group)
        dialog.exec()
        self.load_dataset_configuration()

    def apply_dataset_roi_group(self, source_record: dict, target_records: list[dict]) -> None:
        """Apply one dataset ROI profile without materializing ROI clips yet."""
        if not self.require_config():
            return
        template_path = Path(str(source_record.get("profile", "")))
        if not template_path.is_file():
            QMessageBox.information(self, tr('기준 ROI 없음'), tr('기준 영상에 저장된 ROI가 없습니다.'))
            return
        target_videos = [
            Path(str(record.get("video", "")))
            for record in target_records
            if Path(str(record.get("video", ""))).is_file()
        ]
        if not target_videos:
            QMessageBox.information(self, tr('적용 대상 없음'), tr('ROI를 적용할 영상을 체크하세요.'))
            return
        source_video = str(source_record.get("video", "") or "").strip()
        if not self.validate_project_source_names(
            extra_paths=target_videos + ([Path(source_video)] if source_video else []),
        ):
            return

        try:
            template = json.loads(template_path.read_text(encoding="utf-8"))
            source_width, source_height = map(int, template.get("source_resolution_px", []))
            if source_width < 1 or source_height < 1 or not template.get("arenas"):
                raise ValueError(tr('해상도 또는 ROI 영역이 없습니다.'))
        except Exception as error:
            QMessageBox.warning(self, tr('ROI 템플릿 오류'), tr('기준 ROI를 읽을 수 없습니다.\n{value1}', value1=error))
            return

        choice = QMessageBox(self)
        choice.setWindowTitle(tr('데이터셋 ROI 적용 방식'))
        choice.setText(
            tr('{value1}개 영상에 기준 ROI 설정을 저장합니다.\nROI 영상과 라벨 프레임은 아직 만들지 않습니다.\n\n카메라와 해상도가 같으면 ‘같은 해상도만’을 권장합니다.', value1=len(target_videos))
        )
        exact_button = choice.addButton(tr('같은 해상도만 적용'), QMessageBox.AcceptRole)
        scaled_button = choice.addButton(tr('해상도 비율로 보정'), QMessageBox.ActionRole)
        choice.addButton(QMessageBox.Cancel)
        choice.exec()
        clicked = choice.clickedButton()
        if clicked not in (exact_button, scaled_button):
            return
        scale_mode = clicked is scaled_button

        import cv2
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        provenance = dataset_metadata(payload, create=True).setdefault("videos", {})
        sources = project_metadata(payload).get("source_videos", []) or []
        profile_root = project_state_root(self.config.parent) / "camera_profiles"
        profile_root.mkdir(parents=True, exist_ok=True)
        prepared: list[tuple[Path, Path]] = []
        skipped: list[str] = []

        def same_path(left: Path, right: Path) -> bool:
            """Compare Windows paths without failing on missing/external files."""
            try:
                return left.resolve() == right.resolve()
            except OSError:
                return os.path.normcase(os.path.abspath(str(left))) == os.path.normcase(
                    os.path.abspath(str(right))
                )

        for video in target_videos:
            capture = cv2.VideoCapture(str(video))
            width = int(capture.get(cv2.CAP_PROP_FRAME_WIDTH) or 0)
            height = int(capture.get(cv2.CAP_PROP_FRAME_HEIGHT) or 0)
            capture.release()
            if width < 1 or height < 1:
                skipped.append(tr('{value1}: 영상을 읽을 수 없음', value1=video.name))
                continue
            if (width, height) != (source_width, source_height) and not scale_mode:
                skipped.append(tr('{value1}: {value2}×{value3} 해상도 불일치', value1=video.name, value2=width, value3=height))
                continue

            target_payload = json.loads(json.dumps(template))
            target_payload["created_from_video"] = str(video)
            target_payload["template_source"] = str(template_path)
            if (width, height) != (source_width, source_height):
                x_scale, y_scale = width / source_width, height / source_height
                target_payload["source_resolution_px"] = [width, height]
                for arena in target_payload.get("arenas", []):
                    for polygon_key in ("corners_source_px", "mask_polygon_source_px"):
                        if arena.get(polygon_key):
                            arena[polygon_key] = [
                                [float(point[0]) * x_scale, float(point[1]) * y_scale]
                                for point in arena[polygon_key]
                            ]
                    for zone in arena.get("zones", []):
                        zone["polygon_source_px"] = [
                            [float(point[0]) * x_scale, float(point[1]) * y_scale]
                            for point in zone.get("polygon_source_px", [])
                        ]

            target_profile = profile_root / f"{video.stem}_roi_profile.json"
            target_profile.write_text(
                json.dumps(target_payload, ensure_ascii=False, indent=2), encoding="utf-8"
            )

            # Connect the raw dataset row directly, even when it was added
            # without first being registered in the dashboard/source library.
            video_key = next(
                (
                    key for key in (payload.get("video_sets", {}) or {})
                    if same_path(Path(str(key)), video)
                ),
                str(video),
            )
            metadata = provenance.setdefault(str(video_key), {})
            metadata["roi_profile"] = str(target_profile)
            metadata["roi_template_source"] = str(template_path)
            metadata["roi_template_mode"] = (
                "exact" if (width, height) == (source_width, source_height) else "scaled"
            )
            for source in sources:
                if same_path(Path(str(source.get("path", ""))), video):
                    source["roi_profile"] = str(target_profile)
                    source["roi_template_source"] = str(template_path)
                    source["roi_template_mode"] = metadata["roi_template_mode"]
                    source.pop("roi_customized", None)
            prepared.append((video, target_profile))

        if not prepared:
            message = tr('적용할 수 있는 영상이 없습니다.')
            if skipped:
                message += "\n\n" + "\n".join(skipped[:20])
            QMessageBox.information(self, tr('ROI 적용 결과'), message)
            return

        self.write_project_configuration(payload, tr('데이터셋 ROI 일괄 적용: {value1}개', value1=len(prepared)))
        self.load_dataset_configuration()
        message = tr('{value1}개 영상에 ROI 설정을 저장했습니다.', value1=len(prepared))
        message += tr('\n‘계획 저장 후 대표 프레임 추출’을 누르면 ROI 영상 생성과 프레임 추출이 이어서 실행됩니다.')
        if skipped:
            message += tr('\n\n처리하지 못한 영상:\n') + "\n".join(skipped[:20])
        QMessageBox.information(self, tr('데이터셋 ROI 설정 저장 완료'), message)

    def edit_selected_dataset_roi(self) -> None:
        """Open the shared ROI editor and save only its ROI profile."""
        if not self.require_config():
            return
        selected_rows = self.dataset_video_table.selectionModel().selectedRows()
        if len(selected_rows) != 1:
            QMessageBox.information(
                self,
                tr('영상 한 개 선택'),
                tr('추출 영상 목록에서 ROI를 지정하거나 수정할 영상 한 행을 선택하세요.'),
            )
            return
        row = selected_rows[0].row()
        path_item = self.dataset_video_table.item(row, 1)
        if not path_item:
            return
        selected_video = Path(str(path_item.data(Qt.UserRole)))
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        provenance = (dataset_metadata(payload).get("videos", {}) or {})
        metadata = dict(provenance.get(str(selected_video), {}) or {})

        # An already cropped ROI row points back to its original composite video.
        # A manually added raw row itself is the source even if its metadata keeps
        # the external pre-copy location for provenance.
        if metadata.get("origin") == "quick_roi_02" and metadata.get("source_video"):
            source_video = Path(str(metadata["source_video"]))
        else:
            source_video = selected_video
        if not source_video.is_file():
            QMessageBox.warning(self, tr('원본 영상 없음'), tr('ROI를 지정할 원본 영상을 찾을 수 없습니다.\n{value1}', value1=source_video))
            return

        profile_root = project_state_root(self.config.parent) / "zone_profiles"
        target_profile = profile_root / f"{source_video.stem}_zones.json"
        existing_profile = Path(str(metadata.get("roi_profile", ""))) if metadata.get("roi_profile") else Path()

        def roi_saved(target_profile: Path) -> None:
            latest = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
            changed = False
            latest_provenance = dataset_metadata(latest, create=True).setdefault("videos", {})
            selected_metadata = latest_provenance.setdefault(str(selected_video), {})
            if selected_metadata.get("roi_profile") != str(target_profile):
                selected_metadata["roi_profile"] = str(target_profile)
                changed = True
            for source in (project_metadata(latest).get("source_videos", []) or []):
                try:
                    same_source = Path(str(source.get("path", ""))).resolve() == source_video.resolve()
                except OSError:
                    same_source = False
                if same_source and source.get("roi_profile") != str(target_profile):
                    source["roi_profile"] = str(target_profile)
                    changed = True
            if changed:
                self.write_project_configuration(latest, tr('데이터셋 ROI 저장: {value1}', value1=source_video.name))
            self.load_dataset_configuration()
            self.append_log(
                tr('데이터셋 ROI 설정 저장: {value1} · ROI 영상과 라벨 프레임은 아직 생성하지 않음', value1=source_video.name)
            )

        self.start_tracking_roi_editor(source_video, target_profile, roi_saved, existing_profile)

    def import_dataset_roi_profile(
        self, source_video: Path, roi_profile: Path, *, show_message: bool = True,
        finished_callback=None,
    ) -> None:
        """Materialize dataset ROI clips immediately before frame extraction."""
        if not self.config:
            return
        current_payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        current_metadata = (dataset_metadata(current_payload).get("videos", {}) or {})
        source_metadata = dict(current_metadata.get(str(source_video), {}) or {})
        source_frames_to_pick = int(
            source_metadata.get(
                "frames_to_pick",
                current_payload.get("numframes2pick", self.dataset_frames_per_video.value()),
            )
        )
        scratch_output = project_state_root(self.config.parent) / "runtime" / "dataset-roi-import" / source_video.stem

        def imported(exit_code: int) -> None:
            if exit_code != 0:
                if finished_callback:
                    finished_callback(exit_code)
                return
            payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
            video_sets = payload.get("video_sets", {}) or {}
            provenance = dataset_metadata(payload, create=True).setdefault("videos", {})
            changed = False
            source_key = str(source_video)
            # Keep the composite source in the project for reference, but do not
            # extract labeling frames from it once ROI clips have been created.
            if source_key in video_sets:
                source_metadata = provenance.setdefault(source_key, {})
                if source_metadata.get("extract_enabled", True):
                    source_metadata["extract_enabled"] = False
                    changed = True
                if source_metadata.get("roi_profile") != str(roi_profile):
                    source_metadata["roi_profile"] = str(roi_profile)
                    changed = True
            if changed:
                self.write_project_configuration(payload, tr('합본 원본 추출 해제: {value1}', value1=source_video.name))
            self.refresh_project()
            self.load_dataset_configuration()
            if finished_callback:
                finished_callback(exit_code)

        self.start_process(
            SCRIPTS / "hagisilta_import_quick_rois.py",
            [
                str(scratch_output), str(self.config),
                "--default-frames", str(source_frames_to_pick),
                "--source-video", str(source_video),
                "--roi-profile", str(roi_profile),
            ],
            imported,
        )

    def add_dataset_videos(self) -> None:
        if not self.require_config():
            return
        selected, _ = QFileDialog.getOpenFileNames(
            self, tr('DLC 프로젝트에 영상 추가'), str(self.work_root),
            "Videos (*.mp4 *.avi *.mov *.mkv *.m4v)",
        )
        if not selected:
            return
        import cv2

        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        video_sets = payload.setdefault("video_sets", {})
        provenance = dataset_metadata(payload, create=True).setdefault("videos", {})
        project = Path(payload.get("project_path", self.config.parent))
        video_dir = project / "videos"
        video_dir.mkdir(parents=True, exist_ok=True)
        added: list[str] = []
        failed: list[str] = []
        for item in selected:
            source = Path(item).resolve()
            destination = video_dir / source.name
            if source != destination.resolve() and destination.exists():
                counter = 2
                while destination.exists():
                    destination = video_dir / f"{source.stem}_{counter}{source.suffix}"
                    counter += 1
            if source != destination.resolve():
                shutil.copy2(source, destination)
            capture = cv2.VideoCapture(str(destination))
            width = int(capture.get(cv2.CAP_PROP_FRAME_WIDTH))
            height = int(capture.get(cv2.CAP_PROP_FRAME_HEIGHT))
            capture.release()
            if width < 1 or height < 1:
                failed.append(source.name)
                continue
            video_sets[str(destination)] = {"crop": f"0, {width}, 0, {height}"}
            provenance[str(destination)] = {
                "origin": "manual", "source_video": str(source),
                "frames_to_pick": int(self.dataset_frames_per_video.value()), "extract_enabled": True,
            }
            added.append(str(destination))
        if added:
            self.write_project_configuration(payload, tr('영상 {value1}개 추가', value1=len(added)))
            self.refresh_project()
            self.load_dataset_configuration()
            index = self.dataset_video_list.findData(added[-1])
            if index >= 0:
                self.dataset_video_list.setCurrentIndex(index)
        message = tr('프로젝트에 {value1}개 영상을 추가했습니다. 대표 프레임 추출을 실행하면 라벨 프레임 수가 증가합니다.', value1=len(added))
        if failed:
            message += tr('\n읽지 못한 영상: ') + ", ".join(failed)
        QMessageBox.information(self, tr('영상 추가'), message)

    def remove_dataset_video(self) -> None:
        if not self.require_config():
            return
        selected_rows = sorted({
            index.row() for index in self.dataset_video_table.selectionModel().selectedRows()
        })
        if not selected_rows:
            QMessageBox.information(self, tr('영상 제외'), tr('표에서 제외할 행을 선택하세요.'))
            return
        selected_paths: set[str] = set()
        linked_roi_paths: set[str] = set()
        for row in selected_rows:
            item = self.dataset_video_table.item(row, 1)
            if item is None:
                continue
            selected_paths.add(str(item.data(Qt.UserRole)))
            linked_roi_paths.update(
                str(path) for path in (item.data(Qt.UserRole + 1) or []) if path
            )
        names = "\n".join(f"• {Path(path).name}" for path in sorted(selected_paths))
        answer = QMessageBox.question(
            self, tr('프로젝트 영상 제외'),
            tr('선택한 {value1}개 영상을 프로젝트 목록에서 제외할까요?\n\n{value2}\n\n원본 영상과 기존 라벨 파일은 삭제하지 않습니다.', value1=len(selected_paths), value2=names),
            QMessageBox.Yes | QMessageBox.No, QMessageBox.No,
        )
        if answer != QMessageBox.Yes:
            return
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        video_sets = payload.get("video_sets", {}) or {}
        # The table groups ROI-split DLC videos under their original source.
        # Excluding only the visible source leaves hidden ROI children in
        # video_sets, which makes the row reappear on the next refresh.
        paths_to_remove = selected_paths | linked_roi_paths
        for path in paths_to_remove:
            video_sets.pop(path, None)
        payload["video_sets"] = video_sets
        metadata = (dataset_metadata(payload).get("videos", {}) or {})
        for path in paths_to_remove:
            metadata.pop(path, None)
        if self.dataset_video.text() in selected_paths:
            self.dataset_video.clear()
        self.write_project_configuration(payload, tr('영상 목록에서 {value1}개 제외', value1=len(selected_paths)))
        self.refresh_project()
        self.load_dataset_configuration()

    def load_source_library(self) -> None:
        if not self.config or not self.config.is_file() or not hasattr(self, "source_video_table"):
            return
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        project_meta = project_metadata(payload)
        sources = project_meta.get("source_videos", []) or []
        current = str(project_meta.get("test_video", "")) or (
            self.quick_video.text() if hasattr(self, "quick_video") else ""
        )
        sorting_enabled = self.source_video_table.isSortingEnabled()
        self.source_video_table.setSortingEnabled(False)
        self.source_video_table.blockSignals(True)
        self.source_video_table.setRowCount(0)
        for source in sources:
            path = str(source.get("path", ""))
            row = self.source_video_table.rowCount()
            self.source_video_table.insertRow(row)
            management_check = self.set_centered_table_checkbox(
                self.source_video_table, row, 0, False
            )
            management_check.setToolTip(tr('목록 제외 등 관리 작업에 사용할 영상을 체크합니다.'))
            management_check.stateChanged.connect(self.update_source_management_actions)
            name = QTableWidgetItem(Path(path).name)
            name.setData(Qt.UserRole, path)
            name.setToolTip(path if Path(path).is_file() else tr('파일 없음: {value1}', value1=path))
            name.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            self.source_video_table.setItem(row, 1, name)
            test_sort = QTableWidgetItem(tr('● 현재 시험 영상') if path == current else tr('시험 영상으로 지정'))
            test_sort.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            test_sort.setTextAlignment(Qt.AlignCenter)
            test_sort.setToolTip(
                tr('현재 SuperAnimal 모델 확인에 사용하는 대표 영상입니다.')
                if path == current else tr('클릭하면 이 영상을 SuperAnimal 모델 확인용 대표 영상으로 지정합니다.')
            )
            if path == current:
                current_font = test_sort.font()
                current_font.setBold(True)
                test_sort.setFont(current_font)
                test_sort.setForeground(QColor("#72e5b2"))
            self.source_video_table.setItem(row, 2, test_sort)
            self.source_video_table.setItem(row, 3, QTableWidgetItem(str(source.get("group", ""))))
            self.source_video_table.setItem(row, 4, QTableWidgetItem(str(source.get("subject_id", Path(path).stem))))
            storage = QTableWidgetItem(tr('프로젝트 복사') if source.get("storage") == "copied" else tr('원본 링크'))
            storage.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            self.source_video_table.setItem(row, 5, storage)
            profile = Path(source.get("roi_profile", "")) if source.get("roi_profile") else (
                project_state_root(self.config.parent) / "camera_profiles" / f"{Path(path).stem}_roi_profile.json"
            )
            roi = QTableWidgetItem(tr('준비됨') if profile.is_file() else tr('미설정'))
            roi.setToolTip(str(profile))
            roi.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            self.source_video_table.setItem(row, 6, roi)
        self.source_video_table.blockSignals(False)
        self.source_video_table.setSortingEnabled(sorting_enabled)
        if hasattr(self, "source_stage_badge"):
            has_test_video = bool(current and Path(current).is_file())
            status = tr('{value1} · 준비', value1=Path(current).name) if has_test_video else tr('대표 영상 필요')
            self.set_workflow_badge(self.source_stage_badge, status, has_test_video)
            if has_test_video and not self.source_stage_card.property("autoAdvanced"):
                self.set_workflow_expanded(self.source_stage_card, False)
                next_card = (
                    self.parameter_stage_card
                    if self.roi_stage_badge.objectName() == "stepBadgeReady"
                    else self.roi_stage_card
                )
                self.set_workflow_expanded(next_card, True)
                self.source_stage_card.setProperty("autoAdvanced", True)
        self.update_source_management_actions()
        self.load_batch_source_table()

    def register_source_paths(self, paths: list[Path], copy_files: bool) -> None:
        if not self.require_config() or not paths:
            return
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        project_meta = project_metadata(payload, create=True)
        sources = project_meta.setdefault("source_videos", [])
        hidden_sources = {
            self.normalized_source_key(path)
            for path in (project_meta.get("hidden_source_videos", []) or [])
            if str(path).strip()
        }
        original_hidden_sources = set(hidden_sources)
        known = {
            self.normalized_source_key(str(item.get("path", "")))
            for item in sources
            if str(item.get("path", "")).strip()
        }
        candidates = list(dict.fromkeys(candidate.expanduser().resolve() for candidate in paths
            if candidate.is_file() and candidate.suffix.lower() in {".mp4", ".avi", ".mov", ".mkv", ".m4v"}))
        existing_paths = [Path(item["path"]) for item in sources if str(item.get("path", "")).strip()]
        try:
            validate_unique_source_stems(existing_paths + ([] if copy_files else candidates))
        except ValueError as error:
            QMessageBox.warning(self, tr('영상 이름 중복 확인'), str(error))
            return
        stem_key = lambda path: unicodedata.normalize("NFC", path.stem).casefold()
        reserved_stems = {stem_key(path) for path in existing_paths}
        destination_root = self.config.parent / "original-videos"
        if copy_files:
            destination_root.mkdir(parents=True, exist_ok=True)
        added = 0
        for candidate in candidates:
            source = candidate.expanduser().resolve()
            if not source.is_file() or source.suffix.lower() not in {".mp4", ".avi", ".mov", ".mkv", ".m4v"}:
                continue
            registered = source
            storage = "linked"
            if copy_files:
                registered = destination_root / source.name
                if (registered.exists() and registered.resolve() != source) or (
                    stem_key(registered) in reserved_stems and self.normalized_source_key(registered) not in known
                ):
                    counter = 2
                    while registered.exists() or stem_key(registered) in reserved_stems:
                        registered = destination_root / f"{source.stem}_{counter}{source.suffix}"
                        counter += 1
                if registered.resolve() != source:
                    shutil.copy2(source, registered)
                storage = "copied"
            key = str(registered.resolve())
            normalized_key = self.normalized_source_key(key)
            if normalized_key in known:
                hidden_sources.discard(normalized_key)
                continue
            profile = project_state_root(self.config.parent) / "camera_profiles" / f"{registered.stem}_roi_profile.json"
            sources.append({
                "path": key,
                "original_path": str(source),
                "storage": storage,
                "enabled": True,
                "group": "",
                "subject_id": source.stem,
                "roi_profile": str(profile),
            })
            known.add(normalized_key)
            reserved_stems.add(stem_key(registered))
            hidden_sources.discard(normalized_key)
            added += 1
        project_meta["hidden_source_videos"] = sorted(hidden_sources)
        hidden_changed = hidden_sources != original_hidden_sources
        if added or hidden_changed:
            reason = (
                tr('원본 실험 영상 {value1}개 등록', value1=added)
                if added else tr('원본 실험 영상 목록 제외 해제')
            )
            self.write_project_configuration(payload, reason)
            self.load_source_library()
            self.refresh_project()
            if hasattr(self, "spatial_table"):
                self.refresh_spatial_bundle()
            if hasattr(self, "ymaze_bundle_table"):
                self.refresh_ymaze_bundle_table()
            self.append_log(
                tr('원본 영상 등록 완료: {value1}개', value1=added)
                + (tr(' · 기존 목록 제외 해제') if hidden_changed else "")
            )
        else:
            QMessageBox.information(self, tr('등록할 영상 없음'), tr('새 영상이 없거나 지원하지 않는 형식입니다.'))

    def validate_project_source_names(self, extra_paths: list[Path] | None = None) -> bool:
        try:
            payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {} if self.config else {}
            sources = project_metadata(payload).get("source_videos", []) or []
            source_paths = [Path(item["path"]) for item in sources if str(item.get("path", "")).strip()]
            source_keys = {normalized_source_path(path) for path in source_paths}
            provenance = {
                normalized_source_path(path): metadata
                for path, metadata in (dataset_metadata(payload).get("videos", {}) or {}).items()
                if isinstance(metadata, dict) and metadata.get("origin") == "manual"
            }
            for candidate in extra_paths or []:
                candidate = Path(candidate)
                metadata = provenance.get(normalized_source_path(candidate), {})
                original = str(metadata.get("source_video", "") or "").strip()
                # A directly added dataset copy can retain the registered raw
                # video's name. It is an alias, not a second camera/source.
                # Generated ROI/review clips and renamed copies are not aliases.
                if original and normalized_source_path(original) in source_keys and (
                    unicodedata.normalize("NFC", candidate.stem).casefold()
                    == unicodedata.normalize("NFC", Path(original).stem).casefold()
                ):
                    continue
                source_paths.append(candidate)
            validate_unique_source_stems(source_paths)
        except (OSError, ValueError, yaml.YAMLError) as error:
            QMessageBox.warning(self, tr('영상 이름 중복 확인'), str(error))
            return False
        return True

    def add_source_videos(self) -> None:
        selected, _ = QFileDialog.getOpenFileNames(
            self, tr('원본 실험 영상 여러 개 등록'), str(self.work_root),
            "Videos (*.mp4 *.avi *.mov *.mkv *.m4v)",
        )
        if not selected:
            return
        self.register_source_paths([Path(path) for path in selected], copy_files=False)

    def add_source_folder(self) -> None:
        selected = QFileDialog.getExistingDirectory(self, tr('원본 영상 폴더 등록'), str(self.work_root))
        if not selected:
            return
        root = Path(selected)
        paths = [
            path for path in root.rglob("*")
            if path.is_file() and path.suffix.lower() in {".mp4", ".avi", ".mov", ".mkv", ".m4v"}
        ]
        if not paths:
            QMessageBox.information(self, tr('등록할 영상 없음'), tr('선택한 폴더에서 지원하는 영상 파일을 찾지 못했습니다.'))
            return
        self.register_source_paths(sorted(paths), copy_files=False)

    def save_source_library(self) -> None:
        if not self.require_config():
            return
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        previous = {
            str(item.get("path", "")): item
            for item in (project_metadata(payload).get("source_videos", []) or [])
        }
        sources = []
        for row in range(self.source_video_table.rowCount()):
            path = str(self.source_video_table.item(row, 1).data(Qt.UserRole))
            item = dict(previous.get(path, {}))
            item.update({
                "path": path,
                "group": self.source_video_table.item(row, 3).text().strip(),
                "subject_id": self.source_video_table.item(row, 4).text().strip() or Path(path).stem,
                "roi_profile": str(item.get("roi_profile") or (
                    project_state_root(self.config.parent) / "camera_profiles" / f"{Path(path).stem}_roi_profile.json"
                )),
            })
            sources.append(item)
        project_metadata(payload, create=True)["source_videos"] = sources
        self.write_project_configuration(payload, tr('원본 영상 실험 정보 저장'))
        self.load_source_library()

    def set_all_source_checks(self, checked: bool) -> None:
        for row in range(self.source_video_table.rowCount()):
            cell = self.source_video_table.cellWidget(row, 0)
            checkbox = cell.findChild(QCheckBox) if cell else None
            if checkbox:
                checkbox.setChecked(checked)

    def source_management_checked(self, row: int) -> bool:
        cell = self.source_video_table.cellWidget(row, 0)
        checkbox = cell.findChild(QCheckBox) if cell else None
        return bool(checkbox and checkbox.isChecked())

    def update_source_management_actions(self, _state: int | QTableWidgetItem | None = None) -> None:
        checked = any(
            self.source_management_checked(row)
            for row in range(self.source_video_table.rowCount())
        )
        self.remove_source_button.setEnabled(checked)
        self.change_source_storage_button.setEnabled(checked)
        selected_rows = self.source_video_table.selectionModel().selectedRows()
        if hasattr(self, "set_test_video_button"):
            self.set_test_video_button.setEnabled(len(selected_rows) == 1)
            if len(selected_rows) == 1:
                row = selected_rows[0].row()
                test_item = self.source_video_table.item(row, 2)
                is_current = bool(test_item and test_item.text().startswith("●"))
                self.set_test_video_button.setText(
                    tr('현재 시험 영상') if is_current else tr('선택 행을 시험 영상으로 지정')
                )
                self.set_test_video_button.setEnabled(not is_current)
            else:
                self.set_test_video_button.setText(tr('선택 행을 시험 영상으로 지정'))

    def change_checked_source_storage(self) -> None:
        if not self.require_config():
            return
        selected_rows = [
            row for row in range(self.source_video_table.rowCount())
            if self.source_management_checked(row)
        ]
        if not selected_rows:
            QMessageBox.information(self, tr('저장 방식 변경'), tr('왼쪽 ‘선택’에서 영상을 체크하세요.'))
            return
        selected_paths = {
            str(self.source_video_table.item(row, 1).data(Qt.UserRole))
            for row in selected_rows
        }
        edited_fields = {
            str(self.source_video_table.item(row, 1).data(Qt.UserRole)): {
                "group": self.source_video_table.item(row, 3).text().strip(),
                "subject_id": self.source_video_table.item(row, 4).text().strip(),
            }
            for row in range(self.source_video_table.rowCount())
        }

        dialog = QMessageBox(self)
        dialog.setWindowTitle(tr('체크 영상 저장 방식'))
        dialog.setIcon(QMessageBox.Question)
        dialog.setText(tr('체크한 영상 {value1}개의 저장 방식을 선택하세요.', value1=len(selected_paths)))
        dialog.setInformativeText(
            tr('프로젝트로 복사하면 다른 PC로 옮기기 쉽지만 저장공간을 사용합니다.\n원본 위치 연결로 바꿔도 기존 프로젝트 복사본은 자동 삭제하지 않습니다.')
        )
        copy_button = dialog.addButton(tr('프로젝트로 복사'), QMessageBox.AcceptRole)
        link_button = dialog.addButton(tr('원본 위치 연결'), QMessageBox.ActionRole)
        dialog.addButton(tr('취소'), QMessageBox.RejectRole)
        dialog.exec()
        clicked = dialog.clickedButton()
        if clicked is not copy_button and clicked is not link_button:
            return
        copy_to_project = clicked is copy_button

        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        project_meta = project_metadata(payload, create=True)
        sources = project_meta.get("source_videos", []) or []
        destination_root = self.config.parent / "original-videos"
        stem_key = lambda path: unicodedata.normalize("NFC", path.stem).casefold()
        # Plan every path before copying any files or persisting project state.
        # Reserve stems, not filenames: foo.avi and foo.mp4 share ROI outputs.
        reserved_stems: dict[str, set[str]] = {}
        for source in sources:
            path = str(source.get("path", "") or "").strip()
            if path:
                reserved_stems.setdefault(stem_key(Path(path)), set()).add(normalized_source_path(path))
        copy_jobs: list[tuple[Path, Path]] = []
        changed = 0
        skipped = []
        quick_replacement = ""
        for source in sources:
            old_path = str(source.get("path", ""))
            if old_path in edited_fields:
                source.update(edited_fields[old_path])
                source["subject_id"] = source["subject_id"] or Path(old_path).stem
            if old_path not in selected_paths:
                continue
            if copy_to_project:
                if source.get("storage") == "copied":
                    continue
                source_file = Path(old_path)
                if not source_file.is_file():
                    skipped.append(tr('{value1}: 원본 파일 없음', value1=source_file.name))
                    continue
                old_key = normalized_source_path(source_file)
                reserved_stems.get(stem_key(source_file), set()).discard(old_key)
                destination = destination_root / source_file.name
                destination_key = normalized_source_path(destination)
                owners = reserved_stems.get(stem_key(destination), set())
                if (destination.exists() and destination_key != old_key) or (
                    owners and destination_key not in owners
                ):
                    counter = 2
                    while destination.exists() or reserved_stems.get(stem_key(destination)):
                        destination = destination_root / f"{source_file.stem}_{counter}{source_file.suffix}"
                        counter += 1
                new_path = str(destination.resolve())
                if normalized_source_path(destination) != old_key:
                    copy_jobs.append((source_file, destination))
                source["original_path"] = str(source.get("original_path") or source_file.resolve())
                source["path"] = new_path
                source["storage"] = "copied"
            else:
                original = Path(str(source.get("original_path", "")))
                if not original.is_file():
                    skipped.append(tr('{value1}: 연결할 원본 위치 없음', value1=Path(old_path).name))
                    continue
                new_path = str(original.resolve())
                if source.get("storage") == "linked" and normalized_source_path(new_path) == normalized_source_path(old_path):
                    continue
                reserved_stems.get(stem_key(Path(old_path)), set()).discard(normalized_source_path(old_path))
                source["path"] = new_path
                source["storage"] = "linked"
            reserved_stems.setdefault(stem_key(Path(new_path)), set()).add(normalized_source_path(new_path))
            if str(project_meta.get("test_video", "")) == old_path:
                project_meta["test_video"] = new_path
            if self.quick_video.text() == old_path:
                quick_replacement = new_path
            changed += 1

        if not changed:
            detail = "\n".join(skipped) if skipped else tr('이미 선택한 저장 방식으로 설정되어 있습니다.')
            QMessageBox.information(self, tr('변경 사항 없음'), detail)
            return
        try:
            validate_unique_source_stems(
                source["path"] for source in sources if str(source.get("path", "")).strip()
            )
        except ValueError as error:
            QMessageBox.warning(self, tr('영상 이름 중복 확인'), str(error))
            return
        copied = 0
        try:
            if copy_jobs:
                destination_root.mkdir(parents=True, exist_ok=True)
            for source_file, destination in copy_jobs:
                # Recheck the plan before writing; never replace an unrelated
                # file that appeared after the user confirmed this operation.
                if destination.exists():
                    raise FileExistsError(tr('복사 대상이 이미 있습니다: {value1}', value1=destination))
                shutil.copy2(source_file, destination)
                copied += 1
        except OSError as error:
            retained = tr('\n이미 복사한 {value1}개 파일은 유지됩니다.', value1=copied) if copied else ""
            QMessageBox.warning(self, tr('영상 복사 실패'), tr('프로젝트 설정은 변경하지 않았습니다.\n{value1}{value2}', value1=error, value2=retained))
            return
        self.write_project_configuration(
            payload,
            tr('원본 영상 저장 방식 변경: {value1} {value2}개', value1=tr('프로젝트 복사') if copy_to_project else tr('원본 링크'), value2=changed),
        )
        if quick_replacement:
            self.quick_video.setText(quick_replacement)
        self.load_source_library()
        message = tr('{value1}개 영상의 저장 방식을 변경했습니다.', value1=changed)
        if skipped:
            message += tr('\n\n처리하지 못한 영상:\n') + "\n".join(skipped)
        QMessageBox.information(self, tr('저장 방식 변경 완료'), message)

    def load_batch_source_table(self) -> None:
        if (
            not self.config or not self.config.is_file()
            or not hasattr(self, "batch_source_table")
        ):
            return
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        sources = (project_metadata(payload).get("source_videos", []) or [])
        import cv2
        sorting_enabled = self.batch_source_table.isSortingEnabled()
        self.batch_source_table.setSortingEnabled(False)
        self.batch_source_table.blockSignals(True)
        self.batch_source_table.setRowCount(0)
        completed_total = 0
        for source in sources:
            path = str(source.get("path", ""))
            row = self.batch_source_table.rowCount()
            self.batch_source_table.insertRow(row)
            checkbox = self.set_centered_table_checkbox(
                self.batch_source_table, row, 0, bool(source.get("enabled", True))
            )
            checkbox.stateChanged.connect(self.update_batch_target_summary)
            name = QTableWidgetItem(Path(path).name)
            name.setData(Qt.UserRole, path)
            name.setToolTip(path)
            name.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            self.batch_source_table.setItem(row, 1, name)
            group_item = QTableWidgetItem(str(source.get("group", "")))
            group_item.setToolTip(tr('더블클릭하여 실험군을 입력한 뒤 위의 ‘실험군·개체 ID 저장’을 누르세요.'))
            self.batch_source_table.setItem(row, 2, group_item)
            subject_item = QTableWidgetItem(str(source.get("subject_id", Path(path).stem)))
            subject_item.setToolTip(tr('더블클릭하여 개체 ID를 입력한 뒤 위의 ‘실험군·개체 ID 저장’을 누르세요.'))
            self.batch_source_table.setItem(row, 3, subject_item)
            width = height = frames = 0
            fps = 0.0
            video_path = Path(path)
            if video_path.is_file():
                capture = cv2.VideoCapture(str(video_path))
                width = int(capture.get(cv2.CAP_PROP_FRAME_WIDTH))
                height = int(capture.get(cv2.CAP_PROP_FRAME_HEIGHT))
                frames = int(capture.get(cv2.CAP_PROP_FRAME_COUNT))
                fps = float(capture.get(cv2.CAP_PROP_FPS))
                capture.release()
            duration = frames / fps if fps else 0.0
            info = QTableWidgetItem(
                tr('{value1}×{value2} · {value3:.1f}초', value1=width, value2=height, value3=duration) if width else tr('파일 없음')
            )
            info.setTextAlignment(Qt.AlignCenter)
            self.batch_source_table.setItem(row, 4, info)
            profile = Path(str(source.get("roi_profile", "")))
            roi_count = 0
            if profile.is_file():
                try:
                    roi_payload = json.loads(profile.read_text(encoding="utf-8"))
                    roi_count = len(roi_payload.get("arenas", []))
                except Exception:
                    roi_count = 0
            template = bool(source.get("roi_template_source"))
            roi = QTableWidgetItem(
                tr('{value1} · {value2}개', value1=tr('템플릿') if template else tr('개별'), value2=roi_count) if roi_count else tr('미설정')
            )
            roi.setToolTip(str(profile))
            roi.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            roi.setTextAlignment(Qt.AlignCenter)
            roi.setData(Qt.UserRole, roi_count)
            self.batch_source_table.setItem(row, 5, roi)
            expected = QTableWidgetItem(str(roi_count) if roi_count else "-")
            expected.setTextAlignment(Qt.AlignCenter)
            expected.setData(Qt.UserRole, roi_count)
            self.batch_source_table.setItem(row, 6, expected)
            output_root = Path(self.track_output.text()) if self.track_output.text().strip() else Path()
            source_output = output_root / video_path.stem
            status_text, status_detail, completed = source_disk_summary(
                source_output, roi_count, self.track_shuffle.value()
            )
            completed_total += completed
            if not video_path.is_file():
                status_text = tr('영상 없음')
            elif not roi_count:
                status_text = tr('ROI 필요')
            status = QTableWidgetItem(status_text)
            status.setToolTip(status_detail)
            status.setTextAlignment(Qt.AlignCenter)
            self.batch_source_table.setItem(row, 7, status)
        self.batch_source_table.blockSignals(False)
        self.batch_source_table.setSortingEnabled(sorting_enabled)
        if self.batch_source_table.rowCount() and self.batch_source_table.currentRow() < 0:
            self.batch_source_table.selectRow(0)
        self.update_batch_target_summary()
        if hasattr(self, "track_result_summary"):
            self.batch_qc_button.setEnabled(completed_total > 0)
            if completed_total:
                self.track_result_summary.value_label.setText(
                    tr('저장된 ROI 결과 {value1}개 · 필요하면 전체 결과를 다시 점검하세요.', value1=completed_total)
                )
                self.set_workflow_badge(
                    self.track_result_badge, tr('저장 결과 {value1}개', value1=completed_total), True
                )
            else:
                self.track_result_summary.value_label.setText(tr('아직 트래킹을 실행하지 않았습니다.'))
                self.set_workflow_badge(self.track_result_badge, tr('결과 없음'), False)
        self.flush_tracking_progress(refresh_results=False)

    def set_all_batch_source_checks(self, checked: bool) -> None:
        sorting_enabled = self.batch_source_table.isSortingEnabled()
        self.batch_source_table.setSortingEnabled(False)
        for row in range(self.batch_source_table.rowCount()):
            checkbox = self.table_checkbox(self.batch_source_table, row, 0)
            if checkbox:
                checkbox.setChecked(checked)
        self.batch_source_table.setSortingEnabled(sorting_enabled)
        self.update_batch_target_summary()

    def save_batch_source_metadata(self) -> None:
        """Save editable experiment-group and subject fields from the tracking table."""
        if not self.require_config():
            return
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        project_meta = project_metadata(payload, create=True)
        sources = project_meta.get("source_videos", []) or []
        by_path = {
            self.normalized_source_key(str(item.get("path", ""))): item
            for item in sources
            if str(item.get("path", "")).strip()
        }
        changed = 0
        for row in range(self.batch_source_table.rowCount()):
            path_item = self.batch_source_table.item(row, 1)
            if not path_item:
                continue
            path = str(path_item.data(Qt.UserRole) or "")
            source = by_path.get(self.normalized_source_key(path))
            if source is None:
                continue
            group = self.batch_source_table.item(row, 2)
            subject = self.batch_source_table.item(row, 3)
            new_group = group.text().strip() if group else ""
            new_subject = subject.text().strip() if subject else Path(path).stem
            if source.get("group", "") != new_group or source.get("subject_id", "") != new_subject:
                source["group"] = new_group
                source["subject_id"] = new_subject
                changed += 1
        if not changed:
            QMessageBox.information(self, tr('저장할 변경 없음'), tr('실험군·개체 ID에서 변경된 값이 없습니다.'))
            return
        self.write_project_configuration(payload, tr('트래킹 영상 실험 정보 저장 · {value1}개', value1=changed))
        self.load_source_library()
        QMessageBox.information(self, tr('실험 정보 저장'), tr('{value1}개 영상의 실험군·개체 ID를 저장했습니다.', value1=changed))

    def update_batch_selection_guide(self) -> None:
        if not hasattr(self, "batch_source_table") or not hasattr(self, "batch_selection_guide"):
            return
        rows = self.selected_batch_source_rows()
        row_text = tr('선택 안 됨')
        if len(rows) == 1 and self.batch_source_table.item(rows[0], 1):
            row_text = self.batch_source_table.item(rows[0], 1).text()
        elif rows:
            row_text = tr('{value1}개 행 선택', value1=len(rows))
        checked = sum(
            1
            for index in range(self.batch_source_table.rowCount())
            if (
                self.table_checkbox(self.batch_source_table, index, 0)
                and self.table_checkbox(self.batch_source_table, index, 0).isChecked()
            )
        )
        self.batch_selection_guide.setText(
            tr('파란 행: {value1}  ·  사용 중인 트래킹 대상: {value2}개', value1=row_text, value2=checked)
        )

    def selected_batch_source_rows(self) -> list[int]:
        selection = self.batch_source_table.selectionModel()
        return sorted({index.row() for index in selection.selectedRows()}) if selection else []

    def selected_batch_source_paths(self) -> set[str]:
        return {
            str(item.data(Qt.UserRole))
            for row in self.selected_batch_source_rows()
            if (item := self.batch_source_table.item(row, 1)) is not None
            and str(item.data(Qt.UserRole) or "").strip()
        }

    def reveal_selected_batch_source(self) -> None:
        rows = self.selected_batch_source_rows()
        item = self.batch_source_table.item(rows[0], 1) if len(rows) == 1 else None
        path = Path(str(item.data(Qt.UserRole))) if item else Path()
        if not path.exists():
            QMessageBox.information(self, tr('파일 위치'), tr('선택한 영상 파일을 찾을 수 없습니다.'))
            return
        if sys.platform == "win32":
            QProcess.startDetached("explorer.exe", ["/select,", str(path)])
        else:
            QDesktopServices.openUrl(QUrl.fromLocalFile(str(path.parent)))

    def apply_roi_template_to_selected_batch_rows(self) -> None:
        paths = self.selected_batch_source_paths()
        if not paths:
            QMessageBox.information(self, tr('행 선택 필요'), tr('ROI 템플릿을 적용할 표 행을 선택하세요.'))
            return
        self.apply_roi_template_path_to_batch_selection(None, selected_paths_override=paths)

    def show_batch_source_context_menu(self, position) -> None:
        rows = self.batch_source_table.restore_right_click_rows(position)
        if not rows:
            return
        prefix = tr('이 행') if len(rows) == 1 else tr('선택한 {value1}개 행', value1=len(rows))
        menu = QMenu(self.batch_source_table)
        title = menu.addAction(prefix)
        title.setEnabled(False)
        menu.addSeparator()
        edit_roi = menu.addAction(tr('{value1} ROI 열기·수정', value1=prefix))
        edit_roi.setEnabled(len(rows) == 1)
        apply_rows = menu.addAction(tr('{value1}에 ROI 파일 적용…', value1=prefix))
        reveal = menu.addAction(tr('{value1} 파일 위치 열기', value1=prefix))
        reveal.setEnabled(len(rows) == 1)
        menu.addSeparator()
        remove_rows = menu.addAction(tr('{value1} 목록에서 제외…', value1=prefix))
        menu.addSeparator()
        review_all = menu.addAction(tr('전체 영상 ROI 검수'))
        chosen = menu.exec(self.batch_source_table.viewport().mapToGlobal(position))
        if chosen == edit_roi:
            self.edit_selected_batch_roi()
        elif chosen == apply_rows:
            self.apply_roi_template_to_selected_batch_rows()
        elif chosen == reveal:
            self.reveal_selected_batch_source()
        elif chosen == remove_rows:
            self.remove_selected_batch_source()
        elif chosen == review_all:
            self.open_source_roi_overview()

    def select_ready_batch_sources(self) -> None:
        sorting_enabled = self.batch_source_table.isSortingEnabled()
        self.batch_source_table.setSortingEnabled(False)
        for row in range(self.batch_source_table.rowCount()):
            checkbox = self.table_checkbox(self.batch_source_table, row, 0)
            roi_item = self.batch_source_table.item(row, 5)
            if checkbox:
                checkbox.setChecked(bool(roi_item and int(roi_item.data(Qt.UserRole) or 0) > 0))
        self.batch_source_table.setSortingEnabled(sorting_enabled)
        self.update_batch_target_summary()

    def update_batch_target_summary(self) -> None:
        if not hasattr(self, "batch_source_table"):
            return
        selected = ready = jobs = 0
        for row in range(self.batch_source_table.rowCount()):
            checkbox = self.table_checkbox(self.batch_source_table, row, 0)
            if not checkbox or not checkbox.isChecked():
                continue
            selected += 1
            roi_item = self.batch_source_table.item(row, 5)
            roi_count = int(roi_item.data(Qt.UserRole) or 0) if roi_item else 0
            if roi_count:
                ready += 1
                jobs += roi_count
        final_shuffle = self.project_final_model_shuffle()
        external_model = self.project_external_tracking_model()
        model_mode = (
            str(self.track_model_source.currentData() or "trained")
            if hasattr(self, "track_model_source") else "trained"
        )
        if hasattr(self, "track_model_summary"):
            if model_mode == "superanimal":
                self.track_model_summary.setText(
                    tr('SuperAnimal TopViewMouse · HRNet-W32\n프로젝트 추가학습 없이 체크한 모든 ROI를 DLC 사전학습 모델로 처리합니다.')
                )
                self.set_workflow_badge(self.track_model_badge, tr('DLC 사전학습 모델 · 사용 준비'), True)
            elif external_model:
                self.track_shuffle.setValue(int(external_model["shuffle"]))
                model_parts = list(external_model.get("bodyparts", []) or [])
                self.track_model_summary.setText(
                    tr('외부 모델 · Shuffle {value1} · {value2}\n모델 신체점 {value3}개 · {value4}\n모델 프로젝트: {value5}', value1=external_model['shuffle'], value2=external_model['snapshot'].name, value3=len(model_parts), value4=', '.join(model_parts) if model_parts else tr('모델 설정에서 확인'), value5=external_model['config'].parent)
                )
                self.set_workflow_badge(self.track_model_badge, tr('외부 모델 · 사용 준비'), True)
            else:
                models = {int(model["shuffle"]): model for model in trained_model_inventory(self.config)}
                model = models.get(final_shuffle) if final_shuffle is not None else None
                if model:
                    self.track_shuffle.setValue(final_shuffle)
                    self.track_model_summary.setText(
                        f"Shuffle {final_shuffle} · {Path(model['best']).name if model['best'] else tr('체크포인트 확인 필요')} · "
                        f"Validation RMSE {self.format_model_metric(model['validation_rmse'], ' px')} · "
                        f"Test RMSE {self.format_model_metric(model['test_rmse'], ' px')}"
                    )
                    self.set_workflow_badge(self.track_model_badge, tr('Shuffle {value1} · 사용 준비', value1=final_shuffle), True)
                else:
                    self.track_model_summary.setText(tr('모델 평가에서 사용할 모델을 최종 지정하거나 외부 모델을 불러오세요.'))
                    self.set_workflow_badge(self.track_model_badge, tr('최종 모델 없음'), False)
        if hasattr(self, "restore_project_model_button"):
            self.restore_project_model_button.setEnabled(model_mode == "trained" and bool(external_model))
        if hasattr(self, "track_show_gpu_memory"):
            self.track_show_gpu_memory.setEnabled(model_mode == "trained")
            self.track_show_gpu_memory.setToolTip(
                detailed_tooltip(
                    tr('각 BU Pose 추론 호출에서 DLC의 GPU 메모리 상세 정보를 실행 로그에 표시합니다.'),
                    tr('프로젝트 최종·외부 모델을 선택했을 때만 사용할 수 있습니다.'),
                    tr('일반 실행에서는 꺼 두고 VRAM 부족이나 처리 속도 저하를 진단할 때만 켜세요.'),
                    tr('결과 좌표나 모델 정확도는 바꾸지 않는 진단 옵션입니다.'),
                )
            )
        if hasattr(self, "track_amp"):
            trained_mode = model_mode == "trained"
            self.track_amp.setEnabled(trained_mode)
            self.track_prefetch.setEnabled(trained_mode)
            self.track_prefetch_queue.setEnabled(
                trained_mode and self.track_prefetch.isChecked()
            )
        if hasattr(self, "batch_target_badge"):
            missing = selected - ready
            label = tr('{value1}개 영상 · {value2} ROI', value1=selected, value2=jobs) + (tr(' · {value1}개 준비 필요', value1=missing) if missing else "")
            self.set_workflow_badge(self.batch_target_badge, label, selected > 0 and missing == 0)
        if hasattr(self, "batch_run_button"):
            self.batch_run_button.setText(
                tr('선택 {value1}개 영상 · {value2} ROI 트래킹 시작', value1=selected, value2=jobs) if selected else tr('트래킹할 영상을 선택하세요')
            )
            self.fit_dynamic_action_button(self.batch_run_button)
            self.batch_run_button.setEnabled(
                bool((model_mode == "superanimal" or external_model or final_shuffle) and selected and selected == ready)
            )
        self.update_batch_selection_guide()

    def save_batch_source_selection(self) -> None:
        if not self.require_config():
            return
        enabled_paths = {
            str(self.batch_source_table.item(row, 1).data(Qt.UserRole))
            for row in range(self.batch_source_table.rowCount())
            if (
                self.table_checkbox(self.batch_source_table, row, 0)
                and self.table_checkbox(self.batch_source_table, row, 0).isChecked()
            )
        }
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        sources = (project_metadata(payload).get("source_videos", []) or [])
        for source in sources:
            source["enabled"] = str(source.get("path", "")) in enabled_paths
        self.write_project_configuration(payload, tr('일괄 트래킹 대상 저장: {value1}개', value1=len(enabled_paths)))

    def apply_roi_template_to_batch_selection(self) -> None:
        self.apply_roi_template_path_to_batch_selection(None)

    def apply_selected_row_roi_to_checked(self) -> None:
        row = self.batch_source_table.currentRow()
        if row < 0:
            QMessageBox.information(
                self,
                tr('기준 행 선택'),
                tr('ROI 기준으로 사용할 영상의 아무 칸이나 클릭해 행 전체를 파란색으로 선택하세요.'),
            )
            return
        roi_item = self.batch_source_table.item(row, 5)
        profile = Path(roi_item.toolTip()) if roi_item and roi_item.toolTip() else Path()
        if not profile.is_file():
            QMessageBox.information(self, tr('기준 ROI 없음'), tr('선택한 행에는 적용할 ROI가 없습니다.'))
            return
        self.apply_roi_template_path_to_batch_selection(profile)

    def apply_roi_template_path_to_batch_selection(
        self, template_override: Path | None, selected_paths_override: set[str] | None = None,
    ) -> None:
        if not self.require_config():
            return
        if not self.validate_project_source_names():
            return
        selected_paths = (
            set(selected_paths_override)
            if selected_paths_override is not None
            else {
                str(self.batch_source_table.item(row, 1).data(Qt.UserRole))
                for row in range(self.batch_source_table.rowCount())
                if self.table_checkbox(self.batch_source_table, row, 0)
                and self.table_checkbox(self.batch_source_table, row, 0).isChecked()
            }
        )
        if not selected_paths:
            QMessageBox.information(self, tr('영상 선택 필요'), tr('ROI 템플릿을 적용할 영상을 먼저 체크하세요.'))
            return
        profile_root = project_state_root(self.config.parent) / "camera_profiles"
        if template_override is None:
            selected, _ = QFileDialog.getOpenFileName(
                self, tr('적용할 ROI 템플릿 선택'), str(profile_root), "ROI profile (*.json)"
            )
            if not selected:
                return
            template_path = Path(selected).resolve()
        else:
            template_path = template_override.resolve()
        try:
            template = json.loads(template_path.read_text(encoding="utf-8"))
            source_width, source_height = map(int, template.get("source_resolution_px", []))
            arenas = template.get("arenas", [])
            if source_width < 1 or source_height < 1 or not arenas:
                raise ValueError(tr('해상도 또는 ROI 영역이 없습니다.'))
        except Exception as error:
            QMessageBox.warning(self, tr('ROI 템플릿 오류'), tr('프로필을 읽을 수 없습니다.\n{value1}', value1=error))
            return

        choice = QMessageBox(self)
        choice.setWindowTitle(tr('ROI 템플릿 적용 방식'))
        choice.setText(
            tr('{value1}개 영상에 {value2}개 ROI를 적용합니다.\n\n카메라와 해상도가 같으면 ‘같은 해상도만’을 권장합니다.', value1=len(selected_paths), value2=len(arenas))
        )
        exact_button = choice.addButton(tr('같은 해상도만 적용'), QMessageBox.AcceptRole)
        scaled_button = choice.addButton(tr('해상도 비율로 보정'), QMessageBox.ActionRole)
        choice.addButton(QMessageBox.Cancel)
        choice.exec()
        clicked = choice.clickedButton()
        if clicked not in (exact_button, scaled_button):
            return
        scale_mode = clicked is scaled_button

        import cv2
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        sources = (project_metadata(payload).get("source_videos", []) or [])
        applied, skipped = [], []
        profile_root.mkdir(parents=True, exist_ok=True)
        for source in sources:
            video_path = Path(str(source.get("path", "")))
            if str(video_path) not in selected_paths:
                continue
            capture = cv2.VideoCapture(str(video_path))
            width = int(capture.get(cv2.CAP_PROP_FRAME_WIDTH))
            height = int(capture.get(cv2.CAP_PROP_FRAME_HEIGHT))
            capture.release()
            if width < 1 or height < 1:
                skipped.append(tr('{value1}: 영상을 읽을 수 없음', value1=video_path.name))
                continue
            if (width, height) == (source_width, source_height):
                target_profile = template_path
                mode = "exact"
            elif not scale_mode:
                skipped.append(tr('{value1}: {value2}×{value3} 해상도 불일치', value1=video_path.name, value2=width, value3=height))
                continue
            else:
                scaled = json.loads(json.dumps(template))
                x_scale, y_scale = width / source_width, height / source_height
                scaled["source_resolution_px"] = [width, height]
                scaled["created_from_video"] = str(video_path)
                scaled["template_source"] = str(template_path)
                for arena in scaled.get("arenas", []):
                    for polygon_key in ("corners_source_px", "mask_polygon_source_px"):
                        if arena.get(polygon_key):
                            arena[polygon_key] = [
                                [float(point[0]) * x_scale, float(point[1]) * y_scale]
                                for point in arena[polygon_key]
                            ]
                    for zone in arena.get("zones", []):
                        zone["polygon_source_px"] = [
                            [float(point[0]) * x_scale, float(point[1]) * y_scale]
                            for point in zone.get("polygon_source_px", [])
                        ]
                target_profile = profile_root / f"{video_path.stem}_scaled_roi_profile.json"
                target_profile.write_text(
                    json.dumps(scaled, ensure_ascii=False, indent=2), encoding="utf-8"
                )
                mode = "scaled"
            source["roi_profile"] = str(target_profile)
            source["roi_template_source"] = str(template_path)
            source["roi_template_mode"] = mode
            source.pop("roi_customized", None)
            applied.append(video_path.name)
        if applied:
            self.write_project_configuration(payload, tr('ROI 템플릿 일괄 적용: {value1}개', value1=len(applied)))
            self.load_source_library()
        message = tr('ROI 템플릿을 {value1}개 영상에 적용했습니다.', value1=len(applied))
        if skipped:
            message += tr('\n\n적용하지 못한 영상:\n') + "\n".join(skipped[:20])
        QMessageBox.information(self, tr('ROI 템플릿 적용 완료'), message)

    def set_batch_advanced_visible(self, visible: bool) -> None:
        self.batch_advanced_frame.setVisible(visible)
        self.batch_advanced_toggle.setToolTip(
            tr('클릭하여 세부 실행 설정 접기') if visible else
            tr('클릭하여 세부 실행 설정 펼치기')
        )
