    def create_zone_template_for_selected_batch(self) -> None:
        if not self.require_config():
            return
        row = self.batch_source_table.currentRow()
        if row < 0:
            checked = [
                index for index in range(self.batch_source_table.rowCount())
                if self.table_checkbox(self.batch_source_table, index, 0)
                and self.table_checkbox(self.batch_source_table, index, 0).isChecked()
            ]
            row = checked[0] if checked else -1
        if row < 0 or not self.batch_source_table.item(row, 1):
            QMessageBox.information(self, tr('영상 선택 필요'), tr('표에서 기준 영상을 한 행 선택하세요.'))
            return
        video = Path(str(self.batch_source_table.item(row, 1).data(Qt.UserRole)))
        if not video.is_file():
            QMessageBox.warning(self, tr('영상 없음'), str(video))
            return
        profile_root = project_state_root(self.config.parent) / "zone_profiles"
        profile = profile_root / f"{video.stem}_zones.json"

        def finished(profile: Path) -> None:
            payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
            sources = (project_metadata(payload).get("source_videos", []) or [])
            source = next((item for item in sources if Path(str(item.get("path", ""))) == video), None)
            if source is not None:
                source["roi_profile"] = str(profile)
                source["roi_customized"] = True
                self.write_project_configuration(payload, tr('자유 다각형 ROI·구역 저장: {value1}', value1=video.name))
                self.load_source_library()
            self.zone_video_edit.setText(str(video))
            self.zone_profile_edit.setText(str(profile))
            self.set_workflow_badge(self.zone_template_badge, tr('템플릿 준비'), True)

        self.start_tracking_roi_editor(video, profile, finished)

    def edit_selected_batch_roi(self) -> None:
        if not self.require_config():
            return
        row = self.batch_source_table.currentRow()
        if row < 0 or not self.batch_source_table.item(row, 1):
            QMessageBox.information(
                self,
                tr('행 선택 필요'),
                tr('ROI를 열 영상의 아무 칸이나 클릭해 행 전체를 파란색으로 선택하세요.'),
            )
            return
        video = Path(str(self.batch_source_table.item(row, 1).data(Qt.UserRole)))
        if not video.is_file():
            QMessageBox.warning(self, tr('영상 없음'), str(video))
            return
        self.open_source_roi_editor({"video": str(video)})

    def source_roi_review_records(self) -> list[dict]:
        if not self.config or not self.config.is_file():
            return []
        try:
            payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        except Exception:
            return []
        records = []
        for source in (project_metadata(payload).get("source_videos", []) or []):
            video = Path(str(source.get("path", "")))
            profile = Path(str(source.get("roi_profile", ""))) if source.get("roi_profile") else Path()
            if not video.is_file():
                continue
            if source.get("roi_customized"):
                status = tr('● 개별 ROI 보정')
            elif source.get("roi_template_source"):
                status = tr('공통 ROI 템플릿 적용')
            else:
                status = tr('ROI 준비') if profile.is_file() else tr('ROI 미설정 · 클릭하여 지정')
            records.append({
                "kind": "source_roi", "video": str(video), "profile": str(profile) if profile.is_file() else "",
                "status": status, "override": bool(source.get("roi_customized")),
            })
        return records

    def open_source_roi_overview(self) -> None:
        if not self.require_config():
            return
        records = self.source_roi_review_records()
        if not records:
            QMessageBox.information(self, tr('검수 영상 없음'), tr('프로젝트에 등록된 원본 영상이 없습니다.'))
            return
        dialog = RoiOverviewDialog(
            records,
            tr('원본 전체 영상 ROI 검수'),
            tr('SuperAnimal 모델 확인과 일괄 트래킹에 사용할 ROI를 모든 원본 영상 위에 표시합니다. 어긋난 카드를 클릭하면 공통 템플릿을 건드리지 않고 해당 영상 ROI만 수정합니다.'),
            self,
            records_provider=self.source_roi_review_records,
            group_apply=True,
            group_apply_label=tr('체크 영상에 ROI 설정 적용'),
            group_apply_tooltip=(
                tr('‘이 설정을 기준으로’를 누른 영상의 ROI를 ‘적용 대상’으로 체크한 영상들에 복사합니다. 카메라 위치가 같은 영상끼리만 사용하세요. 해상도가 다르면 적용 전에 같은 해상도만 사용할지 비율로 보정할지 선택할 수 있습니다.')
            ),
        )
        dialog.edit_requested.connect(self.open_source_roi_editor)
        dialog.apply_group_requested.connect(self.apply_source_roi_group)
        dialog.exec()
        self.load_source_library()
        if hasattr(self, "batch_source_table"):
            self.load_batch_source_table()

    def apply_source_roi_group(self, source_record: dict, target_records: list[dict]) -> None:
        profile = Path(str(source_record.get("profile", "")))
        target_paths = {
            str(Path(str(record.get("video", ""))))
            for record in target_records
            if Path(str(record.get("video", ""))).is_file()
        }
        if not profile.is_file():
            QMessageBox.information(
                self, tr('ROI 묶음 적용'), tr('기준 영상에 저장된 ROI 설정이 없습니다.'),
            )
            return
        if not target_paths:
            QMessageBox.information(
                self, tr('ROI 묶음 적용'), tr('ROI를 적용할 대상 영상을 체크하세요.'),
            )
            return
        self.apply_roi_template_path_to_batch_selection(profile, target_paths)

    def open_source_roi_editor(self, record: dict) -> None:
        if not self.validate_project_source_names():
            return
        video = Path(str(record.get("video", "")))
        if not video.is_file() or not self.config:
            return
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        sources = (project_metadata(payload).get("source_videos", []) or [])
        source = next((item for item in sources if Path(str(item.get("path", ""))) == video), None)
        if source is None:
            return
        current_profile = Path(str(source.get("roi_profile", ""))) if source.get("roi_profile") else Path()
        root = project_state_root(self.config.parent) / "zone_profiles"
        target = root / f"{video.stem}_zones.json"

        def saved(target: Path) -> None:
            latest = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
            sources = project_metadata(latest).get("source_videos", []) or []
            source = next((item for item in sources if Path(str(item.get("path", ""))) == video), None)
            if source is None:
                return
            source["roi_profile"] = str(target)
            source["roi_customized"] = True
            source.pop("roi_template_source", None)
            source.pop("roi_template_mode", None)
            self.write_project_configuration(latest, tr('개별 ROI 저장: {value1}', value1=video.name))
            record.update({"profile": str(target), "override": True, "status": tr('● 개별 ROI 보정')})
            self.load_source_library()

        self.start_tracking_roi_editor(video, target, saved, current_profile)

    def nort_spatial_review_records(self) -> list[dict]:
        raw = self.spatial_root_edit.text().strip() if hasattr(self, "spatial_root_edit") else ""
        root = Path(raw) if raw else self.default_spatial_bundle()
        if not root or not root.is_dir():
            return []
        subjects = [root] if any(root.glob("arena_*")) else sorted(
            [path for path in root.iterdir() if path.is_dir() and any(path.glob("arena_*"))],
            key=lambda path: path.name.lower(),
        )
        project_root = self.config.parent if self.config else self.work_root
        hidden_sources = self.project_hidden_source_keys()
        records = []
        for subject in subjects:
            metadata_items = []
            for metadata_path in sorted(subject.glob("arena_*/roi-metadata.json")):
                try:
                    metadata_items.append((metadata_path.parent, json.loads(metadata_path.read_text(encoding="utf-8"))))
                except Exception:
                    pass
            video = next((Path(str(meta.get("source_video", ""))) for _arena, meta in metadata_items if Path(str(meta.get("source_video", ""))).is_file()), None)
            if video is None:
                continue
            if self.normalized_source_key(video) in hidden_sources:
                continue
            profile = next((Path(str(meta.get("roi_profile", ""))) for _arena, meta in metadata_items if Path(str(meta.get("roi_profile", ""))).is_file()), Path())
            overlays = []
            completed = 0
            for arena_dir, metadata in metadata_items:
                arena_id = int(self.spatial_arena_id(arena_dir) or 0)
                setup = project_state_root(project_root) / "spatial" / subject.name / f"arena_{arena_id:02d}_nort_setup.json"
                if setup.is_file():
                    completed += 1
                    overlays.append({"setup": str(setup), "offset": metadata.get("source_offset_px") or [0, 0]})
            records.append({
                "kind": "nort_spatial", "bundle": str(subject), "video": str(video),
                "profile": str(profile) if profile.is_file() else "", "spatial_overlays": overlays,
                "status": tr('공간 설정 {value1}/{value2} · 클릭하여 전체 Arena 편집', value1=completed, value2=len(metadata_items)),
            })
        return records

    def open_nort_spatial_overview(self) -> None:
        records = self.nort_spatial_review_records()
        if not records:
            QMessageBox.information(self, tr('검수 영상 없음'), tr('NORT 트래킹 영상 묶음을 찾지 못했습니다.'))
            return
        dialog = RoiOverviewDialog(
            records,
            tr('NORT 공간 설정 전체 검수'),
            tr('모든 원본 영상에 Arena와 Object A/B를 겹쳐 표시합니다. 카드를 클릭하면 개별 편집하며, 카메라 위치가 같은 영상끼리는 한 카드를 기준으로 선택해 체크 영상에 묶어서 적용할 수 있습니다.'),
            self,
            records_provider=self.nort_spatial_review_records,
            group_apply=True,
        )
        dialog.edit_requested.connect(self.open_nort_spatial_record)
        dialog.apply_group_requested.connect(self.apply_nort_spatial_group)
        dialog.exec()
        self.refresh_spatial_bundle()

    def apply_nort_spatial_group(self, source_record: dict, target_records: list) -> None:
        source = Path(str(source_record.get("bundle", "")))
        targets = {
            str(Path(str(record.get("bundle", ""))))
            for record in target_records
            if Path(str(record.get("bundle", ""))).is_dir()
        }
        if not source.is_dir() or not targets:
            return
        source_arena_ids = {
            int(arena_id)
            for arena_id in (self.spatial_arena_id(path) for path in source.glob("arena_*"))
            if arena_id is not None
        }
        if not source_arena_ids:
            QMessageBox.information(self, tr('그룹 적용'), tr('기준 영상에서 Arena 설정을 찾지 못했습니다.'))
            return
        previous_subject = self.spatial_selected_subject
        previous_subject_checks = set(self.spatial_checked_subjects)
        previous_arena_checks = set(self.spatial_checked_arenas)
        try:
            self.spatial_selected_subject = source
            self.spatial_checked_subjects = targets | {str(source)}
            self.spatial_checked_arenas = source_arena_ids
            self.apply_selected_spatial_template_to_all(set_common=False)
        finally:
            self.spatial_selected_subject = previous_subject
            self.spatial_checked_subjects = previous_subject_checks
            self.spatial_checked_arenas = previous_arena_checks
            self.refresh_spatial_bundle()

    def open_nort_spatial_record(self, record: dict) -> None:
        subject = Path(str(record.get("bundle", "")))
        if not subject.is_dir():
            return
        self.spatial_selected_subject = subject
        for row in range(self.spatial_experiment_table.rowCount()):
            item = self.spatial_experiment_table.item(row, 1)
            if item and str(item.data(Qt.UserRole) or "") == str(subject):
                self.spatial_experiment_table.selectRow(row)
                break
        self.refresh_spatial_bundle()
        target = next((row for row in self.spatial_rows if row["status"] != "ready"), None) or (self.spatial_rows[0] if self.spatial_rows else None)
        if target:
            self.launch_spatial_arena(target)

    def remove_source_video(self) -> None:
        if not self.require_config():
            return
        selected_rows = [
            row for row in range(self.source_video_table.rowCount())
            if self.source_management_checked(row)
        ]
        if not selected_rows:
            QMessageBox.information(
                self,
                tr('목록에서 제외'),
                tr('왼쪽 ‘선택’에서 제외할 영상을 체크하세요.'),
            )
            return
        paths = {
            str(self.source_video_table.item(row, 1).data(Qt.UserRole))
            for row in selected_rows
        }
        self.remove_project_source_paths(paths)

    @staticmethod
    def normalized_source_key(path: str | Path) -> str:
        return os.path.normcase(os.path.normpath(str(path)))

    def project_hidden_source_keys(self, payload: dict | None = None) -> set[str]:
        if payload is None:
            if not self.config or not self.config.is_file():
                return set()
            try:
                payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
            except Exception:
                return set()
        project_meta = project_metadata(payload)
        return {
            self.normalized_source_key(path)
            for path in (project_meta.get("hidden_source_videos", []) or [])
            if str(path).strip()
        }

    def remove_project_source_paths(self, paths: set[str]) -> bool:
        if not self.require_config():
            return False
        clean_paths = {str(path) for path in paths if str(path).strip()}
        if not clean_paths:
            QMessageBox.information(self, tr('목록에서 제외'), tr('제외할 원본 영상 행을 먼저 선택하세요.'))
            return False
        names = "\n".join(f"• {Path(path).name}" for path in sorted(clean_paths))
        answer = QMessageBox.question(
            self,
            tr('원본 영상 목록에서 제외'),
            tr('선택한 {value1}개 영상을 프로젝트 목록에서 제외할까요?\n\n{value2}\n\n실제 영상 파일과 기존 ROI·트래킹·분석 결과는 삭제하지 않습니다.', value1=len(clean_paths), value2=names),
            QMessageBox.Yes | QMessageBox.No, QMessageBox.No,
        )
        if answer != QMessageBox.Yes:
            return False
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        project_meta = project_metadata(payload, create=True)
        remove_keys = {self.normalized_source_key(path) for path in clean_paths}
        project_meta["source_videos"] = [
            item for item in (project_meta.get("source_videos", []) or [])
            if self.normalized_source_key(str(item.get("path", ""))) not in remove_keys
        ]
        hidden = self.project_hidden_source_keys(payload)
        hidden.update(remove_keys)
        project_meta["hidden_source_videos"] = sorted(hidden)
        if self.normalized_source_key(str(project_meta.get("test_video", ""))) in remove_keys:
            project_meta["test_video"] = ""
            self.quick_video.clear()
        self.write_project_configuration(payload, tr('원본 영상 목록에서 {value1}개 제외', value1=len(clean_paths)))
        self.load_source_library()
        self.refresh_project()
        return True

