    def open_dashboard_video_stage(self, row: int, _column: int) -> None:
        item = self.dashboard_video_table.item(row, self.dashboard_video_table.columnCount() - 1)
        if not item: return
        key = str(item.data(Qt.UserRole + 1) or "quick")
        self.show_module(self.module_index(key))

    def auto_load_existing_qc(self) -> None:
        if not self.config or not hasattr(self, "quick_output"):
            return
        self.refresh_quick_review_state()

    def append_log(self, text: str) -> None:
        self.log.appendPlainText(text.rstrip())

