    def update_video_review_selection(self) -> None:
        if not hasattr(self, "review_selection"):
            return
        payload = self.review_selected_payload()
        controlled_buttons = (
            self.review_open_editor_button,
            self.review_open_folder_button,
            self.review_import_button,
            self.review_go_train_button,
        )
        selected_payloads = self.review_selected_payloads()
        if len(selected_payloads) > 1:
            edited_total = sum(int(item.get("edited", 0) or 0) for item in selected_payloads)
            imported_total = sum(int(item.get("imported", 0) or 0) for item in selected_payloads)
            pending_total = sum(
                max(0, int(item.get("edited", 0) or 0) - int(item.get("imported", 0) or 0))
                for item in selected_payloads
            )
            self.review_selection.setText(tr('{value1}개 교정 결과 선택', value1=len(selected_payloads)))
            self.review_import_summary.setText(
                tr('우클릭에서 선택한 결과를 함께 삭제할 수 있습니다. 교정·반영·추가학습은 한 행씩 실행합니다.')
            )
            self.review_metric_edited.setText(f"{edited_total:,}")
            self.review_metric_imported.setText(f"{imported_total:,}")
            self.review_metric_pending.setText(f"{pending_total:,}")
            self.review_import_button.setText(tr('새 수정 프레임 반영'))
            for button in controlled_buttons:
                button.setEnabled(False)
            return
        if not payload:
            self.review_selection.setText(tr('교정 결과를 선택하세요'))
            self.review_import_summary.setText(
                tr('모델 평가 또는 영상 트래킹에서 수정 내용을 저장한 결과가 자동으로 표시됩니다.')
            )
            self.review_metric_edited.setText("0")
            self.review_metric_imported.setText("0")
            self.review_metric_pending.setText("0")
            self.review_import_button.setText(tr('새 수정 프레임 반영'))
            for button in controlled_buttons:
                button.setEnabled(False)
            return
        self.review_selection.setText(
            payload["video"].name
        )
        edited, imported = int(payload["edited"]), int(payload["imported"])
        pending = max(0, edited - imported)
        self.review_import_summary.setText(
            tr('추론 결과 · {value1}', value1=payload['pose'].name)
        )
        self.review_metric_edited.setText(f"{edited:,}")
        self.review_metric_imported.setText(f"{imported:,}")
        self.review_metric_pending.setText(f"{pending:,}")
        self.review_open_editor_button.setEnabled(True)
        self.review_open_folder_button.setEnabled(True)
        importing = getattr(self, "_video_review_import_running", False)
        self.review_import_button.setEnabled(
            pending > 0 and not importing and not getattr(self, "_video_review_refresh_failed", False)
        )
        self.review_import_button.setText(
            tr('수정 프레임 반영 중…') if importing
            else (tr('새 수정 {value1}프레임 반영', value1=pending) if pending else tr('새 수정 프레임 반영'))
        )
        self.review_go_train_button.setEnabled(imported >= edited > 0)

