    def delete_selected_video_review_results(self) -> None:
        if not self.require_config():
            return
        payloads = self.review_selected_payloads()
        if not payloads:
            QMessageBox.information(self, tr('선택 행 없음'), tr('삭제할 교정 결과 행을 선택하세요.'))
            return
        names = "\n".join(f"• {Path(payload['video']).name}" for payload in payloads)
        imported_frames = sum(int(payload.get("imported", 0) or 0) for payload in payloads)
        imported_note = (
            tr('\n이미 학습 데이터에 반영된 {value1}프레임은 유지됩니다.', value1=imported_frames)
            if imported_frames else ""
        )
        answer = QMessageBox.question(
            self,
            tr('교정 결과 삭제'),
            tr('선택한 {value1}개 교정 결과를 삭제할까요?\n\n{value2}\n\n추론 좌표와 해당 교정 세션·반영 기록은 프로젝트 휴지통으로 이동합니다. 원본 영상은 삭제하지 않습니다.{value3}', value1=len(payloads), value2=names, value3=imported_note),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if answer != QMessageBox.Yes:
            return

        trash_root = (
            self.config.parent
            / ".hagisilta-trash"
            / "video-review-results"
            / time.strftime("%Y%m%d-%H%M%S")
        )
        manifest_root = project_state_root(self.config.parent) / "video-review-imports"
        moved = 0
        failures: list[str] = []

        def move_to_bucket(source: Path, bucket: Path) -> None:
            nonlocal moved
            if not source.exists():
                return
            bucket.mkdir(parents=True, exist_ok=True)
            destination = bucket / source.name
            suffix = 2
            while destination.exists():
                destination = bucket / f"{source.stem}-{suffix}{source.suffix}"
                suffix += 1
            try:
                shutil.move(str(source), str(destination))
                moved += 1
            except OSError as error:
                failures.append(f"{source}: {error}")

        for index, payload in enumerate(payloads, start=1):
            video = Path(payload["video"])
            pose = Path(payload["pose"])
            session = Path(payload["session"])
            bucket = trash_root / f"{index:02d}-{video.stem}"

            pose_files = sorted({
                path for path in pose.parent.glob(f"{pose.stem}*") if path.is_file()
            }) if pose.parent.is_dir() else []
            for path in pose_files or ([pose] if pose.exists() else []):
                move_to_bucket(path, bucket / "inference")

            preferred_session_root = self.video_review_output(video, pose)
            if preferred_session_root.exists():
                move_to_bucket(preferred_session_root, bucket / "correction")
            elif session.is_file():
                move_to_bucket(session, bucket / "correction")

            if manifest_root.is_dir():
                for manifest_path in manifest_root.glob("*.json"):
                    try:
                        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
                        same_session = Path(str(manifest.get("session", ""))).resolve() == session.resolve()
                        same_pose = Path(str(manifest.get("source_pose", ""))).resolve() == pose.resolve()
                    except (OSError, ValueError, json.JSONDecodeError):
                        continue
                    if same_session or same_pose:
                        move_to_bucket(manifest_path, bucket / "import-records")

        self.append_log(
            tr('교정 결과 {value1}개 삭제: 생성 항목 {value2}개를 프로젝트 휴지통으로 이동\n복구 위치: {value3}', value1=len(payloads), value2=moved, value3=trash_root)
        )
        self.refresh_video_review_table()
        if failures:
            QMessageBox.warning(
                self,
                tr('일부 교정 결과 삭제 실패'),
                tr('{value1}개 항목을 이동했지만 {value2}개는 처리하지 못했습니다.\n\n', value1=moved, value2=len(failures))
                + "\n".join(failures[:5]),
            )
        else:
            QMessageBox.information(
                self,
                tr('교정 결과 삭제 완료'),
                tr('선택한 {value1}개 결과를 프로젝트 휴지통으로 이동했습니다.\n\n{value2}', value1=len(payloads), value2=trash_root),
            )

    def import_selected_video_review(self) -> None:
        if getattr(self, "_video_review_import_running", False):
            return
        if self.process and self.process.state() != QProcess.NotRunning:
            QMessageBox.information(self, tr('작업 실행 중'), tr('현재 작업이 끝나거나 중지된 뒤 실행하세요.'))
            return
        if not self.require_config():
            return
        # Refresh the persisted import counts before deciding what is pending.
        if not self.refresh_video_review_table():
            QMessageBox.warning(self, tr('교정 결과 읽기 실패'), tr('교정 결과를 읽지 못했습니다. 실행 로그를 확인하세요.'))
            return
        payload = self.review_selected_payload()
        if not payload:
            QMessageBox.information(self, tr('추론 결과 선택'), tr('표에서 결과를 먼저 선택하세요.'))
            return
        session = Path(payload["session"])
        if not session.is_file():
            QMessageBox.information(
                self, tr('교정 세션 없음'), tr('먼저 영상 교정기를 열어 점을 수정한 뒤 Ctrl+S로 저장하세요.')
            )
            return
        if int(payload["imported"]) >= int(payload["edited"]) > 0:
            QMessageBox.information(
                self, tr('이미 반영됨'),
                tr('현재 수정 {value1}프레임이 프로젝트 학습 데이터에 이미 반영되어 있습니다.', value1=payload['edited']),
            )
            return

        def imported(exit_code: int) -> None:
            self._video_review_import_running = False
            refreshed = self.refresh_video_review_table()
            if exit_code == 0 and refreshed:
                QMessageBox.information(
                    self, tr('학습 데이터 반영 완료'),
                    tr('{value1}\n수정 {value2}프레임 반영 완료\n모델 학습에서 새 Shuffle을 만들 수 있습니다.', value1=payload['video'].name, value2=payload['edited']),
                )
            elif exit_code == 0:
                QMessageBox.warning(
                    self, tr('학습 반영 후 목록 확인 필요'),
                    tr('학습 데이터 반영은 끝났지만 목록을 다시 읽지 못했습니다. 실행 로그를 확인하세요.'),
                )

        self._video_review_import_running = True
        self.update_video_review_selection()
        try:
            self.start_process(
                SCRIPTS / "hagisilta_import_video_review.py",
                [str(self.config), str(session)],
                imported,
            )
        except Exception:
            self._video_review_import_running = False
            self.update_video_review_selection()
            raise

        def import_start_failed(error) -> None:
            if error == QProcess.FailedToStart:
                self._video_review_import_running = False
                self.update_video_review_selection()
                self.append_log(tr('교정 라벨 반영 프로세스 시작 실패: {value1}', value1=self.process.errorString()))

        self.process.errorOccurred.connect(import_start_failed)

    def run_qc_directory(
        self, directory: Path, pcutoff: float | None = None, update_quick: bool = True
    ) -> dict | None:
        csvs = self.pose_files(directory) if directory.exists() else []
        if not csvs:
            QMessageBox.information(self, tr('QC 파일 없음'), tr('출력 폴더에서 DLC 좌표 CSV/H5를 찾지 못했습니다.'))
            return None
        return self.run_qc(csvs[0], pcutoff, update_quick)

    def run_qc(
        self, csv_path: Path, pcutoff: float | None = None, update_quick: bool = True
    ) -> dict | None:
        try:
            threshold = float(self.infer_pcutoff.value()) if pcutoff is None else float(pcutoff)
            report = analyze_pose_csv(csv_path, threshold, 50)
            output = csv_path.parent / "qc"
            json_path, hard_path = write_report(report, output)
            summary = report.get("coverage_summary", {})
            self.append_log(
                tr('QC 계산 완료: 신체점 중앙 유효률 {value1:.1f}%\n보고서: {value2}\n어려운 프레임: {value3}', value1=float(summary.get('median_coverage', 0)) * 100, value2=json_path, value3=hard_path)
            )
            self.display_qc(report, update_quick=update_quick)
            return report
        except Exception as error:
            QMessageBox.critical(self, tr('QC 오류'), str(error))
            return None

    def set_quick_recommendation_buttons(self, grade: str | None) -> None:
        """Compatibility wrapper for older QC callers; QC never decides suitability."""
        if not hasattr(self, "quick_review_button"):
            return
        self.quick_review_button.setEnabled(bool(self.quick_review_payloads()))

    def display_qc(self, report: dict, update_quick: bool = True) -> None:
        self.dashboard_qc_grade = None
        self.dashboard_qc_ready = True
        self.dashboard_qc_label = tr('QC 계산 완료')
        if update_quick and hasattr(self, "result_stage_badge"):
            self.set_workflow_badge(self.result_stage_badge, tr('영상 확인 가능'), True)
            self.set_workflow_expanded(self.result_stage_card, True)
            self.set_quick_recommendation_buttons(None)

    def run_project_batch_track(self) -> None:
        if not self.require_config():
            return
        if not self.validate_project_source_names():
            return
        model_mode = str(self.track_model_source.currentData() or "trained")
        external_model = self.project_external_tracking_model()
        final_shuffle = self.project_final_model_shuffle()
        if model_mode == "superanimal":
            inference_config = self.config
            inference_shuffle = 1
            snapshot_index = ""
        elif external_model:
            inference_config = Path(external_model["config"])
            inference_shuffle = int(external_model["shuffle"])
            snapshot_index = str(external_model["snapshot_index"])
        else:
            inference_config = self.config
            inference_shuffle = final_shuffle
            snapshot_index = ""
        if model_mode == "trained" and inference_shuffle is None:
            QMessageBox.information(
                self,
                tr('최종 모델 필요'),
                tr('모델 평가에서 사용할 모델을 최종 지정하거나 외부 모델을 불러온 뒤 실행하세요.'),
            )
            return
        inference_overrides_text = self.track_expert_overrides.toPlainText().strip()
        inference_overrides: dict = {}
        if inference_overrides_text:
            try:
                parsed_overrides = json.loads(inference_overrides_text)
                if not isinstance(parsed_overrides, dict):
                    raise ValueError(tr('JSON 객체여야 합니다.'))
                inference_overrides = parsed_overrides
            except (json.JSONDecodeError, ValueError) as error:
                QMessageBox.warning(self, tr('PyTorch 추론 설정 JSON 오류'), str(error))
                return
        if model_mode == "trained" and self.track_show_gpu_memory.isChecked():
            inference_overrides["show_gpu_memory"] = True
        if model_mode == "trained":
            inference_cfg = inference_overrides.get("inference_cfg", {})
            if not isinstance(inference_cfg, dict):
                QMessageBox.warning(
                    self, tr('PyTorch 추론 설정 JSON 오류'),
                    tr('inference_cfg는 JSON 객체여야 합니다.'),
                )
                return
            multithreading_cfg = inference_cfg.get("multithreading", {})
            if not isinstance(multithreading_cfg, dict):
                QMessageBox.warning(
                    self, tr('PyTorch 추론 설정 JSON 오류'),
                    tr('inference_cfg.multithreading은 JSON 객체여야 합니다.'),
                )
                return
            multithreading_cfg.update({
                "enabled": self.track_prefetch.isChecked(),
                "queue_length": self.track_prefetch_queue.value(),
            })
            inference_cfg["multithreading"] = multithreading_cfg
            autocast_cfg = inference_cfg.get("autocast", {})
            if not isinstance(autocast_cfg, dict):
                QMessageBox.warning(
                    self, tr('PyTorch 추론 설정 JSON 오류'),
                    tr('inference_cfg.autocast는 JSON 객체여야 합니다.'),
                )
                return
            autocast_cfg["enabled"] = self.track_amp.isChecked()
            inference_cfg["autocast"] = autocast_cfg
            inference_overrides["inference_cfg"] = inference_cfg
        trained_keys = {
            "detector_snapshot_index", "detector_batch_size", "dynamic",
            "ctd_conditions", "ctd_tracking", "top_down_dynamic", "use_shelve",
            "robust_nframes", "auto_track", "n_tracks", "animal_names",
            "calibrate", "identity_only", "cropping", "save_as_df",
            "show_gpu_memory", "inference_cfg",
        }
        superanimal_keys = {
            "scale_list", "cropping", "video_adapt", "plot_trajectories",
            "detector_batch_size", "adapt_iterations", "pseudo_threshold",
            "bbox_threshold", "detector_epochs", "pose_epochs", "max_individuals",
            "video_adapt_batch_size", "customized_pose_checkpoint",
            "customized_detector_checkpoint", "customized_model_config",
            "plot_bboxes", "fmpose_return_3d",
        }
        supported_keys = superanimal_keys if model_mode == "superanimal" else trained_keys
        unsupported_keys = sorted(set(inference_overrides) - supported_keys)
        if unsupported_keys:
            QMessageBox.warning(
                self,
                tr('PyTorch 추론 설정 키 확인'),
                tr('현재 {value1} 모델 추론에서 지원하지 않거나 화면에서 별도로 관리하는 키입니다.\n\n', value1=tr('DLC 사전학습') if model_mode == 'superanimal' else tr('학습'))
                + "\n".join(unsupported_keys),
            )
            return
        self.track_shuffle.setValue(int(inference_shuffle or 1))
        self.save_project_ui_state()
        self.save_batch_source_selection()
        self.save_source_library()
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        sources = [
            item for item in (project_metadata(payload).get("source_videos", []) or [])
            if item.get("enabled", True)
        ]
        if not sources:
            QMessageBox.information(self, tr('트래킹 대상 없음'), tr('영상 트래킹의 대상 표에서 영상을 체크하세요.'))
            return
        missing = []
        plan = []
        for item in sources:
            path = Path(str(item.get("path", "")))
            profile = Path(str(item.get("roi_profile", "")))
            if not path.is_file() or not profile.is_file():
                missing.append(f"{path.name}: {tr('영상 없음') if not path.is_file() else tr('ROI 미설정')}")
                continue
            try:
                roi_payload = json.loads(profile.read_text(encoding="utf-8"))
                arenas = [int(arena.get("id", index + 1)) for index, arena in enumerate(roi_payload.get("arenas", []))]
            except Exception as error:
                missing.append(tr('{value1}: ROI 오류 {value2}', value1=path.name, value2=error))
                continue
            if not arenas:
                missing.append(tr('{value1}: ROI 박스 없음', value1=path.name))
                continue
            plan.append({
                "path": str(path), "roi_profile": str(profile), "arenas": arenas,
                "group": item.get("group", ""), "subject_id": item.get("subject_id", path.stem),
            })
        if missing:
            QMessageBox.warning(
                self, tr('일괄 트래킹 준비 필요'),
                tr('아래 영상은 처리할 수 없습니다. SuperAnimal 모델 확인 또는 이 화면의 ROI 편집에서 각 영상의 ROI를 지정하세요.\n\n') + "\n".join(missing[:20]),
            )
            return
        runtime_dir = project_state_root(self.config.parent) / "runtime"
        runtime_dir.mkdir(parents=True, exist_ok=True)
        plan_path = runtime_dir / "batch-track-plan.json"
        plan_path.write_text(json.dumps({"videos": plan}, ensure_ascii=False, indent=2), encoding="utf-8")
        arguments = [
            str(inference_config), str(plan_path), self.track_output.text(),
            "--model-mode", model_mode,
            "--pose-model", str(self.quick_pose_model.currentData()),
            "--detector", str(self.detector_combo.currentData()),
            "--shuffle", str(inference_shuffle), "--batch-size", str(self.track_batch_size.value()),
            "--pcutoff", str(self.track_pcutoff.value()),
            "--execution-mode", str(self.track_execution_mode.currentData()),
            "--roi-workers", str(self.track_roi_workers.value()),
            "--roi-validation", str(self.track_roi_validation.currentData() or "fast"),
            "--pipeline-chunk-size", str(self.track_pipeline_chunk.value()),
            "--device", str(self.track_device.currentData()),
            "--dotsize", str(self.track_dot_size.value()),
            "--inference-overrides-json", json.dumps(inference_overrides, ensure_ascii=False),
            "--temporal-refiner",
            "off",
        ]
        if snapshot_index:
            arguments += ["--snapshot-index", snapshot_index]
        if self.batch_labeled_video.isChecked():
            arguments.append("--labeled-video")
        if self.batch_skip_completed.isChecked() and model_mode == "trained" and not external_model:
            arguments.append("--skip-completed")
        if not self.batch_save_csv.isChecked():
            arguments.append("--no-csv")
        if not self.batch_keep_roi_video.isChecked():
            arguments.append("--delete-roi-video")
        def finished(exit_code: int) -> None:
            self.load_batch_source_table()
            self.refresh_video_review_table()
            if hasattr(self, "track_result_summary"):
                if exit_code == 0:
                    self.track_result_summary.value_label.setText(
                        tr('트래킹이 완료되었습니다. 저장 결과를 집계하고 QC 상태를 확인합니다.')
                    )
                    self.set_workflow_badge(self.track_result_badge, tr('트래킹 완료'), True)
                    self.batch_qc_button.setEnabled(True)
                    self.set_workflow_expanded(self.track_result_card, True)
                else:
                    self.track_result_summary.value_label.setText(
                        tr('트래킹 작업이 오류로 종료되었습니다 · 종료 코드 {value1}', value1=exit_code)
                    )
                    self.set_workflow_badge(self.track_result_badge, tr('실행 오류'), False)
            if exit_code == 0 and self.batch_auto_qc.isChecked():
                self.run_project_batch_qc()
        if hasattr(self, "track_result_summary"):
            self.track_result_summary.value_label.setText(tr('선택한 영상의 ROI 트래킹을 실행하고 있습니다.'))
            self.set_workflow_badge(self.track_result_badge, tr('실행 중'), False)
        self.start_process(SCRIPTS / "hagisilta_tracking_batch.py", arguments, finished)

    def run_project_batch_qc(self) -> None:
        output = Path(self.track_output.text())
        pose_files = self.roi_pose_files(output) if output.exists() else []
        if not pose_files:
            QMessageBox.information(self, tr('일괄 결과 없음'), tr('먼저 등록 원본 전체 ROI 트래킹을 실행하세요.'))
            return
        results = []
        for pose_file in pose_files:
            try:
                report = analyze_pose_csv(pose_file, float(self.track_pcutoff.value()), 50)
                write_report(report, pose_file.parent / "qc")
                results.append((pose_file.parent, report))
            except Exception as error:
                self.append_log(tr('일괄 QC 실패: {value1}\n{value2}', value1=pose_file, value2=error))
        coverage_rows = [
            (str(bodypart), float(values.get("coverage_at_cutoff", 0)))
            for _path, report in results
            for bodypart, values in report.get("metrics", {}).items()
        ]
        coverage_values = [value for _bodypart, value in coverage_rows]
        median = float(np.median(coverage_values)) * 100 if coverage_values else 0.0
        lowest_bodypart, lowest_value = min(coverage_rows, key=lambda row: row[1]) if coverage_rows else ("-", 0.0)
        self.append_log(
            tr('일괄 QC 완료: ROI {value1}개 · 신체점 중앙 유효률 {value2:.1f}% · 최저 {value3} {value4:.1f}%', value1=len(results), value2=median, value3=lowest_bodypart, value4=lowest_value * 100)
        )
        if hasattr(self, "track_result_summary"):
            self.track_result_summary.value_label.setText(
                tr('ROI {value1}개 · 신체점 중앙 유효률 {value2:.1f}% · 최저 {value3} {value4:.1f}%', value1=len(results), value2=median, value3=lowest_bodypart, value4=lowest_value * 100)
            )
            self.set_workflow_badge(
                self.track_result_badge, tr('QC 계산 완료'), bool(results),
            )
            self.batch_qc_button.setEnabled(bool(results))
        QMessageBox.information(
            self, tr('일괄 QC 완료'),
            tr('ROI 결과 {value1}개\n신체점 중앙 유효률 {value2:.1f}%\n최저 {value3} {value4:.1f}%', value1=len(results), value2=median, value3=lowest_bodypart, value4=lowest_value * 100),
        )

    def run_worker(
        self, action: str, video: str | None = None, output: str | None = None,
        shuffle: int = 2, callback=None, pcutoff: float | None = None,
    ) -> None:
        if not self.require_config():
            return
        args = [action, str(self.config)]
        if video:
            args += ["--video", video]
        if output:
            args += ["--output", output]
        args += ["--shuffle", str(shuffle), "--batch-size", str(self.batch.value())]
        if pcutoff is not None:
            args += ["--pcutoff", str(pcutoff)]
        self.start_process(SCRIPTS / "hagisilta_dlc_worker.py", args, callback)

    def extract_frames(self) -> None:
        if not self.require_config():
            return
        payload = yaml.safe_load(self.config.read_text(encoding="utf-8")) or {}
        configured_bodyparts = list(map(str, payload.get("bodyparts", [])))
        if parse_dataset_bodyparts_text(self.dataset_bodyparts.text()) != configured_bodyparts:
            QMessageBox.information(self, tr('구성 저장 필요'), tr('변경한 신체점을 먼저 ‘구성 저장’으로 반영하세요.'))
            return
        metadata_root = dataset_metadata(payload, create=True).setdefault("videos", {})

        # ROI 편집에서는 좌표 설정만 저장한다. 실제 ROI 영상 생성은 사용자가
        # 명시적으로 대표 프레임 추출을 시작한 이 시점에 한 번만 수행한다.
        after_roi_materialization = bool(
            getattr(self, "_dataset_extract_after_roi_materialization", False)
        )
        self._dataset_extract_after_roi_materialization = False
        pending_roi_imports: list[tuple[Path, Path]] = []
        if not after_roi_materialization:
            for row in range(self.dataset_video_table.rowCount()):
                enabled = self.table_checkbox(self.dataset_video_table, row, 0)
                path_item = self.dataset_video_table.item(row, 1)
                if not enabled or not enabled.isChecked() or not path_item:
                    continue
                path = str(path_item.data(Qt.UserRole))
                roi_children = list(path_item.data(Qt.UserRole + 1) or [])
                metadata = metadata_root.setdefault(path, {})
                profile = Path(str(metadata.get("roi_profile", "") or ""))
                if not roi_children and Path(path).is_file() and profile.is_file():
                    metadata["dataset_group_enabled"] = True
                    pending_roi_imports.append((Path(path), profile))
            if pending_roi_imports:
                self.write_project_configuration(
                    payload, tr('대표 프레임 추출 전 ROI 영상 준비 · {value1}개', value1=len(pending_roi_imports))
                )
                queue = list(pending_roi_imports)
                failures: list[str] = []

                def import_next_roi() -> None:
                    if not queue:
                        if failures:
                            QMessageBox.warning(
                                self,
                                tr('ROI 영상 준비 실패'),
                                tr('다음 영상의 ROI 분할에 실패해 프레임 추출을 중단했습니다.\n\n')
                                + "\n".join(failures[:20]),
                            )
                            return
                        self._dataset_extract_after_roi_materialization = True
                        QTimer.singleShot(0, self.extract_frames)
                        return
                    source_video, roi_profile = queue.pop(0)

                    def one_imported(exit_code: int, current=source_video) -> None:
                        if exit_code != 0:
                            failures.append(current.name)
                        import_next_roi()

                    self.import_dataset_roi_profile(
                        source_video,
                        roi_profile,
                        show_message=False,
                        finished_callback=one_imported,
                    )

                self.append_log(
                    tr('대표 프레임 추출 준비: ROI 영상 {value1}개 분할 시작', value1=len(pending_roi_imports))
                )
                import_next_roi()
                return
        videos = []
        planned_paths: set[str] = set()
        for row in range(self.dataset_video_table.rowCount()):
            enabled = self.table_checkbox(self.dataset_video_table, row, 0)
            path_item = self.dataset_video_table.item(row, 1)
            count = self.dataset_video_table.cellWidget(row, 6)
            if not enabled or not enabled.isChecked() or not path_item or not isinstance(count, QSpinBox):
                continue
            path = str(path_item.data(Qt.UserRole))
            frames = int(count.value())
            roi_children = list(path_item.data(Qt.UserRole + 1) or [])
            targets = roi_children or [path]
            if roi_children:
                source_metadata = metadata_root.setdefault(path, {})
                source_metadata["extract_enabled"] = False
                source_metadata["dataset_group_enabled"] = True
            for target in targets:
                target = str(target)
                if target in planned_paths:
                    continue
                planned_paths.add(target)
                videos.append({"path": target, "frames": frames})
                metadata = metadata_root.setdefault(target, {})
                metadata["frames_to_pick"] = frames
                metadata["extract_enabled"] = True
        if not videos:
            QMessageBox.information(self, tr('추출 영상 없음'), tr('표의 ‘사용’ 체크박스를 하나 이상 켜세요.'))
            return
        self.write_project_configuration(payload, tr('영상별 추출 계획 저장 · {value1}개', value1=len(videos)))
        runtime_dir = project_state_root(self.config.parent) / "runtime"
        runtime_dir.mkdir(parents=True, exist_ok=True)
        plan_path = runtime_dir / "dataset-extract-plan.json"
        plan_path.write_text(json.dumps({"videos": videos}, ensure_ascii=False, indent=2), encoding="utf-8")
        def extracted(exit_code: int) -> None:
            self.refresh_project()
            if exit_code == 0 and hasattr(self, "dataset_label_card"):
                self.set_workflow_expanded(self.dataset_plan_card, False)
                self.set_workflow_expanded(self.dataset_label_card, True)
                self.set_workflow_badge(self.dataset_label_badge, tr('프레임 추출 완료'), True)
        self.start_process(
            SCRIPTS / "hagisilta_dlc_worker.py",
            ["extract-plan", str(self.config), "--plan", str(plan_path)],
            extracted,
        )

    def import_quick_roi_videos(self) -> None:
        if not self.require_config():
            return
        quick_output = Path(self.quick_output.text())
        source_video = Path(self.quick_video.text())
        roi_profile = Path(self.quick_roi_profile.text())
        has_inference_metadata = bool(list(quick_output.glob("arena_*/roi-metadata.json")))
        if not has_inference_metadata and not source_video.is_file():
            QMessageBox.information(
                self, tr('대표 영상 없음'),
                tr('SuperAnimal 모델 확인에서 대표 영상을 먼저 지정하세요.'),
            )
            return
        if not has_inference_metadata and not roi_profile.is_file():
            QMessageBox.information(
                self, tr('SuperAnimal ROI 미설정'),
                tr('SuperAnimal 모델 확인에서 ‘ROI 지정/수정’을 눌러 ROI를 먼저 저장하세요.\n박스 추론까지 실행할 필요는 없습니다.'),
            )
            return

        def imported(exit_code: int) -> None:
            if exit_code == 0:
                self.refresh_project()
                self.load_dataset_configuration()
                QMessageBox.information(
                    self, tr('ROI 영상 가져오기 완료'),
                    tr('SuperAnimal 모델 확인에서 사용한 ROI 원본 클립을 등록했습니다.\n영상별 ‘추출 프레임’을 정하고 ‘계획 저장 후 대표 프레임 추출’을 누르세요.'),
                )

        self.start_process(
            SCRIPTS / "hagisilta_import_quick_rois.py",
            [
                str(quick_output), str(self.config),
                "--default-frames", str(self.dataset_frames_per_video.value()),
                "--source-video", str(source_video),
                "--roi-profile", str(roi_profile),
            ],
            imported,
        )

    def extract_outliers(self) -> None:
        output = str(self.config.parent / "active-learning") if self.config else None
        self.run_worker("outliers", self.dataset_video.text(), output)

